static int ds4_gpu_ane_debug_enabled(void) {
    const char *env = getenv("DS4_FLASH_MOE_ANE_DEBUG");
    return env && env[0] && atoi(env) != 0;
}

static int ds4_gpu_ane_stats_enabled(void) {
    if (ds4_gpu_backend_logs_suppressed()) return 0;
    const char *env = getenv("DS4_FLASH_MOE_ANE_STATS");
    return (env && env[0] && atoi(env) != 0) || ds4_gpu_ane_debug_enabled();
}

static void ds4_gpu_ane_record_batch_stats(uint32_t batch,
                                           uint64_t eval_calls,
                                           uint64_t refs,
                                           uint64_t padded_refs) {
    uint32_t idx = DS4_ANE_BATCH_HIST_N - 1u;
    for (uint32_t i = 0; i + 1u < DS4_ANE_BATCH_HIST_N; i++) {
        if (g_ane_batch_hist_values[i] == batch) {
            idx = i;
            break;
        }
    }
    g_ane_prefill_batch_eval_calls[idx] += eval_calls;
    g_ane_prefill_batch_refs[idx] += refs;
    g_ane_prefill_batch_padded_refs[idx] += padded_refs;
}

static void ds4_gpu_ane_prefill_record_reject(const char *reason) {
    if (!reason) {
        return;
    } else if (strcmp(reason, "init") == 0) {
        g_ane_prefill_reject_init++;
    } else if (strcmp(reason, "bad_args") == 0) {
        g_ane_prefill_reject_bad_args++;
    } else if (strcmp(reason, "shape") == 0) {
        g_ane_prefill_reject_type_shape++;
    } else if (strcmp(reason, "row_bytes") == 0) {
        g_ane_prefill_reject_row_bytes++;
    } else if (strcmp(reason, "mode_gate") == 0) {
        g_ane_prefill_reject_mode_gate++;
    } else if (strcmp(reason, "size_overflow") == 0) {
        g_ane_prefill_reject_size++;
    } else if (strcmp(reason, "big_refs") == 0) {
        g_ane_prefill_skip_big_refs++;
    }
}

static void ds4_gpu_print_ane_prefill_stats(void) {
    extern uint64_t g_shared_ane_sync_calls;
    if (!ds4_gpu_ane_stats_enabled() ||
        (g_ane_prefill_attempts == 0 &&
         g_ane_prefill_calls == 0 &&
         g_ane_prefill_compile_attempts == 0 &&
         g_shared_ane_sync_calls == 0)) {
        return;
    }
    fprintf(stderr,
            "ds4: ANE prefill stats attempts=%llu calls=%llu ok=%llu skipped_big_refs=%llu compile_attempts=%llu compile_failures=%llu eval_calls=%llu ane_evaluate_calls=%llu eval_failures=%llu write_failures=%llu reopen_failures=%llu rejects(init=%llu bad_args=%llu type_shape=%llu row_bytes=%llu mode_gate=%llu size=%llu)\n",
            (unsigned long long)g_ane_prefill_attempts,
            (unsigned long long)g_ane_prefill_calls,
            (unsigned long long)g_ane_prefill_successes,
            (unsigned long long)g_ane_prefill_skip_big_refs,
            (unsigned long long)g_ane_prefill_compile_attempts,
            (unsigned long long)g_ane_prefill_compile_failures,
            (unsigned long long)g_ane_prefill_eval_calls,
            (unsigned long long)g_ane_prefill_ane_evaluate_calls,
            (unsigned long long)g_ane_prefill_eval_failures,
            (unsigned long long)g_ane_prefill_write_failures,
            (unsigned long long)g_ane_prefill_reopen_failures,
            (unsigned long long)g_ane_prefill_reject_init,
            (unsigned long long)g_ane_prefill_reject_bad_args,
            (unsigned long long)g_ane_prefill_reject_type_shape,
            (unsigned long long)g_ane_prefill_reject_row_bytes,
            (unsigned long long)g_ane_prefill_reject_mode_gate,
            (unsigned long long)g_ane_prefill_reject_size);
    if (g_ane_prefill_x_values != 0) {
        fprintf(stderr,
                "ds4: ANE quant stats x_values=%llu x_saturated=%llu x_sat_rate=%.6f%% x_abs_max=%.6g\n",
                (unsigned long long)g_ane_prefill_x_values,
                (unsigned long long)g_ane_prefill_x_saturated,
                100.0 * (double)g_ane_prefill_x_saturated / (double)g_ane_prefill_x_values,
                g_ane_prefill_x_abs_max);
    }
    uint64_t hidden_values = 0;
    uint64_t hidden_saturated = 0;
    float hidden_abs_max = 0.0f;
    ds4_ane_mlp_int8w_quant_stats(&hidden_values, &hidden_saturated, &hidden_abs_max);
    if (hidden_values != 0) {
        fprintf(stderr,
                "ds4: ANE i8i8 hidden quant stats hidden_values=%llu hidden_saturated=%llu hidden_sat_rate=%.6f%% hidden_abs_max=%.6g\n",
                (unsigned long long)hidden_values,
                (unsigned long long)hidden_saturated,
                100.0 * (double)hidden_saturated / (double)hidden_values,
                hidden_abs_max);
    }
    if (g_ane_prefill_eval_calls != 0 ||
        g_ane_prefill_dequant_ms != 0.0 ||
        g_shared_ane_sync_calls != 0) {
        const double calls = g_ane_prefill_eval_calls ? (double)g_ane_prefill_eval_calls : 1.0;
        const double ane_calls = g_ane_prefill_ane_evaluate_calls ? (double)g_ane_prefill_ane_evaluate_calls : calls;
        const double pad_util = g_ane_prefill_padded_refs ?
            100.0 * (double)g_ane_prefill_eval_refs / (double)g_ane_prefill_padded_refs : 0.0;
        const double eval_total = g_ane_prefill_eval_ms + g_ane_prefill_eval_ms_b +
                                   g_ane_prefill_eval_ms_c + g_ane_prefill_eval_ms_d;
        /* When dual/multi is active eval_total = A+B(+C+D); ANE wall ≈ max(A..).
         * When solo, eval_ms_{b,c,d} are 0 and ane_wall_est == eval_ms. */
        double ane_wall_est = g_ane_prefill_eval_ms;
        if (g_ane_prefill_eval_ms_b > ane_wall_est) ane_wall_est = g_ane_prefill_eval_ms_b;
        if (g_ane_prefill_eval_ms_c > ane_wall_est) ane_wall_est = g_ane_prefill_eval_ms_c;
        if (g_ane_prefill_eval_ms_d > ane_wall_est) ane_wall_est = g_ane_prefill_eval_ms_d;
        fprintf(stderr,
                "ds4: ANE prefill timing dequant=%.3f ms input=%.3f ms ane_eval=%.3f ms ane_eval_a=%.3f ms ane_eval_b=%.3f ms ane_eval_c=%.3f ms ane_eval_d=%.3f ms ane_wall_est=%.3f ms writeback=%.3f ms helper_avg=%.6f ms ane_calls=%llu ane_call_avg=%.6f ms\n",
                g_ane_prefill_dequant_ms,
                g_ane_prefill_input_ms,
                eval_total,
                g_ane_prefill_eval_ms,
                g_ane_prefill_eval_ms_b,
                g_ane_prefill_eval_ms_c,
                g_ane_prefill_eval_ms_d,
                ane_wall_est,
                g_ane_prefill_writeback_ms,
                eval_total / calls,
                (unsigned long long)g_ane_prefill_ane_evaluate_calls,
                eval_total / ane_calls);
        fprintf(stderr,
                "ds4: ANE prefill timing2 output_pack=%.3f ms measured_total=%.3f ms\n",
                g_ane_prefill_output_ms,
                g_ane_prefill_dequant_ms + g_ane_prefill_input_ms +
                    ane_wall_est + g_ane_prefill_output_ms +
                    g_ane_prefill_writeback_ms);
        if (g_ane_prefill_output_elems != 0 ||
            g_ane_prefill_dequant_wait_ms != 0.0 ||
            g_ane_prefill_post_wait_ms != 0.0) {
            const double gelem = (double)g_ane_prefill_output_elems / 1000000000.0;
            const double convert_rate = g_ane_prefill_output_convert_ms > 0.0 ?
                gelem / (g_ane_prefill_output_convert_ms / 1000.0) : 0.0;
            fprintf(stderr,
                    "ds4: ANE prefill timing3 dequant_wait=%.3f ms post_wait=%.3f ms x_zero=%.3f ms x_copy=%.3f ms out_zero=%.3f ms out_f16_copy=%.3f ms output_convert=%.3f ms output_gpu_encode=%.3f ms output_chunks=%llu output_elems=%llu output_convert_rate=%.3f Gelem/s\n",
                    g_ane_prefill_dequant_wait_ms,
                    g_ane_prefill_post_wait_ms,
                    g_ane_prefill_x_zero_ms,
                    g_ane_prefill_x_copy_ms,
                    g_ane_prefill_out_zero_ms,
                    g_ane_prefill_output_f16_copy_ms,
                    g_ane_prefill_output_convert_ms,
                    g_ane_prefill_output_gpu_encode_ms,
                    (unsigned long long)g_ane_prefill_output_chunks,
                    (unsigned long long)g_ane_prefill_output_elems,
                    convert_rate);
        }
        if (g_ane_prefill_wait_predict_ms != 0.0 ||
            g_ane_prefill_finish_join_ane_ms != 0.0 ||
            g_ane_prefill_finish_join_post_ms != 0.0) {
            fprintf(stderr,
                    "ds4: ANE prefill timing4 wait_predict=%.3f ms finish_join_ane=%.3f ms finish_join_post=%.3f ms wait_predict_calls=%llu finish_calls=%llu\n",
                    g_ane_prefill_wait_predict_ms,
                    g_ane_prefill_finish_join_ane_ms,
                    g_ane_prefill_finish_join_post_ms,
                    (unsigned long long)g_ane_prefill_wait_predict_calls,
                    (unsigned long long)g_ane_prefill_finish_calls);
        }
        /* Forward refs — counters defined below near the shared-expert impl. */
        extern uint64_t g_shared_ane_sync_calls;
        extern double   g_shared_ane_sync_total_ms;
        extern double   g_shared_ane_sync_eval_ms;
        extern double   g_shared_ane_sync_input_ms;
        extern double   g_shared_ane_sync_output_ms;
        extern double   g_shared_ane_sync_init_ms;
        extern double   g_shared_ane_dep_wait_ms;
        extern double   g_shared_ane_join_wait_ms;
        extern double   g_shared_ane_warm_ms;
        extern uint64_t g_shared_ane_cache_evictions;
        if (g_shared_ane_sync_calls > 0) {
            const double avg_eval_ms = g_shared_ane_sync_eval_ms / (double)g_shared_ane_sync_calls;
            const double avg_join_ms = g_shared_ane_join_wait_ms / (double)g_shared_ane_sync_calls;
            const uint32_t cache_window = ds4_gpu_shared_expert_ane_cache_window();
            fprintf(stderr,
                    "ds4: ANE shared-expert calls=%llu total_ms=%.3f eval_ms=%.3f eval_avg=%.3f ms/call input_ms=%.3f output_ms=%.3f init_ms=%.3f warm_ms=%.3f dep_wait_ms=%.3f join_wait_ms=%.3f join_avg=%.3f ms/call cache_window=%u cache_evictions=%llu\n",
                    (unsigned long long)g_shared_ane_sync_calls,
                    g_shared_ane_sync_total_ms,
                    g_shared_ane_sync_eval_ms, avg_eval_ms,
                    g_shared_ane_sync_input_ms, g_shared_ane_sync_output_ms,
                    g_shared_ane_sync_init_ms,
                    g_shared_ane_warm_ms,
                    g_shared_ane_dep_wait_ms,
                    g_shared_ane_join_wait_ms, avg_join_ms,
                    cache_window,
                    (unsigned long long)g_shared_ane_cache_evictions);
        }
        extern uint64_t g_oproj_ane_calls;
        extern double   g_oproj_ane_total_ms;
        extern double   g_oproj_ane_eval_ms;
        extern double   g_oproj_ane_input_ms;
        extern double   g_oproj_ane_output_ms;
        extern double   g_oproj_ane_init_ms;
        extern double   g_oproj_ane_dep_wait_ms;
        extern double   g_oproj_ane_join_wait_ms;
        if (g_oproj_ane_calls > 0) {
            const double avg_eval_ms = g_oproj_ane_eval_ms / (double)g_oproj_ane_calls;
            const double avg_join_ms = g_oproj_ane_join_wait_ms / (double)g_oproj_ane_calls;
            fprintf(stderr,
                    "ds4: ANE O-proj calls=%llu total_ms=%.3f eval_ms=%.3f eval_avg=%.3f ms/call input_ms=%.3f output_ms=%.3f init_ms=%.3f dep_wait_ms=%.3f join_wait_ms=%.3f join_avg=%.3f ms/call\n",
                    (unsigned long long)g_oproj_ane_calls,
                    g_oproj_ane_total_ms,
                    g_oproj_ane_eval_ms, avg_eval_ms,
                    g_oproj_ane_input_ms, g_oproj_ane_output_ms,
                    g_oproj_ane_init_ms,
                    g_oproj_ane_dep_wait_ms,
                    g_oproj_ane_join_wait_ms, avg_join_ms);
        }
        fprintf(stderr,
                "ds4: ANE prefill chunks refs=%llu padded_refs=%llu pad_util=%.2f%% le16=%llu le64=%llu le128=%llu full=%llu\n",
                (unsigned long long)g_ane_prefill_eval_refs,
                (unsigned long long)g_ane_prefill_padded_refs,
                pad_util,
                (unsigned long long)g_ane_prefill_chunks_le16,
                (unsigned long long)g_ane_prefill_chunks_le64,
                (unsigned long long)g_ane_prefill_chunks_le128,
                (unsigned long long)g_ane_prefill_chunks_full);
        fprintf(stderr, "ds4: ANE prefill batch_hist");
        for (uint32_t i = 0; i < DS4_ANE_BATCH_HIST_N; i++) {
            const uint64_t evals = g_ane_prefill_batch_eval_calls[i];
            if (!evals) continue;
            const double util = g_ane_prefill_batch_padded_refs[i] ?
                100.0 * (double)g_ane_prefill_batch_refs[i] /
                    (double)g_ane_prefill_batch_padded_refs[i] : 0.0;
            if (g_ane_batch_hist_values[i]) {
                fprintf(stderr,
                        " B%u=%llu refs=%llu util=%.1f%%",
                        g_ane_batch_hist_values[i],
                        (unsigned long long)evals,
                        (unsigned long long)g_ane_prefill_batch_refs[i],
                        util);
            } else {
                fprintf(stderr,
                        " Bother=%llu refs=%llu util=%.1f%%",
                        (unsigned long long)evals,
                        (unsigned long long)g_ane_prefill_batch_refs[i],
                        util);
            }
        }
        fprintf(stderr, "\n");
    }
}

uint64_t ds4_gpu_system_memory_bytes(void) {
    uint64_t bytes = 0;
    size_t len = sizeof(bytes);
    if (sysctlbyname("hw.memsize", &bytes, &len, NULL, 0) != 0) return 0;
    return len == sizeof(bytes) ? bytes : 0;
}

uint64_t ds4_gpu_recommended_working_set_bytes(void) {
    if (!g_device) return 0;
    return (uint64_t)[g_device recommendedMaxWorkingSetSize];
}

static void ds4_gpu_print_device_summary(void) {
    const char *name = g_device.name ? [g_device.name UTF8String] : "unknown Metal device";
    uint64_t mem = ds4_gpu_system_memory_bytes();
    const uint64_t wset = ds4_gpu_recommended_working_set_bytes();
    if (mem) {
        double gib = (double)mem / 1024.0 / 1024.0 / 1024.0;
        fprintf(stderr,
                "ds4: Metal device %s, %.2f GiB RAM, GPU working-set budget %.2f GiB "
                "(raise with: sudo sysctl iogpu.wired_limit_mb=<MB>)\n",
                name, gib, (double)wset / 1073741824.0);
    } else {
        fprintf(stderr, "ds4: Metal device %s\n", name);
    }
}

static int ds4_gpu_is_m5_device(void) {
    static int initialized;
    static int is_m5;
    if (!initialized) {
        const char *device_name = g_device.name ? [g_device.name UTF8String] : "";
        is_m5 = strstr(device_name, "M5") != NULL;
        initialized = 1;
    }
    return is_m5;
}

int ds4_gpu_mpp_nax_supported(void) {
    return ds4_gpu_is_m5_device();
}

static int ds4_gpu_no_int8_paths_enabled(void) {
    const char *env = getenv("DS4_NO_INT8");
    return env && env[0] && atoi(env) != 0;
}

static int ds4_gpu_resident_mpp_int8_prefill_requested(void) {
    if (ds4_gpu_no_int8_paths_enabled()) {
        const char *half_env = getenv("DS4_RESIDENT_MOE_NAX_HALF");
        return half_env && half_env[0] && atoi(half_env) != 0;
    }
    const char *env = getenv("DS4_RESIDENT_MOE_MPP_INT8_PREFILL");
    if (!env || !env[0]) env = getenv("DS4_RESIDENT_MOE_NAX_INT8_PREFILL");
    if (!env || !env[0]) env = getenv("DS4_RESIDENT_MPP_INT8_PREFILL");
    if (!env || !env[0]) env = getenv("DS4_RESIDENT_MOE_NAX_HALF");
    return env && env[0] && atoi(env) != 0;
}

static int ds4_gpu_env_flag_enabled(const char *name) {
    const char *env = getenv(name);
    return env && env[0] && atoi(env) != 0;
}

static int ds4_gpu_env_value_eq(const char *v, size_t n, const char *literal) {
    size_t m = strlen(literal);
    if (n != m) return 0;
    for (size_t i = 0; i < n; i++) {
        if (tolower((unsigned char)v[i]) != tolower((unsigned char)literal[i])) return 0;
    }
    return 1;
}

static int ds4_gpu_env_bool(const char *name) {
    const char *v = getenv(name);
    if (!v) return -1;

    while (isspace((unsigned char)*v)) v++;
    size_t n = strlen(v);
    while (n > 0 && isspace((unsigned char)v[n - 1])) n--;
    if (n == 0) return 1;

    if (ds4_gpu_env_value_eq(v, n, "1") ||
        ds4_gpu_env_value_eq(v, n, "true") ||
        ds4_gpu_env_value_eq(v, n, "yes") ||
        ds4_gpu_env_value_eq(v, n, "on")) {
        return 1;
    }
    if (ds4_gpu_env_value_eq(v, n, "0") ||
        ds4_gpu_env_value_eq(v, n, "false") ||
        ds4_gpu_env_value_eq(v, n, "no") ||
        ds4_gpu_env_value_eq(v, n, "off")) {
        return 0;
    }

    if (!g_metal_env_invalid_reported) {
        fprintf(stderr,
                "ds4: invalid Metal boolean environment value %s=%.*s; treating presence as enabled\n",
                name, (int)n, v);
        g_metal_env_invalid_reported = 1;
    }
    return 1;
}

static uint32_t ds4_gpu_env_u32_default(const char *name, uint32_t fallback) {
    const char *env = getenv(name);
    if (!env || !env[0]) return fallback;
    char *end = NULL;
    unsigned long parsed = strtoul(env, &end, 10);
    if (end == env || parsed > UINT32_MAX) return fallback;
    return (uint32_t)parsed;
}

static int ds4_gpu_resident_mpp_int8_prefill_forced(void) {
    return ds4_gpu_env_flag_enabled("DS4_RESIDENT_MOE_MPP_FORCE") ||
           ds4_gpu_env_flag_enabled("DS4_RESIDENT_MOE_NAX_FORCE") ||
           ds4_gpu_env_flag_enabled("DS4_RESIDENT_MPP_INT8_FORCE");
}

static uint32_t ds4_gpu_resident_mpp_int8_min_tokens(void) {
    uint32_t min_tokens =
        ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_MPP_MIN_TOKENS", 16384u);
    min_tokens =
        ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_NAX_MIN_TOKENS", min_tokens);
    return ds4_gpu_env_u32_default("DS4_RESIDENT_MPP_INT8_MIN_TOKENS", min_tokens);
}

static uint32_t ds4_gpu_resident_mpp_sync_max_tokens(void) {
    return ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_MPP_SYNC_MAX_TOKENS", 7168u);
}

static int ds4_gpu_resident_nax_half_safe(uint32_t n_tokens) {
    if (!ds4_gpu_mpp_nax_supported()) return 0;
    if (n_tokens >= 64u && (n_tokens % 64u) == 0u) return 1;
    return ds4_gpu_env_flag_enabled("DS4_RESIDENT_MOE_NAX_HALF_ALLOW_PARTIAL");
}

static const char *ds4_gpu_no_int8_backend_remap(const char *backend,
                                                 uint32_t n_tokens) {
    if (!ds4_gpu_no_int8_paths_enabled() || !backend || !backend[0]) return backend;
    if (strcmp(backend, "mulmm") == 0) return backend;

    const int is_half = strstr(backend, "half") != NULL;
    const int is_int8 = strstr(backend, "int8") != NULL;
    const int is_ane = strncmp(backend, "ane", 3) == 0;
    const int is_pathc = strcmp(backend, "pathc") == 0;
    if (!is_half && !is_int8 && !is_ane && !is_pathc) return backend;

    if (ds4_gpu_resident_nax_half_safe(n_tokens)) {
        return is_half ? backend : "nax_half";
    }
    return "mulmm";
}

/* Per-chunk routed-MoE backend resolution for the grouped path. PRECEDENCE:
 *   1. DS4_RESIDENT_MOE_BACKEND            explicit param: force one backend, all chunks
 *   2. DS4_RESIDENT_MOE_PREFILL_BY_TOKENS  the JSON prefill_by_tokens table (the profile
 *      loader encodes it as "max:backend,max:backend,..." ascending by max); pick the
 *      first range whose max >= n_tokens
 *   3. "" -> caller falls back to the predefined env gates (NAX_HALF + MIN_TOKENS).
 * Writes the selected backend name to out (e.g. "nax_half_alu","nax_int8","mulmm"), or
 * "" if neither a param nor a matching range applies. Only grouped-path backends
 * (mulmm / nax_half / nax_half_alu / nax_int8) are honored by the caller. */
void ds4_gpu_resident_backend_for_tokens(uint32_t n_tokens, char *out, size_t outsz) {
    if (!out || outsz == 0) return;
    out[0] = '\0';
    const char *forced = getenv("DS4_RESIDENT_MOE_BACKEND");
    if (forced && forced[0]) {
        forced = ds4_gpu_no_int8_backend_remap(forced, n_tokens);
        size_t n = strlen(forced);
        if (n >= outsz) n = outsz - 1;
        memcpy(out, forced, n);
        out[n] = '\0';
        return;
    }
    const char *tbl = getenv("DS4_RESIDENT_MOE_PREFILL_BY_TOKENS");
    if (!tbl || !tbl[0]) return;
    const char *p = tbl;
    while (*p) {
        char *end = NULL;
        long mx = strtol(p, &end, 10);
        if (end == p || *end != ':') break;
        const char *name = end + 1;
        const char *comma = strchr(name, ',');
        size_t nlen = comma ? (size_t)(comma - name) : strlen(name);
        if ((long)n_tokens <= mx) {
            char name_buf[24];
            if (nlen >= sizeof(name_buf)) nlen = sizeof(name_buf) - 1;
            memcpy(name_buf, name, nlen);
            name_buf[nlen] = '\0';
            const char *mapped = ds4_gpu_no_int8_backend_remap(name_buf, n_tokens);
            nlen = strlen(mapped);
            if (nlen >= outsz) nlen = outsz - 1;
            memcpy(out, mapped, nlen);
            out[nlen] = '\0';
            return;
        }
        if (!comma) break;
        p = comma + 1;
    }
}

static int ds4_gpu_resident_mpp_int8_prefill_should_run(uint32_t n_tokens) {
    if (!ds4_gpu_resident_mpp_int8_prefill_requested()) return 0;
    if (ds4_gpu_resident_mpp_int8_prefill_forced()) return 1;
    const uint32_t min_tokens = ds4_gpu_resident_mpp_int8_min_tokens();
    return min_tokens != 0u && n_tokens >= min_tokens;
}

static int ds4_gpu_resident_mpp_id_map_needs_cpu_access(void) {
    if (!ds4_gpu_resident_mpp_int8_prefill_requested()) return 0;
    if (ds4_gpu_resident_mpp_int8_prefill_forced()) return 1;
    const char *sync_bridge_env = getenv("DS4_RESIDENT_MOE_MPP_SYNC_BRIDGE");
    if (sync_bridge_env && sync_bridge_env[0]) return atoi(sync_bridge_env) != 0;
    const uint32_t min_tokens = ds4_gpu_resident_mpp_int8_min_tokens();
    const uint32_t sync_max_tokens = ds4_gpu_resident_mpp_sync_max_tokens();
    return min_tokens != 0u && sync_max_tokens != 0u && min_tokens <= sync_max_tokens;
}

static int ds4_gpu_use_m5_private_scratch(void) {
    static int initialized;
    static int enabled;
    if (!initialized) {
        enabled = getenv("DS4_METAL_DISABLE_M5_PRIVATE_SCRATCH") == NULL && ds4_gpu_is_m5_device();
        initialized = 1;
    }
    return enabled;
}

static int ds4_gpu_scratch_needs_cpu_access(const char *label) {
    if (!label) return 0;
    return strstr(label, "mask") != NULL ||
           strstr(label, "ane") != NULL ||
           (ds4_gpu_resident_mpp_id_map_needs_cpu_access() &&
            strcmp(label, "ds4_moe_id_map") == 0) ||
           strcmp(label, "ds4_attention_output_group_ids") == 0;
}

#define DS4_METAL_MAX_MODEL_VIEWS 16
#define DS4_METAL_MODEL_MAX_TENSOR_BYTES 704643072ull

typedef struct {
    __strong id<MTLBuffer> buffer;
    const void *model_map;
    uint64_t model_size;
    uint64_t model_offset;
    uint64_t bytes;
} ds4_gpu_model_view;

static ds4_gpu_model_view g_model_views[DS4_METAL_MAX_MODEL_VIEWS];
static uint32_t g_model_view_count;

static int ds4_gpu_lazy_model_views_requested(void) {
    static int initialized;
    static int enabled;
    if (!initialized) {
        const char *env = getenv("DS4_METAL_LAZY_MODEL_VIEWS");
        const char *mode = getenv("DS4_METAL_MODEL_VIEW_MODE");
        enabled = (env && env[0] && atoi(env) != 0) ||
                  (mode && (!strcmp(mode, "lazy") || !strcmp(mode, "range")));
        initialized = 1;
    }
    return enabled;
}

static int ds4_gpu_lazy_model_views_enabled(void) {
    return ds4_gpu_lazy_model_views_requested() && !g_model_force_persistent_views;
}

static int ds4_gpu_decode_residency_requested(void) {
    const char *env = getenv("DS4_METAL_DECODE_RESIDENCY");
    return env && env[0] && atoi(env) != 0;
}

static int ds4_gpu_decode_persistent_views_requested(uint64_t map_size) {
    const char *env = getenv("DS4_METAL_DECODE_PERSISTENT_VIEWS");
    if (env && env[0]) return atoi(env) != 0;
    /*
     * Persistent decode views wrap the whole tensor-data range as a couple of
     * giant no-copy buffers and keep them GPU-resident. That is fast for models
     * that comfortably fit, but a decode command buffer must make the entire
     * referenced backing resident at once: for a model that is a large fraction
     * of system RAM this exhausts the working set and the first decode token
     * fails with kIOGPUCommandBufferCallbackErrorOutOfMemory (observed at 16K
     * context on a 96 GiB machine with a 76.5 GiB model; 8K barely fit). Such
     * models fall back to lazy decode views with a persisted wrap cache
     * (g_model_cache_persist): the per-layer buffers page granularly without the
     * all-or-nothing residency cliff, and the cache keeps per-token cost low.
     */
    const uint64_t ram = ds4_gpu_system_memory_bytes();
    if (ram == 0 || map_size == 0) return 1;
    /* 5/8 of RAM is safely below the observed cliff and leaves room for the KV
     * cache, decode scratch, the OS, and Metal's own working set. */
    return map_size <= (ram / 8) * 5;
}

static int ds4_gpu_backend_logs_suppressed(void) {
    if (ds4_gpu_env_flag_enabled("DS4_AGENT_ALLOW_BACKEND_STATS") ||
        ds4_gpu_env_flag_enabled("DS4_METAL_MODEL_VIEW_TRACE")) {
        return 0;
    }
    return ds4_gpu_env_flag_enabled("DS4_AGENT_SUPPRESS_BACKEND_LOGS");
}

static int ds4_gpu_backend_stats_logs_enabled(void) {
    if (ds4_gpu_backend_logs_suppressed()) return 0;
    return ds4_gpu_env_flag_enabled("DS4_AGENT_ALLOW_BACKEND_STATS") ||
           ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_PROFILE") ||
           ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_STAGE_STATS") ||
           ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_SCHED_STATS") ||
           ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_HYBRID_STATS") ||
           ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_CONCURRENT_STATS") ||
           ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_ANE_PIPELINE_STATS") ||
           ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_ANE_STATS") ||
           ds4_gpu_env_flag_enabled("DS4_RESIDENT_MOE_MPP_STATS") ||
           ds4_gpu_env_flag_enabled("DS4_METAL_GRAPH_PREFILL_PROFILE") ||
           ds4_gpu_env_flag_enabled("DS4_METAL_GRAPH_PREFILL_SPLIT_PROFILE");
}

static const char *ds4_gpu_gguf_tensor_type_name(uint32_t type) {
    switch (type) {
    case 0:                         return "F32";
    case 1:                         return "F16";
    case 8:                         return "Q8_0";
    case DS4_METAL_TENSOR_Q2_K:     return "Q2_K";
    case DS4_METAL_TENSOR_Q4_K:     return "Q4_K";
    case DS4_METAL_TENSOR_Q5_K:     return "Q5_K";
    case DS4_METAL_TENSOR_Q6_K:     return "Q6_K";
    case DS4_METAL_TENSOR_IQ2_XXS:  return "IQ2_XXS";
    case DS4_METAL_TENSOR_IQ3_XXS:  return "IQ3_XXS";
    case DS4_METAL_TENSOR_IQ4_XS:   return "IQ4_XS";
    case DS4_METAL_TENSOR_IQ1_M:    return "IQ1_M";
    case DS4_METAL_TENSOR_MXFP4:    return "MXFP4";
    default:                        return "unknown";
    }
}

static FILE *ds4_gpu_matmul_path_csv(void) {
    static int initialized = 0;
    static FILE *fp = NULL;
    if (initialized) return fp;
    initialized = 1;

    const char *path = getenv("DS4_MATMUL_PATH_CSV");
    if (!path || !path[0]) return NULL;

    fp = fopen(path, "ab");
    if (!fp) {
        if (!ds4_gpu_backend_logs_suppressed()) {
            fprintf(stderr, "ds4: failed to open DS4_MATMUL_PATH_CSV=%s: %s\n",
                    path, strerror(errno));
        }
        return NULL;
    }
    if (fseek(fp, 0, SEEK_END) == 0 && ftell(fp) == 0) {
        fprintf(fp, "seq,path,type,type_id,weight_offset,in_dim,out_dim,tokens,note\n");
    }
    setvbuf(fp, NULL, _IOLBF, 0);
    return fp;
}

static void ds4_gpu_log_matmul_path(const char *path,
                                    uint32_t    type,
                                    uint64_t    weight_offset,
                                    uint64_t    in_dim,
                                    uint64_t    out_dim,
                                    uint64_t    n_tok,
                                    const char *note) {
    FILE *fp = ds4_gpu_matmul_path_csv();
    if (!fp) return;

    static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
    static uint64_t seq = 0;
    pthread_mutex_lock(&mu);
    fprintf(fp,
            "%llu,%s,%s,%u,%llu,%llu,%llu,%llu,%s\n",
            (unsigned long long)++seq,
            path ? path : "unknown",
            ds4_gpu_gguf_tensor_type_name(type),
            type,
            (unsigned long long)weight_offset,
            (unsigned long long)in_dim,
            (unsigned long long)out_dim,
            (unsigned long long)n_tok,
            note ? note : "");
    pthread_mutex_unlock(&mu);
}

static __thread int g_ds4_matmul_path_nested;

static int ds4_gpu_model_residency_disabled_now(void) {
    return getenv("DS4_METAL_NO_RESIDENCY") != NULL;
}

static void ds4_gpu_transient_resources_clear(void) {
    [g_transient_buffers removeAllObjects];
    /*
     * Lazy model views are no-copy wrappers over mmap pages. They are cached
     * only for the lifetime of the in-flight command batch so tiled kernels can
     * reuse a wrapped range without making the driver validate the full model.
     * In lazy decode mode (g_model_cache_persist) the wrap cache instead lives
     * across command batches so per-token re-validation cost is paid once; see
     * the note on g_model_cache_persist.
     */
    if (!g_model_cache_persist) {
        [g_model_buffer_cache removeAllObjects];
    }
}

/* Drop the persisted lazy decode wrap cache. Must be called whenever the set of
 * model-view buffers changes (mode switch, model unload) so stale no-copy
 * wraps over a remapped file are never reused. */
static void ds4_gpu_model_buffer_cache_clear(void) {
    [g_model_buffer_cache removeAllObjects];
}

