static double ds4_gpu_mib(uint64_t bytes) {
    return (double)bytes / (1024.0 * 1024.0);
}

static double ds4_gpu_gib(uint64_t bytes) {
    return (double)bytes / (1024.0 * 1024.0 * 1024.0);
}

int ds4_gpu_get_vm_stats(ds4_gpu_vm_stats *stats) {
    if (!stats) return 0;
    memset(stats, 0, sizeof(*stats));

    task_vm_info_data_t info;
    memset(&info, 0, sizeof(info));
    mach_msg_type_number_t count = TASK_VM_INFO_COUNT;
    kern_return_t kr = task_info(mach_task_self(),
                                 TASK_VM_INFO,
                                 (task_info_t)&info,
                                 &count);
    if (kr != KERN_SUCCESS) return 0;

    stats->resident_size = info.resident_size;
    stats->phys_footprint = info.phys_footprint;
    stats->compressed = info.compressed;
#if defined(TASK_VM_INFO_REV3_COUNT)
    if (count >= TASK_VM_INFO_REV3_COUNT) {
        stats->graphics_footprint = (uint64_t)info.ledger_tag_graphics_footprint;
        stats->graphics_footprint_compressed =
            (uint64_t)info.ledger_tag_graphics_footprint_compressed;
        stats->graphics_nofootprint = (uint64_t)info.ledger_tag_graphics_nofootprint;
        stats->graphics_nofootprint_compressed =
            (uint64_t)info.ledger_tag_graphics_nofootprint_compressed;
    }
#endif
#if defined(TASK_VM_INFO_REV5_COUNT)
    if (count >= TASK_VM_INFO_REV5_COUNT) {
        stats->decompressions = (uint64_t)info.decompressions;
    }
#endif

    uint64_t total_mem = 0;
    size_t total_len = sizeof(total_mem);
    if (sysctlbyname("hw.memsize", &total_mem, &total_len, NULL, 0) == 0) {
        stats->system_memory_total = total_mem;
    }

    mach_port_t host = mach_host_self();
    vm_size_t page_size = 0;
    if (host_page_size(host, &page_size) != KERN_SUCCESS || page_size == 0) {
        page_size = 16384;
    }
    vm_statistics64_data_t vmstat;
    memset(&vmstat, 0, sizeof(vmstat));
    mach_msg_type_number_t vm_count = HOST_VM_INFO64_COUNT;
    if (host_statistics64(host,
                          HOST_VM_INFO64,
                          (host_info64_t)&vmstat,
                          &vm_count) == KERN_SUCCESS) {
        const uint64_t page = (uint64_t)page_size;
        stats->system_memory_free =
            ((uint64_t)vmstat.free_count + (uint64_t)vmstat.speculative_count) * page;
        stats->system_memory_active = (uint64_t)vmstat.active_count * page;
        stats->system_memory_wired = (uint64_t)vmstat.wire_count * page;
        stats->system_memory_compressed =
            (uint64_t)vmstat.total_uncompressed_pages_in_compressor * page;
        stats->system_memory_compressor = (uint64_t)vmstat.compressor_page_count * page;
        stats->system_memory_pressure_bytes =
            stats->system_memory_active +
            stats->system_memory_wired +
            stats->system_memory_compressor;
        if (stats->system_memory_total != 0) {
            uint64_t pct =
                (stats->system_memory_pressure_bytes * 100u) / stats->system_memory_total;
            stats->system_memory_pressure_pct = pct > 100u ? 100u : (uint32_t)pct;
        }
    }
    mach_port_deallocate(mach_task_self(), host);

    struct xsw_usage swap;
    size_t swap_len = sizeof(swap);
    if (sysctlbyname("vm.swapusage", &swap, &swap_len, NULL, 0) == 0) {
        stats->swap_total = (uint64_t)swap.xsu_total;
        stats->swap_used = (uint64_t)swap.xsu_used;
    }
    return 1;
}

void ds4_gpu_print_memory_report(const char *label) {
    const uint64_t scratch =
        (uint64_t)g_flash_attn_mask_bytes +
        (uint64_t)g_flash_attn_pad_bytes +
        (uint64_t)g_flash_attn_tmp_bytes +
        (uint64_t)g_flash_attn_blk_bytes +
        (uint64_t)g_flash_attn_ring_bytes +
        (uint64_t)g_flash_attn_kv_bytes +
        (uint64_t)g_compressor_pool_kv_bytes +
        (uint64_t)g_compressor_pool_score_bytes +
        (uint64_t)g_compressor_pool_score_cont_bytes +
        (uint64_t)g_compressor_pool_softmax_bytes +
        (uint64_t)g_compressor_pool_product_bytes +
        (uint64_t)g_compressor_store_ape_bytes +
        (uint64_t)g_compressor_store_score_bytes +
        (uint64_t)g_embed_rows_bytes +
        (uint64_t)g_router_selection_bytes +
        (uint64_t)g_router_weight_sum_bytes +
        (uint64_t)g_indexer_head_scores_bytes +
        (uint64_t)g_indexer_topk_bytes +
        (uint64_t)g_indexed_topk_bytes +
        (uint64_t)g_f16_round_scratch_bytes +
        (uint64_t)g_raw_store_round_bytes +
        (uint64_t)g_moe_gate_scratch_bytes +
        (uint64_t)g_moe_down_scratch_bytes +
        (uint64_t)g_moe_id_map_bytes;

    fprintf(stderr, "ds4: Metal memory report%s%s\n",
            label && label[0] ? " " : "",
            label && label[0] ? label : "");
    fprintf(stderr,
            "ds4:   runtime tensors live %.2f MiB peak %.2f MiB\n",
            ds4_gpu_mib(g_tensor_alloc_live_bytes),
            ds4_gpu_mib(g_tensor_alloc_peak_bytes));
    fprintf(stderr,
            "ds4:   mmap model wrapper spans %llu buffers %.2f GiB total, %.2f GiB max (not copied)\n",
            (unsigned long long)g_model_wrap_count,
            ds4_gpu_gib(g_model_wrap_bytes),
            ds4_gpu_gib(g_model_wrap_max_bytes));
    fprintf(stderr,
            "ds4:   model residency requests %llu%s\n",
            (unsigned long long)g_model_residency_count,
            ds4_gpu_model_residency_disabled_now() ? " (disabled)" : "");
    fprintf(stderr,
            "ds4:   resident model cache %llu ranges %.2f MiB\n",
            (unsigned long long)g_resident_model_cache_count,
            ds4_gpu_mib(g_resident_model_cache_bytes));
    fprintf(stderr,
            "ds4:   scratch %.2f MiB (flash mask %.2f, pad %.2f, tmp %.2f, blk %.2f, ring %.2f, kv %.2f, compressor %.2f, router %.2f, indexer %.2f, moe %.2f, f16 %.2f, raw-store %.2f)\n",
            ds4_gpu_mib(scratch),
            ds4_gpu_mib((uint64_t)g_flash_attn_mask_bytes),
            ds4_gpu_mib((uint64_t)g_flash_attn_pad_bytes),
            ds4_gpu_mib((uint64_t)g_flash_attn_tmp_bytes),
            ds4_gpu_mib((uint64_t)g_flash_attn_blk_bytes),
            ds4_gpu_mib((uint64_t)g_flash_attn_ring_bytes),
            ds4_gpu_mib((uint64_t)g_flash_attn_kv_bytes),
            ds4_gpu_mib((uint64_t)g_compressor_pool_kv_bytes +
                          (uint64_t)g_compressor_pool_score_bytes +
                          (uint64_t)g_compressor_pool_score_cont_bytes +
                          (uint64_t)g_compressor_pool_softmax_bytes +
                          (uint64_t)g_compressor_pool_product_bytes +
                          (uint64_t)g_compressor_store_ape_bytes +
                          (uint64_t)g_compressor_store_score_bytes +
                          (uint64_t)g_embed_rows_bytes),
            ds4_gpu_mib((uint64_t)g_router_selection_bytes +
                          (uint64_t)g_router_weight_sum_bytes),
            ds4_gpu_mib((uint64_t)g_indexer_head_scores_bytes +
                          (uint64_t)g_indexer_topk_bytes +
                          (uint64_t)g_indexed_topk_bytes),
            ds4_gpu_mib((uint64_t)g_moe_gate_scratch_bytes +
                          (uint64_t)g_moe_down_scratch_bytes +
                          (uint64_t)g_moe_id_map_bytes),
            ds4_gpu_mib((uint64_t)g_f16_round_scratch_bytes),
            ds4_gpu_mib((uint64_t)g_raw_store_round_bytes));
}

