static uint64_t ds4_gpu_obj_id(id obj) {
    return (uint64_t)(uintptr_t)(__bridge const void *)obj;
}

static bool ds4_gpu_flash_moe_icb_slot_key_valid(uint32_t layer_index, int32_t slot) {
    return layer_index < DS4_FLASH_MOE_ICB_MAX_LAYERS &&
           slot >= 0 &&
           slot < (int32_t)DS4_FLASH_MOE_ICB_MAX_SLOTS;
}

static uint32_t ds4_gpu_flash_moe_icb_bucket_for_key(
        const ds4_gpu_flash_moe_icb_key *key) {
    if (!key) return 0;
    switch (key->kind) {
    case DS4_DECODE_REPLAY_MV:
        return key->args.ne13 ? 2u : 1u;
    case DS4_DECODE_REPLAY_PAIR_SWIGLU:
        return 3u;
    case DS4_DECODE_REPLAY_PAIR_SWIGLU_DOWN:
        return key->args2.ne13 ? 6u : 5u;
    default:
        return key->kind % DS4_FLASH_MOE_ICB_SLOT_BUCKETS;
    }
}

static uint32_t ds4_gpu_flash_moe_icb_slot_generation_current(
        uint32_t layer_index,
        int32_t  slot) {
    if (!ds4_gpu_flash_moe_icb_slot_key_valid(layer_index, slot)) return 0;
    return g_flash_moe_icb_slot_generation[layer_index][slot];
}

static void ds4_gpu_flash_moe_icb_unindex_entry(
        uint32_t                          cache_slot,
        const ds4_gpu_flash_moe_icb_entry *entry) {
    if (!entry ||
        !ds4_gpu_flash_moe_icb_slot_key_valid(entry->key.layer_index, entry->key.slot)) {
        return;
    }
    const uint32_t bucket = ds4_gpu_flash_moe_icb_bucket_for_key(&entry->key);
    uint32_t *hint =
        &g_flash_moe_icb_slot_index[entry->key.layer_index][entry->key.slot][bucket];
    if (*hint == cache_slot + 1u) *hint = 0;
}

static void ds4_gpu_flash_moe_icb_reset_entry(ds4_gpu_flash_moe_icb_entry *entry) {
    if (!entry) return;
    entry->valid = false;
    entry->slot_generation = 0;
    entry->args_buf = nil;
    entry->args2_buf = nil;
    entry->act_buf = nil;
    for (uint32_t j = 0; j < DS4_FLASH_MOE_ICB_KERNEL_BUFFERS; j++) {
        entry->buffers[j] = nil;
        entry->offsets[j] = 0;
        entry->usages[j] = 0;
        entry->buffers2[j] = nil;
        entry->offsets2[j] = 0;
        entry->usages2[j] = 0;
    }
    entry->icb = nil;
}

static int ds4_gpu_decode_replay_enabled(void) {
    static int enabled = -1;
    if (enabled < 0) {
        const char *env = getenv("DS4_FLASH_MOE_METAL_DECODE_REPLAY");
        if (!env || !env[0]) {
            env = getenv("LLAMA_FLASH_MOE_EXPERIMENTAL_METAL_DECODE_REPLAY");
        }
        enabled = (!env || !env[0] || atoi(env) != 0) ? 1 : 0;
    }
    return enabled;
}

static int ds4_gpu_decode_replay_stats_enabled(void) {
    return ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_METAL_DECODE_REPLAY_STATS") ||
           ds4_gpu_env_flag_enabled("LLAMA_FLASH_MOE_EXPERIMENTAL_METAL_DECODE_REPLAY_STATS");
}

static uint32_t ds4_gpu_decode_replay_cache_limit(void) {
    static uint32_t limit = 0;
    if (limit == 0) {
        limit = DS4_DECODE_REPLAY_CACHE_MAX;
        const char *env = getenv("DS4_FLASH_MOE_METAL_DECODE_REPLAY_CACHE_LIMIT");
        if (!env || !env[0]) {
            env = getenv("LLAMA_FLASH_MOE_EXPERIMENTAL_METAL_DECODE_REPLAY_CACHE_LIMIT");
        }
        if (env && env[0]) {
            char *end = NULL;
            unsigned long parsed = strtoul(env, &end, 10);
            if (end != env && parsed > 0) {
                limit = (uint32_t)parsed;
                if (limit > DS4_DECODE_REPLAY_CACHE_MAX) {
                    limit = DS4_DECODE_REPLAY_CACHE_MAX;
                }
            }
        }
    }
    return limit;
}

static int ds4_gpu_flash_moe_icb_replay_enabled(void) {
    static int enabled = -1;
    if (enabled < 0) {
        const char *env = getenv("DS4_FLASH_MOE_ICB_REPLAY");
        enabled = (env && env[0] && atoi(env) != 0) ? 1 : 0;
    }
    return enabled;
}

static int ds4_gpu_flash_moe_icb_stats_enabled(void) {
    return ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_ICB_REPLAY_STATS") ||
           ds4_gpu_decode_replay_stats_enabled();
}

static uint32_t ds4_gpu_flash_moe_icb_cache_limit(void) {
    static uint32_t limit = 0;
    if (limit == 0) {
        limit = DS4_FLASH_MOE_ICB_CACHE_MAX;
        const char *env = getenv("DS4_FLASH_MOE_ICB_REPLAY_CACHE_LIMIT");
        if (env && env[0]) {
            char *end = NULL;
            unsigned long parsed = strtoul(env, &end, 10);
            if (end != env && parsed > 0) {
                limit = (uint32_t)parsed;
                if (limit > DS4_FLASH_MOE_ICB_CACHE_MAX) {
                    limit = DS4_FLASH_MOE_ICB_CACHE_MAX;
                }
            }
        }
    }
    return limit;
}

static int ds4_gpu_flash_moe_icb_inherit_buffers(void) {
    static int inherit_buffers = -1;
    if (inherit_buffers < 0) {
        const int env = ds4_gpu_env_bool("DS4_FLASH_MOE_ICB_INHERIT_BUFFERS");
        inherit_buffers = env == 0 ? 0 : 1;
    }
    return inherit_buffers;
}

static int ds4_gpu_flash_moe_icb_fused_unit_enabled(void) {
    return ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_ICB_FUSED_UNIT");
}

static bool ds4_gpu_flash_moe_icb_supported(void) {
    if (!g_device) return false;
    if (@available(macOS 11.0, iOS 13.0, tvOS 14.0, *)) {
        return true;
    }
    return false;
}

static ds4_gpu_mul_mv_id_args ds4_gpu_decode_replay_canonical_args(
        const ds4_gpu_mul_mv_id_args *args) {
    ds4_gpu_mul_mv_id_args out;
    memset(&out, 0, sizeof(out));
    out.nei0 = args->nei0;
    out.nei1 = args->nei1;
    out.nbi1 = args->nbi1;
    out.ne00 = args->ne00;
    out.ne01 = args->ne01;
    out.ne02 = args->ne02;
    out.nb00 = args->nb00;
    out.nb01 = args->nb01;
    out.nb02 = args->nb02;
    out.ne10 = args->ne10;
    out.ne11 = args->ne11;
    out.ne12 = args->ne12;
    out.ne13 = args->ne13;
    out.nb10 = args->nb10;
    out.nb11 = args->nb11;
    out.nb12 = args->nb12;
    out.ne0 = args->ne0;
    out.ne1 = args->ne1;
    out.nb1 = args->nb1;
    out.nr0 = args->nr0;
    return out;
}

static ds4_gpu_dsv4_moe_swiglu_weight_args ds4_gpu_decode_replay_canonical_act(
        const ds4_gpu_dsv4_moe_swiglu_weight_args *act) {
    ds4_gpu_dsv4_moe_swiglu_weight_args out;
    memset(&out, 0, sizeof(out));
    if (act) {
        out.width = act->width;
        out.rows = act->rows;
        out.gate_row_stride = act->gate_row_stride;
        out.up_row_stride = act->up_row_stride;
        out.mid_row_stride = act->mid_row_stride;
        out.weight_stride = act->weight_stride;
        out.write_clamped = act->write_clamped;
        out.clamp_value = act->clamp_value;
    }
    return out;
}

static bool ds4_gpu_decode_replay_key_equal(
        const ds4_gpu_decode_replay_key *a,
        const ds4_gpu_decode_replay_key *b) {
    return memcmp(a, b, sizeof(*a)) == 0;
}

static void ds4_gpu_decode_replay_cache_clear(void) {
    for (uint32_t i = 0; i < DS4_DECODE_REPLAY_CACHE_MAX; i++) {
        g_decode_replay_cache[i].valid = false;
        g_decode_replay_cache[i].args_buf = nil;
        g_decode_replay_cache[i].act_buf = nil;
    }
    g_decode_replay_evict = 0;
}

static void ds4_gpu_flash_moe_icb_cache_clear(void) {
    for (uint32_t i = 0; i < DS4_FLASH_MOE_ICB_CACHE_MAX; i++) {
        ds4_gpu_flash_moe_icb_reset_entry(&g_flash_moe_icb_cache[i]);
    }
    memset(g_flash_moe_icb_slot_generation, 0, sizeof(g_flash_moe_icb_slot_generation));
    memset(g_flash_moe_icb_slot_index, 0, sizeof(g_flash_moe_icb_slot_index));
    g_flash_moe_icb_evict = 0;
}

void ds4_gpu_flash_moe_replay_caches_clear(void) {
    uint32_t live_decode = 0;
    uint32_t live_icb = 0;
    for (uint32_t i = 0; i < DS4_DECODE_REPLAY_CACHE_MAX; i++) {
        if (g_decode_replay_cache[i].valid) live_decode++;
    }
    for (uint32_t i = 0; i < DS4_FLASH_MOE_ICB_CACHE_MAX; i++) {
        if (g_flash_moe_icb_cache[i].valid) live_icb++;
    }
    ds4_gpu_decode_replay_cache_clear();
    ds4_gpu_flash_moe_icb_cache_clear();
    if ((live_decode || live_icb) &&
        ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_REPLAY_CACHE_CLEAR_TRACE") &&
        !ds4_gpu_backend_logs_suppressed()) {
        fprintf(stderr,
                "ds4: cleared Flash-MoE replay caches before slot-bank release "
                "(decode=%u icb=%u)\n",
                live_decode,
                live_icb);
    }
}

void ds4_gpu_flash_moe_icb_invalidate_slot(uint32_t layer_index, int32_t slot) {
    if (!ds4_gpu_flash_moe_icb_replay_enabled()) return;
    if (!ds4_gpu_flash_moe_icb_slot_key_valid(layer_index, slot)) return;
    uint32_t next = ++g_flash_moe_icb_slot_generation[layer_index][slot];
    if (next == 0) {
        next = ++g_flash_moe_icb_slot_generation[layer_index][slot];
    }
    (void)next;
    memset(g_flash_moe_icb_slot_index[layer_index][slot],
           0,
           sizeof(g_flash_moe_icb_slot_index[layer_index][slot]));
    g_flash_moe_icb_invalidations++;
}

static void ds4_gpu_decode_replay_print_stats(void) {
    if (!ds4_gpu_decode_replay_stats_enabled() ||
        ds4_gpu_backend_logs_suppressed()) {
        if (!ds4_gpu_flash_moe_icb_stats_enabled() ||
            ds4_gpu_backend_logs_suppressed()) {
            return;
        }
    }
    if (ds4_gpu_decode_replay_stats_enabled() &&
        !ds4_gpu_backend_logs_suppressed()) {
        uint32_t live = 0;
        for (uint32_t i = 0; i < DS4_DECODE_REPLAY_CACHE_MAX; i++) {
            if (g_decode_replay_cache[i].valid) live++;
        }
        const uint64_t total = g_decode_replay_hits + g_decode_replay_misses;
        const double hit_pct = total ? 100.0 * (double)g_decode_replay_hits / (double)total : 0.0;
        fprintf(stderr,
                "ds4: Metal decode-replay hits=%llu misses=%llu hit=%.1f%% inserts=%llu cache=%u/%u\n",
                (unsigned long long)g_decode_replay_hits,
                (unsigned long long)g_decode_replay_misses,
                hit_pct,
                (unsigned long long)g_decode_replay_inserts,
                live,
                ds4_gpu_decode_replay_cache_limit());
    }
    if (ds4_gpu_flash_moe_icb_stats_enabled() &&
        !ds4_gpu_backend_logs_suppressed()) {
        uint32_t live_icb = 0;
        for (uint32_t i = 0; i < DS4_FLASH_MOE_ICB_CACHE_MAX; i++) {
            if (g_flash_moe_icb_cache[i].valid) live_icb++;
        }
        const uint64_t total_icb = g_flash_moe_icb_hits + g_flash_moe_icb_misses;
        const double hit_pct_icb =
            total_icb ? 100.0 * (double)g_flash_moe_icb_hits / (double)total_icb : 0.0;
        fprintf(stderr,
                "ds4: Metal Flash-MoE ICB replay hits=%llu misses=%llu hit=%.1f%%"
                " builds=%llu execs=%llu failures=%llu invalidations=%llu cache=%u/%u\n",
                (unsigned long long)g_flash_moe_icb_hits,
                (unsigned long long)g_flash_moe_icb_misses,
                hit_pct_icb,
                (unsigned long long)g_flash_moe_icb_builds,
                (unsigned long long)g_flash_moe_icb_execs,
                (unsigned long long)g_flash_moe_icb_build_failures,
                (unsigned long long)g_flash_moe_icb_invalidations,
                live_icb,
                ds4_gpu_flash_moe_icb_cache_limit());
    }
}

static ds4_gpu_decode_replay_entry *ds4_gpu_decode_replay_lookup(
        ds4_gpu_decode_replay_kind kind,
        id<MTLComputePipelineState> pipeline,
        const ds4_gpu_mul_mv_id_args *args,
        const ds4_gpu_dsv4_moe_swiglu_weight_args *act,
        NSUInteger threadgroup_bytes,
        NSUInteger nsg,
        bool rows_per_group_is_nr0) {
    if (!ds4_gpu_decode_replay_enabled() || !g_device || !pipeline || !args ||
        args->ne01 <= 0 || args->nei0 <= 0 || args->nei1 <= 0 || args->nr0 <= 0 ||
        nsg == 0) {
        return NULL;
    }
    if (kind == DS4_DECODE_REPLAY_PAIR_SWIGLU && !act) {
        return NULL;
    }

    ds4_gpu_decode_replay_key key;
    memset(&key, 0, sizeof(key));
    key.kind = (uint32_t)kind;
    key.rows_per_group_is_nr0 = rows_per_group_is_nr0 ? 1u : 0u;
    key.pipeline = (uint64_t)(uintptr_t)(__bridge const void *)pipeline;
    key.threadgroup_bytes = (uint64_t)threadgroup_bytes;
    key.nsg = (uint64_t)nsg;
    key.args = ds4_gpu_decode_replay_canonical_args(args);
    key.act = ds4_gpu_decode_replay_canonical_act(act);

    const uint32_t limit = ds4_gpu_decode_replay_cache_limit();
    for (uint32_t i = 0; i < limit; i++) {
        ds4_gpu_decode_replay_entry *entry = &g_decode_replay_cache[i];
        if (entry->valid && ds4_gpu_decode_replay_key_equal(&entry->key, &key)) {
            g_decode_replay_hits++;
            return entry;
        }
    }

    g_decode_replay_misses++;
    uint32_t slot = UINT32_MAX;
    for (uint32_t i = 0; i < limit; i++) {
        if (!g_decode_replay_cache[i].valid) {
            slot = i;
            break;
        }
    }
    if (slot == UINT32_MAX) {
        slot = g_decode_replay_evict++ % limit;
    }

    ds4_gpu_decode_replay_entry *entry = &g_decode_replay_cache[slot];
    entry->valid = false;
    entry->args_buf = nil;
    entry->act_buf = nil;
    entry->key = key;
    entry->args_buf = [g_device newBufferWithBytes:&entry->key.args
                                            length:sizeof(entry->key.args)
                                           options:MTLResourceStorageModeShared];
    if (kind == DS4_DECODE_REPLAY_PAIR_SWIGLU) {
        entry->act_buf = [g_device newBufferWithBytes:&entry->key.act
                                               length:sizeof(entry->key.act)
                                              options:MTLResourceStorageModeShared];
    }
    if (!entry->args_buf || (kind == DS4_DECODE_REPLAY_PAIR_SWIGLU && !entry->act_buf)) {
        entry->args_buf = nil;
        entry->act_buf = nil;
        return NULL;
    }

    const NSUInteger nr0 = (NSUInteger)args->nr0;
    const NSUInteger rows_per_group = rows_per_group_is_nr0 ? nr0 : nr0 * nsg;
    if (rows_per_group == 0) return NULL;
    const NSUInteger row_groups = ((NSUInteger)args->ne01 + rows_per_group - 1u) / rows_per_group;
    if (kind == DS4_DECODE_REPLAY_SUM6) {
        entry->grid = MTLSizeMake(row_groups, (NSUInteger)args->nei1, 1);
    } else {
        const NSUInteger pairs = (NSUInteger)args->nei0 * (NSUInteger)args->nei1;
        entry->grid = MTLSizeMake(row_groups, 1, pairs);
    }
    entry->threads = MTLSizeMake(32, nsg, 1);
    entry->valid = true;
    g_decode_replay_inserts++;
    return entry;
}

/* Compile the single in-repo Metal source and create the pipelines that every
 * session uses. Shape-dependent kernels with function constants are built
 * lazily by the small ds4_gpu_get_* caches, so startup stays predictable
 * while long-context prefill and decode can still pick specialized variants. */
int ds4_gpu_init(void) {
    if (g_initialized) return 1;

    @autoreleasepool {
        g_device = MTLCreateSystemDefaultDevice();
        if (!g_device) {
            fprintf(stderr, "ds4: Metal device not available\n");
            return 0;
        }
        ds4_gpu_print_device_summary();

        g_queue = [g_device newCommandQueue];
        g_ane_producer_queue = [g_device newCommandQueue];
        if (!g_queue || !g_ane_producer_queue) {
            fprintf(stderr, "ds4: failed to create Metal command queue\n");
            g_ane_producer_queue = nil;
            g_device = nil;
            return 0;
        }
        g_model_buffer_cache = [NSMutableDictionary dictionary];
        g_resident_model_exact_cache = [NSMutableDictionary dictionary];
        g_resident_model_ranges = [NSMutableArray array];
        g_pipeline_cache = [NSMutableDictionary dictionary];
        g_transient_buffers = [NSMutableArray array];
        g_pending_cbs = [NSMutableArray array];
        if (!g_model_buffer_cache || !g_resident_model_exact_cache ||
            !g_resident_model_ranges || !g_pipeline_cache ||
            !g_transient_buffers || !g_pending_cbs) {
            fprintf(stderr, "ds4: Metal bookkeeping allocation failed\n");
            g_pending_cbs = nil;
            g_transient_buffers = nil;
            g_pipeline_cache = nil;
            g_resident_model_ranges = nil;
            g_resident_model_exact_cache = nil;
            g_model_buffer_cache = nil;
            g_queue = nil;
            g_device = nil;
            return 0;
        }

        NSError *error = nil;
        NSString *source = ds4_gpu_full_source();
        if (!source) {
            g_queue = nil;
            g_device = nil;
            return 0;
        }
        MTLCompileOptions *options = [MTLCompileOptions new];
        NSMutableDictionary *macros = [NSMutableDictionary new];

        const int drift_hc_stable        = ds4_gpu_env_bool("DS4_METAL_HC_STABLE")          != 0; // default ON
        const int drift_norm_unify       = ds4_gpu_env_bool("DS4_METAL_NORM_RSQRT_DISABLE") != 0; // default ON
        const int drift_kv_raw_f32       = ds4_gpu_env_bool("DS4_METAL_KV_RAW_F32")         >  0; // default OFF
        const int drift_rope_exp2_log2   = ds4_gpu_env_bool("DS4_METAL_ROPE_EXP2_LOG2")     >  0; // default OFF
        const int drift_math_safe        = ds4_gpu_env_bool("DS4_METAL_MATH_SAFE")          >  0; // default OFF

        if (drift_math_safe) {
            // Diagnostic-only: useful to localize drift sources, but not a
            // shipping default because strict math can cost throughput.
            if (@available(macOS 15.0, *)) {
                options.mathMode = MTLMathModeSafe;
                fprintf(stderr, "ds4: Metal shader library math mode = safe (strict IEEE-754) by DS4_METAL_MATH_SAFE\n");
            } else {
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wdeprecated-declarations"
                options.fastMathEnabled = NO;
#pragma clang diagnostic pop
                fprintf(stderr, "ds4: Metal shader library fast-math disabled by DS4_METAL_MATH_SAFE (pre-macOS 15)\n");
            }
        }

        if (drift_hc_stable)      macros[@"DS4_METAL_HC_STABLE"]          = @"1";
        if (drift_norm_unify)     macros[@"DS4_METAL_NORM_RSQRT_DISABLE"] = @"1";
        if (drift_kv_raw_f32)     macros[@"DS4_METAL_KV_RAW_F32"]         = @"1";
        if (drift_rope_exp2_log2) macros[@"DS4_METAL_ROPE_EXP2_LOG2"]     = @"1";
        fprintf(stderr,
                "ds4: drift-patch flags hc_stable=%s norm_unify=%s kv_raw_f32=%s rope_exp2_log2=%s math_safe=%s tensor_matmul=off\n",
                drift_hc_stable      ? "on"  : "off",
                drift_norm_unify     ? "on"  : "off",
                drift_kv_raw_f32     ? "on"  : "off",
                drift_rope_exp2_log2 ? "on"  : "off",
                drift_math_safe      ? "on"  : "off");
        options.preprocessorMacros = macros;
        id<MTLLibrary> library = [g_device newLibraryWithSource:source options:options error:&error];
        if (!library) {
            fprintf(stderr, "ds4: Metal shader compilation failed: %s\n",
                    [[error localizedDescription] UTF8String]);
            g_queue = nil;
            g_device = nil;
            return 0;
        }
        g_library = library;

        id<MTLFunction> fn = [library newFunctionWithName:@"kernel_get_rows_f32"];
        if (!fn) {
            fprintf(stderr, "ds4: Metal kernel_get_rows_f32 function not found\n");
            g_queue = nil;
            g_device = nil;
            return 0;
        }

        g_get_rows_f32_pipeline = [g_device newComputePipelineStateWithFunction:fn error:&error];
        if (!g_get_rows_f32_pipeline) {
            fprintf(stderr, "ds4: Metal kernel_get_rows_f32 pipeline failed: %s\n",
                    [[error localizedDescription] UTF8String]);
            g_queue = nil;
            g_device = nil;
            return 0;
        }

        fn = [library newFunctionWithName:@"kernel_get_rows_f16"];
        if (!fn) {
            fprintf(stderr, "ds4: Metal kernel_get_rows_f16 function not found\n");
            g_queue = nil;
            g_device = nil;
            return 0;
        }

        g_get_rows_f16_pipeline = [g_device newComputePipelineStateWithFunction:fn error:&error];
        if (!g_get_rows_f16_pipeline) {
            fprintf(stderr, "ds4: Metal kernel_get_rows_f16 pipeline failed: %s\n",
                    [[error localizedDescription] UTF8String]);
            g_queue = nil;
            g_device = nil;
            return 0;
        }

        fn = [library newFunctionWithName:@"kernel_get_rows_i32"];
        if (!fn) {
            fprintf(stderr, "ds4: Metal kernel_get_rows_i32 function not found\n");
            g_queue = nil;
            g_device = nil;
            return 0;
        }

        g_get_rows_i32_pipeline = [g_device newComputePipelineStateWithFunction:fn error:&error];
        if (!g_get_rows_i32_pipeline) {
            fprintf(stderr, "ds4: Metal kernel_get_rows_i32 pipeline failed: %s\n",
                    [[error localizedDescription] UTF8String]);
            g_queue = nil;
            g_device = nil;
            return 0;
        }

        fn = [library newFunctionWithName:@"kernel_repeat_f32"];
        if (!fn) {
            fprintf(stderr, "ds4: Metal kernel_repeat_f32 function not found\n");
            g_queue = nil;
            g_device = nil;
            return 0;
        }

        g_repeat_f32_pipeline = [g_device newComputePipelineStateWithFunction:fn error:&error];
        if (!g_repeat_f32_pipeline) {
            fprintf(stderr, "ds4: Metal kernel_repeat_f32 pipeline failed: %s\n",
                    [[error localizedDescription] UTF8String]);
            g_queue = nil;
            g_device = nil;
            return 0;
        }

        fn = [library newFunctionWithName:@"kernel_set_rows_f32_i32"];
        if (!fn) {
            fprintf(stderr, "ds4: Metal kernel_set_rows_f32_i32 function not found\n");
            g_queue = nil;
            g_device = nil;
            return 0;
        }

        g_set_rows_f32_i32_pipeline = [g_device newComputePipelineStateWithFunction:fn error:&error];
        if (!g_set_rows_f32_i32_pipeline) {
            fprintf(stderr, "ds4: Metal kernel_set_rows_f32_i32 pipeline failed: %s\n",
                    [[error localizedDescription] UTF8String]);
            g_queue = nil;
            g_device = nil;
            return 0;
        }

