static ds4_gpu_tensor *ds4_gpu_tensor_alloc_with_options(uint64_t bytes, MTLResourceOptions options) {
    if (!g_initialized && !ds4_gpu_init()) return NULL;
    if (bytes == 0 || bytes > (uint64_t)NSUIntegerMax) return NULL;

    @autoreleasepool {
        DS4MetalTensor *tensor = [DS4MetalTensor new];
        tensor.buffer = [g_device newBufferWithLength:(NSUInteger)bytes
                                              options:options];
        if (!tensor.buffer) {
            return NULL;
        }
        tensor.offset = 0;
        tensor.bytes = bytes;
        tensor.owner = 1;
        g_tensor_alloc_live_bytes += bytes;
        if (g_tensor_alloc_live_bytes > g_tensor_alloc_peak_bytes) {
            g_tensor_alloc_peak_bytes = g_tensor_alloc_live_bytes;
        }
        if (ds4_gpu_trace_allocs()) {
            fprintf(stderr,
                    "ds4: Metal tensor alloc %.3f MiB live %.3f MiB peak %.3f MiB\n",
                    (double)bytes / (1024.0 * 1024.0),
                    (double)g_tensor_alloc_live_bytes / (1024.0 * 1024.0),
                    (double)g_tensor_alloc_peak_bytes / (1024.0 * 1024.0));
        }
        return (__bridge_retained ds4_gpu_tensor *)tensor;
    }
}

ds4_gpu_tensor *ds4_gpu_tensor_alloc(uint64_t bytes) {
    return ds4_gpu_tensor_alloc_with_options(bytes, MTLResourceStorageModeShared);
}

ds4_gpu_tensor *ds4_gpu_tensor_alloc_untracked(uint64_t bytes) {
    return ds4_gpu_tensor_alloc_with_options(
            bytes,
            MTLResourceStorageModeShared | MTLResourceHazardTrackingModeUntracked);
}

ds4_gpu_tensor *ds4_gpu_flash_moe_record_table_alloc(uint32_t n_slots) {
    if (!g_initialized && !ds4_gpu_init()) return NULL;
    if (!g_moe_mxfp4_record_table_arg_encoder || n_slots == 0 || n_slots > 256u) {
        return NULL;
    }
    const NSUInteger bytes = [g_moe_mxfp4_record_table_arg_encoder encodedLength];
    if (bytes == 0) return NULL;

    @autoreleasepool {
        DS4MetalTensor *tensor = [DS4MetalTensor new];
        tensor.buffer = [g_device newBufferWithLength:bytes
                                              options:MTLResourceStorageModeShared];
        if (!tensor.buffer) return NULL;
        tensor.offset = 0;
        tensor.bytes = (uint64_t)bytes;
        tensor.owner = 1;
        g_tensor_alloc_live_bytes += (uint64_t)bytes;
        if (g_tensor_alloc_live_bytes > g_tensor_alloc_peak_bytes) {
            g_tensor_alloc_peak_bytes = g_tensor_alloc_live_bytes;
        }
        return (__bridge_retained ds4_gpu_tensor *)tensor;
    }
}

int ds4_gpu_flash_moe_record_table_set(
        ds4_gpu_tensor  *table,
        ds4_gpu_tensor **slot_records,
        uint32_t         n_slots) {
    if (!table || !slot_records || n_slots == 0 || n_slots > 256u ||
        !g_moe_mxfp4_record_table_arg_encoder) {
        return 0;
    }
    id<MTLBuffer> table_buf = ds4_gpu_tensor_buffer(table);
    if (!table_buf) return 0;

    @autoreleasepool {
        [g_moe_mxfp4_record_table_arg_encoder setArgumentBuffer:table_buf
                                                         offset:(NSUInteger)ds4_gpu_tensor_offset(table)];
        for (uint32_t slot = 0; slot < n_slots; slot++) {
            ds4_gpu_tensor *record = slot_records[slot];
            id<MTLBuffer> record_buf = ds4_gpu_tensor_buffer(record);
            if (!record_buf) return 0;
            [g_moe_mxfp4_record_table_arg_encoder setBuffer:record_buf
                                                     offset:(NSUInteger)ds4_gpu_tensor_offset(record)
                                                    atIndex:(NSUInteger)slot];
        }
    }
    return 1;
}

ds4_gpu_tensor *ds4_gpu_tensor_alloc_managed(uint64_t bytes) {
    return ds4_gpu_tensor_alloc(bytes);
}

int ds4_gpu_should_use_managed_kv_cache(uint64_t kv_cache_bytes, uint64_t context_bytes) {
    (void)kv_cache_bytes;
    (void)context_bytes;
    return 0;
}

ds4_gpu_tensor *ds4_gpu_tensor_view(const ds4_gpu_tensor *base, uint64_t offset, uint64_t bytes) {
    if (!base) return NULL;
    const DS4MetalTensor *base_obj = ds4_gpu_tensor_const_obj(base);
    if (offset > base_obj.bytes || bytes > base_obj.bytes - offset) return NULL;
    if (base_obj.offset > UINT64_MAX - offset) return NULL;
    const uint64_t absolute_offset = base_obj.offset + offset;
    if (absolute_offset > (uint64_t)NSUIntegerMax) return NULL;

    @autoreleasepool {
        DS4MetalTensor *view = [DS4MetalTensor new];
        view.buffer = base_obj.buffer;
        view.offset = absolute_offset;
        view.bytes = bytes;
        view.owner = 0;
        view.mxfp4_plane_split = base_obj.mxfp4_plane_split;
        return (__bridge_retained ds4_gpu_tensor *)view;
    }
}

ds4_gpu_tensor *ds4_gpu_model_tensor_view(const void *model_map,
                                          uint64_t    model_size,
                                          uint64_t    offset,
                                          uint64_t    bytes) {
    if (!g_initialized && !ds4_gpu_init()) return NULL;
    if (bytes == 0) return NULL;

    uint64_t inner_offset = 0;
    id<MTLBuffer> buffer = ds4_gpu_wrap_model_range(model_map,
                                                    model_size,
                                                    offset,
                                                    bytes,
                                                    &inner_offset);
    if (!buffer || inner_offset > (uint64_t)NSUIntegerMax) return NULL;

    @autoreleasepool {
        DS4MetalTensor *view = [DS4MetalTensor new];
        view.buffer = buffer;
        view.offset = inner_offset;
        view.bytes = bytes;
        view.owner = 0;
        return (__bridge_retained ds4_gpu_tensor *)view;
    }
}

ds4_gpu_tensor *ds4_gpu_mmap_tensor_view(const void *map,
                                         uint64_t    map_size,
                                         uint64_t    offset,
                                         uint64_t    bytes) {
    if (!g_initialized && !ds4_gpu_init()) return NULL;
    if (!map || bytes == 0 || offset > map_size || bytes > map_size - offset) {
        return NULL;
    }

    const long page_long = sysconf(_SC_PAGESIZE);
    const uint64_t page = page_long > 0 ? (uint64_t)page_long : 16384u;
    const uint64_t page_offset = offset & ~(page - 1u);
    const uint64_t leading = offset - page_offset;
    if (leading > UINT64_MAX - bytes) return NULL;
    const uint64_t wrap_bytes = leading + bytes;
    if (page_offset > map_size || wrap_bytes > map_size - page_offset) {
        return NULL;
    }
    if (page_offset > (uint64_t)UINTPTR_MAX ||
        leading > (uint64_t)NSUIntegerMax ||
        wrap_bytes > (uint64_t)NSUIntegerMax) {
        return NULL;
    }

    const uint64_t max_buffer = (uint64_t)[g_device maxBufferLength];
    if (max_buffer != 0 && wrap_bytes > max_buffer) {
        fprintf(stderr,
                "ds4: Metal mmap tensor %.2f MiB exceeds maxBufferLength %.2f MiB\n",
                wrap_bytes / 1024.0 / 1024.0,
                max_buffer / 1024.0 / 1024.0);
        return NULL;
    }

    const uintptr_t addr = (uintptr_t)map;
    if (page_offset > (uint64_t)(UINTPTR_MAX - addr)) return NULL;

    @autoreleasepool {
        DS4MetalTensor *view = [DS4MetalTensor new];
        view.buffer = [g_device newBufferWithBytesNoCopy:(void *)(addr + (uintptr_t)page_offset)
                                                  length:(NSUInteger)wrap_bytes
                                                 options:MTLResourceStorageModeShared
                                             deallocator:nil];
        if (!view.buffer) {
            fprintf(stderr,
                    "ds4: Metal could not wrap mmap tensor range %.2f..%.2f GiB\n",
                    offset / 1073741824.0,
                    (offset + bytes) / 1073741824.0);
            return NULL;
        }
        view.buffer.label = @"ds4_mmap_view";
        view.offset = leading;
        view.bytes = bytes;
        view.owner = 0;
        return (__bridge_retained ds4_gpu_tensor *)view;
    }
}

void ds4_gpu_tensor_free(ds4_gpu_tensor *tensor) {
    if (!tensor) return;
    @autoreleasepool {
        DS4MetalTensor *obj = (__bridge_transfer DS4MetalTensor *)tensor;
        if (obj.owner) {
            if (obj.bytes <= g_tensor_alloc_live_bytes) {
                g_tensor_alloc_live_bytes -= obj.bytes;
            } else {
                g_tensor_alloc_live_bytes = 0;
            }
            if (ds4_gpu_trace_allocs()) {
                fprintf(stderr,
                        "ds4: Metal tensor free %.3f MiB live %.3f MiB peak %.3f MiB\n",
                        (double)obj.bytes / (1024.0 * 1024.0),
                        (double)g_tensor_alloc_live_bytes / (1024.0 * 1024.0),
                        (double)g_tensor_alloc_peak_bytes / (1024.0 * 1024.0));
            }
        }
        obj.buffer = nil;
        obj.offset = 0;
        obj.bytes = 0;
        obj.owner = 0;
        obj.mxfp4_plane_split = 0;
    }
}

int ds4_gpu_tensor_make_purgeable_empty(ds4_gpu_tensor *tensor) {
    if (!tensor) return 0;
    @autoreleasepool {
        DS4MetalTensor *obj = ds4_gpu_tensor_obj(tensor);
        if (!obj || !obj.owner || !obj.buffer) return 0;
        [obj.buffer setPurgeableState:MTLPurgeableStateEmpty];
        return 1;
    }
}

uint64_t ds4_gpu_tensor_bytes(const ds4_gpu_tensor *tensor) {
    if (!tensor) return 0;
    const DS4MetalTensor *obj = ds4_gpu_tensor_const_obj(tensor);
    return obj.bytes;
}

void ds4_gpu_tensor_set_mxfp4_plane_split(ds4_gpu_tensor *tensor, int enabled) {
    if (!tensor) return;
    DS4MetalTensor *obj = ds4_gpu_tensor_obj(tensor);
    obj.mxfp4_plane_split = enabled ? 1u : 0u;
}

int ds4_gpu_tensor_mxfp4_plane_split(const ds4_gpu_tensor *tensor) {
    if (!tensor) return 0;
    const DS4MetalTensor *obj = ds4_gpu_tensor_const_obj(tensor);
    return obj.mxfp4_plane_split != 0;
}

void *ds4_gpu_tensor_contents(ds4_gpu_tensor *tensor) {
    if (!tensor) return NULL;
    DS4MetalTensor *obj = ds4_gpu_tensor_obj(tensor);
    return (uint8_t *)[obj.buffer contents] + obj.offset;
}

int ds4_gpu_tensor_touch_pages(ds4_gpu_tensor *tensor, uint64_t page_bytes) {
    if (!tensor) return 0;
    const uint64_t bytes = ds4_gpu_tensor_bytes(tensor);
    if (bytes == 0) return 1;
    if (page_bytes == 0) {
        const long sys_page = sysconf(_SC_PAGESIZE);
        page_bytes = sys_page > 0 ? (uint64_t)sys_page : 16384u;
    }
    if (page_bytes == 0) return 0;
    volatile uint8_t *p = (volatile uint8_t *)ds4_gpu_tensor_contents(tensor);
    if (!p) return 0;
    for (uint64_t off = 0; off < bytes; off += page_bytes) {
        p[off] = p[off];
    }
    p[bytes - 1u] = p[bytes - 1u];
    return 1;
}

int ds4_gpu_tensor_fill_f32(ds4_gpu_tensor *tensor, float value, uint64_t count) {
    if (!tensor || count > ds4_gpu_tensor_bytes(tensor) / sizeof(float)) return 0;
    float *p = ds4_gpu_tensor_contents(tensor);
    if (!p && count != 0) return 0;
    for (uint64_t i = 0; i < count; i++) p[i] = value;
    if (count != 0 && !ds4_gpu_tensor_did_modify(tensor, 0, count * sizeof(float))) return 0;
    return 1;
}

static int ds4_gpu_tensor_did_modify_enabled(void) {
    const char *env = getenv("DS4_FLASH_MOE_DID_MODIFY_RANGE");
    return env == NULL || env[0] == '\0' || atoi(env) != 0;
}

static int ds4_gpu_mtl_buffer_did_modify(id<MTLBuffer> buffer, NSUInteger offset, NSUInteger bytes) {
    if (!buffer) return 0;
    if (bytes == 0) return 1;
    if (!ds4_gpu_tensor_did_modify_enabled()) return 1;
    if (offset > buffer.length || bytes > buffer.length - offset) return 0;
    @autoreleasepool {
        [buffer didModifyRange:NSMakeRange(offset, bytes)];
    }
    return 1;
}

int ds4_gpu_tensor_did_modify(ds4_gpu_tensor *tensor, uint64_t offset, uint64_t bytes) {
    if (!tensor) return 0;
    DS4MetalTensor *obj = ds4_gpu_tensor_obj(tensor);
    if (offset > obj.bytes || bytes > obj.bytes - offset) return 0;
    if (bytes == 0) return 1;
    if (!ds4_gpu_tensor_did_modify_enabled()) return 1;
    if (obj.offset > (uint64_t)NSUIntegerMax || offset > (uint64_t)NSUIntegerMax - obj.offset ||
        bytes > (uint64_t)NSUIntegerMax) {
        return 0;
    }
    const uint64_t absolute_offset = obj.offset + offset;
    @autoreleasepool {
        [obj.buffer didModifyRange:NSMakeRange((NSUInteger)absolute_offset, (NSUInteger)bytes)];
    }
    return 1;
}

int ds4_gpu_tensor_write(ds4_gpu_tensor *tensor, uint64_t offset, const void *data, uint64_t bytes) {
    if (!tensor || (!data && bytes != 0)) return 0;
    DS4MetalTensor *obj = ds4_gpu_tensor_obj(tensor);
    if (offset > obj.bytes || bytes > obj.bytes - offset) return 0;
    if (bytes != 0) {
        memcpy((uint8_t *)[obj.buffer contents] + obj.offset + offset, data, (size_t)bytes);
        return ds4_gpu_tensor_did_modify(tensor, offset, bytes);
    }
    return 1;
}

int ds4_gpu_tensor_read(const ds4_gpu_tensor *tensor, uint64_t offset, void *data, uint64_t bytes) {
    if (!tensor || (!data && bytes != 0)) return 0;
    const DS4MetalTensor *obj = ds4_gpu_tensor_const_obj(tensor);
    if (offset > obj.bytes || bytes > obj.bytes - offset) return 0;
    if (bytes != 0) {
        memcpy(data, (const uint8_t *)[obj.buffer contents] + obj.offset + offset, (size_t)bytes);
    }
    return 1;
}

int ds4_gpu_tensor_copy(ds4_gpu_tensor *dst, uint64_t dst_offset,
                          const ds4_gpu_tensor *src, uint64_t src_offset,
                          uint64_t bytes) {
    if (!dst || !src) return 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    DS4MetalTensor *d = ds4_gpu_tensor_obj(dst);
    const DS4MetalTensor *s = ds4_gpu_tensor_const_obj(src);
    if (dst_offset > d.bytes || bytes > d.bytes - dst_offset) return 0;
    if (src_offset > s.bytes || bytes > s.bytes - src_offset) return 0;
    if (bytes == 0) return 1;
    if (!g_batch_cb) return 0;

    ds4_gpu_close_batch_encoder();
    id<MTLBlitCommandEncoder> blit = [g_batch_cb blitCommandEncoder];
    if (!blit) return 0;
    [blit copyFromBuffer:s.buffer
            sourceOffset:(NSUInteger)(s.offset + src_offset)
                toBuffer:d.buffer
       destinationOffset:(NSUInteger)(d.offset + dst_offset)
                    size:(NSUInteger)bytes];
    [blit endEncoding];
    return 1;
}

int ds4_gpu_gather_rows_f32_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *src,
        const ds4_gpu_tensor *rows,
        uint32_t                n_rows,
        uint32_t                width) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !src || !rows || n_rows == 0 || width == 0) return 0;

    @autoreleasepool {
        id<MTLBuffer> srcbuf = ds4_gpu_tensor_buffer(src);
        id<MTLBuffer> rowsbuf = ds4_gpu_tensor_buffer(rows);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t row_bytes = (uint64_t)width * sizeof(float);
        if (!srcbuf || !rowsbuf || !outbuf ||
            ds4_gpu_tensor_bytes(rows) < (uint64_t)n_rows * sizeof(int32_t) ||
            ds4_gpu_tensor_bytes(out) < (uint64_t)n_rows * row_bytes) {
            return 0;
        }

        ds4_gpu_get_rows_args args = {
            .ne00t = (int32_t)width,
            .ne00 = (int32_t)width,
            .nb01 = row_bytes,
            .nb02 = ds4_gpu_tensor_bytes(src),
            .nb03 = ds4_gpu_tensor_bytes(src),
            .ne10 = (int32_t)n_rows,
            .nb10 = sizeof(int32_t),
            .nb11 = (uint64_t)n_rows * sizeof(int32_t),
            .nb12 = (uint64_t)n_rows * sizeof(int32_t),
            .nb1 = row_bytes,
            .nb2 = (uint64_t)n_rows * row_bytes,
            .nb3 = (uint64_t)n_rows * row_bytes,
        };

        NSUInteger nth = width;
        const NSUInteger max_threads = g_get_rows_f32_pipeline.maxTotalThreadsPerThreadgroup;
        if (nth > max_threads) nth = max_threads;
        if (nth == 0) nth = 1;
        const NSUInteger nw0 = ((NSUInteger)width + nth - 1u) / nth;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_get_rows_f32_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:srcbuf offset:ds4_gpu_tensor_offset(src) atIndex:1];
        [enc setBuffer:rowsbuf offset:ds4_gpu_tensor_offset(rows) atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [enc dispatchThreadgroups:MTLSizeMake(nw0 * n_rows, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(cb, owned, "gather rows f32");
    }
}

int ds4_gpu_scatter_add_rows_f32_tensor(
        ds4_gpu_tensor       *dst,
        const ds4_gpu_tensor *src,
        const ds4_gpu_tensor *rows,
        uint32_t                n_rows,
        uint32_t                width) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!dst || !src || !rows || n_rows == 0 || width == 0) return 0;

    typedef struct {
        uint32_t width;
        uint32_t rows;
        uint64_t src_row_stride;
        uint64_t dst_row_stride;
    } ds4_gpu_scatter_add_rows_args;

    @autoreleasepool {
        id<MTLBuffer> dstbuf = ds4_gpu_tensor_buffer(dst);
        id<MTLBuffer> srcbuf = ds4_gpu_tensor_buffer(src);
        id<MTLBuffer> rowsbuf = ds4_gpu_tensor_buffer(rows);
        id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_pipeline("kernel_dsv4_scatter_add_rows_f32");
        const uint64_t row_bytes = (uint64_t)width * sizeof(float);
        if (!dstbuf || !srcbuf || !rowsbuf || !pipeline ||
            ds4_gpu_tensor_bytes(src) < (uint64_t)n_rows * row_bytes ||
            ds4_gpu_tensor_bytes(rows) < (uint64_t)n_rows * sizeof(int32_t)) {
            return 0;
        }

        ds4_gpu_scatter_add_rows_args args = {
            .width = width,
            .rows = n_rows,
            .src_row_stride = row_bytes,
            .dst_row_stride = row_bytes,
        };

        NSUInteger nth = pipeline.maxTotalThreadsPerThreadgroup;
        if (nth > 256u) nth = 256u;
        if (nth > width) nth = width;
        if (nth == 0) nth = 1u;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:srcbuf offset:ds4_gpu_tensor_offset(src) atIndex:1];
        [enc setBuffer:rowsbuf offset:ds4_gpu_tensor_offset(rows) atIndex:2];
        [enc setBuffer:dstbuf offset:ds4_gpu_tensor_offset(dst) atIndex:3];
        [enc dispatchThreadgroups:MTLSizeMake(n_rows, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(cb, owned, "scatter-add rows f32");
    }
}

/* iter-4 ANE+NAX hybrid: side-channel mask of experts ANE has already handled
 * (so the per-expert GPU loop in routed_moe_batch_tensor can skip them). */
static uint8_t g_ane_skip_mask[DS4_METAL_N_EXPERT];
static int     g_ane_skip_mask_active = 0;
void ds4_gpu_set_ane_skip_mask(const uint8_t *mask, uint32_t n_experts) {
    if (!mask || n_experts == 0 || n_experts > DS4_METAL_N_EXPERT) { g_ane_skip_mask_active = 0; return; }
    memset(g_ane_skip_mask, 0, sizeof(g_ane_skip_mask));
    memcpy(g_ane_skip_mask, mask, n_experts);
    g_ane_skip_mask_active = 1;
}
void ds4_gpu_clear_ane_skip_mask(void) {
    memset(g_ane_skip_mask, 0, sizeof(g_ane_skip_mask));
    g_ane_skip_mask_active = 0;
}

int ds4_gpu_begin_commands(void) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (g_batch_cb) return 0;
    g_batch_cb = [g_queue commandBuffer];
    return g_batch_cb != nil;
}

int ds4_gpu_flush_commands(void) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!g_batch_cb) return 0;
    g_fz_flush++;

    ds4_gpu_close_batch_encoder();
    id<MTLCommandBuffer> cb = g_batch_cb;
    g_batch_cb = nil;
    [cb commit];
    [g_pending_cbs addObject:cb];

    g_batch_cb = [g_queue commandBuffer];
    if (!g_batch_cb) {
        (void)ds4_gpu_wait_pending_command_buffers("command batch");
        ds4_gpu_transient_resources_clear();
        return 0;
    }
    return 1;
}

int ds4_gpu_flush_commands_blocking(void) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!g_batch_cb) return 0;
    g_fz_flush++;

    /*
     * Like ds4_gpu_flush_commands(), but drains the just-committed work before
     * opening the next command buffer. This caps the in-flight depth to one
     * command buffer, which bounds the resources the driver must keep wired at
     * once. For a model whose weights are a large fraction of RAM that keeps the
     * forced-resident set to the layers in a single split instead of the whole
     * decode tape, leaving the rest of the model as evictable-but-present cache.
     * The cost is lost CPU/GPU overlap across the split boundary, so it is only
     * used when explicitly requested (DS4_METAL_DECODE_FLUSH_EVERY).
     */
    ds4_gpu_close_batch_encoder();
    id<MTLCommandBuffer> cb = g_batch_cb;
    g_batch_cb = nil;
    [cb commit];
    [g_pending_cbs addObject:cb];
    int ok = ds4_gpu_wait_pending_command_buffers("command batch");
    ds4_gpu_transient_resources_clear();

    g_batch_cb = [g_queue commandBuffer];
    if (!g_batch_cb) return 0;
    return ok;
}

int ds4_gpu_end_commands(void) {
    if (!g_batch_cb) return 0;
    ds4_gpu_close_batch_encoder();
    id<MTLCommandBuffer> cb = g_batch_cb;
    g_batch_cb = nil;
    int r = ds4_gpu_finish_command_buffer(cb, 1, "command batch");
    /* per-token/chunk fusion-boundary dump (env DS4_METAL_FUSION_PROFILE). The 1 owned_commit
     * + 1 wait here are the legitimate end sync; >1 means extra mid-graph syncs (the waste). */
    ds4_gpu_fusion_profile_dump("batch");
    return r;
}

int ds4_gpu_synchronize(void) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (g_batch_cb) return ds4_gpu_end_commands();  /* end_commands dumps "batch" */
    ds4_gpu_fusion_profile_dump("sync");
    if ([g_pending_cbs count] != 0) {
        int ok = ds4_gpu_wait_pending_command_buffers("synchronize");
        ds4_gpu_transient_resources_clear();
        return ok;
    }

    id<MTLCommandBuffer> cb = [g_queue commandBuffer];
    if (!cb) return 0;
    return ds4_gpu_finish_command_buffer(cb, 1, "synchronize");
}

void ds4_gpu_cleanup(void) {
    if (!g_initialized) return;

    @autoreleasepool {
        ds4_gpu_print_ane_prefill_stats();
        ds4_gpu_decode_replay_print_stats();
        if (g_batch_cb) {
            ds4_gpu_close_batch_encoder();
            [g_batch_cb commit];
            [g_batch_cb waitUntilCompleted];
            g_batch_cb = nil;
        }
        (void)ds4_gpu_wait_pending_command_buffers("cleanup");
        ds4_gpu_transient_resources_clear();
        ds4_gpu_decode_replay_cache_clear();
        ds4_gpu_flash_moe_icb_cache_clear();
        g_set_rows_f32_i32_pipeline = nil;
        g_get_rows_f32_pipeline = nil;
