        if (!ds4_gpu_encode_cpy_f32_f16_1d(cb,
                                             compbuf,
                                             ds4_gpu_tensor_offset(comp_kv),
                                             g_flash_attn_kv_buffer,
                                             (NSUInteger)n_tokens * row_bytes_f16,
                                             n_comp * head_dim)) {
