/* Wide-token MoE prefill tiles (ported from antirez/ds4 PR #264). NR1=32 is the
 * legacy/decode tile; 64/128/256 amortize per-threadgroup dequant+setup overhead on
 * aligned prefill batches. Only q2_K/q4_K/iq2_xxs have wide kernels. The encode
 * grid-X must match the selected kernel's NR1 exactly (see _mapped_tile). */
static uint32_t ds4_gpu_moe_mm_tile_n(uint32_t gate_type, uint32_t n_tokens) {
    const uint32_t tile_max = ds4_gpu_env_u32_default("DS4_METAL_MOE_TILE_MAX", 32u);
    if (tile_max <= 32u) {
        return 32u;
    }
    if (gate_type == DS4_METAL_TENSOR_Q4_K ||
        gate_type == DS4_METAL_TENSOR_Q2_K ||
        gate_type == DS4_METAL_TENSOR_IQ2_XXS ||
        gate_type == DS4_METAL_TENSOR_MXFP4) {
        if (tile_max >= 256u && n_tokens >= 256u && (n_tokens % 256u) == 0u) {
            return 256u;
        }
        if (tile_max >= 128u && n_tokens >= 128u && (n_tokens % 128u) == 0u) {
            return 128u;
        }
        if (tile_max >= 64u && n_tokens >= 64u && (n_tokens % 64u) == 0u) {
            return 64u;
        }
    }
    return 32u;
}

static uint32_t ds4_gpu_moe_mm_min_refs(uint32_t gate_type, uint32_t down_type) {
    uint32_t fallback = 32u;
    if (gate_type == DS4_METAL_TENSOR_IQ1_M ||
        gate_type == DS4_METAL_TENSOR_IQ3_XXS ||
        gate_type == DS4_METAL_TENSOR_IQ4_XS ||
        gate_type == DS4_METAL_TENSOR_Q5_K ||
        gate_type == DS4_METAL_TENSOR_Q6_K ||
        down_type == DS4_METAL_TENSOR_IQ1_M ||
        down_type == DS4_METAL_TENSOR_IQ3_XXS ||
        down_type == DS4_METAL_TENSOR_IQ4_XS ||
        down_type == DS4_METAL_TENSOR_Q5_K ||
        down_type == DS4_METAL_TENSOR_Q6_K) {
        fallback = 2u;
    }
    uint32_t min_refs = ds4_gpu_env_u32_default("DS4_METAL_MOE_MM_MIN_REFS", fallback);
    if (min_refs == 0u) min_refs = 1u;
    return min_refs;
}

