static int ds4_gpu_encode_mul_mm_id(
        id<MTLCommandBuffer>        cb,
        id<MTLComputePipelineState> map_pipeline,
        id<MTLComputePipelineState> mm_pipeline,
        const ds4_gpu_mul_mm_id_map_args *map_args,
        const ds4_gpu_mul_mm_id_args *mm_args,
        id<MTLBuffer>               src0,
        NSUInteger                  src0_off,
        id<MTLBuffer>               src1,
        NSUInteger                  src1_off,
        id<MTLBuffer>               dst,
        NSUInteger                  dst_off,
        id<MTLBuffer>               ids,
        NSUInteger                  ids_off) {
    if (!cb || !map_pipeline || !mm_pipeline || !map_args || !mm_args ||
        !src0 || !src1 || !dst || !ids ||
        mm_args->ne00 <= 0 || mm_args->ne0 <= 0 ||
        mm_args->ne20 <= 0 || mm_args->ne21 <= 0 || mm_args->ne02 <= 0) {
        return 0;
    }

    return ds4_gpu_encode_mul_mm_id_map(cb,
                                          map_pipeline,
                                          map_args,
                                          mm_args,
                                          ids,
                                          ids_off) &&
           ds4_gpu_encode_mul_mm_id_mapped(cb,
                                             mm_pipeline,
                                             mm_args,
                                             src0,
                                             src0_off,
                                             src1,
                                             src1_off,
                                             dst,
                                             dst_off);
}

static int ds4_gpu_encode_mul_mm_id_map(
        id<MTLCommandBuffer>        cb,
        id<MTLComputePipelineState> map_pipeline,
        const ds4_gpu_mul_mm_id_map_args *map_args,
        const ds4_gpu_mul_mm_id_args *mm_args,
        id<MTLBuffer>               ids,
        NSUInteger                  ids_off) {
    if (!cb || !map_pipeline || !map_args || !mm_args || !ids ||
        mm_args->ne20 <= 0 || mm_args->ne21 <= 0 || mm_args->ne02 <= 0) {
        return 0;
    }

    const NSUInteger tpe_bytes = (NSUInteger)mm_args->ne02 * sizeof(int32_t);
    const NSUInteger hids_bytes = (NSUInteger)mm_args->ne02 * (NSUInteger)mm_args->ne21 * sizeof(int32_t);
    if (tpe_bytes > NSUIntegerMax - hids_bytes) return 0;
    if (!ds4_gpu_ensure_scratch_buffer(&g_moe_id_map_buffer,
                                         &g_moe_id_map_bytes,
                                         tpe_bytes + hids_bytes,
                                         "ds4_moe_id_map")) {
        return 0;
    }

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:map_pipeline];
    [enc setBytes:map_args length:sizeof(*map_args) atIndex:0];
    [enc setBuffer:ids offset:ids_off atIndex:1];
    [enc setBuffer:g_moe_id_map_buffer offset:0 atIndex:2];
    [enc setBuffer:g_moe_id_map_buffer offset:tpe_bytes atIndex:3];
    [enc setThreadgroupMemoryLength:(NSUInteger)mm_args->ne02 * (NSUInteger)mm_args->ne20 * sizeof(uint16_t) atIndex:0];
    [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
         threadsPerThreadgroup:MTLSizeMake((NSUInteger)mm_args->ne02, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_zero_skipped_moe_counts(
        id<MTLCommandBuffer> cb,
        uint32_t             n_experts) {
    if (!cb || !g_ane_skip_mask_active || n_experts == 0 || n_experts > DS4_METAL_N_EXPERT ||
        !g_moe_id_map_buffer) {
        return 0;
    }
    if (!ds4_gpu_ensure_scratch_buffer(&g_ane_skip_mask_buffer,
                                       &g_ane_skip_mask_bytes,
                                       DS4_METAL_N_EXPERT,
                                       "ds4_ane_skip_mask")) {
        return 0;
    }
    uint8_t *mask = (uint8_t *)[g_ane_skip_mask_buffer contents];
    if (!mask) return 0;
    memcpy(mask, g_ane_skip_mask, DS4_METAL_N_EXPERT);
    if (!ds4_gpu_mtl_buffer_did_modify(g_ane_skip_mask_buffer, 0, DS4_METAL_N_EXPERT)) return 0;

    id<MTLComputePipelineState> pipeline =
        ds4_gpu_get_pipeline("kernel_dsv4_moe_zero_skipped_counts");
    if (!pipeline) return 0;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:pipeline];
    [enc setBuffer:g_moe_id_map_buffer offset:0 atIndex:0];
    [enc setBuffer:g_ane_skip_mask_buffer offset:0 atIndex:1];
    [enc dispatchThreads:MTLSizeMake((NSUInteger)n_experts, 1, 1)
     threadsPerThreadgroup:MTLSizeMake(256u, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_mul_mm_id_mapped_tile(
        id<MTLCommandBuffer>        cb,
        id<MTLComputePipelineState> mm_pipeline,
        const ds4_gpu_mul_mm_id_args *mm_args,
        id<MTLBuffer>               src0,
        NSUInteger                  src0_off,
        id<MTLBuffer>               src1,
        NSUInteger                  src1_off,
        id<MTLBuffer>               dst,
        NSUInteger                  dst_off,
        uint32_t                    token_tile_n) {
    if (!cb || !mm_pipeline || !mm_args || !src0 || !src1 || !dst ||
        !g_moe_id_map_buffer ||
        mm_args->ne00 <= 0 || mm_args->ne0 <= 0 ||
        mm_args->ne20 <= 0 || mm_args->ne21 <= 0 || mm_args->ne02 <= 0) {
        return 0;
    }

    /*
     * token_tile_n is a contract with the selected kernel's NR1. Legacy callers
     * pass 0 and use the unsuffixed NR1=32 kernels, so default MUST be 32. Wide
     * paths pass 64/128/256 only after selecting the matching suffixed pipeline,
     * or the dispatch grid-X mismatches the kernel and corrupts output
     * (antirez/ds4 "Harden wide MoE tile dispatch").
     */
    const NSUInteger tile_n = token_tile_n != 0u ? (NSUInteger)token_tile_n : 32u;

    const NSUInteger tpe_bytes = (NSUInteger)mm_args->ne02 * sizeof(int32_t);
    const NSUInteger hids_bytes = (NSUInteger)mm_args->ne02 * (NSUInteger)mm_args->ne21 * sizeof(int32_t);
    if (tpe_bytes > NSUIntegerMax - hids_bytes ||
        g_moe_id_map_bytes < tpe_bytes + hids_bytes) {
        return 0;
    }

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:mm_pipeline];
    [enc setBytes:mm_args length:sizeof(*mm_args) atIndex:0];
    [enc setBuffer:src0 offset:src0_off atIndex:1];
    [enc setBuffer:src1 offset:src1_off atIndex:2];
    [enc setBuffer:g_moe_id_map_buffer offset:0 atIndex:3];
    [enc setBuffer:g_moe_id_map_buffer offset:tpe_bytes atIndex:4];
    [enc setBuffer:dst offset:dst_off atIndex:5];
    [enc setThreadgroupMemoryLength:8192u atIndex:0];
    [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)mm_args->ne21 + tile_n - 1u) / tile_n,
                                          ((NSUInteger)mm_args->ne0 + 63u) / 64u,
                                          (NSUInteger)mm_args->ne02)
         threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_mul_mm_id_mapped(
        id<MTLCommandBuffer>        cb,
        id<MTLComputePipelineState> mm_pipeline,
        const ds4_gpu_mul_mm_id_args *mm_args,
        id<MTLBuffer>               src0,
        NSUInteger                  src0_off,
        id<MTLBuffer>               src1,
        NSUInteger                  src1_off,
        id<MTLBuffer>               dst,
        NSUInteger                  dst_off) {
    return ds4_gpu_encode_mul_mm_id_mapped_tile(cb, mm_pipeline, mm_args, src0, src0_off,
                                                src1, src1_off, dst, dst_off, 0u);
}

static int ds4_gpu_encode_swiglu_flat(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        gate,
        NSUInteger           gate_off,
        id<MTLBuffer>        up,
        NSUInteger           up_off,
        id<MTLBuffer>        out,
        NSUInteger           out_off,
        uint32_t             n) {
    if (!cb || !gate || !up || !out || n == 0) return 0;

    ds4_gpu_glu_args args = {
        .ne00 = (int32_t)n,
        .nb01 = (uint64_t)n * sizeof(float),
        .ne10 = (int32_t)n,
        .nb11 = (uint64_t)n * sizeof(float),
        .ne0 = (int32_t)n,
        .nb1 = (uint64_t)n * sizeof(float),
        .i00 = 0,
        .i10 = 0,
        .alpha = 0.0f,
        .limit = 0.0f,
    };
    NSUInteger nth = g_swiglu_pipeline.maxTotalThreadsPerThreadgroup;
    const NSUInteger ds4_nth = n > 1 ? (NSUInteger)n / 2u : 1u;
    if (nth > ds4_nth) nth = ds4_nth;
    if (nth == 0) nth = 1u;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_swiglu_pipeline];
    [enc setBytes:&args length:sizeof(args) atIndex:0];
    [enc setBuffer:gate offset:gate_off atIndex:1];
    [enc setBuffer:up   offset:up_off   atIndex:2];
    [enc setBuffer:out  offset:out_off  atIndex:3];
    [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
         threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_moe_swiglu_weight(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        gate,
        NSUInteger           gate_off,
        id<MTLBuffer>        up,
        NSUInteger           up_off,
        id<MTLBuffer>        mid,
        NSUInteger           mid_off,
        id<MTLBuffer>        weights,
        NSUInteger           weights_off,
        uint32_t             width,
        uint32_t             rows,
        float                clamp_value,
        bool                 mid_f16) {
    if (!cb || !gate || !up || !mid || !weights || width == 0 || rows == 0) return 0;

    id<MTLComputePipelineState> pipeline =
        ds4_gpu_get_pipeline(mid_f16 ? "kernel_dsv4_moe_swiglu_weight_f16" :
                                         "kernel_dsv4_moe_swiglu_weight");
    if (!pipeline) return 0;

    ds4_gpu_dsv4_moe_swiglu_weight_args args = {
        .width = width,
        .rows = rows,
        .gate_row_stride = (uint64_t)width * sizeof(float),
        .up_row_stride = (uint64_t)width * sizeof(float),
        .mid_row_stride = (uint64_t)width * (mid_f16 ? sizeof(uint16_t) : sizeof(float)),
        .weight_stride = sizeof(float),
        .write_clamped = getenv("DS4_METAL_MOE_WRITE_CLAMPED_ACT") != NULL ? 1u : 0u,
        .clamp_value = clamp_value,
    };

    NSUInteger nth = pipeline.maxTotalThreadsPerThreadgroup;
    if (nth > 256u) nth = 256u;
    if (nth > width) nth = width;
    if (nth == 0) nth = 1u;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:pipeline];
    [enc setBytes:&args length:sizeof(args) atIndex:0];
    [enc setBuffer:gate    offset:gate_off    atIndex:1];
    [enc setBuffer:up      offset:up_off      atIndex:2];
    [enc setBuffer:mid     offset:mid_off     atIndex:3];
    [enc setBuffer:weights offset:weights_off atIndex:4];
    [enc dispatchThreadgroups:MTLSizeMake(rows, 1, 1)
         threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static ds4_gpu_bin_args ds4_gpu_make_moe_add_args(
        uint32_t out_dim,
        uint32_t n_tokens,
        uint64_t src0_token_stride,
        uint64_t src1_token_stride,
        uint64_t dst_token_stride) {
    return (ds4_gpu_bin_args) {
        .ne00 = (int32_t)out_dim,
        .ne01 = (int32_t)n_tokens,
        .ne02 = 1,
        .ne03 = 1,
        .nb00 = sizeof(float),
        .nb01 = src0_token_stride,
        .nb02 = (uint64_t)n_tokens * src0_token_stride,
        .nb03 = (uint64_t)n_tokens * src0_token_stride,
        .ne10 = (int32_t)out_dim,
        .ne11 = (int32_t)n_tokens,
        .ne12 = 1,
        .ne13 = 1,
        .nb10 = sizeof(float),
        .nb11 = src1_token_stride,
        .nb12 = (uint64_t)n_tokens * src1_token_stride,
        .nb13 = (uint64_t)n_tokens * src1_token_stride,
        .ne0 = (int32_t)out_dim,
        .ne1 = (int32_t)n_tokens,
        .ne2 = 1,
        .ne3 = 1,
        .nb0 = sizeof(float),
        .nb1 = dst_token_stride,
        .nb2 = (uint64_t)n_tokens * dst_token_stride,
        .nb3 = (uint64_t)n_tokens * dst_token_stride,
        .offs = 0,
        .o1 = { 0 },
    };
}

static int ds4_gpu_encode_moe_sum_experts(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        experts,
        NSUInteger           experts_off,
        id<MTLBuffer>        out,
        NSUInteger           out_off,
        uint32_t             out_dim,
        uint32_t             n_expert,
        uint32_t             n_tokens) {
    if (!cb || !experts || !out || out_dim == 0 || n_expert < 2 || n_tokens == 0) return 0;

    const uint64_t out_row_bytes = (uint64_t)out_dim * sizeof(float);
    const uint64_t expert_token_stride = (uint64_t)n_expert * out_row_bytes;

    ds4_gpu_bin_args first =
        ds4_gpu_make_moe_add_args(out_dim, n_tokens, expert_token_stride, expert_token_stride, out_row_bytes);
    if (!ds4_gpu_encode_bin_f32_rows(cb,
                                       g_add_pipeline,
                                       &first,
                                       experts,
                                       experts_off,
                                       experts,
                                       experts_off + (NSUInteger)out_row_bytes,
                                       out,
                                       out_off)) {
        return 0;
    }

    ds4_gpu_bin_args accum =
        ds4_gpu_make_moe_add_args(out_dim, n_tokens, out_row_bytes, expert_token_stride, out_row_bytes);
    for (uint32_t slot = 2; slot < n_expert; slot++) {
        if (!ds4_gpu_encode_bin_f32_rows(cb,
                                           g_add_pipeline,
                                           &accum,
                                           out,
                                           out_off,
                                           experts,
                                           experts_off + (NSUInteger)((uint64_t)slot * out_row_bytes),
                                           out,
                                           out_off)) {
            return 0;
        }
    }
    return 1;
}

int ds4_gpu_moe_sum_experts_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *experts,
        uint32_t                out_dim,
        uint32_t                n_expert) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !experts || out_dim == 0 || n_expert < 2) return 0;

    @autoreleasepool {
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> expertsbuf = ds4_gpu_tensor_buffer(experts);
        const uint64_t out_bytes = (uint64_t)out_dim * sizeof(float);
        const uint64_t experts_bytes = (uint64_t)n_expert * out_bytes;
        if (!outbuf || !expertsbuf ||
            ds4_gpu_tensor_bytes(out) < out_bytes ||
            ds4_gpu_tensor_bytes(experts) < experts_bytes) {
            return 0;
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        const int ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                       expertsbuf,
                                                       ds4_gpu_tensor_offset(experts),
                                                       outbuf,
                                                       ds4_gpu_tensor_offset(out),
                                                       out_dim,
                                                       n_expert,
                                                       1);
        if (!ok) return 0;
        return ds4_gpu_finish_command_buffer(cb, owned, "MoE sum experts tensor");
    }
}

static int ds4_gpu_mxfp4_native_decode_available(
        uint32_t gate_type,
        uint32_t down_type,
        uint64_t gate_row_bytes,
        uint64_t down_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t out_dim) {
    (void)out_dim;
    if (gate_type != DS4_METAL_TENSOR_MXFP4 ||
        down_type != DS4_METAL_TENSOR_MXFP4 ||
        !ds4_gpu_mxfp4_native_requested() ||
        !ds4_gpu_has_native_mxfp4()) {
        return 0;
    }
    if (expert_in_dim == 0 || expert_mid_dim == 0 ||
        (expert_in_dim % 32u) != 0 ||
        (expert_mid_dim % 32u) != 0) {
        return 0;
    }
    const uint64_t expected_gate_row = (uint64_t)(expert_in_dim / 32u) * 17u;
    const uint64_t expected_down_row = (uint64_t)(expert_mid_dim / 32u) * 17u;
    return gate_row_bytes == expected_gate_row &&
           down_row_bytes == expected_down_row;
}

static int ds4_gpu_mxfp4_native_decode_ensure_scratch(
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t out_dim) {
    const uint64_t x_half_bytes = (uint64_t)expert_in_dim * sizeof(uint16_t);
    const uint64_t mid_half_bytes = (uint64_t)expert_mid_dim * sizeof(uint16_t);
    const uint64_t gate_plane_bytes = (uint64_t)expert_mid_dim * expert_in_dim;
    const uint64_t down_plane_bytes = (uint64_t)out_dim * expert_mid_dim;
    if (x_half_bytes > NSUIntegerMax ||
        mid_half_bytes > NSUIntegerMax ||
        gate_plane_bytes > NSUIntegerMax ||
        down_plane_bytes > NSUIntegerMax) {
        return 0;
    }
    return ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_x_half_buffer,
                                         &g_mpp_prefill_x_half_bytes,
                                         (NSUInteger)x_half_bytes,
                                         "ds4_mxfp4_decode_x_half") &&
           ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_mid_half_buffer,
                                         &g_mpp_prefill_mid_half_bytes,
                                         (NSUInteger)mid_half_bytes,
                                         "ds4_mxfp4_decode_mid_half") &&
           ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_gate_i8_buffer,
                                         &g_mpp_prefill_gate_i8_bytes,
                                         (NSUInteger)gate_plane_bytes,
                                         "ds4_mxfp4_decode_gate_planes") &&
           ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_up_i8_buffer,
                                         &g_mpp_prefill_up_i8_bytes,
                                         (NSUInteger)gate_plane_bytes,
                                         "ds4_mxfp4_decode_up_planes") &&
           ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_down_i8_buffer,
                                         &g_mpp_prefill_down_i8_bytes,
                                         (NSUInteger)down_plane_bytes,
                                         "ds4_mxfp4_decode_down_planes");
}

static void ds4_gpu_mxfp4_native_decode_log_once(const char *path, int plane_split) {
    static int logged_repack = 0;
    static int logged_plane = 0;
    int *logged = plane_split ? &logged_plane : &logged_repack;
    if (!*logged) {
        *logged = 1;
        fprintf(stderr,
                "ds4: [mxfp4-native] MPP 4.1 scale-plane decode arm engaged (%s, %s)\n",
                path ? path : "decode",
                plane_split ? "plane-sidecar/no-repack" : "repack-per-use");
    }
}

static int ds4_gpu_mxfp4_native_decode2_available(
        uint32_t gate_type,
        uint32_t down_type,
        uint64_t gate_row_bytes,
        uint64_t down_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        uint32_t n_expert,
        int      plane_split) {
    if (!plane_split || n_expert != 6) return 0;
    if (!ds4_gpu_mxfp4_native_decode_available(gate_type,
                                               down_type,
                                               gate_row_bytes,
                                               down_row_bytes,
                                               expert_in_dim,
                                               expert_mid_dim,
                                               out_dim)) {
        return 0;
    }
    ds4_gpu_ensure_mxfp4_native_library();
    return g_mxfp4_plane_id_pair_swiglu_pipeline != nil &&
           g_mxfp4_plane_id_sum6_pipeline != nil;
}

static int ds4_gpu_mxfp4_native_down_sum6_available(
        uint32_t down_type,
        uint64_t down_row_bytes,
        uint32_t expert_mid_dim,
        uint32_t out_dim) {
    (void)out_dim;
    if (down_type != DS4_METAL_TENSOR_MXFP4 ||
        !ds4_gpu_mxfp4_native_requested() ||
        !ds4_gpu_has_native_mxfp4() ||
        expert_mid_dim == 0 ||
        (expert_mid_dim % 32u) != 0) {
        return 0;
    }
    const uint64_t expected_down_row = (uint64_t)(expert_mid_dim / 32u) * 17u;
    if (down_row_bytes != expected_down_row) return 0;
    ds4_gpu_ensure_mxfp4_native_library();
    return g_mxfp4_plane_slots6_sum6_pipeline != nil;
}

static id<MTLBuffer> ds4_gpu_mxfp4_decode_selected_ids_upload(
        const int32_t *ids,
        uint32_t       n_expert) {
    if (!g_device || !ids || n_expert != 6) return nil;
    const NSUInteger bytes = (NSUInteger)n_expert * sizeof(int32_t);
    if (!g_mxfp4_decode_selected_ids_buffer ||
        g_mxfp4_decode_selected_ids_bytes < bytes) {
        g_mxfp4_decode_selected_ids_buffer =
            [g_device newBufferWithLength:bytes options:MTLResourceStorageModeShared];
        if (!g_mxfp4_decode_selected_ids_buffer) {
            g_mxfp4_decode_selected_ids_bytes = 0;
            return nil;
        }
        g_mxfp4_decode_selected_ids_buffer.label = @"ds4_mxfp4_decode_selected_ids";
        g_mxfp4_decode_selected_ids_bytes = bytes;
    }
    void *dst = [g_mxfp4_decode_selected_ids_buffer contents];
    if (!dst) return nil;
    memcpy(dst, ids, bytes);
    return g_mxfp4_decode_selected_ids_buffer;
}

static void ds4_gpu_mxfp4_native_decode2_log_once(const char *path) {
    static int logged_banked = 0;
    static int logged_slotwise = 0;
    static int logged_chunked = 0;
    static int logged_other = 0;
    int *logged = &logged_other;
    if (path && strstr(path, "chunked")) {
        logged = &logged_chunked;
    } else if (path && strstr(path, "banked")) {
        logged = &logged_banked;
    } else if (path && strstr(path, "slotwise")) {
        logged = &logged_slotwise;
    }
    if (!*logged) {
        *logged = 1;
        fprintf(stderr,
                "ds4: [mxfp4-native] two-dispatch plane decode arm engaged (%s, experts=6)\n",
                path ? path : "decode");
    }
}

static int ds4_gpu_encode_mxfp4_native_decode_route(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        x_half,
        id<MTLBuffer>        gate_src,
        NSUInteger           gate_src_off,
        id<MTLBuffer>        up_src,
        NSUInteger           up_src_off,
        id<MTLBuffer>        down_src,
        NSUInteger           down_src_off,
        id<MTLBuffer>        selected,
        NSUInteger           selected_off,
        uint32_t             route,
        uint64_t             gate_slot_stride,
        uint64_t             down_slot_stride,
        int                  plane_split,
        id<MTLBuffer>        gate,
        NSUInteger           gate_off,
        id<MTLBuffer>        up,
        NSUInteger           up_off,
        id<MTLBuffer>        mid,
        NSUInteger           mid_off,
        id<MTLBuffer>        weights,
        NSUInteger           weights_off,
        id<MTLBuffer>        down_dst,
        NSUInteger           down_dst_off,
        uint32_t             expert_in_dim,
        uint32_t             expert_mid_dim,
        uint32_t             out_dim,
        float                clamp) {
    if (!cb || !x_half || !gate_src || !up_src || !down_src ||
        !gate || !up || !mid || !weights || !down_dst ||
        expert_in_dim == 0 || expert_mid_dim == 0 || out_dim == 0) {
        return 0;
    }
    const NSUInteger gate_scales_off =
        (NSUInteger)((uint64_t)expert_in_dim * expert_mid_dim / 2u);
    const NSUInteger down_scales_off =
        (NSUInteger)((uint64_t)expert_mid_dim * out_dim / 2u);
    int ok = 0;
    const int selected_plane_split = plane_split && selected;
    const int direct_plane_split = plane_split && !selected;
    if (plane_split) {
        if (selected) {
            if (gate_slot_stride == 0 || down_slot_stride == 0 ||
                gate_slot_stride > UINT32_MAX ||
                down_slot_stride > UINT32_MAX) {
                return 0;
            }
            if (gate_src_off > NSUIntegerMax - gate_scales_off ||
                up_src_off > NSUIntegerMax - gate_scales_off ||
                down_src_off > NSUIntegerMax - down_scales_off) {
                return 0;
            }
            ok = 1;
        } else {
            ok = 1;
        }
    } else if (selected) {
        if (gate_slot_stride == 0 || down_slot_stride == 0 ||
            gate_slot_stride > UINT32_MAX ||
            down_slot_stride > UINT32_MAX) {
            return 0;
        }
        ok = ds4_gpu_encode_mxfp4_repack_selected_planes(cb,
                                                         gate_src,
                                                         gate_src_off,
                                                         g_mpp_prefill_gate_i8_buffer,
                                                         0,
                                                         gate_scales_off,
                                                         selected,
                                                         selected_off,
                                                         route,
                                                         expert_mid_dim,
                                                         expert_in_dim,
                                                         (uint32_t)gate_slot_stride) &&
             ds4_gpu_encode_mxfp4_repack_selected_planes(cb,
                                                         up_src,
                                                         up_src_off,
                                                         g_mpp_prefill_up_i8_buffer,
                                                         0,
                                                         gate_scales_off,
                                                         selected,
                                                         selected_off,
                                                         route,
                                                         expert_mid_dim,
                                                         expert_in_dim,
                                                         (uint32_t)gate_slot_stride) &&
             ds4_gpu_encode_mxfp4_repack_selected_planes(cb,
                                                         down_src,
                                                         down_src_off,
                                                         g_mpp_prefill_down_i8_buffer,
                                                         0,
                                                         down_scales_off,
                                                         selected,
                                                         selected_off,
                                                         route,
                                                         out_dim,
                                                         expert_mid_dim,
                                                         (uint32_t)down_slot_stride);
    } else {
        ok = ds4_gpu_encode_mxfp4_repack_planes(cb,
                                                gate_src,
                                                gate_src_off,
                                                g_mpp_prefill_gate_i8_buffer,
                                                0,
                                                gate_scales_off,
                                                expert_mid_dim,
                                                expert_in_dim) &&
             ds4_gpu_encode_mxfp4_repack_planes(cb,
                                                up_src,
                                                up_src_off,
                                                g_mpp_prefill_up_i8_buffer,
                                                0,
                                                gate_scales_off,
                                                expert_mid_dim,
                                                expert_in_dim) &&
             ds4_gpu_encode_mxfp4_repack_planes(cb,
                                                down_src,
                                                down_src_off,
                                                g_mpp_prefill_down_i8_buffer,
                                                0,
                                                down_scales_off,
                                                out_dim,
                                                expert_mid_dim);
    }
    if (!ok) return 0;
    if (direct_plane_split &&
        (gate_src_off > NSUIntegerMax - gate_scales_off ||
         up_src_off > NSUIntegerMax - gate_scales_off ||
         down_src_off > NSUIntegerMax - down_scales_off)) {
        return 0;
    }

    if (selected_plane_split) {
        static int logged_selected_no_copy = 0;
        if (!logged_selected_no_copy) {
            logged_selected_no_copy = 1;
            fprintf(stderr,
                    "ds4: [mxfp4-native] selected-slot decode uses direct plane matmul "
                    "(no selected plane copy)\n");
        }
        return ds4_gpu_encode_mxfp4_native_matmul_selected(cb,
                                                           x_half, 0,
                                                           gate_src,
                                                           gate_src_off,
                                                           gate_src_off + gate_scales_off,
                                                           gate, gate_off,
                                                           1, expert_mid_dim, expert_in_dim,
                                                           selected,
                                                           selected_off,
                                                           (uint32_t)gate_slot_stride,
                                                           route) &&
               ds4_gpu_encode_mxfp4_native_matmul_selected(cb,
                                                           x_half, 0,
                                                           up_src,
                                                           up_src_off,
                                                           up_src_off + gate_scales_off,
                                                           up, up_off,
                                                           1, expert_mid_dim, expert_in_dim,
                                                           selected,
                                                           selected_off,
                                                           (uint32_t)gate_slot_stride,
                                                           route) &&
               ds4_gpu_encode_moe_swiglu_weight(cb,
                                                gate, gate_off,
                                                up, up_off,
                                                mid, mid_off,
                                                weights, weights_off,
                                                expert_mid_dim,
                                                1,
                                                clamp,
                                                false) &&
               ds4_gpu_encode_cpy_f32_f16_1d(cb,
                                             mid,
                                             mid_off,
                                             g_mpp_prefill_mid_half_buffer,
                                             0,
                                             expert_mid_dim) &&
               ds4_gpu_encode_mxfp4_native_matmul_selected(cb,
                                                           g_mpp_prefill_mid_half_buffer, 0,
                                                           down_src,
                                                           down_src_off,
                                                           down_src_off + down_scales_off,
                                                           down_dst, down_dst_off,
                                                           1, out_dim, expert_mid_dim,
                                                           selected,
                                                           selected_off,
                                                           (uint32_t)down_slot_stride,
                                                           route);
    }

    id<MTLBuffer> gate_w = direct_plane_split ? gate_src : g_mpp_prefill_gate_i8_buffer;
    id<MTLBuffer> up_w = direct_plane_split ? up_src : g_mpp_prefill_up_i8_buffer;
    id<MTLBuffer> down_w = direct_plane_split ? down_src : g_mpp_prefill_down_i8_buffer;
    const NSUInteger gate_data_off = direct_plane_split ? gate_src_off : 0;
    const NSUInteger up_data_off = direct_plane_split ? up_src_off : 0;
    const NSUInteger down_data_off = direct_plane_split ? down_src_off : 0;
    const NSUInteger gate_scale_off = direct_plane_split ? gate_src_off + gate_scales_off : gate_scales_off;
    const NSUInteger up_scale_off = direct_plane_split ? up_src_off + gate_scales_off : gate_scales_off;
    const NSUInteger down_scale_off = direct_plane_split ? down_src_off + down_scales_off : down_scales_off;

    return ds4_gpu_encode_mxfp4_native_matmul(cb,
                                             x_half, 0,
                                             gate_w,
                                             gate_data_off, gate_scale_off,
                                             gate, gate_off,
                                             1, expert_mid_dim, expert_in_dim) &&
           ds4_gpu_encode_mxfp4_native_matmul(cb,
                                             x_half, 0,
                                             up_w,
                                             up_data_off, up_scale_off,
                                             up, up_off,
                                             1, expert_mid_dim, expert_in_dim) &&
           ds4_gpu_encode_moe_swiglu_weight(cb,
                                            gate, gate_off,
                                            up, up_off,
                                            mid, mid_off,
                                            weights, weights_off,
                                            expert_mid_dim,
                                            1,
                                            clamp,
                                            false) &&
           ds4_gpu_encode_cpy_f32_f16_1d(cb,
                                         mid,
                                         mid_off,
                                         g_mpp_prefill_mid_half_buffer,
                                         0,
                                         expert_mid_dim) &&
           ds4_gpu_encode_mxfp4_native_matmul(cb,
                                             g_mpp_prefill_mid_half_buffer, 0,
                                             down_w,
                                             down_data_off, down_scale_off,
                                             down_dst, down_dst_off,
                                             1, out_dim, expert_mid_dim);
}

static int ds4_gpu_encode_get_rows_i32_token_rows(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        table,
        NSUInteger           table_off,
        id<MTLBuffer>        tokens,
        NSUInteger           tokens_off,
        const int32_t       *token_inline,
        id<MTLBuffer>        selected,
        NSUInteger           selected_off,
        uint32_t             hash_rows,
        uint32_t             hash_width,
        uint32_t             n_expert_used,
        uint32_t             n_tokens) {
    if (!cb || !table || !selected || hash_rows == 0 || hash_width == 0 ||
        n_expert_used == 0 || n_expert_used > hash_width || n_tokens == 0) return 0;
    if (!tokens && !token_inline) return 0;

    const uint64_t table_row_bytes = (uint64_t)hash_width * sizeof(int32_t);
    const uint64_t selected_row_bytes = (uint64_t)n_expert_used * sizeof(int32_t);
    const uint64_t token_bytes = (uint64_t)n_tokens * sizeof(int32_t);
    ds4_gpu_get_rows_args args = {
        .ne00t = (int64_t)n_expert_used,
        .ne00 = (int64_t)hash_width,
        .nb01 = table_row_bytes,
        .nb02 = (uint64_t)hash_rows * table_row_bytes,
        .nb03 = (uint64_t)hash_rows * table_row_bytes,
        .ne10 = (int32_t)n_tokens,
        .nb10 = sizeof(int32_t),
        .nb11 = token_bytes,
        .nb12 = token_bytes,
        .nb1 = selected_row_bytes,
        .nb2 = (uint64_t)n_tokens * selected_row_bytes,
        .nb3 = (uint64_t)n_tokens * selected_row_bytes,
    };

    NSUInteger nth = (NSUInteger)n_expert_used;
    const NSUInteger max_threads = g_get_rows_i32_pipeline.maxTotalThreadsPerThreadgroup;
    if (nth > max_threads) nth = max_threads;
    if (nth == 0) nth = 1u;
    const NSUInteger nw0 = ((NSUInteger)n_expert_used + nth - 1u) / nth;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_get_rows_i32_pipeline];
    [enc setBytes:&args length:sizeof(args) atIndex:0];
    [enc setBuffer:table offset:table_off atIndex:1];
    if (tokens) {
        [enc setBuffer:tokens offset:tokens_off atIndex:2];
    } else {
        [enc setBytes:token_inline length:sizeof(*token_inline) atIndex:2];
    }
    [enc setBuffer:selected offset:selected_off atIndex:3];
    [enc dispatchThreadgroups:MTLSizeMake(nw0 * n_tokens, 1, 1)
         threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_get_rows_f32_router_weights(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        probs,
        NSUInteger           probs_off,
        id<MTLBuffer>        selected,
        NSUInteger           selected_off,
        id<MTLBuffer>        weights,
        NSUInteger           weights_off,
        uint32_t             n_expert,
        uint32_t             n_expert_used,
        uint32_t             n_tokens) {
    if (!cb || !probs || !selected || !weights || n_expert == 0 || n_expert_used == 0 || n_tokens == 0) return 0;

    const uint64_t probs_token_bytes = (uint64_t)n_expert * sizeof(float);
    const uint64_t selected_row_bytes = (uint64_t)n_expert_used * sizeof(int32_t);
    const uint64_t weights_row_bytes = (uint64_t)n_expert_used * sizeof(float);
    ds4_gpu_get_rows_args args = {
        .ne00t = 1,
        .ne00 = 1,
        .nb01 = sizeof(float),
        .nb02 = probs_token_bytes,
        .nb03 = (uint64_t)n_tokens * probs_token_bytes,
        .ne10 = (int64_t)n_expert_used,
        .nb10 = sizeof(int32_t),
        .nb11 = selected_row_bytes,
        .nb12 = (uint64_t)n_tokens * selected_row_bytes,
        .nb1 = sizeof(float),
        .nb2 = weights_row_bytes,
        .nb3 = (uint64_t)n_tokens * weights_row_bytes,
    };

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_get_rows_f32_pipeline];
    [enc setBytes:&args length:sizeof(args) atIndex:0];
    [enc setBuffer:probs offset:probs_off atIndex:1];
    [enc setBuffer:selected offset:selected_off atIndex:2];
    [enc setBuffer:weights offset:weights_off atIndex:3];
    [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n_expert_used, n_tokens, 1)
         threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_sum_rows_f32(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        src,
        NSUInteger           src_off,
        id<MTLBuffer>        dst,
        NSUInteger           dst_off,
        uint32_t             width,
        uint32_t             rows) {
    if (!cb || !src || !dst || width == 0 || rows == 0) return 0;

    const uint64_t src_row_bytes = (uint64_t)width * sizeof(float);
    ds4_gpu_kargs_sum_rows args = {
        .ne00 = (int64_t)width,
        .ne01 = (int64_t)rows,
        .ne02 = 1,
        .ne03 = 1,
        .nb00 = sizeof(float),
        .nb01 = src_row_bytes,
        .nb02 = (uint64_t)rows * src_row_bytes,
        .nb03 = (uint64_t)rows * src_row_bytes,
        .ne0 = 1,
        .ne1 = (int64_t)rows,
        .ne2 = 1,
        .ne3 = 1,
        .nb0 = sizeof(float),
        .nb1 = sizeof(float),
        .nb2 = (uint64_t)rows * sizeof(float),
        .nb3 = (uint64_t)rows * sizeof(float),
    };

    NSUInteger nth = 32u;
    const NSUInteger max_threads = g_sum_rows_f32_f32_pipeline.maxTotalThreadsPerThreadgroup;
    while (nth < (NSUInteger)args.ne00 && nth < max_threads) nth *= 2u;
    if (nth > max_threads) nth = max_threads;
    if (nth > (NSUInteger)args.ne00) nth = (NSUInteger)args.ne00;
    if (nth == 0) nth = 1u;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_sum_rows_f32_f32_pipeline];
    [enc setBytes:&args length:sizeof(args) atIndex:0];
    [enc setBuffer:src offset:src_off atIndex:1];
    [enc setBuffer:dst offset:dst_off atIndex:2];
    [enc setThreadgroupMemoryLength:32u * sizeof(float) atIndex:0];
    [enc dispatchThreadgroups:MTLSizeMake(rows, 1, 1)
         threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_router_select(
        id<MTLCommandBuffer>  cb,
        ds4_gpu_tensor     *selected,
        ds4_gpu_tensor     *weights,
        ds4_gpu_tensor     *probs,
        id<MTLBuffer>         logitsbuf,
        NSUInteger            logits_off,
        id<MTLBuffer>         biasbuf,
        NSUInteger            bias_off,
        id<MTLBuffer>         hashbuf,
        NSUInteger            hash_off,
        id<MTLBuffer>         tokensbuf,
        NSUInteger            tokens_off,
        const int32_t        *single_token,
        uint32_t              hash_rows,
        uint32_t              hash_width,
        uint32_t              n_tokens,
        uint32_t              n_expert,
        uint32_t              n_expert_used,
        float                 expert_weight_scale,
        bool                  has_bias,
        bool                  hash_mode) {
    id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
    id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
    id<MTLBuffer> probsbuf = ds4_gpu_tensor_buffer(probs);
    const NSUInteger selected_off = ds4_gpu_tensor_offset(selected);
    const NSUInteger weights_off = ds4_gpu_tensor_offset(weights);
    const NSUInteger probs_off = ds4_gpu_tensor_offset(probs);

    if (!cb || !selectedbuf || !weightsbuf || !probsbuf || !logitsbuf ||
        n_tokens == 0 || n_expert == 0 || n_expert_used == 0) return 0;

    const NSUInteger probs_bytes = (NSUInteger)n_tokens * (NSUInteger)n_expert * sizeof(float);
    const bool flash_router_fast_path =
        n_expert == 256u &&
        n_expert_used == 6u &&
        (!hash_mode || hash_width == 6u) &&
        fabsf(expert_weight_scale - 1.5f) <= 1.0e-6f;

    int ok = 0;
    if (flash_router_fast_path &&
        !g_quality_mode && n_tokens == 1 &&
        getenv("DS4_METAL_DISABLE_ROUTER_SELECT_FUSION") == NULL) {
        id<MTLComputePipelineState> softplus_sqrt_pipeline =
            ds4_gpu_hot_pipeline(g_dsv4_softplus_sqrt_pipeline,
                                    "kernel_dsv4_softplus_sqrt_f32_4");
        id<MTLComputePipelineState> router_finalize_pipeline =
            ds4_gpu_hot_pipeline(g_dsv4_router_finalize_one_pipeline,
                                    "kernel_dsv4_router_finalize_one");
        id<MTLComputePipelineState> router_weights_pipeline =
            ds4_gpu_hot_pipeline(g_dsv4_router_weights_one_pipeline,
                                    "kernel_dsv4_router_weights_one");
        if (!softplus_sqrt_pipeline || !router_finalize_pipeline || !router_weights_pipeline) return 0;

        ok = ds4_gpu_encode_unary_f32_rows(cb,
                                             softplus_sqrt_pipeline,
                                             logitsbuf,
                                             logits_off,
                                             probsbuf,
                                             probs_off,
                                             n_expert,
                                             1,
                                             1,
                                             0.0f,
                                             0.0f);
        if (!ok) return 0;

        const bool use_token_buffer = single_token == NULL;
        ds4_gpu_dsv4_router_select_one_args args = {
            .has_bias = has_bias ? 1u : 0u,
            .hash_mode = hash_mode ? 1u : 0u,
            .use_token_buffer = use_token_buffer ? 1u : 0u,
            .token = single_token ? (uint32_t)*single_token : 0u,
            .hash_rows = hash_rows,
        };

        const float zero_f32 = 0.0f;
        const int32_t zero_i32 = 0;
        if ((has_bias && !biasbuf) ||
            (hash_mode && !hashbuf) ||
            (use_token_buffer && !tokensbuf)) {
            return 0;
        }

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:router_finalize_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:probsbuf offset:probs_off atIndex:1];
        if (has_bias) {
            [enc setBuffer:biasbuf offset:bias_off atIndex:2];
        } else {
            [enc setBytes:&zero_f32 length:sizeof(zero_f32) atIndex:2];
        }
        if (hash_mode) {
            [enc setBuffer:hashbuf offset:hash_off atIndex:3];
        } else {
            [enc setBytes:&zero_i32 length:sizeof(zero_i32) atIndex:3];
        }
        if (use_token_buffer) {
            [enc setBuffer:tokensbuf offset:tokens_off atIndex:4];
        } else {
            [enc setBytes:&zero_i32 length:sizeof(zero_i32) atIndex:4];
        }
        [enc setBuffer:selectedbuf offset:selected_off atIndex:5];
        [enc setThreadgroupMemoryLength:256u * sizeof(float) + 256u * sizeof(int32_t) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:router_weights_pipeline];
        [enc setBuffer:probsbuf offset:probs_off atIndex:0];
        [enc setBuffer:selectedbuf offset:selected_off atIndex:1];
        [enc setBuffer:weightsbuf offset:weights_off atIndex:2];
        [enc dispatchThreads:MTLSizeMake(n_expert_used, 1, 1)
        threadsPerThreadgroup:MTLSizeMake(n_expert_used, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return 1;
    }

    const NSUInteger sum_bytes = (NSUInteger)n_tokens * sizeof(float);
    if (!ds4_gpu_ensure_scratch_buffer(&g_router_weight_sum_buffer,
                                         &g_router_weight_sum_bytes,
                                         sum_bytes,
                                         "ds4_router_weight_sum")) {
        return 0;
    }

    if (flash_router_fast_path && !g_quality_mode && n_tokens == 1) {
        id<MTLComputePipelineState> softplus_sqrt_pipeline =
            ds4_gpu_hot_pipeline(g_dsv4_softplus_sqrt_pipeline,
                                    "kernel_dsv4_softplus_sqrt_f32_4");
        ok = softplus_sqrt_pipeline &&
             ds4_gpu_encode_unary_f32_rows(cb,
                                             softplus_sqrt_pipeline,
                                             logitsbuf,
                                             logits_off,
                                             probsbuf,
                                             probs_off,
                                             n_expert,
                                             1,
                                             1,
                                             0.0f,
                                             0.0f);
    } else {
        ok = ds4_gpu_encode_unary_f32_rows(cb,
                                             g_unary_softplus_pipeline,
                                             logitsbuf,
                                             logits_off,
                                             probsbuf,
                                             probs_off,
                                             n_expert,
                                             n_tokens,
                                             1,
                                             0.0f,
                                             0.0f) &&
             ds4_gpu_encode_unary_f32_rows(cb,
                                             g_unary_sqrt_pipeline,
                                             probsbuf,
                                             probs_off,
                                             probsbuf,
                                             probs_off,
                                             n_expert,
                                             n_tokens,
                                             1,
                                             0.0f,
                                             0.0f);
    }
    if (!ok) return 0;

    if (hash_mode) {
        ok = ds4_gpu_encode_get_rows_i32_token_rows(cb,
                                                      hashbuf,
                                                      hash_off,
                                                      tokensbuf,
                                                      tokens_off,
                                                      single_token,
                                                      selectedbuf,
                                                      selected_off,
                                                      hash_rows,
                                                      hash_width,
                                                      n_expert_used,
                                                      n_tokens);
    } else {
        ds4_gpu_tensor *score_tensor = probs;
        DS4MetalTensor *selection_view = nil;

        if (has_bias) {
            if (!biasbuf ||
                !ds4_gpu_ensure_scratch_buffer(&g_router_selection_buffer,
                                                 &g_router_selection_bytes,
                                                 probs_bytes,
                                                 "ds4_router_selection")) {
                return 0;
            }

            ds4_gpu_bin_args add_args =
                ds4_gpu_make_bin_rows_args(n_expert, n_tokens, n_expert);
            ok = ds4_gpu_encode_bin_f32_rows(cb,
                                               g_add_pipeline,
                                               &add_args,
                                               probsbuf,
                                               probs_off,
                                               biasbuf,
                                               bias_off,
                                               g_router_selection_buffer,
                                               0);
            if (!ok) return 0;

            selection_view = [DS4MetalTensor new];
            selection_view.buffer = g_router_selection_buffer;
            selection_view.offset = 0;
            selection_view.bytes = probs_bytes;
            selection_view.owner = 0;
            score_tensor = (__bridge ds4_gpu_tensor *)selection_view;
        }

        ok = ds4_gpu_indexer_topk_tensor(selected,
                                         score_tensor,
                                         n_expert,
                                         n_tokens,
                                         n_expert_used) != 0;
    }
    if (!ok) return 0;

    if (flash_router_fast_path && !g_quality_mode && n_tokens == 1) {
        id<MTLComputePipelineState> router_weights_pipeline =
            ds4_gpu_hot_pipeline(g_dsv4_router_weights_one_pipeline,
                                    "kernel_dsv4_router_weights_one");
        if (!router_weights_pipeline) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:router_weights_pipeline];
        [enc setBuffer:probsbuf offset:probs_off atIndex:0];
        [enc setBuffer:selectedbuf offset:selected_off atIndex:1];
        [enc setBuffer:weightsbuf offset:weights_off atIndex:2];
        [enc dispatchThreads:MTLSizeMake(n_expert_used, 1, 1)
        threadsPerThreadgroup:MTLSizeMake(n_expert_used, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return 1;
    }

    ok = ds4_gpu_encode_get_rows_f32_router_weights(cb,
                                                      probsbuf,
                                                      probs_off,
                                                      selectedbuf,
                                                      selected_off,
                                                      weightsbuf,
                                                      weights_off,
                                                      n_expert,
                                                      n_expert_used,
                                                      n_tokens) &&
         ds4_gpu_encode_sum_rows_f32(cb,
                                       weightsbuf,
                                       weights_off,
                                       g_router_weight_sum_buffer,
                                       0,
                                       n_expert_used,
                                       n_tokens) &&
         ds4_gpu_encode_unary_f32_rows(cb,
                                         g_unary_clamp_pipeline,
                                         g_router_weight_sum_buffer,
                                         0,
                                         g_router_weight_sum_buffer,
                                         0,
                                         1,
                                         n_tokens,
                                         0,
                                         6.103515625e-5f,
                                         ds4_gpu_positive_infinity());
    if (!ok) return 0;

    ds4_gpu_bin_args div_args = ds4_gpu_make_bin_rowwise_scalar_args(n_expert_used, n_tokens);
    const float scale = expert_weight_scale;
    ds4_gpu_bin_args scale_args = ds4_gpu_make_bin_rows_args(n_expert_used, n_tokens, 1);

    ok = ds4_gpu_encode_bin_f32_rows(cb,
                                       g_bin_div_row_pipeline,
                                       &div_args,
                                       weightsbuf,
                                       weights_off,
                                       g_router_weight_sum_buffer,
                                       0,
                                       weightsbuf,
                                       weights_off);
    if (!ok) return 0;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_bin_mul_scalar_pipeline];
    [enc setBytes:&scale_args length:sizeof(scale_args) atIndex:0];
    [enc setBuffer:weightsbuf offset:weights_off atIndex:1];
    [enc setBytes:&scale length:sizeof(scale) atIndex:2];
    [enc setBuffer:weightsbuf offset:weights_off atIndex:3];
    [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)scale_args.ne1,
                                          (NSUInteger)scale_args.ne2,
                                          (NSUInteger)scale_args.ne3)
         threadsPerThreadgroup:MTLSizeMake(ds4_gpu_bin_threads(n_expert_used, g_bin_mul_scalar_pipeline), 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);

    return 1;
}

int ds4_gpu_router_select_tensor(
        ds4_gpu_tensor       *selected,
        ds4_gpu_tensor       *weights,
        ds4_gpu_tensor       *probs,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                bias_offset,
        uint64_t                hash_offset,
        uint32_t                hash_rows,
        uint32_t                hash_width,
        uint32_t                token,
        uint32_t                n_expert,
        uint32_t                n_expert_used,
        float                   expert_weight_scale,
        uint32_t                n_expert_groups,
        uint32_t                n_group_used,
        bool                    has_bias,
        bool                    hash_mode,
        const ds4_gpu_tensor *logits) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!selected || !weights || !probs || !logits || !model_map ||
        n_expert == 0 || n_expert_used == 0) return 0;
    if (hash_mode && token >= hash_rows) return 0;
    if (hash_mode && (hash_width == 0 || n_expert_used > hash_width)) return 0;
    if (n_expert_groups > 1u || n_group_used > 0u) {
        fprintf(stderr, "ds4: Metal router group gating is not part of this DeepSeek V4 path\n");
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> logitsbuf = ds4_gpu_tensor_buffer(logits);
        id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> probsbuf = ds4_gpu_tensor_buffer(probs);
        if (!logitsbuf || !selectedbuf || !weightsbuf || !probsbuf ||
            ds4_gpu_tensor_bytes(logits) < (uint64_t)n_expert * sizeof(float) ||
            ds4_gpu_tensor_bytes(selected) < (uint64_t)n_expert_used * sizeof(int) ||
            ds4_gpu_tensor_bytes(weights) < (uint64_t)n_expert_used * sizeof(float) ||
            ds4_gpu_tensor_bytes(probs) < (uint64_t)n_expert * sizeof(float)) {
            fprintf(stderr, "ds4: Metal router select received undersized buffers\n");
            return 0;
        }

        uint64_t bias_inner = 0;
        uint64_t hash_inner = 0;
        id<MTLBuffer> biasbuf = nil;
        id<MTLBuffer> hashbuf = nil;
        NSUInteger bias_set_offset = 0;
        NSUInteger hash_set_offset = 0;
        if (has_bias && !hash_mode) {
            const uint64_t bias_bytes = (uint64_t)n_expert * sizeof(float);
            biasbuf = ds4_gpu_wrap_model_range(model_map, model_size, bias_offset, bias_bytes, &bias_inner);
            if (!biasbuf) return 0;
            bias_set_offset = (NSUInteger)bias_inner;
        }
        if (hash_mode) {
            const uint64_t hash_bytes = (uint64_t)hash_rows * hash_width * sizeof(int32_t);
            hashbuf = ds4_gpu_wrap_model_range(model_map, model_size, hash_offset, hash_bytes, &hash_inner);
            if (!hashbuf) return 0;
            hash_set_offset = (NSUInteger)hash_inner;
        }

        const bool had_batch = g_batch_cb != nil;
        if (!had_batch && ds4_gpu_begin_commands() == 0) return 0;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        const int32_t token_i32 = (int32_t)token;
        int ok = cb &&
                 ds4_gpu_encode_router_select(cb,
                                                      selected,
                                                      weights,
                                                      probs,
                                                      logitsbuf,
                                                      ds4_gpu_tensor_offset(logits),
                                                      biasbuf,
                                                      bias_set_offset,
                                                      hashbuf,
                                                      hash_set_offset,
                                                      nil,
                                                      0,
                                                      &token_i32,
                                                      hash_rows,
                                                      hash_width,
                                                      1,
                                                      n_expert,
                                                      n_expert_used,
                                                      expert_weight_scale,
                                                      has_bias && !hash_mode,
                                                      hash_mode);
        if (!had_batch) {
            ok = ds4_gpu_end_commands() != 0 && ok;
        }
        if (!ok) return 0;
    }

    return 1;
}

int ds4_gpu_router_select_batch_tensor(
        ds4_gpu_tensor       *selected,
        ds4_gpu_tensor       *weights,
