            ds4_gpu_tensor_bytes(logits) < (uint64_t)n_tokens * n_expert * sizeof(float) ||
            ds4_gpu_tensor_bytes(selected) < (uint64_t)n_tokens * n_expert_used * sizeof(int) ||
            ds4_gpu_tensor_bytes(weights) < (uint64_t)n_tokens * n_expert_used * sizeof(float) ||
            ds4_gpu_tensor_bytes(probs) < (uint64_t)n_tokens * n_expert * sizeof(float) ||
            ds4_gpu_tensor_bytes(tokens) < (uint64_t)n_tokens * sizeof(int32_t)) {
            fprintf(stderr, "ds4: Metal router batch select received undersized buffers\n");
            return 0;
        }

        uint64_t bias_inner = 0;
        uint64_t hash_inner = 0;
        id<MTLBuffer> biasbuf = nil;
        id<MTLBuffer> hashbuf = nil;
        NSUInteger bias_set_offset = 0;
        NSUInteger hash_set_offset = 0;
        if (has_bias && !hash_mode) {
            const uint64_t bias_bytes = (uint64_t)n_expert * sizeof(float);
            biasbuf = ds4_gpu_wrap_model_range(model_map, model_size, bias_offset, bias_bytes, &bias_inner);
            if (!biasbuf) return 0;
            bias_set_offset = (NSUInteger)bias_inner;
        }
        if (hash_mode) {
            const uint64_t hash_bytes = (uint64_t)hash_rows * hash_width * sizeof(int32_t);
            hashbuf = ds4_gpu_wrap_model_range(model_map, model_size, hash_offset, hash_bytes, &hash_inner);
            if (!hashbuf) return 0;
            hash_set_offset = (NSUInteger)hash_inner;
        }

        const bool had_batch = g_batch_cb != nil;
        if (!had_batch && ds4_gpu_begin_commands() == 0) return 0;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        int ok = cb &&
                 ds4_gpu_encode_router_select(cb,
                                                      selected,
                                                      weights,
                                                      probs,
                                                      logitsbuf,
                                                      ds4_gpu_tensor_offset(logits),
                                                      biasbuf,
                                                      bias_set_offset,
                                                      hashbuf,
                                                      hash_set_offset,
                                                      tokensbuf,
                                                      ds4_gpu_tensor_offset(tokens),
                                                      NULL,
                                                      hash_rows,
                                                      hash_width,
                                                      n_tokens,
                                                      n_expert,
                                                      n_expert_used,
                                                      expert_weight_scale,
                                                      has_bias && !hash_mode,
                                                      hash_mode);
        if (!had_batch) {
            ok = ds4_gpu_end_commands() != 0 && ok;
        }
        if (!ok) return 0;
    }

    return 1;
}

int ds4_gpu_glm_router_select_tensor(
        ds4_gpu_tensor       *selected,
        ds4_gpu_tensor       *weights,
        ds4_gpu_tensor       *probs,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                bias_offset,
        uint32_t                n_expert,
        uint32_t                n_expert_used,
        float                   expert_weight_scale,
        bool                    has_bias,
        const ds4_gpu_tensor *logits,
        uint32_t                n_tokens) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!selected || !weights || !probs || !logits ||
        n_expert == 0 || n_expert_used == 0 || n_tokens == 0 ||
        n_expert_used > n_expert) {
        return 0;
    }
    if (has_bias && !model_map) return 0;

    @autoreleasepool {
        id<MTLBuffer> logitsbuf = ds4_gpu_tensor_buffer(logits);
        id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> probsbuf = ds4_gpu_tensor_buffer(probs);
        const uint64_t logits_bytes = (uint64_t)n_tokens * n_expert * sizeof(float);
        const uint64_t selected_bytes = (uint64_t)n_tokens * n_expert_used * sizeof(int32_t);
        const uint64_t weights_bytes = (uint64_t)n_tokens * n_expert_used * sizeof(float);
        const uint64_t probs_bytes = logits_bytes;
        if (!logitsbuf || !selectedbuf || !weightsbuf || !probsbuf ||
            ds4_gpu_tensor_bytes(logits) < logits_bytes ||
            ds4_gpu_tensor_bytes(selected) < selected_bytes ||
            ds4_gpu_tensor_bytes(weights) < weights_bytes ||
            ds4_gpu_tensor_bytes(probs) < probs_bytes) {
            fprintf(stderr, "ds4: Metal GLM router received undersized buffers\n");
            return 0;
        }

        id<MTLBuffer> biasbuf = nil;
        NSUInteger bias_set_offset = 0;
        uint64_t bias_inner = 0;
        if (has_bias) {
            const uint64_t bias_bytes = (uint64_t)n_expert * sizeof(float);
            biasbuf = ds4_gpu_wrap_model_range(model_map, model_size, bias_offset, bias_bytes, &bias_inner);
            if (!biasbuf) return 0;
            bias_set_offset = (NSUInteger)bias_inner;
        }

        const NSUInteger sum_bytes = (NSUInteger)n_tokens * sizeof(float);
        if (!ds4_gpu_ensure_scratch_buffer(&g_router_weight_sum_buffer,
                                             &g_router_weight_sum_bytes,
                                             sum_bytes,
                                             "ds4_glm_router_weight_sum")) {
            return 0;
        }

        const bool had_batch = g_batch_cb != nil;
        if (!had_batch && ds4_gpu_begin_commands() == 0) return 0;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        DS4MetalTensor *selection_view = nil;
        id<MTLComputeCommandEncoder> enc = nil;

        int ok = ds4_gpu_encode_unary_f32_rows(cb,
                                                g_unary_sigmoid_pipeline,
                                                logitsbuf,
                                                ds4_gpu_tensor_offset(logits),
                                                probsbuf,
                                                ds4_gpu_tensor_offset(probs),
                                                n_expert,
                                                n_tokens,
                                                1,
                                                0.0f,
                                                0.0f);
        if (!ok) goto finish;

        ds4_gpu_tensor *score_tensor = probs;
        if (has_bias) {
            if (!ds4_gpu_ensure_scratch_buffer(&g_router_selection_buffer,
                                                 &g_router_selection_bytes,
                                                 (NSUInteger)probs_bytes,
                                                 "ds4_glm_router_selection")) {
                ok = 0;
                goto finish;
            }

            ds4_gpu_bin_args add_args =
                ds4_gpu_make_bin_rows_args(n_expert, n_tokens, n_expert);
            ok = ds4_gpu_encode_bin_f32_rows(cb,
                                               g_add_pipeline,
                                               &add_args,
                                               probsbuf,
                                               ds4_gpu_tensor_offset(probs),
                                               biasbuf,
                                               bias_set_offset,
                                               g_router_selection_buffer,
                                               0);
            if (!ok) goto finish;

            selection_view = [DS4MetalTensor new];
            selection_view.buffer = g_router_selection_buffer;
            selection_view.offset = 0;
            selection_view.bytes = probs_bytes;
            selection_view.owner = 0;
            score_tensor = (__bridge ds4_gpu_tensor *)selection_view;
        }

        ok = ds4_gpu_indexer_topk_tensor(selected,
                                         score_tensor,
                                         n_expert,
                                         n_tokens,
                                         n_expert_used) &&
             ds4_gpu_encode_get_rows_f32_router_weights(cb,
                                                         probsbuf,
                                                         ds4_gpu_tensor_offset(probs),
                                                         selectedbuf,
                                                         ds4_gpu_tensor_offset(selected),
                                                         weightsbuf,
                                                         ds4_gpu_tensor_offset(weights),
                                                         n_expert,
                                                         n_expert_used,
                                                         n_tokens) &&
             ds4_gpu_encode_sum_rows_f32(cb,
                                           weightsbuf,
                                           ds4_gpu_tensor_offset(weights),
                                           g_router_weight_sum_buffer,
                                           0,
                                           n_expert_used,
                                           n_tokens) &&
             ds4_gpu_encode_unary_f32_rows(cb,
                                             g_unary_clamp_pipeline,
                                             g_router_weight_sum_buffer,
                                             0,
                                             g_router_weight_sum_buffer,
                                             0,
                                             1,
                                             n_tokens,
                                             0,
                                             6.103515625e-5f,
                                             ds4_gpu_positive_infinity());
        if (!ok) goto finish;

        ds4_gpu_bin_args div_args = ds4_gpu_make_bin_rowwise_scalar_args(n_expert_used, n_tokens);
        ds4_gpu_bin_args scale_args = ds4_gpu_make_bin_rows_args(n_expert_used, n_tokens, 1);
        ok = ds4_gpu_encode_bin_f32_rows(cb,
                                           g_bin_div_row_pipeline,
                                           &div_args,
                                           weightsbuf,
                                           ds4_gpu_tensor_offset(weights),
                                           g_router_weight_sum_buffer,
                                           0,
                                           weightsbuf,
                                           ds4_gpu_tensor_offset(weights));
        if (!ok) goto finish;

        enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_bin_mul_scalar_pipeline];
        [enc setBytes:&scale_args length:sizeof(scale_args) atIndex:0];
        [enc setBuffer:weightsbuf offset:ds4_gpu_tensor_offset(weights) atIndex:1];
        [enc setBytes:&expert_weight_scale length:sizeof(expert_weight_scale) atIndex:2];
        [enc setBuffer:weightsbuf offset:ds4_gpu_tensor_offset(weights) atIndex:3];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)scale_args.ne1,
                                              (NSUInteger)scale_args.ne2,
                                              (NSUInteger)scale_args.ne3)
             threadsPerThreadgroup:MTLSizeMake(ds4_gpu_bin_threads(n_expert_used, g_bin_mul_scalar_pipeline), 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

finish:
        if (!had_batch) {
            ok = ds4_gpu_end_commands() != 0 && ok;
        }
        if (!ok) return 0;
    }

    return 1;
}

int ds4_gpu_routed_moe_one_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                gate_offset,
        uint64_t                up_offset,
        uint64_t                down_offset,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t                n_total_expert,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !gate || !up || !mid || !x || !model_map || !selected || !weights ||
        n_total_expert == 0 || n_total_expert > DS4_METAL_N_EXPERT ||
        n_expert == 0 || n_expert > DS4_METAL_N_EXPERT_USED ||
        n_expert > n_total_expert) {
        return 0;
    }
    if ((expert_in_dim % 256u) != 0 || (expert_mid_dim % 256u) != 0) return 0;

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> gatebuf = ds4_gpu_tensor_buffer(gate);
        id<MTLBuffer> upbuf = ds4_gpu_tensor_buffer(up);
        id<MTLBuffer> midbuf = ds4_gpu_tensor_buffer(mid);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> expertsbuf = ds4_gpu_tensor_buffer(experts);
        id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        const uint64_t x_bytes = (uint64_t)expert_in_dim * sizeof(float);
        const uint64_t mid_bytes = (uint64_t)n_expert * expert_mid_dim * sizeof(float);
        const uint64_t out_bytes = (uint64_t)out_dim * sizeof(float);
        if (!xbuf || !gatebuf || !upbuf || !midbuf || !outbuf || !selectedbuf || !weightsbuf ||
            ds4_gpu_tensor_bytes(x) < x_bytes ||
            ds4_gpu_tensor_bytes(gate) < mid_bytes ||
            ds4_gpu_tensor_bytes(up) < mid_bytes ||
            ds4_gpu_tensor_bytes(mid) < mid_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes ||
            ds4_gpu_tensor_bytes(selected) < (uint64_t)n_expert * sizeof(int) ||
            ds4_gpu_tensor_bytes(weights) < (uint64_t)n_expert * sizeof(float)) {
            fprintf(stderr, "ds4: Metal routed tensor MoE received undersized activation buffers\n");
            return 0;
        }
        if (n_expert > 1 &&
            (!expertsbuf ||
             ds4_gpu_tensor_bytes(experts) < (uint64_t)n_expert * out_dim * sizeof(float))) {
            fprintf(stderr, "ds4: Metal routed tensor MoE received undersized expert output buffer\n");
            return 0;
        }

        const uint64_t gate_tensor_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
        const uint64_t down_tensor_bytes = (uint64_t)n_total_expert * down_expert_bytes;
        uint64_t gate_inner = 0;
        uint64_t up_inner = 0;
        uint64_t down_inner = 0;
        id<MTLBuffer> gate_buf = ds4_gpu_wrap_model_range(model_map, model_size, gate_offset, gate_tensor_bytes, &gate_inner);
        id<MTLBuffer> up_buf = ds4_gpu_wrap_model_range(model_map, model_size, up_offset, gate_tensor_bytes, &up_inner);
        id<MTLBuffer> down_buf = ds4_gpu_wrap_model_range(model_map, model_size, down_offset, down_tensor_bytes, &down_inner);
        if (!gate_buf || !up_buf || !down_buf) return 0;

        const uint32_t n_tokens = 1;
        const uint32_t pair_rows = n_tokens * n_expert;
        const uint64_t down_scratch_bytes = (uint64_t)pair_rows * out_dim * sizeof(float);
        if ((n_expert > 1 && !expertsbuf &&
             !ds4_gpu_ensure_scratch_buffer(&g_moe_down_scratch_buffer,
                                              &g_moe_down_scratch_bytes,
                                              (NSUInteger)down_scratch_bytes,
                                              "ds4_moe_down_scratch"))) {
            return 0;
        }

        const uint32_t gate_nr0 = ds4_gpu_routed_mv_nr0(gate_type);
        const uint32_t down_nr0 = ds4_gpu_routed_mv_nr0(down_type);
        id<MTLComputePipelineState> gate_mv_pipeline = ds4_gpu_routed_mv_pipeline(gate_type);
        id<MTLComputePipelineState> down_mv_pipeline = ds4_gpu_routed_mv_pipeline(down_type);
        if (gate_nr0 == 0 || down_nr0 == 0 || !gate_mv_pipeline || !down_mv_pipeline) {
            fprintf(stderr, "ds4: unsupported Metal routed MoE quant types gate=%u down=%u\n",
                    gate_type, down_type);
            return 0;
        }

        ds4_gpu_mul_mv_id_args gate_args =
            ds4_gpu_make_mul_mv_id_args(expert_in_dim, expert_mid_dim, n_total_expert,
                                          gate_row_bytes, gate_expert_bytes,
                                          1, n_expert, n_tokens, gate_nr0);
        ds4_gpu_mul_mv_id_args down_args =
            ds4_gpu_make_mul_mv_id_args(expert_mid_dim, out_dim, n_total_expert,
                                          down_row_bytes, down_expert_bytes,
                                          n_expert, n_expert, n_tokens, down_nr0);

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        const NSUInteger gate_smem = ds4_gpu_routed_mv_smem(gate_type);
        const NSUInteger down_smem = ds4_gpu_routed_mv_smem(down_type);
        int ok = 1;
        const bool write_clamped_moe =
            getenv("DS4_METAL_MOE_WRITE_CLAMPED_ACT") != NULL;
        id<MTLComputePipelineState> pair_swiglu_pipeline = nil;
        if (gate_type == DS4_METAL_TENSOR_IQ2_XXS) {
            pair_swiglu_pipeline = g_moe_mul_mv_id_iq2_xxs_pair_swiglu_pipeline;
        } else if (gate_type == DS4_METAL_TENSOR_Q4_K) {
            pair_swiglu_pipeline = g_moe_mul_mv_id_q4_k_pair_swiglu_pipeline;
        } else if (gate_type == DS4_METAL_TENSOR_MXFP4 &&
                   ds4_gpu_env_bool("DS4_METAL_ENABLE_MXFP4_PAIR_SWIGLU") > 0) {
            pair_swiglu_pipeline = g_moe_mul_mv_id_mxfp4_pair_swiglu_pipeline;
        }
        const bool fuse_pair_swiglu =
            !g_quality_mode &&
            !write_clamped_moe &&
            getenv("DS4_METAL_DISABLE_ROUTED_PAIR_SWIGLU_FUSION") == NULL &&
            pair_swiglu_pipeline != nil;
        if (fuse_pair_swiglu) {
            ds4_gpu_dsv4_moe_swiglu_weight_args act_args = {
                .width = expert_mid_dim,
                .rows = pair_rows,
                .gate_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .up_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .mid_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .weight_stride = sizeof(float),
                .write_clamped = 0,
                .clamp_value = clamp,
            };
            ok = ds4_gpu_encode_mul_mv_id_pair_swiglu_decode_replay(cb,
                                                                      pair_swiglu_pipeline,
                                                                      &gate_args,
                                                                      &act_args,
                                                                      gate_buf,
                                                                      (NSUInteger)gate_inner,
                                                                      up_buf,
                                                                      (NSUInteger)up_inner,
                                                                      xbuf,
                                                                      ds4_gpu_tensor_offset(x),
                                                                      gatebuf,
                                                                      ds4_gpu_tensor_offset(gate),
                                                                      upbuf,
                                                                      ds4_gpu_tensor_offset(up),
                                                                      midbuf,
                                                                      ds4_gpu_tensor_offset(mid),
                                                                      selectedbuf,
                                                                      ds4_gpu_tensor_offset(selected),
                                                                      weightsbuf,
                                                                      ds4_gpu_tensor_offset(weights),
                                                                      gate_smem,
                                                                      2,
                                                                      false);
        } else if (!g_quality_mode &&
                   gate_type == DS4_METAL_TENSOR_IQ2_XXS &&
                   g_moe_mul_mv_id_iq2_xxs_pair_pipeline) {
            ok = ds4_gpu_encode_mul_mv_id_pair_decode_replay(cb,
                                                              g_moe_mul_mv_id_iq2_xxs_pair_pipeline,
                                                              &gate_args,
                                                              gate_buf,
                                                              (NSUInteger)gate_inner,
                                                              up_buf,
                                                              (NSUInteger)up_inner,
                                                              xbuf,
                                                              ds4_gpu_tensor_offset(x),
                                                              gatebuf,
                                                              ds4_gpu_tensor_offset(gate),
                                                              upbuf,
                                                              ds4_gpu_tensor_offset(up),
                                                              selectedbuf,
                                                              ds4_gpu_tensor_offset(selected),
                                                              gate_smem,
                                                              2,
                                                              false);
        } else if (!g_quality_mode &&
                   gate_type == DS4_METAL_TENSOR_Q4_K &&
                   g_moe_mul_mv_id_q4_k_pair_pipeline) {
            ok = ds4_gpu_encode_mul_mv_id_pair_decode_replay(cb,
                                                              g_moe_mul_mv_id_q4_k_pair_pipeline,
                                                              &gate_args,
                                                              gate_buf,
                                                              (NSUInteger)gate_inner,
                                                              up_buf,
                                                              (NSUInteger)up_inner,
                                                              xbuf,
                                                              ds4_gpu_tensor_offset(x),
                                                              gatebuf,
                                                              ds4_gpu_tensor_offset(gate),
                                                              upbuf,
                                                              ds4_gpu_tensor_offset(up),
                                                              selectedbuf,
                                                              ds4_gpu_tensor_offset(selected),
                                                              gate_smem,
                                                              2,
                                                              false);
        } else {
            ok = ds4_gpu_encode_mul_mv_id_decode_replay(cb,
                                                         gate_mv_pipeline,
                                                         &gate_args,
                                                         gate_buf,
                                                         (NSUInteger)gate_inner,
                                                         xbuf,
                                                         ds4_gpu_tensor_offset(x),
                                                         gatebuf,
                                                         ds4_gpu_tensor_offset(gate),
                                                         selectedbuf,
                                                         ds4_gpu_tensor_offset(selected),
                                                         gate_smem,
                                                         2,
                                                         false) &&
                 ds4_gpu_encode_mul_mv_id_decode_replay(cb,
                                                         gate_mv_pipeline,
                                                         &gate_args,
                                                         up_buf,
                                                         (NSUInteger)up_inner,
                                                         xbuf,
                                                         ds4_gpu_tensor_offset(x),
                                                         upbuf,
                                                         ds4_gpu_tensor_offset(up),
                                                         selectedbuf,
                                                         ds4_gpu_tensor_offset(selected),
                                                         gate_smem,
                                                         2,
                                                         false);
        }
        if (ok && !fuse_pair_swiglu) {
            ok = ds4_gpu_encode_moe_swiglu_weight(cb,
                                                    gatebuf,
                                                    ds4_gpu_tensor_offset(gate),
                                                    upbuf,
                                                    ds4_gpu_tensor_offset(up),
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    weightsbuf,
                                                    ds4_gpu_tensor_offset(weights),
                                                    expert_mid_dim,
                                                    pair_rows,
                                                    clamp,
                                                    false);
        }

        id<MTLBuffer> down_dst = n_expert == 1 ? outbuf : (expertsbuf ? expertsbuf : g_moe_down_scratch_buffer);
        NSUInteger down_dst_off = n_expert == 1 ? ds4_gpu_tensor_offset(out) :
            (expertsbuf ? ds4_gpu_tensor_offset(experts) : 0);
        id<MTLComputePipelineState> down_sum6_pipeline = nil;
        if (down_type == DS4_METAL_TENSOR_Q2_K) {
            down_sum6_pipeline = g_moe_mul_mv_id_q2_k_sum6_pipeline;
        } else if (down_type == DS4_METAL_TENSOR_Q4_K) {
            down_sum6_pipeline = g_moe_mul_mv_id_q4_k_sum6_pipeline;
        } else if (down_type == DS4_METAL_TENSOR_MXFP4) {
            down_sum6_pipeline = g_moe_mul_mv_id_mxfp4_sum6_pipeline;
        }
        const bool direct_down_sum =
            !g_quality_mode &&
            ds4_gpu_env_bool("DS4_METAL_ENABLE_ROUTED_DOWN_SUM6") > 0 &&
            getenv("DS4_METAL_DISABLE_ROUTED_DOWN_SUM6") == NULL &&
            n_expert == 6 &&
            down_sum6_pipeline != nil;
        if (ok && direct_down_sum) {
            ok = ds4_gpu_encode_mul_mv_id_sum6_decode_replay(cb,
                                                              down_sum6_pipeline,
                                                              &down_args,
                                                              down_buf,
                                                              (NSUInteger)down_inner,
                                                              midbuf,
                                                              ds4_gpu_tensor_offset(mid),
                                                              outbuf,
                                                              ds4_gpu_tensor_offset(out),
                                                              selectedbuf,
                                                              ds4_gpu_tensor_offset(selected),
                                                              down_smem,
                                                              2);
        } else if (ok) {
            ok = ds4_gpu_encode_mul_mv_id_decode_replay(cb,
                                                         down_mv_pipeline,
                                                         &down_args,
                                                         down_buf,
                                                         (NSUInteger)down_inner,
                                                         midbuf,
                                                         ds4_gpu_tensor_offset(mid),
                                                         down_dst,
                                                         down_dst_off,
                                                         selectedbuf,
                                                         ds4_gpu_tensor_offset(selected),
                                                         down_smem,
                                                         2,
                                                         false);
        }
        if (ok && n_expert > 1 && !direct_down_sum) {
            ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                       down_dst,
                                                       down_dst_off,
                                                       outbuf,
                                                       ds4_gpu_tensor_offset(out),
                                                       out_dim,
                                                       n_expert,
                                                       n_tokens);
        }
        if (!ok) return 0;

        if (!ds4_gpu_finish_command_buffer(cb, owned, "routed tensor MoE")) return 0;
    }

    return 1;
}

static int ds4_gpu_routed_moe_banked_tensor_impl(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        ds4_gpu_tensor       *gate_bank,
        ds4_gpu_tensor       *up_bank,
        ds4_gpu_tensor       *down_bank,
        uint32_t                n_slots,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_slot_stride,
        uint64_t                gate_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_slot_stride,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x,
        uint32_t                n_tokens) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !gate || !up || !mid || !x || !gate_bank || !up_bank ||
        !down_bank || !selected || !weights || n_slots == 0 ||
        n_tokens == 0 || n_expert == 0 || n_expert > 8) {
        return 0;
    }
    if ((expert_in_dim % 256u) != 0 || (expert_mid_dim % 256u) != 0) return 0;
    if (gate_slot_stride == 0) gate_slot_stride = gate_expert_bytes;
    if (down_slot_stride == 0) down_slot_stride = down_expert_bytes;
    if ((n_slots - 1ull) > (UINT64_MAX - gate_expert_bytes) / gate_slot_stride ||
        (n_slots - 1ull) > (UINT64_MAX - down_expert_bytes) / down_slot_stride) {
        return 0;
    }
    const uint64_t gate_bank_needed = (uint64_t)(n_slots - 1u) * gate_slot_stride + gate_expert_bytes;
    const uint64_t down_bank_needed = (uint64_t)(n_slots - 1u) * down_slot_stride + down_expert_bytes;

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> gatebuf = ds4_gpu_tensor_buffer(gate);
        id<MTLBuffer> upbuf = ds4_gpu_tensor_buffer(up);
        id<MTLBuffer> midbuf = ds4_gpu_tensor_buffer(mid);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> expertsbuf = ds4_gpu_tensor_buffer(experts);
        id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> gate_buf = ds4_gpu_tensor_buffer(gate_bank);
        id<MTLBuffer> up_buf = ds4_gpu_tensor_buffer(up_bank);
        id<MTLBuffer> down_buf = ds4_gpu_tensor_buffer(down_bank);
        const uint64_t x_bytes = (uint64_t)n_tokens * expert_in_dim * sizeof(float);
        const uint64_t mid_bytes = (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float);
        const uint64_t out_bytes = (uint64_t)n_tokens * out_dim * sizeof(float);
        const uint64_t selected_bytes = (uint64_t)n_tokens * n_expert * sizeof(int32_t);
        const uint64_t weights_bytes = (uint64_t)n_tokens * n_expert * sizeof(float);
        if (!xbuf || !gatebuf || !upbuf || !midbuf || !outbuf ||
            !selectedbuf || !weightsbuf || !gate_buf || !up_buf || !down_buf ||
            ds4_gpu_tensor_bytes(x) < x_bytes ||
            ds4_gpu_tensor_bytes(gate) < mid_bytes ||
            ds4_gpu_tensor_bytes(up) < mid_bytes ||
            ds4_gpu_tensor_bytes(mid) < mid_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes ||
            ds4_gpu_tensor_bytes(selected) < selected_bytes ||
            ds4_gpu_tensor_bytes(weights) < weights_bytes ||
            ds4_gpu_tensor_bytes(gate_bank) < gate_bank_needed ||
            ds4_gpu_tensor_bytes(up_bank) < gate_bank_needed ||
            ds4_gpu_tensor_bytes(down_bank) < down_bank_needed) {
            fprintf(stderr, "ds4: Metal banked routed tensor MoE received undersized buffers\n");
            return 0;
        }
        if (n_expert > 1 &&
            (!expertsbuf ||
             ds4_gpu_tensor_bytes(experts) < (uint64_t)n_tokens * n_expert * out_dim * sizeof(float))) {
            fprintf(stderr, "ds4: Metal banked routed tensor MoE received undersized expert output buffer\n");
            return 0;
        }

        const uint64_t gate_inner = ds4_gpu_tensor_offset(gate_bank);
        const uint64_t up_inner = ds4_gpu_tensor_offset(up_bank);
        const uint64_t down_inner = ds4_gpu_tensor_offset(down_bank);
        const int native_plane_split =
            ds4_gpu_tensor_mxfp4_plane_split(gate_bank) &&
            ds4_gpu_tensor_mxfp4_plane_split(up_bank) &&
            ds4_gpu_tensor_mxfp4_plane_split(down_bank);
        const int hybrid_down_plane_split =
            !ds4_gpu_tensor_mxfp4_plane_split(gate_bank) &&
            !ds4_gpu_tensor_mxfp4_plane_split(up_bank) &&
            ds4_gpu_tensor_mxfp4_plane_split(down_bank);
        const int hybrid_mxfp4_down =
            gate_type == DS4_METAL_TENSOR_IQ2_XXS &&
            down_type == DS4_METAL_TENSOR_MXFP4;
        if (hybrid_mxfp4_down && ds4_gpu_mxfp4_native_requested()) {
            ds4_gpu_ensure_mxfp4_native_library();
        }
        const uint64_t expected_down_row =
            (uint64_t)(expert_mid_dim / 32u) * 17u;
        const int hybrid_native_down_sum =
            hybrid_mxfp4_down &&
            hybrid_down_plane_split &&
            ds4_gpu_mxfp4_native_requested() &&
            ds4_gpu_has_native_mxfp4() &&
            ((n_tokens == 1 && g_mxfp4_plane_id_sum6_pipeline != nil) ||
             (n_tokens > 1 && g_mxfp4_plane_id_batch_sum6_pipeline != nil)) &&
            expert_mid_dim != 0 &&
            (expert_mid_dim % 32u) == 0 &&
            down_row_bytes == expected_down_row &&
            down_slot_stride <= UINT32_MAX;

        const uint32_t pair_rows = n_tokens * n_expert;
        const uint64_t down_scratch_bytes = (uint64_t)pair_rows * out_dim * sizeof(float);
        if ((n_expert > 1 && !expertsbuf &&
             !ds4_gpu_ensure_scratch_buffer(&g_moe_down_scratch_buffer,
                                              &g_moe_down_scratch_bytes,
                                              (NSUInteger)down_scratch_bytes,
                                              "ds4_moe_down_scratch"))) {
            return 0;
        }

        if (n_tokens == 1 &&
            ds4_gpu_mxfp4_native_decode2_available(gate_type,
                                                   down_type,
                                                   gate_row_bytes,
                                                   down_row_bytes,
                                                   expert_in_dim,
                                                   expert_mid_dim,
                                                   out_dim,
                                                   n_expert,
                                                   native_plane_split) &&
            gate_slot_stride <= UINT32_MAX &&
            down_slot_stride <= UINT32_MAX) {
            const uint64_t gate_scales_off64 =
                gate_inner + (uint64_t)expert_in_dim * expert_mid_dim / 2u;
            const uint64_t up_scales_off64 =
                up_inner + (uint64_t)expert_in_dim * expert_mid_dim / 2u;
            const uint64_t down_scales_off64 =
                down_inner + (uint64_t)expert_mid_dim * out_dim / 2u;
            if (gate_inner > NSUIntegerMax ||
                up_inner > NSUIntegerMax ||
                down_inner > NSUIntegerMax ||
                gate_scales_off64 > NSUIntegerMax ||
                up_scales_off64 > NSUIntegerMax ||
                down_scales_off64 > NSUIntegerMax) {
                return 0;
            }
            int owned = 0;
            id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
            if (!cb) return 0;
            const uint32_t write_clamped =
                getenv("DS4_METAL_MOE_WRITE_CLAMPED_ACT") != NULL ? 1u : 0u;
            const int ok = ds4_gpu_encode_mxfp4_plane_id_decode2(
                    cb,
                    xbuf,
                    ds4_gpu_tensor_offset(x),
                    gate_buf,
                    (NSUInteger)gate_inner,
                    (NSUInteger)gate_scales_off64,
                    up_buf,
                    (NSUInteger)up_inner,
                    (NSUInteger)up_scales_off64,
                    selectedbuf,
                    ds4_gpu_tensor_offset(selected),
                    weightsbuf,
                    ds4_gpu_tensor_offset(weights),
                    gatebuf,
                    ds4_gpu_tensor_offset(gate),
                    upbuf,
                    ds4_gpu_tensor_offset(up),
                    midbuf,
                    ds4_gpu_tensor_offset(mid),
                    down_buf,
                    (NSUInteger)down_inner,
                    (NSUInteger)down_scales_off64,
                    outbuf,
                    ds4_gpu_tensor_offset(out),
                    expert_in_dim,
                    expert_mid_dim,
                    (uint32_t)gate_slot_stride,
                    (uint32_t)down_slot_stride,
                    out_dim,
                    clamp,
                    write_clamped);
            if (!ok) return 0;
            ds4_gpu_mxfp4_native_decode2_log_once("banked");
            if (!ds4_gpu_finish_command_buffer(cb, owned, "native MXFP4 banked routed tensor MoE decode2")) return 0;
            return 1;
        }

        if (n_tokens == 1 &&
            ds4_gpu_mxfp4_native_decode_available(gate_type,
                                                  down_type,
                                                  gate_row_bytes,
                                                  down_row_bytes,
                                                  expert_in_dim,
                                                  expert_mid_dim,
                                                  out_dim) &&
            gate_slot_stride <= UINT32_MAX &&
            down_slot_stride <= UINT32_MAX) {
            if (!ds4_gpu_mxfp4_native_decode_ensure_scratch(expert_in_dim,
                                                            expert_mid_dim,
                                                            out_dim)) {
                return 0;
            }
            int owned = 0;
            id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
            if (!cb) return 0;
            id<MTLBuffer> down_dst =
                n_expert == 1 ? outbuf : (expertsbuf ? expertsbuf : g_moe_down_scratch_buffer);
            NSUInteger down_dst_base =
                n_expert == 1 ? ds4_gpu_tensor_offset(out) :
                (expertsbuf ? ds4_gpu_tensor_offset(experts) : 0);
            const NSUInteger gate_base_off = ds4_gpu_tensor_offset(gate);
            const NSUInteger up_base_off = ds4_gpu_tensor_offset(up);
            const NSUInteger mid_base_off = ds4_gpu_tensor_offset(mid);
            const NSUInteger weights_base_off = ds4_gpu_tensor_offset(weights);
            const NSUInteger selected_base_off = ds4_gpu_tensor_offset(selected);
            const uint64_t mid_row_bytes = (uint64_t)expert_mid_dim * sizeof(float);
            const uint64_t out_row_bytes = (uint64_t)out_dim * sizeof(float);
            int ok = ds4_gpu_encode_cpy_f32_f16_1d(cb,
                                                   xbuf,
                                                   ds4_gpu_tensor_offset(x),
                                                   g_mpp_prefill_x_half_buffer,
                                                   0,
                                                   expert_in_dim);
            for (uint32_t k = 0; ok && k < n_expert; k++) {
                const NSUInteger row_mid_off =
                    (NSUInteger)((uint64_t)k * mid_row_bytes);
                const NSUInteger row_out_off =
                    (NSUInteger)((uint64_t)k * out_row_bytes);
                ok = ds4_gpu_encode_mxfp4_native_decode_route(
                         cb,
                         g_mpp_prefill_x_half_buffer,
                         gate_buf,
                         (NSUInteger)gate_inner,
                         up_buf,
                         (NSUInteger)up_inner,
                         down_buf,
                         (NSUInteger)down_inner,
                         selectedbuf,
                         selected_base_off,
                         k,
                         gate_slot_stride,
                         down_slot_stride,
                         native_plane_split,
                         gatebuf,
                         gate_base_off + row_mid_off,
                         upbuf,
                         up_base_off + row_mid_off,
                         midbuf,
                         mid_base_off + row_mid_off,
                         weightsbuf,
                         weights_base_off + (NSUInteger)((uint64_t)k * sizeof(float)),
                         down_dst,
                         down_dst_base + (n_expert == 1 ? 0 : row_out_off),
                         expert_in_dim,
                         expert_mid_dim,
                         out_dim,
                         clamp);
            }
            if (ok && n_expert > 1) {
                ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                    down_dst,
                                                    down_dst_base,
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    out_dim,
                                                    n_expert,
                                                    n_tokens);
            }
            if (!ok) return 0;
            ds4_gpu_mxfp4_native_decode_log_once("banked", native_plane_split);
            if (!ds4_gpu_finish_command_buffer(cb, owned, "native MXFP4 banked routed tensor MoE")) return 0;
            return 1;
        }
        if (native_plane_split) {
            fprintf(stderr, "ds4: MXFP4_NATIVE plane-split banked decode cannot use legacy block kernels\n");
            return 0;
        }
        if (hybrid_mxfp4_down && hybrid_down_plane_split && !hybrid_native_down_sum) {
            static int s_warned_hybrid_missing_selected_sum6 = 0;
            if (!s_warned_hybrid_missing_selected_sum6 &&
                ds4_gpu_env_flag_enabled("DS4_DEBUG_RESUME")) {
                s_warned_hybrid_missing_selected_sum6 = 1;
                fprintf(stderr,
                        "ds4: hybrid IQ2/MXFP4 plane-split banked decode missing native selected sum6 support\n");
            }
            return 0;
        }

        const uint32_t gate_nr0 = ds4_gpu_routed_mv_nr0(gate_type);
        const uint32_t down_nr0 = ds4_gpu_routed_mv_nr0(down_type);
        id<MTLComputePipelineState> gate_mv_pipeline = ds4_gpu_routed_mv_pipeline(gate_type);
        id<MTLComputePipelineState> down_mv_pipeline = ds4_gpu_routed_mv_pipeline(down_type);
        if (gate_nr0 == 0 || down_nr0 == 0 || !gate_mv_pipeline || !down_mv_pipeline) {
            fprintf(stderr, "ds4: unsupported Metal banked routed MoE quant types gate=%u down=%u\n",
                    gate_type, down_type);
            return 0;
        }

        ds4_gpu_mul_mv_id_args gate_args =
            ds4_gpu_make_mul_mv_id_args(expert_in_dim, expert_mid_dim, n_slots,
                                          gate_row_bytes, gate_slot_stride,
                                          1, n_expert, n_tokens, gate_nr0);
        ds4_gpu_mul_mv_id_args down_args =
            ds4_gpu_make_mul_mv_id_args(expert_mid_dim, out_dim, n_slots,
                                          down_row_bytes, down_slot_stride,
                                          n_expert, n_expert, n_tokens, down_nr0);

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        const NSUInteger gate_smem = ds4_gpu_routed_mv_smem(gate_type);
        const NSUInteger down_smem = ds4_gpu_routed_mv_smem(down_type);
        int ok = 1;
        const bool write_clamped_moe =
            getenv("DS4_METAL_MOE_WRITE_CLAMPED_ACT") != NULL;
        id<MTLComputePipelineState> pair_swiglu_pipeline = nil;
        if (gate_type == DS4_METAL_TENSOR_IQ2_XXS) {
            pair_swiglu_pipeline = g_moe_mul_mv_id_iq2_xxs_pair_swiglu_pipeline;
        } else if (gate_type == DS4_METAL_TENSOR_Q4_K) {
            pair_swiglu_pipeline = g_moe_mul_mv_id_q4_k_pair_swiglu_pipeline;
        } else if (gate_type == DS4_METAL_TENSOR_MXFP4 &&
                   ds4_gpu_env_bool("DS4_METAL_ENABLE_MXFP4_PAIR_SWIGLU") > 0) {
            pair_swiglu_pipeline = g_moe_mul_mv_id_mxfp4_pair_swiglu_pipeline;
        }
        const bool fuse_pair_swiglu =
            !g_quality_mode &&
            !write_clamped_moe &&
            getenv("DS4_METAL_DISABLE_ROUTED_PAIR_SWIGLU_FUSION") == NULL &&
            pair_swiglu_pipeline != nil;
        if (fuse_pair_swiglu) {
            ds4_gpu_dsv4_moe_swiglu_weight_args act_args = {
                .width = expert_mid_dim,
                .rows = pair_rows,
                .gate_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .up_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .mid_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .weight_stride = sizeof(float),
                .write_clamped = 0,
                .clamp_value = clamp,
            };
            ok = ds4_gpu_encode_mul_mv_id_pair_swiglu_decode_replay(cb,
                                                                      pair_swiglu_pipeline,
                                                                      &gate_args,
                                                                      &act_args,
                                                                      gate_buf,
                                                                      (NSUInteger)gate_inner,
                                                                      up_buf,
                                                                      (NSUInteger)up_inner,
                                                                      xbuf,
                                                                      ds4_gpu_tensor_offset(x),
                                                                      gatebuf,
                                                                      ds4_gpu_tensor_offset(gate),
                                                                      upbuf,
                                                                      ds4_gpu_tensor_offset(up),
                                                                      midbuf,
                                                                      ds4_gpu_tensor_offset(mid),
                                                                      selectedbuf,
                                                                      ds4_gpu_tensor_offset(selected),
                                                                      weightsbuf,
                                                                      ds4_gpu_tensor_offset(weights),
                                                                      gate_smem,
                                                                      2,
                                                                      false);
        } else if (!g_quality_mode &&
                   gate_type == DS4_METAL_TENSOR_IQ2_XXS &&
                   g_moe_mul_mv_id_iq2_xxs_pair_pipeline) {
            ok = ds4_gpu_encode_mul_mv_id_pair_decode_replay(cb,
                                                              g_moe_mul_mv_id_iq2_xxs_pair_pipeline,
                                                              &gate_args,
                                                              gate_buf,
                                                              (NSUInteger)gate_inner,
                                                              up_buf,
                                                              (NSUInteger)up_inner,
                                                              xbuf,
                                                              ds4_gpu_tensor_offset(x),
                                                              gatebuf,
                                                              ds4_gpu_tensor_offset(gate),
                                                              upbuf,
                                                              ds4_gpu_tensor_offset(up),
                                                              selectedbuf,
                                                              ds4_gpu_tensor_offset(selected),
                                                              gate_smem,
                                                              2,
                                                              false);
        } else if (!g_quality_mode &&
                   gate_type == DS4_METAL_TENSOR_Q4_K &&
                   g_moe_mul_mv_id_q4_k_pair_pipeline) {
            ok = ds4_gpu_encode_mul_mv_id_pair_decode_replay(cb,
                                                              g_moe_mul_mv_id_q4_k_pair_pipeline,
                                                              &gate_args,
                                                              gate_buf,
                                                              (NSUInteger)gate_inner,
                                                              up_buf,
                                                              (NSUInteger)up_inner,
                                                              xbuf,
                                                              ds4_gpu_tensor_offset(x),
                                                              gatebuf,
                                                              ds4_gpu_tensor_offset(gate),
                                                              upbuf,
                                                              ds4_gpu_tensor_offset(up),
                                                              selectedbuf,
                                                              ds4_gpu_tensor_offset(selected),
                                                              gate_smem,
                                                              2,
                                                              false);
        } else {
            ok = ds4_gpu_encode_mul_mv_id_decode_replay(cb,
                                                         gate_mv_pipeline,
                                                         &gate_args,
                                                         gate_buf,
                                                         (NSUInteger)gate_inner,
                                                         xbuf,
                                                         ds4_gpu_tensor_offset(x),
                                                         gatebuf,
                                                         ds4_gpu_tensor_offset(gate),
                                                         selectedbuf,
                                                         ds4_gpu_tensor_offset(selected),
                                                         gate_smem,
                                                         2,
                                                         false) &&
                 ds4_gpu_encode_mul_mv_id_decode_replay(cb,
                                                         gate_mv_pipeline,
                                                         &gate_args,
                                                         up_buf,
                                                         (NSUInteger)up_inner,
                                                         xbuf,
                                                         ds4_gpu_tensor_offset(x),
                                                         upbuf,
                                                         ds4_gpu_tensor_offset(up),
                                                         selectedbuf,
                                                         ds4_gpu_tensor_offset(selected),
                                                         gate_smem,
                                                         2,
                                                         false);
        }
        if (ok && !fuse_pair_swiglu) {
            ok = ds4_gpu_encode_moe_swiglu_weight(cb,
                                                    gatebuf,
                                                    ds4_gpu_tensor_offset(gate),
                                                    upbuf,
                                                    ds4_gpu_tensor_offset(up),
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    weightsbuf,
                                                    ds4_gpu_tensor_offset(weights),
                                                    expert_mid_dim,
                                                    pair_rows,
                                                    clamp,
                                                    false);
        }

        id<MTLBuffer> down_dst = n_expert == 1 ? outbuf : (expertsbuf ? expertsbuf : g_moe_down_scratch_buffer);
        NSUInteger down_dst_off = n_expert == 1 ? ds4_gpu_tensor_offset(out) :
            (expertsbuf ? ds4_gpu_tensor_offset(experts) : 0);
        id<MTLComputePipelineState> down_sum6_pipeline = nil;
        if (down_type == DS4_METAL_TENSOR_Q2_K) {
            down_sum6_pipeline = g_moe_mul_mv_id_q2_k_sum6_pipeline;
        } else if (down_type == DS4_METAL_TENSOR_Q4_K) {
            down_sum6_pipeline = g_moe_mul_mv_id_q4_k_sum6_pipeline;
        } else if (down_type == DS4_METAL_TENSOR_MXFP4) {
            down_sum6_pipeline = g_moe_mul_mv_id_mxfp4_sum6_pipeline;
        }
        const bool direct_down_sum =
            !g_quality_mode &&
            getenv("DS4_METAL_DISABLE_ROUTED_DOWN_SUM6") == NULL &&
            n_expert == 6 &&
            down_sum6_pipeline != nil &&
            (n_tokens > 1 ||
             ds4_gpu_env_bool("DS4_METAL_ENABLE_ROUTED_DOWN_SUM6") > 0);
        if (ok && hybrid_native_down_sum) {
            const uint64_t down_scales_off64 =
                down_inner + (uint64_t)expert_mid_dim * (uint64_t)out_dim / 2u;
            if (down_inner > NSUIntegerMax || down_scales_off64 > NSUIntegerMax) {
                ok = 0;
            } else if (n_tokens > 1) {
                ok = ds4_gpu_encode_mxfp4_plane_id_batch_sum6(
                         cb,
                         down_buf,
                         (NSUInteger)down_inner,
                         (NSUInteger)down_scales_off64,
                         selectedbuf,
                         ds4_gpu_tensor_offset(selected),
                         midbuf,
                         ds4_gpu_tensor_offset(mid),
                         outbuf,
                         ds4_gpu_tensor_offset(out),
                         expert_mid_dim,
                         out_dim,
                         (uint32_t)down_slot_stride,
                         n_tokens);
            } else {
                ok = ds4_gpu_encode_mxfp4_plane_id_sum6(
                         cb,
                         down_buf,
                         (NSUInteger)down_inner,
                         (NSUInteger)down_scales_off64,
                         selectedbuf,
                         ds4_gpu_tensor_offset(selected),
                         midbuf,
                         ds4_gpu_tensor_offset(mid),
                         outbuf,
                         ds4_gpu_tensor_offset(out),
                         expert_mid_dim,
                         out_dim,
                         (uint32_t)down_slot_stride);
            }
        } else if (ok && direct_down_sum) {
            ok = ds4_gpu_encode_mul_mv_id_sum6_decode_replay(cb,
                                                              down_sum6_pipeline,
                                                              &down_args,
                                                              down_buf,
                                                              (NSUInteger)down_inner,
                                                              midbuf,
                                                              ds4_gpu_tensor_offset(mid),
                                                              outbuf,
                                                              ds4_gpu_tensor_offset(out),
                                                              selectedbuf,
                                                              ds4_gpu_tensor_offset(selected),
                                                              down_smem,
                                                              2);
        } else if (ok) {
            ok = ds4_gpu_encode_mul_mv_id_decode_replay(cb,
                                                         down_mv_pipeline,
                                                         &down_args,
                                                         down_buf,
                                                         (NSUInteger)down_inner,
                                                         midbuf,
                                                         ds4_gpu_tensor_offset(mid),
                                                         down_dst,
                                                         down_dst_off,
                                                         selectedbuf,
                                                         ds4_gpu_tensor_offset(selected),
                                                         down_smem,
                                                         2,
                                                         false);
        }
        if (ok && n_expert > 1 && !direct_down_sum && !hybrid_native_down_sum) {
            ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                   down_dst,
                                                   down_dst_off,
                                                   outbuf,
                                                   ds4_gpu_tensor_offset(out),
                                                   out_dim,
                                                   n_expert,
                                                   n_tokens);
        }
        if (!ok) return 0;
        if (hybrid_native_down_sum) {
            static int s_hybrid_banked_logged = 0;
            if (!s_hybrid_banked_logged) {
                s_hybrid_banked_logged = 1;
                fprintf(stderr,
                        "ds4: [hybrid-moe] IQ2 gate/up + MXFP4_NATIVE down banked decode arm engaged (GPU-selected MPP 4.1 sum6)\n");
            }
        }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "banked routed tensor MoE")) return 0;
    }

    return 1;
}

int ds4_gpu_routed_moe_one_banked_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        ds4_gpu_tensor       *gate_bank,
        ds4_gpu_tensor       *up_bank,
        ds4_gpu_tensor       *down_bank,
        uint32_t                n_slots,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_slot_stride,
        uint64_t                gate_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_slot_stride,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x) {
    return ds4_gpu_routed_moe_banked_tensor_impl(out,
                                                 gate,
                                                 up,
                                                 mid,
                                                 experts,
                                                 gate_bank,
                                                 up_bank,
                                                 down_bank,
                                                 n_slots,
                                                 gate_type,
                                                 down_type,
                                                 gate_expert_bytes,
                                                 gate_slot_stride,
                                                 gate_row_bytes,
                                                 down_expert_bytes,
                                                 down_slot_stride,
                                                 down_row_bytes,
                                                 expert_in_dim,
                                                 expert_mid_dim,
                                                 out_dim,
                                                 selected,
                                                 weights,
                                                 n_expert,
                                                 clamp,
                                                 x,
                                                 1u);
}

int ds4_gpu_routed_moe_banked_batch_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        ds4_gpu_tensor       *gate_bank,
        ds4_gpu_tensor       *up_bank,
        ds4_gpu_tensor       *down_bank,
        uint32_t                n_slots,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_slot_stride,
        uint64_t                gate_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_slot_stride,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x,
        uint32_t                n_tokens) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !gate || !up || !mid || !x || !gate_bank || !up_bank ||
        !down_bank || !selected || !weights || n_slots == 0 ||
        n_tokens == 0 || n_tokens > 5u ||
        n_expert == 0 || n_expert > 8) {
        return 0;
    }
    if ((expert_in_dim % 256u) != 0 || (expert_mid_dim % 256u) != 0) return 0;
    if (gate_slot_stride == 0) gate_slot_stride = gate_expert_bytes;
    if (down_slot_stride == 0) down_slot_stride = down_expert_bytes;
    if ((n_slots - 1ull) > (UINT64_MAX - gate_expert_bytes) / gate_slot_stride ||
        (n_slots - 1ull) > (UINT64_MAX - down_expert_bytes) / down_slot_stride) {
        return 0;
    }
    const uint64_t gate_bank_needed = (uint64_t)(n_slots - 1u) * gate_slot_stride + gate_expert_bytes;
    const uint64_t down_bank_needed = (uint64_t)(n_slots - 1u) * down_slot_stride + down_expert_bytes;

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> gatebuf = ds4_gpu_tensor_buffer(gate);
        id<MTLBuffer> upbuf = ds4_gpu_tensor_buffer(up);
        id<MTLBuffer> midbuf = ds4_gpu_tensor_buffer(mid);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> gate_buf = ds4_gpu_tensor_buffer(gate_bank);
        id<MTLBuffer> up_buf = ds4_gpu_tensor_buffer(up_bank);
        id<MTLBuffer> down_buf = ds4_gpu_tensor_buffer(down_bank);
        const uint64_t x_bytes = (uint64_t)n_tokens * expert_in_dim * sizeof(float);
        const uint64_t mid_bytes = (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float);
        const uint64_t out_bytes = (uint64_t)n_tokens * out_dim * sizeof(float);
        const uint64_t selected_bytes = (uint64_t)n_tokens * n_expert * sizeof(int32_t);
        const uint64_t weights_bytes = (uint64_t)n_tokens * n_expert * sizeof(float);
        if (!xbuf || !gatebuf || !upbuf || !midbuf || !outbuf ||
            !selectedbuf || !weightsbuf || !gate_buf || !up_buf || !down_buf ||
            ds4_gpu_tensor_bytes(x) < x_bytes ||
            ds4_gpu_tensor_bytes(gate) < mid_bytes ||
            ds4_gpu_tensor_bytes(up) < mid_bytes ||
            ds4_gpu_tensor_bytes(mid) < mid_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes ||
            ds4_gpu_tensor_bytes(selected) < selected_bytes ||
            ds4_gpu_tensor_bytes(weights) < weights_bytes ||
            ds4_gpu_tensor_bytes(gate_bank) < gate_bank_needed ||
            ds4_gpu_tensor_bytes(up_bank) < gate_bank_needed ||
            ds4_gpu_tensor_bytes(down_bank) < down_bank_needed) {
            fprintf(stderr, "ds4: Metal banked routed batch MoE received undersized buffers\n");
            return 0;
        }

        const int native_plane_split =
            ds4_gpu_tensor_mxfp4_plane_split(gate_bank) &&
            ds4_gpu_tensor_mxfp4_plane_split(up_bank) &&
            ds4_gpu_tensor_mxfp4_plane_split(down_bank);
        if (!native_plane_split) {
            return ds4_gpu_routed_moe_banked_tensor_impl(out,
                                                         gate,
                                                         up,
                                                         mid,
                                                         experts,
                                                         gate_bank,
                                                         up_bank,
                                                         down_bank,
                                                         n_slots,
                                                         gate_type,
                                                         down_type,
                                                         gate_expert_bytes,
                                                         gate_slot_stride,
                                                         gate_row_bytes,
                                                         down_expert_bytes,
                                                         down_slot_stride,
                                                         down_row_bytes,
                                                         expert_in_dim,
                                                         expert_mid_dim,
                                                         out_dim,
                                                         selected,
                                                         weights,
                                                         n_expert,
                                                         clamp,
                                                         x,
                                                         n_tokens);
        }
        if (n_tokens > 4u ||
            !ds4_gpu_mxfp4_native_decode2_available(gate_type,
                                                    down_type,
                                                    gate_row_bytes,
                                                    down_row_bytes,
                                                    expert_in_dim,
                                                    expert_mid_dim,
                                                    out_dim,
                                                    n_expert,
                                                    native_plane_split) ||
            !g_mxfp4_plane_id_batch_pair_swiglu_pipeline ||
            !g_mxfp4_plane_id_batch_sum6_pipeline ||
            gate_slot_stride > UINT32_MAX ||
            down_slot_stride > UINT32_MAX) {
            return 0;
        }

        const uint64_t gate_inner = ds4_gpu_tensor_offset(gate_bank);
        const uint64_t up_inner = ds4_gpu_tensor_offset(up_bank);
        const uint64_t down_inner = ds4_gpu_tensor_offset(down_bank);
        const uint64_t gate_scales_off64 =
            gate_inner + (uint64_t)expert_in_dim * expert_mid_dim / 2u;
        const uint64_t up_scales_off64 =
            up_inner + (uint64_t)expert_in_dim * expert_mid_dim / 2u;
        const uint64_t down_scales_off64 =
            down_inner + (uint64_t)expert_mid_dim * out_dim / 2u;
        if (gate_inner > NSUIntegerMax ||
            up_inner > NSUIntegerMax ||
            down_inner > NSUIntegerMax ||
            gate_scales_off64 > NSUIntegerMax ||
            up_scales_off64 > NSUIntegerMax ||
            down_scales_off64 > NSUIntegerMax) {
            return 0;
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        const uint32_t write_clamped =
            getenv("DS4_METAL_MOE_WRITE_CLAMPED_ACT") != NULL ? 1u : 0u;
        const int ok = ds4_gpu_encode_mxfp4_plane_id_batch_decode2(
                cb,
                xbuf,
                ds4_gpu_tensor_offset(x),
                gate_buf,
                (NSUInteger)gate_inner,
                (NSUInteger)gate_scales_off64,
                up_buf,
                (NSUInteger)up_inner,
                (NSUInteger)up_scales_off64,
                selectedbuf,
                ds4_gpu_tensor_offset(selected),
                weightsbuf,
                ds4_gpu_tensor_offset(weights),
                gatebuf,
                ds4_gpu_tensor_offset(gate),
                upbuf,
                ds4_gpu_tensor_offset(up),
                midbuf,
                ds4_gpu_tensor_offset(mid),
                down_buf,
                (NSUInteger)down_inner,
                (NSUInteger)down_scales_off64,
                outbuf,
                ds4_gpu_tensor_offset(out),
                expert_in_dim,
                expert_mid_dim,
                (uint32_t)gate_slot_stride,
                (uint32_t)down_slot_stride,
                out_dim,
                clamp,
                write_clamped,
                n_tokens);
        if (!ok) return 0;
        ds4_gpu_mxfp4_native_decode2_log_once("banked-batch");
        if (!ds4_gpu_finish_command_buffer(cb, owned, "native MXFP4 banked routed batch MoE decode2")) return 0;
    }

    return 1;
}

int ds4_gpu_routed_moe_one_slots6_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        ds4_gpu_tensor       *gate_slots[6],
        ds4_gpu_tensor       *up_slots[6],
        ds4_gpu_tensor       *down_slots[6],
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_row_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *weights,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !gate || !up || !mid || !x || !weights ||
        !gate_slots || !up_slots || !down_slots || n_expert != 6) {
        return 0;
    }
    if ((expert_in_dim % 256u) != 0 || (expert_mid_dim % 256u) != 0) return 0;
    const int native_possible =
        ds4_gpu_mxfp4_native_decode_available(gate_type,
                                              down_type,
                                              gate_row_bytes,
                                              down_row_bytes,
                                              expert_in_dim,
                                              expert_mid_dim,
                                              out_dim);
    const int hybrid_mxfp4_down =
        gate_type == DS4_METAL_TENSOR_IQ2_XXS &&
        down_type == DS4_METAL_TENSOR_MXFP4;
    const int hybrid_native_down_possible =
        hybrid_mxfp4_down &&
        ds4_gpu_mxfp4_native_down_sum6_available(down_type,
                                                 down_row_bytes,
                                                 expert_mid_dim,
                                                 out_dim);
    id<MTLComputePipelineState> pair_swiglu_pipeline = nil;
    id<MTLComputePipelineState> down_slots6_pipeline = nil;
    if (gate_type == DS4_METAL_TENSOR_IQ2_XXS &&
        down_type == DS4_METAL_TENSOR_Q2_K) {
        pair_swiglu_pipeline = g_moe_mul_mv_slots6_iq2_xxs_pair_swiglu_pipeline;
        down_slots6_pipeline = g_moe_mul_mv_slots6_q2_k_pipeline;
    } else if (hybrid_mxfp4_down) {
        pair_swiglu_pipeline = g_moe_mul_mv_slots6_iq2_xxs_pair_swiglu_pipeline;
    } else if (gate_type == DS4_METAL_TENSOR_MXFP4 &&
               down_type == DS4_METAL_TENSOR_MXFP4) {
        pair_swiglu_pipeline = g_moe_mul_mv_slots6_mxfp4_pair_swiglu_pipeline;
        down_slots6_pipeline = g_moe_mul_mv_slots6_mxfp4_pipeline;
    }
    if (!native_possible &&
        !hybrid_native_down_possible &&
        (!pair_swiglu_pipeline || !down_slots6_pipeline)) {
        return 0;
    }
    if (hybrid_mxfp4_down && !pair_swiglu_pipeline) {
        return 0;
    }

    const uint64_t gate_expert_bytes = (uint64_t)expert_mid_dim * gate_row_bytes;
    const uint64_t down_expert_bytes = (uint64_t)out_dim * down_row_bytes;
    const uint64_t x_bytes = (uint64_t)expert_in_dim * sizeof(float);
    const uint64_t mid_row_bytes = (uint64_t)expert_mid_dim * sizeof(float);
    const uint64_t mid_bytes = (uint64_t)n_expert * mid_row_bytes;
    const uint64_t out_row_bytes = (uint64_t)out_dim * sizeof(float);
    const uint64_t out_bytes = (uint64_t)out_dim * sizeof(float);
    id<MTLComputePipelineState> down_slots6_sum6_pipeline = nil;
    if (down_type == DS4_METAL_TENSOR_Q2_K) {
        down_slots6_sum6_pipeline = g_moe_mul_mv_slots6_q2_k_sum6_pipeline;
    } else if (down_type == DS4_METAL_TENSOR_MXFP4) {
        down_slots6_sum6_pipeline = g_moe_mul_mv_slots6_mxfp4_sum6_pipeline;
    }
    const bool direct_down_sum =
        !g_quality_mode &&
        !hybrid_mxfp4_down &&
        ds4_gpu_env_bool("DS4_FLASH_MOE_SLOTS6_DIRECT_DOWN_SUM") > 0 &&
        getenv("DS4_FLASH_MOE_SLOTS6_DISABLE_DOWN_SUM6") == NULL &&
        down_slots6_sum6_pipeline != nil;
    const uint64_t experts_bytes = (uint64_t)n_expert * out_row_bytes;

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> gatebuf = ds4_gpu_tensor_buffer(gate);
        id<MTLBuffer> upbuf = ds4_gpu_tensor_buffer(up);
        id<MTLBuffer> midbuf = ds4_gpu_tensor_buffer(mid);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> expertsbuf = ds4_gpu_tensor_buffer(experts);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        __unsafe_unretained id<MTLBuffer> gate_slot_bufs[6] = {
            nil, nil, nil, nil, nil, nil
        };
        __unsafe_unretained id<MTLBuffer> up_slot_bufs[6] = {
            nil, nil, nil, nil, nil, nil
        };
        __unsafe_unretained id<MTLBuffer> down_slot_bufs[6] = {
            nil, nil, nil, nil, nil, nil
        };
        NSUInteger gate_slot_offsets[6] = { 0, 0, 0, 0, 0, 0 };
        NSUInteger up_slot_offsets[6] = { 0, 0, 0, 0, 0, 0 };
        NSUInteger down_slot_offsets[6] = { 0, 0, 0, 0, 0, 0 };

            const int native_experts_ok =
                expertsbuf && ds4_gpu_tensor_bytes(experts) >= experts_bytes;
            if (!xbuf || !gatebuf || !upbuf || !midbuf || !outbuf || !weightsbuf ||
                (!native_possible && !hybrid_native_down_possible &&
                 !direct_down_sum && !expertsbuf) ||
                ds4_gpu_tensor_bytes(x) < x_bytes ||
                ds4_gpu_tensor_bytes(gate) < mid_bytes ||
                ds4_gpu_tensor_bytes(up) < mid_bytes ||
                ds4_gpu_tensor_bytes(mid) < mid_bytes ||
                ds4_gpu_tensor_bytes(out) < out_bytes ||
                (!native_possible && !hybrid_native_down_possible && !direct_down_sum &&
                 ds4_gpu_tensor_bytes(experts) < experts_bytes) ||
                ds4_gpu_tensor_bytes(weights) < (uint64_t)n_expert * sizeof(float)) {
                fprintf(stderr, "ds4: Metal slots6 routed tensor MoE received undersized buffers\n");
                return 0;
            }

        int native_plane_split = 1;
        int hybrid_down_plane_split = 1;
        for (uint32_t i = 0; i < 6; i++) {
            if (!gate_slots[i] || !up_slots[i] || !down_slots[i] ||
                ds4_gpu_tensor_bytes(gate_slots[i]) < gate_expert_bytes ||
                ds4_gpu_tensor_bytes(up_slots[i]) < gate_expert_bytes ||
                ds4_gpu_tensor_bytes(down_slots[i]) < down_expert_bytes) {
                fprintf(stderr, "ds4: Metal slots6 routed tensor MoE received undersized expert slot\n");
                return 0;
            }
            gate_slot_bufs[i] = ds4_gpu_tensor_buffer(gate_slots[i]);
            up_slot_bufs[i] = ds4_gpu_tensor_buffer(up_slots[i]);
            down_slot_bufs[i] = ds4_gpu_tensor_buffer(down_slots[i]);
            gate_slot_offsets[i] = ds4_gpu_tensor_offset(gate_slots[i]);
            up_slot_offsets[i] = ds4_gpu_tensor_offset(up_slots[i]);
            down_slot_offsets[i] = ds4_gpu_tensor_offset(down_slots[i]);
            if (!gate_slot_bufs[i] || !up_slot_bufs[i] || !down_slot_bufs[i]) {
                return 0;
            }
            native_plane_split =
                native_plane_split &&
                ds4_gpu_tensor_mxfp4_plane_split(gate_slots[i]) &&
                ds4_gpu_tensor_mxfp4_plane_split(up_slots[i]) &&
                ds4_gpu_tensor_mxfp4_plane_split(down_slots[i]);
            hybrid_down_plane_split =
                hybrid_down_plane_split &&
                !ds4_gpu_tensor_mxfp4_plane_split(gate_slots[i]) &&
                !ds4_gpu_tensor_mxfp4_plane_split(up_slots[i]) &&
                ds4_gpu_tensor_mxfp4_plane_split(down_slots[i]);
        }

            const uint32_t n_tokens = 1;
            if (native_possible) {
                if (!native_experts_ok &&
                    !ds4_gpu_ensure_scratch_buffer(&g_moe_down_scratch_buffer,
                                                   &g_moe_down_scratch_bytes,
                                                   (NSUInteger)experts_bytes,
                                                   "ds4_mxfp4_decode_slots6_down")) {
                    return 0;
                }
                if (!ds4_gpu_mxfp4_native_decode_ensure_scratch(expert_in_dim,
                                                                expert_mid_dim,
                                                                out_dim)) {
                    return 0;
                }
                int owned = 0;
                id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
                if (!cb) return 0;
                id<MTLBuffer> down_dst = native_experts_ok ? expertsbuf : g_moe_down_scratch_buffer;
                const NSUInteger down_dst_base = native_experts_ok ? ds4_gpu_tensor_offset(experts) : 0;
            const NSUInteger gate_base_off = ds4_gpu_tensor_offset(gate);
            const NSUInteger up_base_off = ds4_gpu_tensor_offset(up);
            const NSUInteger mid_base_off = ds4_gpu_tensor_offset(mid);
            const NSUInteger weights_base_off = ds4_gpu_tensor_offset(weights);
            int ok = ds4_gpu_encode_cpy_f32_f16_1d(cb,
                                                   xbuf,
                                                   ds4_gpu_tensor_offset(x),
                                                   g_mpp_prefill_x_half_buffer,
                                                   0,
                                                   expert_in_dim);
            for (uint32_t k = 0; ok && k < n_expert; k++) {
                const NSUInteger row_mid_off =
                    (NSUInteger)((uint64_t)k * mid_row_bytes);
                const NSUInteger row_out_off =
                    (NSUInteger)((uint64_t)k * out_row_bytes);
                ok = ds4_gpu_encode_mxfp4_native_decode_route(
                         cb,
                         g_mpp_prefill_x_half_buffer,
                         gate_slot_bufs[k],
                         gate_slot_offsets[k],
                         up_slot_bufs[k],
                         up_slot_offsets[k],
                         down_slot_bufs[k],
                         down_slot_offsets[k],
                         nil,
                         0,
                         k,
                         0,
                         0,
                         native_plane_split,
                         gatebuf,
                         gate_base_off + row_mid_off,
                         upbuf,
                         up_base_off + row_mid_off,
                         midbuf,
                         mid_base_off + row_mid_off,
                         weightsbuf,
                         weights_base_off + (NSUInteger)((uint64_t)k * sizeof(float)),
                         down_dst,
                         down_dst_base + row_out_off,
                         expert_in_dim,
                         expert_mid_dim,
                         out_dim,
                         clamp);
            }
            if (ok) {
                ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                    down_dst,
                                                    down_dst_base,
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    out_dim,
                                                    n_expert,
                                                    n_tokens);
            }
            if (!ok) return 0;
            ds4_gpu_mxfp4_native_decode_log_once("slots6", native_plane_split);
            if (!ds4_gpu_finish_command_buffer(cb, owned, "native MXFP4 slots6 routed tensor MoE")) return 0;
            return 1;
        }
	        if (native_plane_split) {
	            fprintf(stderr, "ds4: MXFP4_NATIVE plane-split slots6 decode cannot use legacy block kernels\n");
	            return 0;
	        }
        const int hybrid_native_down_sum =
            hybrid_mxfp4_down && hybrid_native_down_possible && hybrid_down_plane_split;
        if (hybrid_mxfp4_down && !hybrid_native_down_sum) {
            return 0;
        }

	        const uint32_t gate_nr0 = ds4_gpu_routed_mv_nr0(gate_type);
	        const uint32_t down_nr0 = ds4_gpu_routed_mv_nr0(down_type);
	        if (gate_nr0 == 0 || (!hybrid_native_down_sum && down_nr0 == 0)) return 0;

        ds4_gpu_mul_mv_id_args gate_args =
            ds4_gpu_make_mul_mv_id_args(expert_in_dim, expert_mid_dim, 1,
                                          gate_row_bytes, gate_expert_bytes,
                                          1, n_expert, n_tokens, gate_nr0);
        ds4_gpu_mul_mv_id_args down_args =
            ds4_gpu_make_mul_mv_id_args(expert_mid_dim, out_dim, 1,
                                          down_row_bytes, down_expert_bytes,
                                          n_expert, n_expert, n_tokens, down_nr0);
        ds4_gpu_mul_mv_id_args down_route_args =
            ds4_gpu_make_mul_mv_id_args(expert_mid_dim, out_dim, 1,
                                          down_row_bytes, down_expert_bytes,
                                          1, 1, n_tokens, down_nr0);

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        const NSUInteger gate_smem = ds4_gpu_routed_mv_smem(gate_type);
        const NSUInteger down_smem = ds4_gpu_routed_mv_smem(down_type);
        ds4_gpu_dsv4_moe_swiglu_weight_args act_args = {
            .width = expert_mid_dim,
            .rows = n_expert,
            .gate_row_stride = mid_row_bytes,
            .up_row_stride = mid_row_bytes,
            .mid_row_stride = mid_row_bytes,
            .weight_stride = sizeof(float),
            .write_clamped = getenv("DS4_METAL_MOE_WRITE_CLAMPED_ACT") != NULL ? 1 : 0,
            .clamp_value = clamp,
        };

        int ok = ds4_gpu_encode_mul_mv_slots6_pair_swiglu(
                     cb,
                     pair_swiglu_pipeline,
                     &gate_args,
                     &act_args,
                     gate_slot_bufs,
                     gate_slot_offsets,
                     up_slot_bufs,
                     up_slot_offsets,
                     xbuf,
                     ds4_gpu_tensor_offset(x),
                     gatebuf,
                     ds4_gpu_tensor_offset(gate),
                     upbuf,
                     ds4_gpu_tensor_offset(up),
                     midbuf,
                     ds4_gpu_tensor_offset(mid),
	                     weightsbuf,
	                     ds4_gpu_tensor_offset(weights),
	                     gate_smem,
	                     2,
	                     false);
        if (ok && hybrid_native_down_sum) {
            __unsafe_unretained id<MTLBuffer> down_data_bufs[6] = {
                nil, nil, nil, nil, nil, nil
            };
            __unsafe_unretained id<MTLBuffer> down_scales_bufs[6] = {
                nil, nil, nil, nil, nil, nil
            };
            NSUInteger down_data_offsets[6] = { 0, 0, 0, 0, 0, 0 };
            NSUInteger down_scales_offsets[6] = { 0, 0, 0, 0, 0, 0 };
            const uint64_t down_scales_rel64 =
                (uint64_t)expert_mid_dim * (uint64_t)out_dim / 2u;
            if (down_scales_rel64 > NSUIntegerMax) {
                ok = 0;
            }
            for (uint32_t k = 0; ok && k < n_expert; k++) {
                if (down_slot_offsets[k] > NSUIntegerMax - (NSUInteger)down_scales_rel64) {
                    ok = 0;
                    break;
                }
                down_data_bufs[k] = down_slot_bufs[k];
                down_scales_bufs[k] = down_slot_bufs[k];
                down_data_offsets[k] = down_slot_offsets[k];
                down_scales_offsets[k] =
                    down_slot_offsets[k] + (NSUInteger)down_scales_rel64;
            }
            if (ok) {
                ok = ds4_gpu_encode_mxfp4_plane_slots6_sum6(
                         cb,
                         down_data_bufs,
                         down_data_offsets,
                         down_scales_bufs,
                         down_scales_offsets,
                         midbuf,
                         ds4_gpu_tensor_offset(mid),
                         outbuf,
                         ds4_gpu_tensor_offset(out),
                         expert_mid_dim,
                         out_dim);
            }
        } else if (ok && direct_down_sum) {
	            ok = ds4_gpu_encode_mul_mv_slots6_sum6(
	                     cb,
	                     down_slots6_sum6_pipeline,
                     &down_args,
                     down_slot_bufs,
                     down_slot_offsets,
                     midbuf,
                     ds4_gpu_tensor_offset(mid),
                     outbuf,
                     ds4_gpu_tensor_offset(out),
                     down_smem,
                     2);
        } else if (ok && down_slots6_pipeline &&
                   getenv("DS4_FLASH_MOE_SLOTS6_DISABLE_GROUPED_DOWN") == NULL) {
            ok = ds4_gpu_encode_mul_mv_slots6(
                     cb,
                     down_slots6_pipeline,
                     &down_args,
                     down_slot_bufs,
                     down_slot_offsets,
                     midbuf,
                     ds4_gpu_tensor_offset(mid),
                     expertsbuf,
                     ds4_gpu_tensor_offset(experts),
                     down_smem,
                     2,
                     false);
            if (ok) {
                ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                    expertsbuf,
                                                    ds4_gpu_tensor_offset(experts),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    out_dim,
                                                    n_expert,
                                                    n_tokens);
            }
        } else if (ok) {
            id<MTLComputePipelineState> down_mv_pipeline =
                ds4_gpu_routed_mv_pipeline(down_type);
            id<MTLBuffer> zero_selected = ds4_gpu_zero_i32_buffer();
            if (!down_mv_pipeline || !zero_selected) return 0;
            const NSUInteger mid_base_off = ds4_gpu_tensor_offset(mid);
            const NSUInteger experts_base_off = ds4_gpu_tensor_offset(experts);
            for (uint32_t k = 0; ok && k < n_expert; k++) {
                ok = ds4_gpu_encode_mul_mv_id_decode_replay(
                         cb,
                         down_mv_pipeline,
                         &down_route_args,
                         down_slot_bufs[k],
                         down_slot_offsets[k],
                         midbuf,
                         mid_base_off + (NSUInteger)((uint64_t)k * mid_row_bytes),
                         expertsbuf,
                         experts_base_off + (NSUInteger)((uint64_t)k * out_row_bytes),
                         zero_selected,
                         0,
                         down_smem,
                         2,
                         false);
            }
            if (ok) {
                ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                    expertsbuf,
                                                    experts_base_off,
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    out_dim,
                                                    n_expert,
                                                    n_tokens);
            }
	        }
	        if (!ok) return 0;
        if (hybrid_native_down_sum) {
            static int s_hybrid_slots6_logged = 0;
            if (!s_hybrid_slots6_logged) {
                s_hybrid_slots6_logged = 1;
                fprintf(stderr,
                        "ds4: [hybrid-moe] IQ2 gate/up + MXFP4_NATIVE down slots6 fused decode arm engaged (MPP 4.1 sum6)\n");
            }
        }
	        if (!ds4_gpu_finish_command_buffer(cb, owned, "slots6 routed tensor MoE")) return 0;
	    }

    return 1;
}

int ds4_gpu_routed_moe_one_slots8_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        ds4_gpu_tensor       *gate_slots[8],
        ds4_gpu_tensor       *up_slots[8],
        ds4_gpu_tensor       *down_slots[8],
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_row_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *weights,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !gate || !up || !mid || !experts || !x || !weights ||
        !gate_slots || !up_slots || !down_slots || n_expert != 8) {
        return 0;
    }
    if ((expert_in_dim % 256u) != 0 || (expert_mid_dim % 256u) != 0) return 0;

    const uint64_t gate_expert_bytes = (uint64_t)expert_mid_dim * gate_row_bytes;
    const uint64_t down_expert_bytes = (uint64_t)out_dim * down_row_bytes;
    const uint64_t x_bytes = (uint64_t)expert_in_dim * sizeof(float);
    const uint64_t mid_row_bytes = (uint64_t)expert_mid_dim * sizeof(float);
    const uint64_t mid_bytes = (uint64_t)n_expert * mid_row_bytes;
    const uint64_t out_row_bytes = (uint64_t)out_dim * sizeof(float);
    const uint64_t out_bytes = (uint64_t)out_dim * sizeof(float);
    const uint64_t experts_bytes = (uint64_t)n_expert * out_row_bytes;

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> gatebuf = ds4_gpu_tensor_buffer(gate);
        id<MTLBuffer> upbuf = ds4_gpu_tensor_buffer(up);
        id<MTLBuffer> midbuf = ds4_gpu_tensor_buffer(mid);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> expertsbuf = ds4_gpu_tensor_buffer(experts);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> zero_selected = ds4_gpu_zero_i32_buffer();
        __unsafe_unretained id<MTLBuffer> gate_slot_bufs[8] = {
            nil, nil, nil, nil, nil, nil, nil, nil
        };
        __unsafe_unretained id<MTLBuffer> up_slot_bufs[8] = {
            nil, nil, nil, nil, nil, nil, nil, nil
        };
        __unsafe_unretained id<MTLBuffer> down_slot_bufs[8] = {
            nil, nil, nil, nil, nil, nil, nil, nil
        };
        NSUInteger gate_slot_offsets[8] = { 0, 0, 0, 0, 0, 0, 0, 0 };
        NSUInteger up_slot_offsets[8] = { 0, 0, 0, 0, 0, 0, 0, 0 };
        NSUInteger down_slot_offsets[8] = { 0, 0, 0, 0, 0, 0, 0, 0 };

        if (!xbuf || !gatebuf || !upbuf || !midbuf || !outbuf || !expertsbuf ||
            !weightsbuf || !zero_selected ||
            ds4_gpu_tensor_bytes(x) < x_bytes ||
            ds4_gpu_tensor_bytes(gate) < mid_bytes ||
            ds4_gpu_tensor_bytes(up) < mid_bytes ||
            ds4_gpu_tensor_bytes(mid) < mid_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes ||
            ds4_gpu_tensor_bytes(experts) < experts_bytes ||
            ds4_gpu_tensor_bytes(weights) < (uint64_t)n_expert * sizeof(float)) {
            fprintf(stderr, "ds4: Metal slots8 routed tensor MoE received undersized buffers\n");
            return 0;
        }

        for (uint32_t i = 0; i < n_expert; i++) {
            if (!gate_slots[i] || !up_slots[i] || !down_slots[i] ||
                ds4_gpu_tensor_bytes(gate_slots[i]) < gate_expert_bytes ||
                ds4_gpu_tensor_bytes(up_slots[i]) < gate_expert_bytes ||
                ds4_gpu_tensor_bytes(down_slots[i]) < down_expert_bytes) {
                fprintf(stderr, "ds4: Metal slots8 routed tensor MoE received undersized expert slot\n");
                return 0;
            }
            gate_slot_bufs[i] = ds4_gpu_tensor_buffer(gate_slots[i]);
            up_slot_bufs[i] = ds4_gpu_tensor_buffer(up_slots[i]);
            down_slot_bufs[i] = ds4_gpu_tensor_buffer(down_slots[i]);
            gate_slot_offsets[i] = ds4_gpu_tensor_offset(gate_slots[i]);
            up_slot_offsets[i] = ds4_gpu_tensor_offset(up_slots[i]);
            down_slot_offsets[i] = ds4_gpu_tensor_offset(down_slots[i]);
            if (!gate_slot_bufs[i] || !up_slot_bufs[i] || !down_slot_bufs[i]) {
                return 0;
            }
        }

        const uint32_t gate_nr0 = ds4_gpu_routed_mv_nr0(gate_type);
        const uint32_t down_nr0 = ds4_gpu_routed_mv_nr0(down_type);
        id<MTLComputePipelineState> gate_mv_pipeline = ds4_gpu_routed_mv_pipeline(gate_type);
        id<MTLComputePipelineState> down_mv_pipeline = ds4_gpu_routed_mv_pipeline(down_type);
        if (gate_nr0 == 0 || down_nr0 == 0 || !gate_mv_pipeline || !down_mv_pipeline) {
            fprintf(stderr, "ds4: unsupported Metal slots8 routed MoE quant types gate=%u down=%u\n",
                    gate_type, down_type);
            return 0;
        }

        ds4_gpu_mul_mv_id_args gate_args =
            ds4_gpu_make_mul_mv_id_args(expert_in_dim, expert_mid_dim, 1,
                                          gate_row_bytes, gate_expert_bytes,
                                          1, 1, 1, gate_nr0);
        ds4_gpu_mul_mv_id_args down_args =
            ds4_gpu_make_mul_mv_id_args(expert_mid_dim, out_dim, 1,
                                          down_row_bytes, down_expert_bytes,
                                          1, 1, 1, down_nr0);

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        const NSUInteger x_off = ds4_gpu_tensor_offset(x);
        const NSUInteger gate_base_off = ds4_gpu_tensor_offset(gate);
        const NSUInteger up_base_off = ds4_gpu_tensor_offset(up);
        const NSUInteger mid_base_off = ds4_gpu_tensor_offset(mid);
        const NSUInteger weights_off = ds4_gpu_tensor_offset(weights);
        const NSUInteger experts_base_off = ds4_gpu_tensor_offset(experts);
        const NSUInteger out_off = ds4_gpu_tensor_offset(out);
        const NSUInteger gate_smem = ds4_gpu_routed_mv_smem(gate_type);
        const NSUInteger down_smem = ds4_gpu_routed_mv_smem(down_type);

        int ok = 1;
        for (uint32_t k = 0; ok && k < n_expert; k++) {
            const NSUInteger row_mid_off = (NSUInteger)((uint64_t)k * mid_row_bytes);
            ok = ds4_gpu_encode_mul_mv_id_decode_replay(cb,
                                                         gate_mv_pipeline,
                                                         &gate_args,
                                                         gate_slot_bufs[k],
                                                         gate_slot_offsets[k],
                                                         xbuf,
                                                         x_off,
                                                         gatebuf,
                                                         gate_base_off + row_mid_off,
                                                         zero_selected,
                                                         0,
                                                         gate_smem,
                                                         2,
                                                         false) &&
                 ds4_gpu_encode_mul_mv_id_decode_replay(cb,
                                                         gate_mv_pipeline,
                                                         &gate_args,
                                                         up_slot_bufs[k],
                                                         up_slot_offsets[k],
                                                         xbuf,
                                                         x_off,
                                                         upbuf,
                                                         up_base_off + row_mid_off,
                                                         zero_selected,
                                                         0,
                                                         gate_smem,
                                                         2,
                                                         false);
        }
        if (ok) {
            ok = ds4_gpu_encode_moe_swiglu_weight(cb,
                                                  gatebuf,
                                                  gate_base_off,
                                                  upbuf,
                                                  up_base_off,
                                                  midbuf,
                                                  mid_base_off,
                                                  weightsbuf,
                                                  weights_off,
                                                  expert_mid_dim,
                                                  n_expert,
                                                  clamp,
                                                  false);
        }
        for (uint32_t k = 0; ok && k < n_expert; k++) {
            const NSUInteger row_mid_off = (NSUInteger)((uint64_t)k * mid_row_bytes);
            const NSUInteger row_out_off = (NSUInteger)((uint64_t)k * out_row_bytes);
            ok = ds4_gpu_encode_mul_mv_id_decode_replay(cb,
                                                         down_mv_pipeline,
                                                         &down_args,
                                                         down_slot_bufs[k],
                                                         down_slot_offsets[k],
                                                         midbuf,
                                                         mid_base_off + row_mid_off,
                                                         expertsbuf,
                                                         experts_base_off + row_out_off,
                                                         zero_selected,
                                                         0,
                                                         down_smem,
                                                         2,
                                                         false);
        }
        if (ok) {
            ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                expertsbuf,
                                                experts_base_off,
                                                outbuf,
                                                out_off,
                                                out_dim,
                                                n_expert,
                                                1);
        }
        if (!ok) return 0;
        if (!ds4_gpu_finish_command_buffer(cb, owned, "slots8 routed tensor MoE")) return 0;
    }

    return 1;
}

int ds4_gpu_routed_moe_one_slots6_record_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *slot_records[6],
        uint64_t                gate_offset,
        uint64_t                up_offset,
        uint64_t                down_offset,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_row_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *weights,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !gate || !up || !mid || !x || !weights || !slot_records ||
        n_expert != 6 ||
        gate_type != DS4_METAL_TENSOR_MXFP4 ||
        down_type != DS4_METAL_TENSOR_MXFP4) {
        return 0;
    }
    if ((expert_in_dim % 256u) != 0 || (expert_mid_dim % 256u) != 0) return 0;
    const int native_possible =
        ds4_gpu_mxfp4_native_decode_available(gate_type,
                                              down_type,
                                              gate_row_bytes,
                                              down_row_bytes,
                                              expert_in_dim,
                                              expert_mid_dim,
                                              out_dim);
    if (!native_possible &&
        (!g_moe_mul_mv_slots6_mxfp4_record_pair_swiglu_pipeline ||
         !g_moe_mul_mv_slots6_mxfp4_record_sum6_pipeline ||
         getenv("DS4_FLASH_MOE_SLOTS6_DISABLE_DOWN_SUM6") != NULL)) {
        return 0;
    }

    const uint64_t gate_expert_bytes = (uint64_t)expert_mid_dim * gate_row_bytes;
    const uint64_t down_expert_bytes = (uint64_t)out_dim * down_row_bytes;
    const uint64_t x_bytes = (uint64_t)expert_in_dim * sizeof(float);
    const uint64_t mid_row_bytes = (uint64_t)expert_mid_dim * sizeof(float);
    const uint64_t mid_bytes = (uint64_t)n_expert * mid_row_bytes;
    const uint64_t out_bytes = (uint64_t)out_dim * sizeof(float);
    const uint64_t weights_bytes = (uint64_t)n_expert * sizeof(float);
    uint64_t record_needed = 0;
    if (gate_offset > UINT64_MAX - gate_expert_bytes ||
        up_offset > UINT64_MAX - gate_expert_bytes ||
        down_offset > UINT64_MAX - down_expert_bytes) {
        return 0;
    }
    record_needed = gate_offset + gate_expert_bytes;
    if (record_needed < up_offset + gate_expert_bytes) {
        record_needed = up_offset + gate_expert_bytes;
    }
    if (record_needed < down_offset + down_expert_bytes) {
        record_needed = down_offset + down_expert_bytes;
    }

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> gatebuf = ds4_gpu_tensor_buffer(gate);
        id<MTLBuffer> upbuf = ds4_gpu_tensor_buffer(up);
        id<MTLBuffer> midbuf = ds4_gpu_tensor_buffer(mid);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        __unsafe_unretained id<MTLBuffer> slot_bufs[6] = {
            nil, nil, nil, nil, nil, nil
        };
        NSUInteger slot_offsets[6] = { 0, 0, 0, 0, 0, 0 };

        if (!xbuf || !gatebuf || !upbuf || !midbuf || !outbuf || !weightsbuf ||
            ds4_gpu_tensor_bytes(x) < x_bytes ||
            ds4_gpu_tensor_bytes(gate) < mid_bytes ||
            ds4_gpu_tensor_bytes(up) < mid_bytes ||
            ds4_gpu_tensor_bytes(mid) < mid_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes ||
            ds4_gpu_tensor_bytes(weights) < weights_bytes) {
            fprintf(stderr, "ds4: Metal slots6 record routed tensor MoE received undersized buffers\n");
            return 0;
        }
        int native_plane_split = 1;
        for (uint32_t i = 0; i < 6; i++) {
            if (!slot_records[i] ||
                ds4_gpu_tensor_bytes(slot_records[i]) < record_needed) {
                fprintf(stderr, "ds4: Metal slots6 record routed tensor MoE received undersized expert record\n");
                return 0;
            }
            slot_bufs[i] = ds4_gpu_tensor_buffer(slot_records[i]);
            slot_offsets[i] = ds4_gpu_tensor_offset(slot_records[i]);
            if (!slot_bufs[i]) return 0;
            native_plane_split =
                native_plane_split &&
                ds4_gpu_tensor_mxfp4_plane_split(slot_records[i]);
        }

        const uint32_t n_tokens = 1;
        if (native_possible) {
            const uint64_t experts_bytes = (uint64_t)n_expert * out_bytes;
            if (experts_bytes > NSUIntegerMax ||
                !ds4_gpu_ensure_scratch_buffer(&g_moe_down_scratch_buffer,
                                               &g_moe_down_scratch_bytes,
                                               (NSUInteger)experts_bytes,
                                               "ds4_mxfp4_decode_record_down")) {
                return 0;
            }
            if (!ds4_gpu_mxfp4_native_decode_ensure_scratch(expert_in_dim,
                                                            expert_mid_dim,
                                                            out_dim)) {
                return 0;
            }
            int owned = 0;
            id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
            if (!cb) return 0;
            const NSUInteger gate_base_off = ds4_gpu_tensor_offset(gate);
            const NSUInteger up_base_off = ds4_gpu_tensor_offset(up);
            const NSUInteger mid_base_off = ds4_gpu_tensor_offset(mid);
            const NSUInteger weights_base_off = ds4_gpu_tensor_offset(weights);
            int ok = ds4_gpu_encode_cpy_f32_f16_1d(cb,
                                                   xbuf,
                                                   ds4_gpu_tensor_offset(x),
                                                   g_mpp_prefill_x_half_buffer,
                                                   0,
                                                   expert_in_dim);
            for (uint32_t k = 0; ok && k < n_expert; k++) {
                const NSUInteger row_mid_off =
                    (NSUInteger)((uint64_t)k * mid_row_bytes);
                const NSUInteger row_out_off =
                    (NSUInteger)((uint64_t)k * out_bytes);
                ok = ds4_gpu_encode_mxfp4_native_decode_route(
                         cb,
                         g_mpp_prefill_x_half_buffer,
                         slot_bufs[k],
                         slot_offsets[k] + (NSUInteger)gate_offset,
                         slot_bufs[k],
                         slot_offsets[k] + (NSUInteger)up_offset,
                         slot_bufs[k],
                         slot_offsets[k] + (NSUInteger)down_offset,
                         nil,
                         0,
                         k,
                         0,
                         0,
                         native_plane_split,
                         gatebuf,
                         gate_base_off + row_mid_off,
                         upbuf,
                         up_base_off + row_mid_off,
                         midbuf,
                         mid_base_off + row_mid_off,
                         weightsbuf,
                         weights_base_off + (NSUInteger)((uint64_t)k * sizeof(float)),
                         g_moe_down_scratch_buffer,
                         row_out_off,
                         expert_in_dim,
                         expert_mid_dim,
                         out_dim,
                         clamp);
            }
            if (ok) {
                ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                    g_moe_down_scratch_buffer,
                                                    0,
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    out_dim,
                                                    n_expert,
                                                    n_tokens);
            }
            if (!ok) return 0;
            ds4_gpu_mxfp4_native_decode_log_once("slots6-record", native_plane_split);
            if (!ds4_gpu_finish_command_buffer(cb, owned, "native MXFP4 slots6 record routed tensor MoE")) return 0;
            return 1;
        }
        if (native_plane_split) {
            fprintf(stderr, "ds4: MXFP4_NATIVE plane-split record decode cannot use legacy block kernels\n");
            return 0;
        }

        const uint32_t gate_nr0 = ds4_gpu_routed_mv_nr0(gate_type);
        const uint32_t down_nr0 = ds4_gpu_routed_mv_nr0(down_type);
        if (gate_nr0 == 0 || down_nr0 == 0) return 0;

        ds4_gpu_mul_mv_id_args gate_args =
            ds4_gpu_make_mul_mv_id_args(expert_in_dim, expert_mid_dim, 1,
                                          gate_row_bytes, gate_expert_bytes,
                                          1, n_expert, n_tokens, gate_nr0);
        ds4_gpu_mul_mv_id_args down_args =
            ds4_gpu_make_mul_mv_id_args(expert_mid_dim, out_dim, 1,
                                          down_row_bytes, down_expert_bytes,
                                          n_expert, n_expert, n_tokens, down_nr0);
        ds4_gpu_dsv4_moe_swiglu_weight_args act_args = {
            .width = expert_mid_dim,
            .rows = n_expert,
            .gate_row_stride = mid_row_bytes,
            .up_row_stride = mid_row_bytes,
            .mid_row_stride = mid_row_bytes,
            .weight_stride = sizeof(float),
            .write_clamped = getenv("DS4_METAL_MOE_WRITE_CLAMPED_ACT") != NULL ? 1 : 0,
            .clamp_value = clamp,
        };
        ds4_gpu_slots6_record_offsets rec = {
            .gate_offset = gate_offset,
            .up_offset = up_offset,
            .down_offset = down_offset,
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        const NSUInteger gate_smem = ds4_gpu_routed_mv_smem(gate_type);
        const NSUInteger down_smem = ds4_gpu_routed_mv_smem(down_type);
        int ok = 0;
        if (ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_SLOTS6_RECORD_FUSED_ENCODER")) {
            ok = ds4_gpu_encode_mul_mv_slots6_record_pair_swiglu_sum6(
                     cb,
                     g_moe_mul_mv_slots6_mxfp4_record_pair_swiglu_pipeline,
                     g_moe_mul_mv_slots6_mxfp4_record_sum6_pipeline,
                     &gate_args,
                     &down_args,
                     &act_args,
                     &rec,
                     slot_bufs,
                     slot_offsets,
                     xbuf,
                     ds4_gpu_tensor_offset(x),
                     gatebuf,
                     ds4_gpu_tensor_offset(gate),
                     upbuf,
                     ds4_gpu_tensor_offset(up),
                     midbuf,
                     ds4_gpu_tensor_offset(mid),
                     weightsbuf,
                     ds4_gpu_tensor_offset(weights),
                     outbuf,
                     ds4_gpu_tensor_offset(out),
                     gate_smem,
                     down_smem,
                     2,
                     false);
        } else {
            ok = ds4_gpu_encode_mul_mv_slots6_record_pair_swiglu(
                     cb,
