            NSUInteger up_scales_offs[DS4_GPU_SLOTS6_CHUNKED_MAX] = { 0, 0, 0, 0 };
            NSUInteger down_scales_offs[DS4_GPU_SLOTS6_CHUNKED_MAX] = { 0, 0, 0, 0 };
