static float ds4_gpu_prefill_int8_qscale_from_env(const char *primary,
                                                  const char *fallback,
                                                  float       default_value) {
    const char *env = getenv(primary);
    if (!env || !env[0]) env = getenv(fallback);
    if (env && env[0]) {
        char *end = NULL;
        float parsed = strtof(env, &end);
        if (end != env && parsed > 0.0f && isfinite(parsed)) return parsed;
    }
    return default_value;
}

void ds4_gpu_prefill_int8_scales(int prefer_ane_env,
                                 float *w_qscale,
                                 float *w_scale,
                                 float *x_qscale,
                                 float *x_scale,
                                 float *mid_qscale,
                                 float *mid_scale) {
    const char *w_primary =
        prefer_ane_env ? "DS4_FLASH_MOE_ANE_INT8_QSCALE" : "DS4_FLASH_MOE_MPP_INT8_QSCALE";
    const char *w_fallback =
        prefer_ane_env ? "DS4_FLASH_MOE_MPP_INT8_QSCALE" : "DS4_FLASH_MOE_ANE_INT8_QSCALE";
    const char *x_primary =
        prefer_ane_env ? "DS4_FLASH_MOE_ANE_X_QSCALE" : "DS4_FLASH_MOE_MPP_INT8_X_QSCALE";
    const char *x_fallback =
        prefer_ane_env ? "DS4_FLASH_MOE_MPP_INT8_X_QSCALE" : "DS4_FLASH_MOE_ANE_X_QSCALE";
    const char *mid_primary =
        prefer_ane_env ? "DS4_FLASH_MOE_ANE_MID_QSCALE" : "DS4_FLASH_MOE_MPP_INT8_MID_QSCALE";
    const char *mid_fallback =
        prefer_ane_env ? "DS4_FLASH_MOE_MPP_INT8_MID_QSCALE" : "DS4_FLASH_MOE_ANE_MID_QSCALE";

    float wq = ds4_gpu_prefill_int8_qscale_from_env(w_primary, w_fallback, 512.0f);
    float xq = ds4_gpu_prefill_int8_qscale_from_env(x_primary, x_fallback, 32.0f);
    float midq = ds4_gpu_prefill_int8_qscale_from_env(mid_primary, mid_fallback, 32.0f);

    if (w_qscale) *w_qscale = wq;
    if (w_scale) *w_scale = 1.0f / wq;
    if (x_qscale) *x_qscale = xq;
    if (x_scale) *x_scale = 1.0f / xq;
    if (mid_qscale) *mid_qscale = midq;
    if (mid_scale) *mid_scale = 1.0f / midq;
}

static void ds4_gpu_ane_prefill_env(float *w_qscale,
                                    float *w_scale,
                                    float *x_qscale,
                                    float *x_scale,
                                    float *mid_qscale,
                                    float *mid_scale,
                                    uint32_t *batch,
                                    uint32_t *compile_limit) {
    float aq = 512.0f;
    float wscale = 1.0f / 512.0f;
    float xq = 32.0f;
    float xscale = 1.0f / 32.0f;
    float midq = 32.0f;
    float midscale = 1.0f / 32.0f;
    ds4_gpu_prefill_int8_scales(1, &aq, &wscale, &xq, &xscale, &midq, &midscale);

    uint32_t b = 256u;
    const char *batch_env = getenv("DS4_FLASH_MOE_ANE_BATCH");
    if (batch_env && batch_env[0]) {
        char *end = NULL;
        unsigned long parsed = strtoul(batch_env, &end, 10);
        if (end != batch_env && parsed > 0 && parsed <= 4096ul) b = (uint32_t)parsed;
    }

    uint32_t limit = 8u;
    const char *compile_limit_env = getenv("DS4_FLASH_MOE_ANE_COMPILE_LIMIT");
    if (compile_limit_env && compile_limit_env[0]) {
        char *end = NULL;
        unsigned long parsed = strtoul(compile_limit_env, &end, 10);
        if (end != compile_limit_env && parsed <= 128ul) limit = (uint32_t)parsed;
    }

    if (w_qscale) *w_qscale = aq;
    if (w_scale) *w_scale = wscale;
    if (x_qscale) *x_qscale = xq;
    if (x_scale) *x_scale = xscale;
    if (mid_qscale) *mid_qscale = midq;
    if (mid_scale) *mid_scale = midscale;
    if (batch) *batch = b;
    if (compile_limit) *compile_limit = limit;
}

static int ds4_gpu_env_has_value(const char *name) {
    const char *e = getenv(name);
    return e && e[0];
}

static void ds4_gpu_ane_prefill_apply_q4_int8_scale(uint32_t gate_type,
                                                    uint32_t down_type,
                                                    float   *w_qscale,
                                                    float   *w_scale) {
    if (gate_type != DS4_METAL_TENSOR_Q4_K ||
        down_type != DS4_METAL_TENSOR_Q4_K ||
        !w_qscale ||
        !w_scale) {
        return;
    }

    float q = *w_qscale;
    if (ds4_gpu_env_has_value("DS4_FLASH_MOE_ANE_Q4_INT8_QSCALE") ||
        ds4_gpu_env_has_value("DS4_FLASH_MOE_ANE_Q4_W_QSCALE")) {
        q = ds4_gpu_prefill_int8_qscale_from_env("DS4_FLASH_MOE_ANE_Q4_INT8_QSCALE",
                                                 "DS4_FLASH_MOE_ANE_Q4_W_QSCALE",
                                                 320.0f);
    } else if (!ds4_gpu_env_has_value("DS4_FLASH_MOE_ANE_INT8_QSCALE")) {
        q = 320.0f;
    }
    if (q > 0.0f && isfinite(q)) {
        *w_qscale = q;
        *w_scale = 1.0f / q;
    }
}

/* The i8i8 ANE MIL generator is shape-parameterized, but keep production entry
 * points fail-closed to the Flash and experimental Pro routed expert shapes. */
static int ds4_gpu_ane_prefill_shape_supported(uint32_t expert_in_dim,
                                               uint32_t expert_mid_dim,
                                               uint32_t out_dim) {
    if (expert_in_dim != out_dim) return 0;
    if ((expert_in_dim % 256u) != 0 || (expert_mid_dim % 256u) != 0) return 0;
    if (expert_in_dim == 4096u && expert_mid_dim == 2048u) return 1;
    if (expert_in_dim == 7168u && expert_mid_dim == 3072u) return 1;
    return ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_ANE_ALLOW_UNTESTED_SHAPE");
}

static const char *ds4_gpu_ane_mode_name(int mode);

/* Acquire a free dequant slot; grow its buffers if needed.  Blocks (cv) when
 * all slots are in use, which serves as backpressure if the scheduler tries
 * to start more concurrent ANE jobs than the pool can hold.  Returns -1 on
 * fatal allocation failure. */
static int ds4_gpu_ane_acquire_dequant_slot(NSUInteger gate_i8_bytes,
                                             NSUInteger up_i8_bytes,
                                             NSUInteger down_i8_bytes,
                                             NSUInteger x_i8_bytes) {
    pthread_mutex_lock(&g_ane_dequant_slot_mu);
    int idx = -1;
    while (idx < 0) {
        for (int i = 0; i < DS4_ANE_DEQUANT_SLOTS; i++) {
            if (!g_ane_dequant_slots[i].in_use) {
                g_ane_dequant_slots[i].in_use = 1;
                idx = i;
                break;
            }
        }
        if (idx < 0) {
            pthread_cond_wait(&g_ane_dequant_slot_cv, &g_ane_dequant_slot_mu);
        }
    }
    pthread_mutex_unlock(&g_ane_dequant_slot_mu);

    ds4_ane_dequant_slot_t *slot = &g_ane_dequant_slots[idx];
    if (!ds4_gpu_ensure_scratch_buffer(&slot->gate_i8, &slot->gate_i8_bytes,
                                       gate_i8_bytes, "ds4_ane_dequant_slot_gate_i8") ||
        !ds4_gpu_ensure_scratch_buffer(&slot->up_i8, &slot->up_i8_bytes,
                                       up_i8_bytes, "ds4_ane_dequant_slot_up_i8") ||
        !ds4_gpu_ensure_scratch_buffer(&slot->down_i8, &slot->down_i8_bytes,
                                       down_i8_bytes, "ds4_ane_dequant_slot_down_i8") ||
        !ds4_gpu_ensure_scratch_buffer(&slot->x_i8, &slot->x_i8_bytes,
                                       x_i8_bytes, "ds4_ane_dequant_slot_x_i8")) {
        pthread_mutex_lock(&g_ane_dequant_slot_mu);
        slot->in_use = 0;
        pthread_cond_broadcast(&g_ane_dequant_slot_cv);
        pthread_mutex_unlock(&g_ane_dequant_slot_mu);
        return -1;
    }
    return idx;
}

static void ds4_gpu_ane_release_dequant_slot(int idx) {
    if (idx < 0 || idx >= DS4_ANE_DEQUANT_SLOTS) return;
    pthread_mutex_lock(&g_ane_dequant_slot_mu);
    g_ane_dequant_slots[idx].in_use = 0;
    pthread_cond_broadcast(&g_ane_dequant_slot_cv);
    pthread_mutex_unlock(&g_ane_dequant_slot_mu);
}

static void ds4_gpu_ane_ctx_cache_clear(void) {
    for (uint32_t i = 0; i < DS4_ANE_CTX_CACHE_MAX; i++) {
        ds4_ane_mlp_int8w_destroy(g_ane_ctx_cache[i].ctx);
        memset(&g_ane_ctx_cache[i], 0, sizeof(g_ane_ctx_cache[i]));
        ds4_ane_mlp_int8w_destroy(g_ane_ctx_cache_b[i].ctx);
        memset(&g_ane_ctx_cache_b[i], 0, sizeof(g_ane_ctx_cache_b[i]));
        ds4_ane_mlp_int8w_destroy(g_ane_ctx_cache_c[i].ctx);
        memset(&g_ane_ctx_cache_c[i], 0, sizeof(g_ane_ctx_cache_c[i]));
        ds4_ane_mlp_int8w_destroy(g_ane_ctx_cache_d[i].ctx);
        memset(&g_ane_ctx_cache_d[i], 0, sizeof(g_ane_ctx_cache_d[i]));
    }
}

static uint32_t ds4_gpu_ane_parse_batch_list(uint32_t fallback,
                                             uint32_t *batches,
                                             uint32_t max_batches) {
    if (!batches || max_batches == 0) return 0;
    uint32_t count = 0;
    const char *env = getenv("DS4_FLASH_MOE_ANE_BATCHES");
    if (env && env[0]) {
        const char *p = env;
        while (*p && count < max_batches) {
            while (*p == ',' || *p == ':' || *p == ';' || isspace((unsigned char)*p)) p++;
            if (!*p) break;
            char *end = NULL;
            unsigned long parsed = strtoul(p, &end, 10);
            if (end == p) break;
            if (parsed > 0 && parsed <= 4096ul) {
                uint32_t b = (uint32_t)parsed;
                int dup = 0;
                for (uint32_t i = 0; i < count; i++) {
                    if (batches[i] == b) {
                        dup = 1;
                        break;
                    }
                }
                if (!dup) batches[count++] = b;
            }
            p = end;
        }
    }
    if (count == 0) batches[count++] = fallback ? fallback : 256u;
    for (uint32_t i = 1; i < count; i++) {
        uint32_t v = batches[i];
        uint32_t j = i;
        while (j > 0 && batches[j - 1] > v) {
            batches[j] = batches[j - 1];
            j--;
        }
        batches[j] = v;
    }
    return count;
}

static uint32_t ds4_gpu_ane_select_batch(uint32_t refs, uint32_t fallback) {
    uint32_t batches[DS4_ANE_CTX_CACHE_MAX];
    uint32_t count = ds4_gpu_ane_parse_batch_list(fallback, batches, DS4_ANE_CTX_CACHE_MAX);
    if (count == 0) return fallback ? fallback : 256u;
    for (uint32_t i = 0; i < count; i++) {
        if (refs <= batches[i]) return batches[i];
    }
    return batches[count - 1];
}

static ds4_ane_mlp_int8w_ctx *ds4_gpu_ane_get_i8i8_tiled_ctx_mode(uint32_t H,
                                                                  uint32_t I,
                                                                  uint32_t B,
                                                                  float w_scale,
                                                                  float x_scale,
                                                                  float mid_scale,
                                                                  uint32_t compile_limit,
                                                                  int mode) {
    if (mode != 13) mode = 6;
    const int verbose_trace = ds4_gpu_prefill_verbose_trace_enabled();
    const double trace_t0 = verbose_trace ? ds4_gpu_now_ms() : 0.0;
    for (uint32_t i = 0; i < DS4_ANE_CTX_CACHE_MAX; i++) {
        ds4_ane_ctx_cache_entry *entry = &g_ane_ctx_cache[i];
        if (entry->ctx &&
            entry->mode == mode &&
            entry->H == (int)H &&
            entry->I == (int)I &&
            entry->B == (int)B &&
            fabsf(entry->w_scale - w_scale) <= 1.0e-8f &&
            fabsf(entry->x_scale - x_scale) <= 1.0e-8f &&
            fabsf(entry->mid_scale - mid_scale) <= 1.0e-8f) {
            if (verbose_trace) {
                fprintf(stderr,
                        "ds4: prefill trace backend=ANE-cache hit cache=primary mode=%s slot=%u B=%u H=%u I=%u elapsed=%.3f ms\n",
                        ds4_gpu_ane_mode_name(mode),
                        i,
                        B,
                        H,
                        I,
                        ds4_gpu_now_ms() - trace_t0);
            }
            return entry->ctx;
        }
    }
    if (g_ane_prefill_compile_attempts >= compile_limit) {
        g_ane_prefill_compile_failures++;
        if (verbose_trace) {
            fprintf(stderr,
                    "ds4: prefill trace backend=ANE-cache compile-budget-exhausted cache=primary mode=%s B=%u H=%u I=%u attempts=%llu limit=%u elapsed=%.3f ms\n",
                    ds4_gpu_ane_mode_name(mode),
                    B,
                    H,
                    I,
                    (unsigned long long)g_ane_prefill_compile_attempts,
                    compile_limit,
                    ds4_gpu_now_ms() - trace_t0);
        }
        return NULL;
    }
    uint32_t slot = DS4_ANE_CTX_CACHE_MAX;
    for (uint32_t i = 0; i < DS4_ANE_CTX_CACHE_MAX; i++) {
        if (!g_ane_ctx_cache[i].ctx) {
            slot = i;
            break;
        }
    }
    if (slot == DS4_ANE_CTX_CACHE_MAX) {
        g_ane_prefill_compile_failures++;
        if (verbose_trace) {
            fprintf(stderr,
                    "ds4: prefill trace backend=ANE-cache cache-full cache=primary mode=%s B=%u H=%u I=%u entries=%u elapsed=%.3f ms\n",
                    ds4_gpu_ane_mode_name(mode),
                    B,
                    H,
                    I,
                    (unsigned)DS4_ANE_CTX_CACHE_MAX,
                    ds4_gpu_now_ms() - trace_t0);
        }
        return NULL;
    }
    g_ane_prefill_compile_attempts++;
    if (verbose_trace) {
        fprintf(stderr,
                "ds4: prefill trace backend=ANE-cache compile begin cache=primary mode=%s slot=%u B=%u H=%u I=%u attempt=%llu limit=%u\n",
                ds4_gpu_ane_mode_name(mode),
                slot,
                B,
                H,
                I,
                (unsigned long long)g_ane_prefill_compile_attempts,
                compile_limit);
    }
    ds4_ane_mlp_int8w_ctx *ctx = mode == 13 ?
        ds4_ane_mlp_i8w_i8x_tiled_fused_routed_create((int)H,
                                                       (int)I,
                                                       (int)B,
                                                       w_scale,
                                                       x_scale,
                                                       mid_scale) :
        ds4_ane_mlp_i8w_i8x_tiled_fused_create((int)H,
                                                (int)I,
                                                (int)B,
                                                w_scale,
                                                x_scale,
                                                mid_scale);
    if (!ctx) {
        g_ane_prefill_compile_failures++;
        if (verbose_trace) {
            fprintf(stderr,
                    "ds4: prefill trace backend=ANE-cache compile failed cache=primary mode=%s slot=%u B=%u elapsed=%.3f ms\n",
                    ds4_gpu_ane_mode_name(mode),
                    slot,
                    B,
                    ds4_gpu_now_ms() - trace_t0);
        }
        return NULL;
    }
    g_ane_ctx_cache[slot].ctx = ctx;
    g_ane_ctx_cache[slot].mode = mode;
    g_ane_ctx_cache[slot].H = (int)H;
    g_ane_ctx_cache[slot].I = (int)I;
    g_ane_ctx_cache[slot].B = (int)B;
    g_ane_ctx_cache[slot].w_scale = w_scale;
    g_ane_ctx_cache[slot].x_scale = x_scale;
    g_ane_ctx_cache[slot].mid_scale = mid_scale;
    if (verbose_trace) {
        fprintf(stderr,
                "ds4: prefill trace backend=ANE-cache compile end cache=primary mode=%s slot=%u B=%u elapsed=%.3f ms\n",
                ds4_gpu_ane_mode_name(mode),
                slot,
                B,
                ds4_gpu_now_ms() - trace_t0);
    }
    if (ds4_gpu_backend_stats_logs_enabled()) {
        fprintf(stderr,
                "ds4: ANE %s cached async prefill B=%u H=%u I=%u w_scale=%.6g x_scale=%.6g mid_scale=%.6g\n",
                ds4_gpu_ane_mode_name(mode), B, H, I, w_scale, x_scale, mid_scale);
    }
    return ctx;
}

static ds4_ane_mlp_int8w_ctx *ds4_gpu_ane_get_i8i8_tiled_ctx(uint32_t H,
                                                             uint32_t I,
                                                             uint32_t B,
                                                             float w_scale,
                                                             float x_scale,
                                                             float mid_scale,
                                                             uint32_t compile_limit) {
    return ds4_gpu_ane_get_i8i8_tiled_ctx_mode(H, I, B, w_scale, x_scale,
                                               mid_scale, compile_limit, 6);
}

/* Shared implementation for the secondary-cluster context getters.  The cache
 * argument selects which parallel context slot table to use (one per worker).
 * Like ds4_gpu_ane_get_i8i8_tiled_ctx but allocates against the given cache so
 * the caller gets a context handle distinct from the primary, for use on a
 * different ANE cluster.  Same shape + scales; same fallback budget tracking. */
static ds4_ane_mlp_int8w_ctx *ds4_gpu_ane_get_i8i8_tiled_ctx_from(
        ds4_ane_ctx_cache_entry *cache,
        uint32_t H,
        uint32_t I,
        uint32_t B,
        float w_scale,
        float x_scale,
        float mid_scale,
        uint32_t compile_limit,
        int mode) {
    if (mode != 13) mode = 6;
    const char *cache_label =
        cache == g_ane_ctx_cache_b ? "B" :
        cache == g_ane_ctx_cache_c ? "C" :
        cache == g_ane_ctx_cache_d ? "D" : "secondary";
    const int verbose_trace = ds4_gpu_prefill_verbose_trace_enabled();
    const double trace_t0 = verbose_trace ? ds4_gpu_now_ms() : 0.0;
    for (uint32_t i = 0; i < DS4_ANE_CTX_CACHE_MAX; i++) {
        ds4_ane_ctx_cache_entry *entry = &cache[i];
        if (entry->ctx &&
            entry->mode == mode &&
            entry->H == (int)H &&
            entry->I == (int)I &&
            entry->B == (int)B &&
            fabsf(entry->w_scale - w_scale) <= 1.0e-8f &&
            fabsf(entry->x_scale - x_scale) <= 1.0e-8f &&
            fabsf(entry->mid_scale - mid_scale) <= 1.0e-8f) {
            if (verbose_trace) {
                fprintf(stderr,
                        "ds4: prefill trace backend=ANE-cache hit cache=%s mode=%s slot=%u B=%u H=%u I=%u elapsed=%.3f ms\n",
                        cache_label,
                        ds4_gpu_ane_mode_name(mode),
                        i,
                        B,
                        H,
                        I,
                        ds4_gpu_now_ms() - trace_t0);
            }
            return entry->ctx;
        }
    }
    if (g_ane_prefill_compile_attempts >= compile_limit) {
        g_ane_prefill_compile_failures++;
        if (verbose_trace) {
            fprintf(stderr,
                    "ds4: prefill trace backend=ANE-cache compile-budget-exhausted cache=%s mode=%s B=%u H=%u I=%u attempts=%llu limit=%u elapsed=%.3f ms\n",
                    cache_label,
                    ds4_gpu_ane_mode_name(mode),
                    B,
                    H,
                    I,
                    (unsigned long long)g_ane_prefill_compile_attempts,
                    compile_limit,
                    ds4_gpu_now_ms() - trace_t0);
        }
        return NULL;
    }
    uint32_t slot = DS4_ANE_CTX_CACHE_MAX;
    for (uint32_t i = 0; i < DS4_ANE_CTX_CACHE_MAX; i++) {
        if (!cache[i].ctx) {
            slot = i;
            break;
        }
    }
    if (slot == DS4_ANE_CTX_CACHE_MAX) {
        g_ane_prefill_compile_failures++;
        if (verbose_trace) {
            fprintf(stderr,
                    "ds4: prefill trace backend=ANE-cache cache-full cache=%s mode=%s B=%u H=%u I=%u entries=%u elapsed=%.3f ms\n",
                    cache_label,
                    ds4_gpu_ane_mode_name(mode),
                    B,
                    H,
                    I,
                    (unsigned)DS4_ANE_CTX_CACHE_MAX,
                    ds4_gpu_now_ms() - trace_t0);
        }
        return NULL;
    }
    g_ane_prefill_compile_attempts++;
    if (verbose_trace) {
        fprintf(stderr,
                "ds4: prefill trace backend=ANE-cache compile begin cache=%s mode=%s slot=%u B=%u H=%u I=%u attempt=%llu limit=%u\n",
                cache_label,
                ds4_gpu_ane_mode_name(mode),
                slot,
                B,
                H,
                I,
                (unsigned long long)g_ane_prefill_compile_attempts,
                compile_limit);
    }
    ds4_ane_mlp_int8w_ctx *ctx_new = mode == 13 ?
        ds4_ane_mlp_i8w_i8x_tiled_fused_routed_create((int)H, (int)I, (int)B,
                                                       w_scale, x_scale, mid_scale) :
        ds4_ane_mlp_i8w_i8x_tiled_fused_create((int)H, (int)I, (int)B,
                                                w_scale, x_scale, mid_scale);
    if (!ctx_new) {
        g_ane_prefill_compile_failures++;
        if (verbose_trace) {
            fprintf(stderr,
                    "ds4: prefill trace backend=ANE-cache compile failed cache=%s mode=%s slot=%u B=%u elapsed=%.3f ms\n",
                    cache_label,
                    ds4_gpu_ane_mode_name(mode),
                    slot,
                    B,
                    ds4_gpu_now_ms() - trace_t0);
        }
        return NULL;
    }
    cache[slot].ctx = ctx_new;
    cache[slot].mode = mode;
    cache[slot].H = (int)H;
    cache[slot].I = (int)I;
    cache[slot].B = (int)B;
    cache[slot].w_scale = w_scale;
    cache[slot].x_scale = x_scale;
    cache[slot].mid_scale = mid_scale;
    if (verbose_trace) {
        fprintf(stderr,
                "ds4: prefill trace backend=ANE-cache compile end cache=%s mode=%s slot=%u B=%u elapsed=%.3f ms\n",
                cache_label,
                ds4_gpu_ane_mode_name(mode),
                slot,
                B,
                ds4_gpu_now_ms() - trace_t0);
    }
    return ctx_new;
}

