        "\n"
        "kernel void ds4_mpp_scatter_ids_i32_f32_counted(device const int32_t *src [[buffer(0)]],\n"
        "                                              device const int32_t *hids [[buffer(1)]],\n"
        "                                              device float *dst [[buffer(2)]],\n"
