        "\n"
        "kernel void ds4_mpp_swiglu_weight_f32(device const float *gate [[buffer(0)]],\n"
        "                                     device const float *up [[buffer(1)]],\n"
        "                                     device float *mid [[buffer(2)]],\n"
        "                                     device const float *weights [[buffer(3)]],\n"
        "                                     constant uint &width [[buffer(4)]],\n"
        "                                     constant uint &rows [[buffer(5)]],\n"
        "                                     constant float &clamp_value [[buffer(6)]],\n"
        "                                     constant float &input_scale [[buffer(7)]],\n"
        "                                     uint row [[threadgroup_position_in_grid]],\n"
        "                                     uint tid [[thread_position_in_threadgroup]],\n"
        "                                     uint ntg [[threads_per_threadgroup]]) {\n"
        "    if (row >= rows) return;\n"
        "    const float route_weight = weights[row];\n"
        "    device const float *gate_row = gate + (ulong)row * width;\n"
        "    device const float *up_row = up + (ulong)row * width;\n"
        "    device float *mid_row = mid + (ulong)row * width;\n"
        "    for (uint i = tid; i < width; i += ntg) {\n"
        "        float g = gate_row[i] * input_scale;\n"
        "        float u = up_row[i] * input_scale;\n"
        "        if (clamp_value > 1.0e-6f) {\n"
        "            g = min(g, clamp_value);\n"
        "            u = clamp(u, -clamp_value, clamp_value);\n"
        "        }\n"
        "        const float silu = g / (1.0f + exp(-g));\n"
        "        mid_row[i] = silu * u * route_weight;\n"
        "    }\n"
        "}\n"
        "\n"
        "kernel void ds4_mpp_swiglu_i32_weight_f32(device const int32_t *gate [[buffer(0)]],\n"
        "                                         device const int32_t *up [[buffer(1)]],\n"
        "                                         device float *mid [[buffer(2)]],\n"
        "                                         device const float *weights [[buffer(3)]],\n"
        "                                         constant uint &width [[buffer(4)]],\n"
        "                                         constant uint &rows [[buffer(5)]],\n"
        "                                         constant float &clamp_value [[buffer(6)]],\n"
        "                                         constant float &input_scale [[buffer(7)]],\n"
        "                                         uint row [[threadgroup_position_in_grid]],\n"
        "                                         uint tid [[thread_position_in_threadgroup]],\n"
        "                                         uint ntg [[threads_per_threadgroup]]) {\n"
        "    if (row >= rows) return;\n"
        "    const float route_weight = weights[row];\n"
        "    device const int32_t *gate_row = gate + (ulong)row * width;\n"
        "    device const int32_t *up_row = up + (ulong)row * width;\n"
        "    device float *mid_row = mid + (ulong)row * width;\n"
        "    for (uint i = tid; i < width; i += ntg) {\n"
        "        float g = float(gate_row[i]) * input_scale;\n"
        "        float u = float(up_row[i]) * input_scale;\n"
        "        if (clamp_value > 1.0e-6f) {\n"
        "            g = min(g, clamp_value);\n"
        "            u = clamp(u, -clamp_value, clamp_value);\n"
        "        }\n"
        "        const float silu = g / (1.0f + exp(-g));\n"
        "        mid_row[i] = silu * u * route_weight;\n"
        "    }\n"
        "}\n"
        "\n"
        "kernel void ds4_mpp_swiglu_i32_weight_i8(device const int32_t *gate [[buffer(0)]],\n"
        "                                        device const int32_t *up [[buffer(1)]],\n"
        "                                        device int8_t *mid [[buffer(2)]],\n"
        "                                        device const float *weights [[buffer(3)]],\n"
        "                                        constant uint &width [[buffer(4)]],\n"
        "                                        constant uint &rows [[buffer(5)]],\n"
        "                                        constant float &clamp_value [[buffer(6)]],\n"
        "                                        constant float &input_scale [[buffer(7)]],\n"
        "                                        constant float &mid_qscale [[buffer(8)]],\n"
        "                                        uint row [[threadgroup_position_in_grid]],\n"
        "                                        uint tid [[thread_position_in_threadgroup]],\n"
        "                                        uint ntg [[threads_per_threadgroup]]) {\n"
        "    if (row >= rows) return;\n"
        "    const float route_weight = weights[row];\n"
        "    device const int32_t *gate_row = gate + (ulong)row * width;\n"
        "    device const int32_t *up_row = up + (ulong)row * width;\n"
        "    device int8_t *mid_row = mid + (ulong)row * width;\n"
        "    for (uint i = tid; i < width; i += ntg) {\n"
        "        float g = float(gate_row[i]) * input_scale;\n"
        "        float u = float(up_row[i]) * input_scale;\n"
        "        if (clamp_value > 1.0e-6f) {\n"
        "            g = min(g, clamp_value);\n"
        "            u = clamp(u, -clamp_value, clamp_value);\n"
        "        }\n"
        "        const float silu = g / (1.0f + exp(-g));\n"
        "        const float v = silu * u * route_weight * mid_qscale;\n"
        "        mid_row[i] = int8_t(int(rint(clamp(v, -128.0f, 127.0f))));\n"
        "    }\n"
        "}\n"
        "\n"
        "kernel void ds4_mpp_swiglu_i32_hids_weight_i8_counted(device const int32_t *gate [[buffer(0)]],\n"
        "                                                     device const int32_t *up [[buffer(1)]],\n"
        "                                                     device int8_t *mid [[buffer(2)]],\n"
        "                                                     device const float *weights [[buffer(3)]],\n"
        "                                                     device const int32_t *hids [[buffer(4)]],\n"
        "                                                     device const uint *counts [[buffer(5)]],\n"
        "                                                     constant uint &expert [[buffer(6)]],\n"
        "                                                     constant uint &width [[buffer(7)]],\n"
        "                                                     constant float &clamp_value [[buffer(8)]],\n"
        "                                                     constant float &input_scale [[buffer(9)]],\n"
        "                                                     constant float &mid_qscale [[buffer(10)]],\n"
        "                                                     uint row [[threadgroup_position_in_grid]],\n"
        "                                                     uint tid [[thread_position_in_threadgroup]],\n"
        "                                                     uint ntg [[threads_per_threadgroup]]) {\n"
        "    if (row >= counts[expert]) return;\n"
        "    const int32_t id = hids[row];\n"
        "    const float route_weight = weights[id];\n"
        "    device const int32_t *gate_row = gate + (ulong)row * width;\n"
        "    device const int32_t *up_row = up + (ulong)row * width;\n"
        "    device int8_t *mid_row = mid + (ulong)row * width;\n"
        "    for (uint i = tid; i < width; i += ntg) {\n"
        "        float g = float(gate_row[i]) * input_scale;\n"
        "        float u = float(up_row[i]) * input_scale;\n"
        "        if (clamp_value > 1.0e-6f) {\n"
        "            g = min(g, clamp_value);\n"
        "            u = clamp(u, -clamp_value, clamp_value);\n"
        "        }\n"
        "        const float silu = g / (1.0f + exp(-g));\n"
        "        const float v = silu * u * route_weight * mid_qscale;\n"
        "        mid_row[i] = int8_t(int(rint(clamp(v, -128.0f, 127.0f))));\n"
        "    }\n"
        "}\n"
        "\n"
        "kernel void ds4_mpp_scale_i32_f32(device const int32_t *src [[buffer(0)]], device float *dst [[buffer(1)]],\n"
        "                                  constant uint &n [[buffer(2)]], constant float &scale [[buffer(3)]],\n"
        "                                  uint tid [[thread_position_in_grid]]) {\n"
        "    if (tid >= n) return;\n"
        "    dst[tid] = float(src[tid]) * scale;\n"
        "}\n"
        "\n"
        "kernel void ds4_ane_output_pack_f16_f32(device const half *src [[buffer(0)]],\n"
        "                                        device float *dst [[buffer(1)]],\n"
        "                                        device const float *weights [[buffer(2)]],\n"
        "                                        constant uint &width [[buffer(3)]],\n"
        "                                        constant uint &rows [[buffer(4)]],\n"
        "                                        uint row [[threadgroup_position_in_grid]],\n"
        "                                        uint tid [[thread_position_in_threadgroup]],\n"
        "                                        uint ntg [[threads_per_threadgroup]]) {\n"
        "    if (row >= rows) return;\n"
        "    const float weight = weights[row];\n"
        "    device const half *src_row = src + (ulong)row * width;\n"
        "    device float *dst_row = dst + (ulong)row * width;\n"
        "    for (uint i = tid; i < width; i += ntg) {\n"
        "        dst_row[i] = float(src_row[i]) * weight;\n"
        "    }\n"
        "}\n";
}

static id<MTLComputePipelineState> ds4_gpu_make_mpp_pipeline(
        id<MTLLibrary> library,
        NSString      *name) {
    if (!library || !name) return nil;
    NSError *error = nil;
    id<MTLFunction> fn = [library newFunctionWithName:name];
    if (!fn) return nil;
    id<MTLComputePipelineState> pipeline =
        [g_device newComputePipelineStateWithFunction:fn error:&error];
    if (!pipeline) {
        fprintf(stderr, "ds4: MPP int8 pipeline %s failed: %s\n",
                [name UTF8String], [[error localizedDescription] UTF8String]);
    }
    return pipeline;
}

/* Build the fused-dequant NAX matmul library (separate MTLLanguageVersion4_0 library,
 * reads metal/nax_fused.metal from disk). Idempotent; builds once. Hosts the routed-MoE
 * fused kernels and the dense Q8_0 NAX matmul. Non-fatal: callers fall back if a pipeline
 * is nil. */
static void ds4_gpu_ensure_nax_fused_library(void) {
    static bool tried = false;
    if (tried) return;
    tried = true;
    if (!g_device) return;
    NSFileManager *fm = [NSFileManager defaultManager];
    const char *override_path = getenv("DS4_METAL_NAX_FUSED_SOURCE");
    NSMutableArray<NSString *> *paths = [NSMutableArray array];
    if (override_path && override_path[0]) [paths addObject:[NSString stringWithUTF8String:override_path]];
    [paths addObject:@"metal/nax_fused.metal"];
    [paths addObject:@"./metal/nax_fused.metal"];
    NSString *fused_src = nil;
    for (NSString *path in paths) {
        if (![fm fileExistsAtPath:path]) continue;
        fused_src = [NSString stringWithContentsOfFile:path encoding:NSUTF8StringEncoding error:NULL];
        if (fused_src) break;
    }
    if (!fused_src) return;
    NSError *ferr = nil;
    MTLCompileOptions *fopts = [MTLCompileOptions new];
    fopts.languageVersion = MTLLanguageVersion4_0;
    /* Autotune knobs injected as preprocessor macros from env (see metal/nax_fused.metal).
     * Unset env -> macro omitted -> kernel's #ifndef default (shipped behavior). */
    {
        NSMutableDictionary *macros = [NSMutableDictionary dictionary];
        const char *idx_relaxed = getenv("DS4_GPU_INDEXER_RELAXED");
        if (idx_relaxed && idx_relaxed[0])
            macros[@"DS4_IDX_RELAXED"] = (atoi(idx_relaxed) != 0) ? @"true" : @"false";
        const char *idx_walk = getenv("DS4_GPU_INDEXER_WALK");
        if (idx_walk && idx_walk[0])
            macros[@"DS4_IDX_WALK"] = (atoi(idx_walk) != 0) ? @"1" : @"0";
        const char *dense_walk = getenv("DS4_GPU_DENSE_WALK");
        if (dense_walk && dense_walk[0])
            macros[@"DS4_DENSE_WALK"] = (atoi(dense_walk) != 0) ? @"1" : @"0";
        const char *attn_nr1 = getenv("DS4_GPU_ATTN_NR1");
        if (attn_nr1 && attn_nr1[0])
            macros[@"DS4_ATTN_NR1"] = (atoi(attn_nr1) == 64) ? @"64" : @"128";
        const char *attn_nk = getenv("DS4_GPU_ATTN_NK");
        if (attn_nk && attn_nk[0])
            macros[@"DS4_ATTN_NK"] = (atoi(attn_nk) == 64) ? @"64" : @"32";
        if (macros.count) {
            fopts.preprocessorMacros = macros;
            fprintf(stderr, "ds4: NAX fused library macros: %s\n",
                    [[macros description] UTF8String]);
        }
    }
    g_nax_fused_library = [g_device newLibraryWithSource:fused_src options:fopts error:&ferr];
    if (!g_nax_fused_library) {
        fprintf(stderr, "ds4: NAX fused matmul library compile failed: %s\n",
                [[ferr localizedDescription] UTF8String]);
        return;
    }
    g_mpp_iq2_fused_pipeline = ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_mpp_iq2_i8_i32_counted");
    g_mpp_iq2_fused_n64_pipeline = ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_mpp_iq2_i8_i32_counted_n64");
    g_mpp_iq2_fused_n128_pipeline = ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_mpp_iq2_i8_i32_counted_n128");
    g_mpp_iq2_fused_n256_pipeline = ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_mpp_iq2_i8_i32_counted_n256");
    g_mpp_fused_gate_up_swiglu_h_h_f_n32_pipeline =
        ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_mpp_fused_gate_up_swiglu_h_h_f_n32");
    g_mpp_mul_rows_weight_f32_pipeline =
        ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_mpp_mul_rows_weight_f32");
    g_mpp_iq2_fused_gate_up_swiglu_pipeline =
        ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_mpp_iq2_fused_gate_up_swiglu_counted");
    g_mpp_iq2_fused_gate_up_swiglu_contig_pipeline =
        ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_mpp_iq2_fused_gate_up_swiglu_contig");
    g_mpp_iq2_fused_gate_up_swiglu_contig_m32_pipeline =
        ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_mpp_iq2_fused_gate_up_swiglu_contig_m32");
    g_mpp_iq2_i8_i32_multi_pipeline =
        ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_mpp_iq2_i8_i32_multi");
    g_mpp_q2k_i8_i32_multi_pipeline =
        ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_mpp_q2k_i8_i32_multi");
    g_mpp_q2k_fused_pipeline = ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_mpp_q2k_i8_i32_counted");
    g_mpp_q2k_fused_n64_pipeline = ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_mpp_q2k_i8_i32_counted_n64");
    g_mpp_q2k_fused_n128_pipeline = ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_mpp_q2k_i8_i32_counted_n128");
    g_mpp_q2k_fused_n256_pipeline = ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_mpp_q2k_i8_i32_counted_n256");
    g_dense_q8_nax_pipeline  = ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_dense_q8_nax");
    g_dense_i8_fused_pipeline = ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_dense_i8_fused");
    g_repack_q8_i8_pipeline = ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_repack_q8_to_i8_rowscale");
    g_quant_act_pertoken_i8_pipeline = ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_quant_act_pertoken_i8");
    g_indexer_scores_nax_pipeline = ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_indexer_scores_nax");
    g_attn_out_low_nax_pipeline = ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_attn_out_low_q8_nax");
    g_attn_out_low_i8_pipeline = ds4_gpu_make_mpp_pipeline(g_nax_fused_library, @"ds4_attn_out_low_i8_fused");
}

/* MTLLanguageVersion4_1 is declared in the macOS 27 SDK; the numeric fallback
 * keeps builds on older SDKs working (use is runtime-gated by @available). */
#define DS4_MTL_LANGUAGE_VERSION_4_1 ((MTLLanguageVersion)((4 << 16) + 1))

static NSString *ds4_gpu_read_metal_source(const char *env_override,
                                           NSString   *rel_path) {
    NSFileManager *fm = [NSFileManager defaultManager];
    NSMutableArray<NSString *> *paths = [NSMutableArray array];
    if (env_override) {
        const char *p = getenv(env_override);
        if (p && p[0]) [paths addObject:[NSString stringWithUTF8String:p]];
    }
    [paths addObject:rel_path];
    [paths addObject:[@"./" stringByAppendingString:rel_path]];
    for (NSString *path in paths) {
        if (![fm fileExistsAtPath:path]) continue;
        NSString *src = [NSString stringWithContentsOfFile:path
                                                  encoding:NSUTF8StringEncoding
                                                     error:NULL];
        if (src) return src;
    }
    return nil;
}

/* Build the optional native-MXFP4 library (docs/mxfp4-native-sidecar-plan.md,
 * "MPP 4.1 readiness scaffolding").  Separate MTLLanguageVersion4_1 library on
 * macOS 27 — the scale-plane matmul2d needs the 4.1 tensor_blockwise headers;
 * on macOS 26 it falls back to 4_0, which compiles only the plane-repack
 * kernel (the native section is #if-guarded by __HAVE_TENSOR_MULTIPLANE__).
 * Source = metal/mxfp4_common.h PREPENDED to metal/mxfp4_native.metal because
 * newLibraryWithSource: cannot resolve local #includes.  Idempotent;
 * non-fatal: callers must treat nil pipelines as "native path unavailable". */
static void ds4_gpu_ensure_mxfp4_native_library(void) {
    static bool tried = false;
    if (tried) return;
    tried = true;
    if (!g_device) return;
    NSString *hdr = ds4_gpu_read_metal_source("DS4_METAL_MXFP4_COMMON_SOURCE",
                                              @"metal/mxfp4_common.h");
    NSString *body = ds4_gpu_read_metal_source("DS4_METAL_MXFP4_NATIVE_SOURCE",
                                               @"metal/mxfp4_native.metal");
    if (!hdr || !body) {
        fprintf(stderr, "ds4: MXFP4 native metal sources not found (metal/mxfp4_common.h + metal/mxfp4_native.metal)\n");
        return;
    }
    NSString *src = [NSString stringWithFormat:@"%@\n%@", hdr, body];
    MTLCompileOptions *opts = [MTLCompileOptions new];
    bool lang41 = false;
    if (@available(macOS 27.0, *)) {
        opts.languageVersion = DS4_MTL_LANGUAGE_VERSION_4_1;
        lang41 = true;
    } else {
        opts.languageVersion = MTLLanguageVersion4_0;
    }
    NSError *err = nil;
    g_mxfp4_native_library = [g_device newLibraryWithSource:src options:opts error:&err];
    if (!g_mxfp4_native_library && lang41) {
        /* macOS 27 host with a pre-4.1 Metal toolchain: retry repack-only. */
        opts.languageVersion = MTLLanguageVersion4_0;
        err = nil;
        lang41 = false;
        g_mxfp4_native_library = [g_device newLibraryWithSource:src options:opts error:&err];
    }
    if (!g_mxfp4_native_library) {
        fprintf(stderr, "ds4: MXFP4 native library compile failed: %s\n",
                [[err localizedDescription] UTF8String]);
        return;
    }
    g_mxfp4_repack_planes_pipeline =
        ds4_gpu_make_mpp_pipeline(g_mxfp4_native_library, @"kernel_dsv4_mxfp4_repack_planes");
    g_mxfp4_repack_selected_planes_pipeline =
        ds4_gpu_make_mpp_pipeline(g_mxfp4_native_library, @"kernel_dsv4_mxfp4_repack_selected_planes");
    g_mxfp4_copy_selected_planes_pipeline =
        ds4_gpu_make_mpp_pipeline(g_mxfp4_native_library, @"kernel_dsv4_mxfp4_copy_selected_planes");
    g_mxfp4_native_matmul_n64_pipeline =
        ds4_gpu_make_mpp_pipeline(g_mxfp4_native_library, @"kernel_dsv4_mxfp4_native_matmul_n64");
    g_mxfp4_native_matmul_selected_n64_pipeline =
        ds4_gpu_make_mpp_pipeline(g_mxfp4_native_library, @"kernel_dsv4_mxfp4_native_matmul_selected_n64");
    g_mxfp4_plane_id_pair_swiglu_pipeline =
        ds4_gpu_make_mpp_pipeline(g_mxfp4_native_library, @"kernel_dsv4_mxfp4_plane_id_pair_swiglu_f32");
    g_mxfp4_plane_id_sum6_pipeline =
        ds4_gpu_make_mpp_pipeline(g_mxfp4_native_library, @"kernel_dsv4_mxfp4_plane_id_sum6_f32");
    g_mxfp4_plane_id_batch_pair_swiglu_pipeline =
        ds4_gpu_make_mpp_pipeline(g_mxfp4_native_library, @"kernel_dsv4_mxfp4_plane_id_batch_pair_swiglu_f32");
    g_mxfp4_plane_id_batch_sum6_pipeline =
        ds4_gpu_make_mpp_pipeline(g_mxfp4_native_library, @"kernel_dsv4_mxfp4_plane_id_batch_sum6_f32");
    g_mxfp4_plane_slots6_sum6_pipeline =
        ds4_gpu_make_mpp_pipeline(g_mxfp4_native_library, @"kernel_dsv4_mxfp4_plane_slots6_sum6_f32");
    g_mxfp4_plane_id_chunked_pair_swiglu_pipeline =
        ds4_gpu_make_mpp_pipeline(g_mxfp4_native_library, @"kernel_dsv4_mxfp4_plane_id_chunked_pair_swiglu_f32");
    g_mxfp4_plane_id_chunked_sum6_pipeline =
        ds4_gpu_make_mpp_pipeline(g_mxfp4_native_library, @"kernel_dsv4_mxfp4_plane_id_chunked_sum6_f32");
    fprintf(stderr, "ds4: MXFP4 native library (MSL %s): repack=%s selected-repack=%s selected-plane-copy=%s scale-plane matmul=%s selected-matmul=%s decode2=%s/%s batch-decode2=%s/%s hybrid-down=%s chunked-decode2=%s/%s\n",
            lang41 ? "4.1" : "4.0",
            g_mxfp4_repack_planes_pipeline ? "ok" : "MISSING",
            g_mxfp4_repack_selected_planes_pipeline ? "ok" : "MISSING",
            g_mxfp4_copy_selected_planes_pipeline ? "ok" : "MISSING",
            g_mxfp4_native_matmul_n64_pipeline ? "ok" : "unavailable (needs macOS 27 toolchain + M5)",
            g_mxfp4_native_matmul_selected_n64_pipeline ? "ok" : "unavailable",
            g_mxfp4_plane_id_pair_swiglu_pipeline ? "pair" : "missing-pair",
            g_mxfp4_plane_id_sum6_pipeline ? "sum6" : "missing-sum6",
            g_mxfp4_plane_id_batch_pair_swiglu_pipeline ? "pair" : "missing-pair",
            g_mxfp4_plane_id_batch_sum6_pipeline ? "sum6" : "missing-sum6",
            g_mxfp4_plane_slots6_sum6_pipeline ? "sum6" : "missing-sum6",
            g_mxfp4_plane_id_chunked_pair_swiglu_pipeline ? "pair" : "missing-pair",
            g_mxfp4_plane_id_chunked_sum6_pipeline ? "sum6" : "missing-sum6");
}

/* Native-MXFP4 opt-in (default off): DS4_MXFP4_NATIVE=1. */
int ds4_gpu_mxfp4_native_requested(void) {
    return ds4_gpu_env_flag_enabled("DS4_MXFP4_NATIVE");
}

/* Definitive native-MXFP4 probe (plan item 4): true only when the MPP 4.1
 * scale-plane matmul pipeline actually built on this OS/toolchain/GPU.
 * Cheap after the first call; safe to call from backend selection. */
int ds4_gpu_has_native_mxfp4(void) {
    if (!g_device) return 0;
    ds4_gpu_ensure_mxfp4_native_library();
    return g_mxfp4_native_matmul_n64_pipeline != nil;
}

/* Encode the one-time MXFP4 plane repack: ggml 17 B split-half blocks at
 * (src + src_off) -> FP4 seq-pair data plane at (dst + data_off) + E8M0
 * scale plane at (dst + scales_off), for one [rows][depth] weight matrix.
 * data plane = rows*depth/2 bytes, scale plane = rows*depth/32 bytes. */
static int ds4_gpu_encode_mxfp4_repack_planes(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        src,
        NSUInteger           src_off,
        id<MTLBuffer>        dst,
        NSUInteger           data_off,
        NSUInteger           scales_off,
        uint32_t             rows,
        uint32_t             depth) {
    if (!cb || !src || !dst || rows == 0 || depth == 0 || (depth % 32u) != 0) return 0;
    ds4_gpu_ensure_mxfp4_native_library();
    if (!g_mxfp4_repack_planes_pipeline) return 0;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_mxfp4_repack_planes_pipeline];
    [enc setBuffer:src offset:src_off atIndex:0];
    [enc setBuffer:dst offset:data_off atIndex:1];
    [enc setBuffer:dst offset:scales_off atIndex:2];
    const uint32_t zero = 0;
    [enc setBytes:&rows length:sizeof(rows) atIndex:3];
    [enc setBytes:&depth length:sizeof(depth) atIndex:4];
    [enc setBytes:&zero length:sizeof(zero) atIndex:5];
    [enc setBytes:&zero length:sizeof(zero) atIndex:6];
    [enc setBytes:&zero length:sizeof(zero) atIndex:7];
    [enc dispatchThreadgroups:MTLSizeMake((depth / 32u + 63u) / 64u, rows, 1)
         threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_mxfp4_repack_selected_planes(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        src,
        NSUInteger           src_off,
        id<MTLBuffer>        dst,
        NSUInteger           data_off,
        NSUInteger           scales_off,
        id<MTLBuffer>        selected,
        NSUInteger           selected_off,
        uint32_t             route,
        uint32_t             rows,
        uint32_t             depth,
        uint32_t             slot_stride) {
    if (!cb || !src || !dst || !selected || rows == 0 || depth == 0 ||
        (depth % 32u) != 0 || slot_stride == 0) {
        return 0;
    }
    ds4_gpu_ensure_mxfp4_native_library();
    if (!g_mxfp4_repack_selected_planes_pipeline) return 0;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_mxfp4_repack_selected_planes_pipeline];
    [enc setBuffer:src offset:src_off atIndex:0];
    [enc setBuffer:dst offset:data_off atIndex:1];
    [enc setBuffer:dst offset:scales_off atIndex:2];
    [enc setBuffer:selected offset:selected_off atIndex:3];
    [enc setBytes:&rows length:sizeof(rows) atIndex:4];
    [enc setBytes:&depth length:sizeof(depth) atIndex:5];
    [enc setBytes:&slot_stride length:sizeof(slot_stride) atIndex:6];
    [enc setBytes:&route length:sizeof(route) atIndex:7];
    [enc dispatchThreadgroups:MTLSizeMake((depth / 32u + 63u) / 64u, rows, 1)
         threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_mxfp4_copy_selected_planes(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        src,
        NSUInteger           src_data_off,
        NSUInteger           src_scales_off,
        id<MTLBuffer>        dst,
        NSUInteger           data_off,
        NSUInteger           scales_off,
        id<MTLBuffer>        selected,
        NSUInteger           selected_off,
        uint32_t             route,
        uint32_t             rows,
        uint32_t             depth,
        uint32_t             slot_stride) {
    if (!cb || !src || !dst || !selected || rows == 0 || depth == 0 ||
        (depth % 32u) != 0 || slot_stride == 0) {
        return 0;
    }
    const uint64_t data_bytes = (uint64_t)rows * depth / 2u;
    const uint64_t scale_bytes = (uint64_t)rows * (depth / 32u);
    const uint64_t total_bytes = data_bytes + scale_bytes;
    if (total_bytes == 0 || total_bytes > UINT32_MAX) return 0;
    ds4_gpu_ensure_mxfp4_native_library();
    if (!g_mxfp4_copy_selected_planes_pipeline) return 0;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_mxfp4_copy_selected_planes_pipeline];
    [enc setBuffer:src offset:src_data_off atIndex:0];
    [enc setBuffer:src offset:src_scales_off atIndex:1];
    [enc setBuffer:dst offset:data_off atIndex:2];
    [enc setBuffer:dst offset:scales_off atIndex:3];
    [enc setBuffer:selected offset:selected_off atIndex:4];
    [enc setBytes:&rows length:sizeof(rows) atIndex:5];
    [enc setBytes:&depth length:sizeof(depth) atIndex:6];
    [enc setBytes:&slot_stride length:sizeof(slot_stride) atIndex:7];
    [enc setBytes:&route length:sizeof(route) atIndex:8];
    const NSUInteger tew = g_mxfp4_copy_selected_planes_pipeline.threadExecutionWidth;
    [enc dispatchThreads:MTLSizeMake((NSUInteger)total_bytes, 1, 1)
   threadsPerThreadgroup:MTLSizeMake(tew * 4u, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

/* Encode the native scale-plane matmul: c[m][n] f32 = a[m][k] f16 x MXFP4
 * weight planes (data at w+data_off, scales at w+scales_off), weights [n][k].
 * MPP clamps to tensor extents (probe-verified), so partial 64-row m tiles
 * are safe. */
static int ds4_gpu_encode_mxfp4_native_matmul(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        a,
        NSUInteger           a_off,
        id<MTLBuffer>        w,
        NSUInteger           data_off,
        NSUInteger           scales_off,
        id<MTLBuffer>        c,
        NSUInteger           c_off,
        uint32_t             m,
        uint32_t             n,
        uint32_t             k) {
    if (!cb || !a || !w || !c || m == 0 || n == 0 || k == 0 || (k % 32u) != 0) return 0;
    ds4_gpu_ensure_mxfp4_native_library();
    if (!g_mxfp4_native_matmul_n64_pipeline) return 0;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_mxfp4_native_matmul_n64_pipeline];
    [enc setBuffer:a offset:a_off atIndex:0];
    [enc setBuffer:w offset:data_off atIndex:1];
    [enc setBuffer:c offset:c_off atIndex:2];
    [enc setBytes:&m length:sizeof(m) atIndex:3];
    [enc setBytes:&n length:sizeof(n) atIndex:4];
    [enc setBytes:&k length:sizeof(k) atIndex:5];
    [enc setBuffer:w offset:scales_off atIndex:6];
    const NSUInteger tew = g_mxfp4_native_matmul_n64_pipeline.threadExecutionWidth;
    [enc dispatchThreadgroups:MTLSizeMake((n + 63u) / 64u, (m + 63u) / 64u, 1)
         threadsPerThreadgroup:MTLSizeMake(tew * 4u, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_mxfp4_native_matmul_selected(
        id<MTLCommandBuffer> cb,
