    }

    NSError *error = nil;
    MTLCompileOptions *options = [MTLCompileOptions new];
    options.languageVersion = MTLLanguageVersion4_0;
    id<MTLLibrary> library =
        [g_device newLibraryWithSource:[NSString stringWithUTF8String:ds4_gpu_mpp_int8_source()]
