static int ds4_gpu_encode_mpp_dequant_mxfp4_i8(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        src,
        NSUInteger           src_off,
        id<MTLBuffer>        dst,
        uint32_t             q_rows,
        uint32_t             q_cols,
        float                qscale) {
    if (!cb || !src || !dst || q_rows == 0 || q_cols == 0 || (q_cols % 32u) != 0) return 0;
    const uint32_t total = q_rows * (q_cols / 32u) * 2u;
    NSUInteger nth = g_mpp_dequant_mxfp4_i8_pipeline.maxTotalThreadsPerThreadgroup;
    if (nth > 256u) nth = 256u;
    if (nth == 0) nth = 1u;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_mpp_dequant_mxfp4_i8_pipeline];
    [enc setBuffer:src offset:src_off atIndex:0];
    [enc setBuffer:dst offset:0 atIndex:1];
    [enc setBytes:&q_rows length:sizeof(q_rows) atIndex:2];
    [enc setBytes:&q_cols length:sizeof(q_cols) atIndex:3];
    [enc setBytes:&total length:sizeof(total) atIndex:4];
    [enc setBytes:&qscale length:sizeof(qscale) atIndex:5];
    [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)total + nth - 1u) / nth, 1, 1)
         threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_mpp_dequant_mxfp4_planes_i8(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        src,
        NSUInteger           src_off,
        id<MTLBuffer>        dst,
        uint32_t             q_rows,
        uint32_t             q_cols,
        float                qscale) {
    if (!cb || !src || !dst || q_rows == 0 || q_cols == 0 || (q_cols % 32u) != 0) return 0;
    const uint32_t total = q_rows * (q_cols / 32u) * 2u;
    NSUInteger nth = g_mpp_dequant_mxfp4_planes_i8_pipeline.maxTotalThreadsPerThreadgroup;
    if (nth > 256u) nth = 256u;
    if (nth == 0) nth = 1u;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_mpp_dequant_mxfp4_planes_i8_pipeline];
    [enc setBuffer:src offset:src_off atIndex:0];
    [enc setBuffer:dst offset:0 atIndex:1];
    [enc setBytes:&q_rows length:sizeof(q_rows) atIndex:2];
    [enc setBytes:&q_cols length:sizeof(q_cols) atIndex:3];
    [enc setBytes:&total length:sizeof(total) atIndex:4];
    [enc setBytes:&qscale length:sizeof(qscale) atIndex:5];
    [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)total + nth - 1u) / nth, 1, 1)
         threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_mpp_dequant_i8_for_type(
        uint32_t             type,
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        src,
        NSUInteger           src_off,
        id<MTLBuffer>        dst,
        uint32_t             q_rows,
        uint32_t             q_cols,
        float                qscale) {
    switch (type) {
    case DS4_METAL_TENSOR_IQ2_XXS:
        return ds4_gpu_encode_mpp_dequant_iq2_xxs_i8(cb, src, src_off, dst,
                                                     q_rows, q_cols, qscale);
    case DS4_METAL_TENSOR_Q2_K:
        return ds4_gpu_encode_mpp_dequant_q2_k_i8(cb, src, src_off, dst,
                                                  q_rows, q_cols, qscale);
    case DS4_METAL_TENSOR_Q4_K:
        return ds4_gpu_encode_mpp_dequant_q4_k_i8(cb, src, src_off, dst,
                                                  q_rows, q_cols, qscale);
    case DS4_METAL_TENSOR_MXFP4:
        return ds4_gpu_encode_mpp_dequant_mxfp4_i8(cb, src, src_off, dst,
                                                   q_rows, q_cols, qscale);
    default:
        return 0;
    }
}

static int ds4_gpu_encode_mpp_dequant_i8_for_bank_type(
        uint32_t             type,
        int                  mxfp4_plane_split,
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        src,
        NSUInteger           src_off,
        id<MTLBuffer>        dst,
        uint32_t             q_rows,
        uint32_t             q_cols,
        float                qscale) {
    if (type == DS4_METAL_TENSOR_MXFP4 && mxfp4_plane_split) {
        return ds4_gpu_encode_mpp_dequant_mxfp4_planes_i8(cb, src, src_off, dst,
                                                          q_rows, q_cols, qscale);
    }
    return ds4_gpu_encode_mpp_dequant_i8_for_type(type, cb, src, src_off, dst,
                                                  q_rows, q_cols, qscale);
}

