static int ds4_gpu_encode_ane_dequant_f16_for_type(
        uint32_t             type,
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        src,
        NSUInteger           src_off,
        id<MTLBuffer>        dst,
        uint32_t             q_rows,
        uint32_t             q_cols) {
    switch (type) {
    case DS4_METAL_TENSOR_IQ2_XXS:
        return ds4_gpu_encode_ane_dequant_iq2_xxs_f16(cb, src, src_off, dst,
                                                      q_rows, q_cols);
    case DS4_METAL_TENSOR_Q2_K:
        return ds4_gpu_encode_ane_dequant_q2_k_f16(cb, src, src_off, dst,
                                                   q_rows, q_cols);
    case DS4_METAL_TENSOR_Q4_K:
        return ds4_gpu_encode_ane_dequant_q4_k_f16(cb, src, src_off, dst,
                                                   q_rows, q_cols);
    case DS4_METAL_TENSOR_MXFP4:
        return ds4_gpu_encode_ane_dequant_mxfp4_f16(cb, src, src_off, dst,
                                                    q_rows, q_cols);
    default:
        return 0;
    }
}

static int ds4_gpu_encode_ane_dequant_f16_for_bank_type(
        uint32_t             type,
        int                  mxfp4_plane_split,
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        src,
        NSUInteger           src_off,
        id<MTLBuffer>        dst,
        uint32_t             q_rows,
        uint32_t             q_cols) {
    if (type == DS4_METAL_TENSOR_MXFP4 && mxfp4_plane_split) {
        return ds4_gpu_encode_ane_dequant_mxfp4_planes_f16(cb, src, src_off, dst,
                                                           q_rows, q_cols);
    }
    return ds4_gpu_encode_ane_dequant_f16_for_type(type, cb, src, src_off, dst,
                                                   q_rows, q_cols);
}

static int ds4_gpu_encode_mpp_matmul(
        id<MTLCommandBuffer> cb,
        id<MTLComputePipelineState> pipeline,
        id<MTLBuffer> a,
        NSUInteger a_off,
        id<MTLBuffer> b,
        id<MTLBuffer> c,
        NSUInteger c_off,
        uint32_t m,
        uint32_t n,
        uint32_t k) {
    if (!cb || !pipeline || !a || !b || !c || m == 0 || n == 0 || k == 0) return 0;
    MTLSize tg = MTLSizeMake((NSUInteger)pipeline.threadExecutionWidth * 4u, 1, 1);
    MTLSize grid = MTLSizeMake(((NSUInteger)n + 31u) / 32u,
                               ((NSUInteger)m + 63u) / 64u,
                               1);

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:pipeline];
    [enc setBuffer:a offset:a_off atIndex:0];
    [enc setBuffer:b offset:0 atIndex:1];
    [enc setBuffer:c offset:c_off atIndex:2];
    [enc setBytes:&m length:sizeof(m) atIndex:3];
    [enc setBytes:&n length:sizeof(n) atIndex:4];
    [enc setBytes:&k length:sizeof(k) atIndex:5];
    [enc dispatchThreadgroups:grid threadsPerThreadgroup:tg];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

/* matmul2d encode with a parameterized N-tile (32/64/128) for the half-x-half
 * routed NAX path. grid-X must match the compiled kernel's N-tile. */
static int ds4_gpu_encode_mpp_matmul_tile(
        id<MTLCommandBuffer> cb,
        id<MTLComputePipelineState> pipeline,
        uint32_t tile_n,
        id<MTLBuffer> a,
        NSUInteger a_off,
        id<MTLBuffer> b,
        id<MTLBuffer> c,
        NSUInteger c_off,
        uint32_t m,
        uint32_t n,
        uint32_t k) {
    if (!cb || !pipeline || !a || !b || !c || m == 0 || n == 0 || k == 0) return 0;
    const NSUInteger tn = tile_n != 0u ? (NSUInteger)tile_n : 32u;
    MTLSize tg = MTLSizeMake((NSUInteger)pipeline.threadExecutionWidth * 4u, 1, 1);
    MTLSize grid = MTLSizeMake(((NSUInteger)n + tn - 1u) / tn,
                               ((NSUInteger)m + 63u) / 64u,
                               1);
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:pipeline];
    [enc setBuffer:a offset:a_off atIndex:0];
    [enc setBuffer:b offset:0 atIndex:1];
    [enc setBuffer:c offset:c_off atIndex:2];
    [enc setBytes:&m length:sizeof(m) atIndex:3];
    [enc setBytes:&n length:sizeof(n) atIndex:4];
    [enc setBytes:&k length:sizeof(k) atIndex:5];
    [enc dispatchThreadgroups:grid threadsPerThreadgroup:tg];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

/* iter-4 Path C: dispatch the fused gate+up+swiglu kernel that fuses two
 * matmul2d ops + per-element SwiGLU in one shader using cooperative tensors.
 * Targets in-kernel NAX∥ALU concurrency (~1.46x per expert measurement).
 * Output `mid` (M x N float) replaces the separate gate matmul + up matmul +
 * swiglu chain. Down matmul still runs separately (mid_dim=2048 doesn't fit
 * threadgroup memory for in-kernel down fusion). */
static int ds4_gpu_encode_mpp_fused_gate_up_swiglu(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        x,
        NSUInteger           x_off,
        id<MTLBuffer>        gateW,
        id<MTLBuffer>        upW,
        id<MTLBuffer>        mid,
        NSUInteger           mid_off,
        uint32_t             M,
        uint32_t             N,
        uint32_t             K,
        float                clamp_v) {
    if (!cb || !x || !gateW || !upW || !mid || M == 0 || N == 0 || K == 0 ||
        !g_mpp_fused_gate_up_swiglu_h_h_f_n32_pipeline) {
        return 0;
    }
    id<MTLComputePipelineState> p = g_mpp_fused_gate_up_swiglu_h_h_f_n32_pipeline;
    /* Kernel (FIXED 2026-06-01): NR0=64 (M-tile) NR1=32 (N-tile) SG=4 — mirrors the
     * validated h_h_f matmul (dynamic_extent K). Grid: ((N+31)/32, (M+63)/64), tg = 4
     * simdgroups. Requires M % 64 == 0 (guaranteed by the resident-path %64 floor). The
     * previous NR0=32/SG=1/NK=32 version reduced only 32 of K and diverged. */
    MTLSize tg = MTLSizeMake((NSUInteger)p.threadExecutionWidth * 4u, 1, 1);
    MTLSize grid = MTLSizeMake(((NSUInteger)N + 31u) / 32u,
                               ((NSUInteger)M + 63u) / 64u,
                               1);
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:p];
    [enc setBuffer:x     offset:x_off atIndex:0];
    [enc setBuffer:gateW offset:0     atIndex:1];
    [enc setBuffer:upW   offset:0     atIndex:2];
    [enc setBuffer:mid   offset:mid_off atIndex:3];
    [enc setBytes:&M length:sizeof(M) atIndex:4];
    [enc setBytes:&N length:sizeof(N) atIndex:5];
    [enc setBytes:&K length:sizeof(K) atIndex:6];
    [enc setBytes:&clamp_v length:sizeof(clamp_v) atIndex:7];
    [enc dispatchThreadgroups:grid threadsPerThreadgroup:tg];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

/* Reapply per-token routing weight after the Plan A fused gate+up+swiglu kernel
 * (which omits it). mid[row, 0..width) *= weights[row], rows = n_tokens. Used by
 * the slot-bank banked path where mid is per-expert contiguous and row-aligned
 * with the weights buffer. */
static int ds4_gpu_encode_mpp_mul_rows_weight_f32(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        mid,
        NSUInteger           mid_off,
        id<MTLBuffer>        weights,
        NSUInteger           weights_off,
        uint32_t             width,
        uint32_t             rows) {
    if (!cb || !mid || !weights || width == 0 || rows == 0 ||
        !g_mpp_mul_rows_weight_f32_pipeline) {
        return 0;
    }
    NSUInteger nth = g_mpp_mul_rows_weight_f32_pipeline.maxTotalThreadsPerThreadgroup;
    if (nth > 256u) nth = 256u;
    if (nth > width) nth = width;
    if (nth == 0) nth = 1u;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_mpp_mul_rows_weight_f32_pipeline];
    [enc setBuffer:mid offset:mid_off atIndex:0];
    [enc setBuffer:weights offset:weights_off atIndex:1];
    [enc setBytes:&width length:sizeof(width) atIndex:2];
    [enc setBytes:&rows length:sizeof(rows) atIndex:3];
    [enc dispatchThreadgroups:MTLSizeMake(rows, 1, 1)
         threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

