        n == 0 || k == 0 || !g_mpp_i8_i8_i32_dual_counted_pipeline) {
        return 0;
    }
    MTLSize tg = MTLSizeMake((NSUInteger)g_mpp_i8_i8_i32_dual_counted_pipeline.threadExecutionWidth * 4u,
                             1,
                             1);
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_mpp_i8_i8_i32_dual_counted_pipeline];
    [enc setBuffer:a offset:a_off atIndex:0];
    [enc setBuffer:b0 offset:0 atIndex:1];
    [enc setBuffer:c0 offset:c0_off atIndex:2];
    [enc setBuffer:b1 offset:0 atIndex:3];
    [enc setBuffer:c1 offset:c1_off atIndex:4];
    [enc setBuffer:counts offset:0 atIndex:5];
    [enc setBytes:&expert length:sizeof(expert) atIndex:6];
    [enc setBytes:&n length:sizeof(n) atIndex:7];
    [enc setBytes:&k length:sizeof(k) atIndex:8];
    [enc dispatchThreadgroupsWithIndirectBuffer:indirect
                           indirectBufferOffset:indirect_off
                          threadsPerThreadgroup:tg];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_resident_mpp_dual_gate_up_enabled(void) {
    return ds4_gpu_env_flag_enabled("DS4_RESIDENT_MOE_MPP_DUAL_GATE_UP") ||
           ds4_gpu_env_flag_enabled("DS4_RESIDENT_MOE_NAX_DUAL_GATE_UP");
}

/* Fused-dequant NAX matmul: reads quantized weights directly (iq2_xxs gate/up,
 * q2_K down), dequantizes per K-tile into threadgroup memory, and matmuls on NAX
 * with no global int8 weight buffer.  Enabled by DS4_RESIDENT_MOE_MPP_FUSED_DEQUANT
 * (default on when the fused library compiled). */
static int ds4_gpu_resident_mpp_fused_dequant_enabled(void) {
    if (ds4_gpu_no_int8_paths_enabled()) return 0;
    if (!g_mpp_iq2_fused_pipeline || !g_mpp_q2k_fused_pipeline) return 0;
    const char *env = getenv("DS4_RESIDENT_MOE_MPP_FUSED_DEQUANT");
    if (env && env[0]) return atoi(env) != 0;
    return 1; /* default on when available */
}

static uint32_t ds4_gpu_resident_mpp_int8_tile_n(void) {
    uint32_t tile_n =
        ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_MPP_INT8_TILE", 32u);
    tile_n =
        ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_NAX_INT8_TILE", tile_n);
    return (tile_n >= 256u) ? 256u :
           (tile_n >= 128u) ? 128u :
           (tile_n >= 64u)  ? 64u  : 32u;
}

static id<MTLComputePipelineState> ds4_gpu_iq2_fused_pipeline_for_tile(uint32_t tile_n) {
    switch (tile_n) {
    case 256u: return g_mpp_iq2_fused_n256_pipeline;
    case 128u: return g_mpp_iq2_fused_n128_pipeline;
    case 64u:  return g_mpp_iq2_fused_n64_pipeline;
    default:   return g_mpp_iq2_fused_pipeline;
    }
}

static id<MTLComputePipelineState> ds4_gpu_q2k_fused_pipeline_for_tile(uint32_t tile_n) {
    switch (tile_n) {
    case 256u: return g_mpp_q2k_fused_n256_pipeline;
    case 128u: return g_mpp_q2k_fused_n128_pipeline;
    case 64u:  return g_mpp_q2k_fused_n64_pipeline;
    default:   return g_mpp_q2k_fused_pipeline;
    }
}

/* Path C non-dedup: fused iq2-gate + iq2-up + swiglu + i8 quantize in one kernel.
 * Opt-in via DS4_RESIDENT_MOE_NAX_FULL_FUSED=1 (default off — new code, behind a
 * flag for safe rollout). Only meaningful when use_fused is already on. */
static int ds4_gpu_resident_mpp_full_fused_gate_up_swiglu_enabled(void) {
    if (ds4_gpu_no_int8_paths_enabled()) return 0;
    if (!g_mpp_iq2_fused_gate_up_swiglu_pipeline) return 0;
    const char *env = getenv("DS4_RESIDENT_MOE_NAX_FULL_FUSED");
    if (env && env[0]) return atoi(env) != 0;
    return 0; /* default off */
}

static int ds4_gpu_flash_mpp_full_fused_gate_up_swiglu_enabled(void) {
    if (ds4_gpu_no_int8_paths_enabled()) return 0;
    if (!g_mpp_iq2_fused_gate_up_swiglu_contig_pipeline &&
        !g_mpp_iq2_fused_gate_up_swiglu_contig_m32_pipeline) return 0;
    const char *env = getenv("DS4_FLASH_MOE_MPP_I8I8_FULL_FUSED_PREFILL");
    if (!env || !env[0]) env = getenv("DS4_FLASH_MOE_ANE_I8I8_FULL_FUSED_PREFILL");
    if (!env || !env[0]) env = getenv("DS4_RESIDENT_MOE_NAX_FULL_FUSED");
    return env && env[0] && atoi(env) != 0;
}

static uint32_t ds4_gpu_flash_mpp_full_fused_min_refs(void) {
    uint32_t v = ds4_gpu_env_u32_default("DS4_FLASH_MOE_MPP_I8I8_FULL_FUSED_MIN_REFS", 128u);
    return ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_NAX_FULL_FUSED_MIN_REFS", v);
}

static uint32_t ds4_gpu_flash_mpp_full_fused_m_tile(void) {
    uint32_t v = ds4_gpu_env_u32_default("DS4_FLASH_MOE_MPP_I8I8_FULL_FUSED_M_TILE", 64u);
    return v <= 32u ? 32u : 64u;
}

/* Encode one fused per-expert matmul (kernel reads counts[expert] for M, indirect
 * dispatch grid = (N/32, tile_groups)).  w is the quantized weight buffer bound at
 * w_off (the expert's weight slice). */
static int ds4_gpu_encode_mpp_fused_matmul_counted_indirect(
        id<MTLCommandBuffer>         cb,
        id<MTLComputePipelineState>  pipeline,
        id<MTLBuffer>                a,
        NSUInteger                   a_off,
        id<MTLBuffer>                w,
        NSUInteger                   w_off,
        id<MTLBuffer>                c,
        NSUInteger                   c_off,
        id<MTLBuffer>                counts,
        uint32_t                     expert,
        uint32_t                     n,
        uint32_t                     k,
        float                        qscale,
        id<MTLBuffer>                indirect,
        NSUInteger                   indirect_off) {
    if (!cb || !pipeline || !a || !w || !c || !counts || !indirect ||
        n == 0 || k == 0 || (k % 256u) != 0) {
        return 0;
    }
    MTLSize tg = MTLSizeMake((NSUInteger)pipeline.threadExecutionWidth * 4u, 1, 1);
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:pipeline];
    [enc setBuffer:a offset:a_off atIndex:0];
    [enc setBuffer:w offset:w_off atIndex:1];
    [enc setBuffer:c offset:c_off atIndex:2];
    [enc setBuffer:counts offset:0 atIndex:3];
    [enc setBytes:&expert length:sizeof(expert) atIndex:4];
    [enc setBytes:&n length:sizeof(n) atIndex:5];
    [enc setBytes:&k length:sizeof(k) atIndex:6];
    [enc setBytes:&qscale length:sizeof(qscale) atIndex:7];
    [enc dispatchThreadgroupsWithIndirectBuffer:indirect
                           indirectBufferOffset:indirect_off
                          threadsPerThreadgroup:tg];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

// Path C non-dedup: one-shot fused iq2-gate + iq2-up + swiglu + routing-weight
// + i8 quantize. Replaces three dispatches (gate matmul + up matmul + swiglu)
// with one. Indirect dispatch args MUST be the matmul-style grid
// (ceil(N/32), ceil(M/64), 1) — i.e., reuse `gate_arg_off` from the caller.
static int ds4_gpu_encode_mpp_iq2_fused_gate_up_swiglu_counted_indirect(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        a,
        NSUInteger           a_off,
        id<MTLBuffer>        wq_gate,
        NSUInteger           wq_gate_off,
        id<MTLBuffer>        wq_up,
        NSUInteger           wq_up_off,
        id<MTLBuffer>        mid_i8,
        NSUInteger           mid_off,
        id<MTLBuffer>        weights,
        NSUInteger           weights_off,
        id<MTLBuffer>        hids,
        NSUInteger           hids_off,
        id<MTLBuffer>        counts,
        uint32_t             expert,
        uint32_t             n,
        uint32_t             k,
        float                qscale,
        float                input_scale,
        float                clamp_value,
        float                mid_qscale,
        id<MTLBuffer>        indirect,
        NSUInteger           indirect_off) {
    if (!cb || !a || !wq_gate || !wq_up || !mid_i8 || !weights || !hids ||
        !counts || !indirect || n == 0 || k == 0 || (k % 256u) != 0 ||
        !g_mpp_iq2_fused_gate_up_swiglu_pipeline) {
        return 0;
    }
    id<MTLComputePipelineState> p = g_mpp_iq2_fused_gate_up_swiglu_pipeline;
    MTLSize tg = MTLSizeMake((NSUInteger)p.threadExecutionWidth * 4u, 1, 1);
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:p];
    [enc setBuffer:a       offset:a_off       atIndex:0];
    [enc setBuffer:wq_gate offset:wq_gate_off atIndex:1];
    [enc setBuffer:wq_up   offset:wq_up_off   atIndex:2];
    [enc setBuffer:mid_i8  offset:mid_off     atIndex:3];
    [enc setBuffer:weights offset:weights_off atIndex:4];
    [enc setBuffer:hids    offset:hids_off    atIndex:5];
    [enc setBuffer:counts  offset:0           atIndex:6];
    [enc setBytes:&expert      length:sizeof(expert)      atIndex:7];
    [enc setBytes:&n           length:sizeof(n)           atIndex:8];
    [enc setBytes:&k           length:sizeof(k)           atIndex:9];
    [enc setBytes:&qscale      length:sizeof(qscale)      atIndex:10];
    [enc setBytes:&input_scale length:sizeof(input_scale) atIndex:11];
    [enc setBytes:&clamp_value length:sizeof(clamp_value) atIndex:12];
    [enc setBytes:&mid_qscale  length:sizeof(mid_qscale)  atIndex:13];
    [enc dispatchThreadgroupsWithIndirectBuffer:indirect
                           indirectBufferOffset:indirect_off
                          threadsPerThreadgroup:tg];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

// Slot-bank Path C: contiguous per-expert rows, no hids indirection.
static int ds4_gpu_encode_mpp_iq2_fused_gate_up_swiglu_contig(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        a,
        NSUInteger           a_off,
        id<MTLBuffer>        wq_gate,
        NSUInteger           wq_gate_off,
        id<MTLBuffer>        wq_up,
        NSUInteger           wq_up_off,
        id<MTLBuffer>        mid_i8,
        NSUInteger           mid_off,
        id<MTLBuffer>        weights,
        NSUInteger           weights_off,
        uint32_t             m,
        uint32_t             n,
        uint32_t             k,
        float                qscale,
        float                input_scale,
        float                clamp_value,
        float                mid_qscale) {
    if (!cb || !a || !wq_gate || !wq_up || !mid_i8 || !weights ||
        m == 0 || n == 0 || k == 0 || (k % 256u) != 0) {
        return 0;
    }
    const uint32_t m_tile = ds4_gpu_flash_mpp_full_fused_m_tile();
    id<MTLComputePipelineState> p =
        (m_tile == 32u && g_mpp_iq2_fused_gate_up_swiglu_contig_m32_pipeline) ?
        g_mpp_iq2_fused_gate_up_swiglu_contig_m32_pipeline :
        g_mpp_iq2_fused_gate_up_swiglu_contig_pipeline;
    if (!p) return 0;
    MTLSize tg = MTLSizeMake((NSUInteger)p.threadExecutionWidth * 4u, 1, 1);
    MTLSize grid = MTLSizeMake(((NSUInteger)n + 31u) / 32u,
                               ((NSUInteger)m + (NSUInteger)m_tile - 1u) / (NSUInteger)m_tile,
                               1);
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:p];
    [enc setBuffer:a       offset:a_off       atIndex:0];
    [enc setBuffer:wq_gate offset:wq_gate_off atIndex:1];
    [enc setBuffer:wq_up   offset:wq_up_off   atIndex:2];
    [enc setBuffer:mid_i8  offset:mid_off     atIndex:3];
    [enc setBuffer:weights offset:weights_off atIndex:4];
    [enc setBytes:&m           length:sizeof(m)           atIndex:5];
    [enc setBytes:&n           length:sizeof(n)           atIndex:6];
    [enc setBytes:&k           length:sizeof(k)           atIndex:7];
    [enc setBytes:&qscale      length:sizeof(qscale)      atIndex:8];
    [enc setBytes:&input_scale length:sizeof(input_scale) atIndex:9];
    [enc setBytes:&clamp_value length:sizeof(clamp_value) atIndex:10];
    [enc setBytes:&mid_qscale  length:sizeof(mid_qscale)  atIndex:11];
    [enc dispatchThreadgroups:grid threadsPerThreadgroup:tg];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

// Multi-expert iq2 / q2k matmul: ONE dispatch covers G experts.
// Caller is responsible for:
//   - A: packed acts [TOTAL x K] int8, ordered by expert.
//   - Wq: per-expert iq2/q2k weight slabs [N x K] each, indexed by `te[]`.
//   - C: output [TOTAL x N] int32, parallel to A's ordering.
//   - te/tr0/trc: per-tile metadata buffers (uint × ntiles).
//   - grid = (ceil(N/32), ntiles, 1), tg = (TEW*4, 1, 1).
// Returns 0 on bad args / missing pipeline, 1 on success.
static int ds4_gpu_encode_mpp_iq2_i8_i32_multi(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        a,
        NSUInteger           a_off,
        id<MTLBuffer>        wq,
        NSUInteger           wq_off,
        id<MTLBuffer>        c,
        NSUInteger           c_off,
        id<MTLBuffer>        te,
        NSUInteger           te_off,
        id<MTLBuffer>        tr0,
        NSUInteger           tr0_off,
        id<MTLBuffer>        trc,
        NSUInteger           trc_off,
        uint32_t             n_tiles,
        uint32_t             n,
        uint32_t             k,
        float                qscale) {
    if (!cb || !a || !wq || !c || !te || !tr0 || !trc || n_tiles == 0 ||
        n == 0 || k == 0 || (k % 256u) != 0 ||
        !g_mpp_iq2_i8_i32_multi_pipeline) {
        return 0;
    }
    id<MTLComputePipelineState> p = g_mpp_iq2_i8_i32_multi_pipeline;
    MTLSize tg = MTLSizeMake((NSUInteger)p.threadExecutionWidth * 4u, 1, 1);
    MTLSize grid = MTLSizeMake(((NSUInteger)n + 31u) / 32u, (NSUInteger)n_tiles, 1);
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:p];
    [enc setBuffer:a   offset:a_off   atIndex:0];
    [enc setBuffer:wq  offset:wq_off  atIndex:1];
    [enc setBuffer:c   offset:c_off   atIndex:2];
    [enc setBuffer:te  offset:te_off  atIndex:3];
    [enc setBuffer:tr0 offset:tr0_off atIndex:4];
    [enc setBuffer:trc offset:trc_off atIndex:5];
    [enc setBytes:&n      length:sizeof(n)      atIndex:6];
    [enc setBytes:&k      length:sizeof(k)      atIndex:7];
    [enc setBytes:&qscale length:sizeof(qscale) atIndex:8];
    [enc dispatchThreadgroups:grid threadsPerThreadgroup:tg];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_mpp_q2k_i8_i32_multi(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        a,
        NSUInteger           a_off,
