    [enc setBytes:&width length:sizeof(width) atIndex:4];
    [enc setBytes:&rows length:sizeof(rows) atIndex:5];
    [enc setBytes:&clamp_value length:sizeof(clamp_value) atIndex:6];
    [enc setBytes:&input_scale length:sizeof(input_scale) atIndex:7];
    [enc setBytes:&mid_qscale length:sizeof(mid_qscale) atIndex:8];
    [enc dispatchThreadgroups:MTLSizeMake(rows, 1, 1)
         threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_mpp_scale_i32_f32(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        src,
        id<MTLBuffer>        dst,
        NSUInteger           dst_off,
        uint32_t             n,
        float                scale) {
    if (!cb || !src || !dst || n == 0) return 0;
    NSUInteger nth = g_mpp_scale_i32_f32_pipeline.maxTotalThreadsPerThreadgroup;
    if (nth > 256u) nth = 256u;
    if (nth == 0) nth = 1u;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_mpp_scale_i32_f32_pipeline];
    [enc setBuffer:src offset:0 atIndex:0];
    [enc setBuffer:dst offset:dst_off atIndex:1];
    [enc setBytes:&n length:sizeof(n) atIndex:2];
    [enc setBytes:&scale length:sizeof(scale) atIndex:3];
    [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n + nth - 1u) / nth, 1, 1)
         threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

int ds4_gpu_routed_moe_expert_banked_batch_mpp_int8_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *gate_bank,
        ds4_gpu_tensor       *up_bank,
        ds4_gpu_tensor       *down_bank,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        float                   clamp,
        const ds4_gpu_tensor *x,
        uint32_t                n_tokens,
        bool                   *mid_is_f16) {
    (void)selected;
    if (mid_is_f16) *mid_is_f16 = false;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !gate || !up || !mid || !x || !gate_bank || !up_bank ||
        !down_bank || !weights || n_tokens == 0) {
        return 0;
    }
    /* Native-MXFP4 arm (MPP 4.1 scale-plane matmul2d): opt-in via
     * DS4_MXFP4_NATIVE=1 + runtime probe; consumes the streamed ggml blocks
     * via a per-call plane repack instead of the dequant-to-i8/f16 staging
     * passes.  Plane-split sidecars use native by default; the dequant
     * W8A8/NAX route is diagnostic-only because full-model profiles showed
     * routing drift after the first few layers. */
    const bool mxfp4_path =
        gate_type == DS4_METAL_TENSOR_MXFP4 &&
        down_type == DS4_METAL_TENSOR_MXFP4;
    const bool gate_mxfp4_plane_split =
        gate_type == DS4_METAL_TENSOR_MXFP4 &&
        ds4_gpu_tensor_mxfp4_plane_split(gate_bank);
    const bool up_mxfp4_plane_split =
        gate_type == DS4_METAL_TENSOR_MXFP4 &&
        ds4_gpu_tensor_mxfp4_plane_split(up_bank);
    const bool down_mxfp4_plane_split =
        down_type == DS4_METAL_TENSOR_MXFP4 &&
        ds4_gpu_tensor_mxfp4_plane_split(down_bank);
    const bool mxfp4_plane_split =
        mxfp4_path &&
        gate_mxfp4_plane_split &&
        up_mxfp4_plane_split &&
        down_mxfp4_plane_split;
    const bool hybrid_iq2_gate_up_mxfp4_down =
        gate_type == DS4_METAL_TENSOR_IQ2_XXS &&
        down_type == DS4_METAL_TENSOR_MXFP4 &&
        !gate_mxfp4_plane_split &&
        !up_mxfp4_plane_split &&
        down_mxfp4_plane_split;
    const bool mxfp4_native_dequant_experiment =
        mxfp4_plane_split &&
        ds4_gpu_env_flag_enabled("DS4_MXFP4_NATIVE_DEQUANT_PREFILL_EXPERIMENT");
    const bool mxfp4_w8a8_prefill_requested =
        mxfp4_plane_split &&
        mxfp4_native_dequant_experiment &&
        (ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_MPP_INT8_PREFILL") ||
         ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_MPP_INT8_ACT") ||
         ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_MPP_I8I8_PREFILL") ||
         ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_MPP_I8I8_FUSED_PREFILL") ||
         ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_MPP_I8I8_FULL_FUSED_PREFILL") ||
         ds4_gpu_env_flag_enabled("DS4_RESIDENT_MOE_NAX_HALF"));
    const bool use_fp4_native =
        mxfp4_path &&
        ds4_gpu_mxfp4_native_requested() &&
        ds4_gpu_has_native_mxfp4() &&
        !mxfp4_w8a8_prefill_requested;
    const bool use_fp4_native_plane_split = use_fp4_native && mxfp4_plane_split;
    const bool use_mxfp4_dequant =
        mxfp4_path &&
        !use_fp4_native &&
        (!mxfp4_plane_split || mxfp4_native_dequant_experiment);
    const bool use_hybrid_native_down =
        hybrid_iq2_gate_up_mxfp4_down &&
        ds4_gpu_mxfp4_native_requested() &&
        ds4_gpu_has_native_mxfp4();
    if (!use_fp4_native &&
        !use_mxfp4_dequant &&
        !use_hybrid_native_down &&
        (gate_type != DS4_METAL_TENSOR_IQ2_XXS ||
         (down_type != DS4_METAL_TENSOR_Q2_K &&
          down_type != DS4_METAL_TENSOR_IQ2_XXS))) {
        return 0;
    }
    if (expert_in_dim != 4096u ||
        expert_mid_dim != 2048u ||
        out_dim != 4096u) {
        return 0;
    }

    if (use_fp4_native || use_mxfp4_dequant) {
        const uint64_t gate_fp4_row_bytes = (uint64_t)(expert_in_dim / 32u) * 17u;
        const uint64_t down_fp4_row_bytes = (uint64_t)(expert_mid_dim / 32u) * 17u;
        if (gate_row_bytes != gate_fp4_row_bytes ||
            down_row_bytes != down_fp4_row_bytes ||
            gate_expert_bytes != gate_row_bytes * expert_mid_dim ||
            down_expert_bytes != down_row_bytes * out_dim) {
            return 0;
        }
    } else if (hybrid_iq2_gate_up_mxfp4_down) {
        const uint64_t gate_iq2_row_bytes = (uint64_t)(expert_in_dim / 256u) * 66u;
        const uint64_t down_fp4_row_bytes = (uint64_t)(expert_mid_dim / 32u) * 17u;
        if (gate_row_bytes != gate_iq2_row_bytes ||
            down_row_bytes != down_fp4_row_bytes ||
            gate_expert_bytes != gate_row_bytes * expert_mid_dim ||
            down_expert_bytes != down_row_bytes * out_dim) {
            return 0;
        }
    } else {
        const uint64_t gate_iq2_row_bytes = (uint64_t)(expert_in_dim / 256u) * 66u;
        const uint64_t down_iq2_row_bytes = (uint64_t)(expert_mid_dim / 256u) * 66u;
        const uint64_t down_q2_row_bytes = (uint64_t)(expert_mid_dim / 256u) * 84u;
        const uint64_t expected_down_row_bytes =
            down_type == DS4_METAL_TENSOR_IQ2_XXS ? down_iq2_row_bytes : down_q2_row_bytes;
        if (gate_row_bytes != gate_iq2_row_bytes ||
            down_row_bytes != expected_down_row_bytes ||
            gate_expert_bytes != gate_row_bytes * expert_mid_dim ||
            down_expert_bytes != down_row_bytes * out_dim) {
            return 0;
        }
    }

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> gatebuf = ds4_gpu_tensor_buffer(gate);
        id<MTLBuffer> upbuf = ds4_gpu_tensor_buffer(up);
        id<MTLBuffer> midbuf = ds4_gpu_tensor_buffer(mid);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> gate_bankbuf = ds4_gpu_tensor_buffer(gate_bank);
        id<MTLBuffer> up_bankbuf = ds4_gpu_tensor_buffer(up_bank);
        id<MTLBuffer> down_bankbuf = ds4_gpu_tensor_buffer(down_bank);

        const uint64_t x_bytes = (uint64_t)n_tokens * expert_in_dim * sizeof(float);
        const uint64_t x_half_bytes = (uint64_t)n_tokens * expert_in_dim * sizeof(uint16_t);
        const uint64_t x_i8_bytes = (uint64_t)n_tokens * expert_in_dim;
        const uint64_t mid_bytes = (uint64_t)n_tokens * expert_mid_dim * sizeof(float);
        const uint64_t out_bytes = (uint64_t)n_tokens * out_dim * sizeof(float);
        const uint64_t gate_i8_bytes = (uint64_t)expert_in_dim * expert_mid_dim;
        const uint64_t down_i8_bytes = (uint64_t)expert_mid_dim * out_dim;
        const uint64_t gate_i32_bytes = (uint64_t)n_tokens * expert_mid_dim * sizeof(int32_t);
        const uint64_t out_i32_bytes = (uint64_t)n_tokens * out_dim * sizeof(int32_t);
        const bool no_int8_paths = ds4_gpu_no_int8_paths_enabled();
        if (!use_fp4_native &&
            no_int8_paths && !ds4_gpu_resident_nax_half_safe(n_tokens)) {
            return 0;
        }
        const char *i8_i8_env = getenv("DS4_FLASH_MOE_MPP_I8I8_PREFILL");
        const char *i8_act_env = getenv("DS4_FLASH_MOE_MPP_INT8_ACT");
        const bool use_i8_i8 =
            !no_int8_paths &&
            ((i8_i8_env && i8_i8_env[0] && atoi(i8_i8_env) != 0) ||
             (i8_act_env && i8_act_env[0] && atoi(i8_act_env) != 0));
        const char *i8_i8_fused_env = getenv("DS4_FLASH_MOE_MPP_I8I8_FUSED_PREFILL");
        const bool use_i8_i8_fused = use_i8_i8 &&
                                     i8_i8_fused_env != NULL &&
                                     atoi(i8_i8_fused_env) != 0;
        /* True half x half routed NAX path (non-int8): dequant experts -> f16
         * weight bank, half activations, matmul2d half x half. Tile (N) swept
         * 32/64/128/256 via DS4_RESIDENT_MOE_NAX_HALF_TILE (default 128). */
        const char *nax_half_env = getenv("DS4_RESIDENT_MOE_NAX_HALF");
        const bool use_h_h =
            (nax_half_env && nax_half_env[0] && atoi(nax_half_env) != 0) ||
            no_int8_paths;
        uint32_t h_h_tile = ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_NAX_HALF_TILE", 128u);
        h_h_tile = (h_h_tile >= 256u) ? 256u :
                   (h_h_tile >= 128u) ? 128u :
                   (h_h_tile >= 64u)  ? 64u  : 32u;
        id<MTLComputePipelineState> h_h_gate_pipe =
            (h_h_tile == 256u) ? g_mpp_h_h_f_n256_pipeline :
            (h_h_tile == 128u) ? g_mpp_h_h_f_n128_pipeline :
            (h_h_tile == 64u)  ? g_mpp_h_h_f_n64_pipeline  : g_mpp_h_h_f_n32_pipeline;
        id<MTLComputePipelineState> h_h_down_pipe =
            (h_h_tile == 256u) ? g_mpp_f_h_f_n256_pipeline :
            (h_h_tile == 128u) ? g_mpp_f_h_f_n128_pipeline :
            (h_h_tile == 64u)  ? g_mpp_f_h_f_n64_pipeline  : g_mpp_f_h_f_n32_pipeline;
        /* Plan A (NAX+ALU): replace the separate gate/up matmul + weighted swiglu
         * in the use_h_h path with the single fused gate+up+swiglu kernel, then
         * reapply the per-token routing weight (the fused kernel omits it). Gated
         * by the same envs as resident: DS4_RESIDENT_MOE_NAX_FUSED_GATE_UP (on/off)
         * + DS4_RESIDENT_MOE_NAX_FUSED_MIN_REFS (min per-expert tokens; default 128,
         * set 0 to fuse every expert). Requires use_h_h (f16 weight bank). */
        const char *fused_gu_env = getenv("DS4_RESIDENT_MOE_NAX_FUSED_GATE_UP");
        const bool use_fused_gate_up =
            use_h_h && fused_gu_env && fused_gu_env[0] && atoi(fused_gu_env) != 0 &&
            g_mpp_fused_gate_up_swiglu_h_h_f_n32_pipeline != nil &&
            g_mpp_mul_rows_weight_f32_pipeline != nil;
        const uint32_t fused_min_refs =
            ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_NAX_FUSED_MIN_REFS", 128u);
        float mpp_i8_qscale = 512.0f;
        float mpp_i8_scale = 1.0f / 512.0f;
        float mpp_x_qscale = 32.0f;
        float mpp_mid_qscale = 32.0f;
        ds4_gpu_prefill_int8_scales(0,
                                    &mpp_i8_qscale,
                                    &mpp_i8_scale,
                                    &mpp_x_qscale,
                                    NULL,
                                    &mpp_mid_qscale,
                                    NULL);
        const float mpp_gate_scale = 1.0f / (mpp_x_qscale * mpp_i8_qscale);
        const float mpp_down_scale = 1.0f / (mpp_mid_qscale * mpp_i8_qscale);

        if (!xbuf || !gatebuf || !upbuf || !midbuf || !outbuf || !weightsbuf ||
            !gate_bankbuf || !up_bankbuf || !down_bankbuf ||
            ds4_gpu_tensor_bytes(x) < x_bytes ||
            ds4_gpu_tensor_bytes(gate) < mid_bytes ||
            ds4_gpu_tensor_bytes(up) < mid_bytes ||
            ds4_gpu_tensor_bytes(mid) < mid_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes ||
            ds4_gpu_tensor_bytes(weights) < (uint64_t)n_tokens * sizeof(float) ||
            ds4_gpu_tensor_bytes(gate_bank) < gate_expert_bytes ||
            ds4_gpu_tensor_bytes(up_bank) < gate_expert_bytes ||
            ds4_gpu_tensor_bytes(down_bank) < down_expert_bytes) {
            return 0;
        }
        if (x_half_bytes > NSUIntegerMax ||
            x_i8_bytes > NSUIntegerMax ||
            gate_i8_bytes > NSUIntegerMax ||
            down_i8_bytes > NSUIntegerMax ||
            gate_i32_bytes > NSUIntegerMax ||
            out_i32_bytes > NSUIntegerMax ||
            x_bytes / sizeof(float) > UINT32_MAX) {
            return 0;
        }
        if (!ds4_gpu_ensure_mpp_int8_prefill_pipelines()) return 0;
        int scratch_ok = ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_gate_i8_buffer,
                                                       &g_mpp_prefill_gate_i8_bytes,
                                                       (NSUInteger)gate_i8_bytes,
                                                       "ds4_mpp_prefill_gate_i8") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_up_i8_buffer,
                                                       &g_mpp_prefill_up_i8_bytes,
                                                       (NSUInteger)gate_i8_bytes,
                                                       "ds4_mpp_prefill_up_i8") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_down_i8_buffer,
                                                       &g_mpp_prefill_down_i8_bytes,
                                                       (NSUInteger)down_i8_bytes,
                                                       "ds4_mpp_prefill_down_i8");
        if (use_fp4_native || use_hybrid_native_down) {
            /* Planes live inside the i8 scratch buffers (data at 0, scales at
             * rows*k/2; 17/32 of the i8 footprint).  Only x/mid need f16. */
            scratch_ok = scratch_ok &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_x_half_buffer,
                                                       &g_mpp_prefill_x_half_bytes,
                                                       (NSUInteger)x_half_bytes,
                                                       "ds4_mpp_prefill_x_half") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_mid_half_buffer,
                                                       &g_mpp_prefill_mid_half_bytes,
                                                       (NSUInteger)(mid_bytes / 2u),
                                                       "ds4_mpp_prefill_mid_half");
        } else if (use_h_h) {
            scratch_ok = scratch_ok &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_x_half_buffer,
                                                       &g_mpp_prefill_x_half_bytes,
                                                       (NSUInteger)x_half_bytes,
                                                       "ds4_mpp_prefill_x_half") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_gate_f16_buffer,
                                                       &g_mpp_prefill_gate_f16_bytes,
                                                       (NSUInteger)gate_i8_bytes * 2u,
                                                       "ds4_mpp_prefill_gate_f16") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_up_f16_buffer,
                                                       &g_mpp_prefill_up_f16_bytes,
                                                       (NSUInteger)gate_i8_bytes * 2u,
                                                       "ds4_mpp_prefill_up_f16") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_down_f16_buffer,
                                                       &g_mpp_prefill_down_f16_bytes,
                                                       (NSUInteger)down_i8_bytes * 2u,
                                                       "ds4_mpp_prefill_down_f16");
        } else if (use_i8_i8) {
            scratch_ok = scratch_ok &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_x_i8_buffer,
                                                       &g_mpp_prefill_x_i8_bytes,
                                                       (NSUInteger)x_i8_bytes,
                                                       "ds4_mpp_prefill_x_i8") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_gate_i32_buffer,
                                                       &g_mpp_prefill_gate_i32_bytes,
                                                       (NSUInteger)gate_i32_bytes,
                                                       "ds4_mpp_prefill_gate_i32") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_up_i32_buffer,
                                                       &g_mpp_prefill_up_i32_bytes,
                                                       (NSUInteger)gate_i32_bytes,
                                                       "ds4_mpp_prefill_up_i32") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_mid_i8_buffer,
                                                       &g_mpp_prefill_mid_i8_bytes,
                                                       (NSUInteger)((uint64_t)n_tokens * expert_mid_dim),
                                                       "ds4_mpp_prefill_mid_i8") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_out_i32_buffer,
                                                       &g_mpp_prefill_out_i32_bytes,
                                                       (NSUInteger)out_i32_bytes,
                                                       "ds4_mpp_prefill_out_i32");
        } else {
            scratch_ok = scratch_ok &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_x_half_buffer,
                                             &g_mpp_prefill_x_half_bytes,
                                             (NSUInteger)x_half_bytes,
                                             "ds4_mpp_prefill_x_half");
        }
        if (!scratch_ok) {
            return 0;
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        const uint32_t x_elems = n_tokens * expert_in_dim;
        const uint32_t mid_elems = n_tokens * expert_mid_dim;
        int ok = 0;
        if (use_fp4_native) {
            /* MPP 4.1 native scale-plane MXFP4: repack the streamed ggml
             * blocks into FP4+E8M0 planes (packed into the i8 scratch
             * buffers: data plane at 0, scale plane at rows*k/2), then
             * matmul2d consumes the planes directly -- no dequant pass, no
             * int8 rescale (FP4 decode is exact, so swiglu scale = 1.0). */
            const NSUInteger gate_scales_off =
                (NSUInteger)expert_in_dim * expert_mid_dim / 2u;
            const NSUInteger down_scales_off =
                (NSUInteger)expert_mid_dim * out_dim / 2u;
            static int s_fp4_native_logged = 0;
            if (!s_fp4_native_logged) {
                s_fp4_native_logged = 1;
                fprintf(stderr,
                        "ds4: [mxfp4-native] MPP 4.1 scale-plane prefill arm engaged (%s, first group n_tokens=%u)\n",
                        use_fp4_native_plane_split ? "plane-sidecar/no-repack" : "repack-per-use",
                        n_tokens);
            }
            const NSUInteger gate_data_off = ds4_gpu_tensor_offset(gate_bank);
            const NSUInteger up_data_off = ds4_gpu_tensor_offset(up_bank);
            const NSUInteger down_data_off = ds4_gpu_tensor_offset(down_bank);
            if (use_fp4_native_plane_split &&
                (gate_data_off > NSUIntegerMax - gate_scales_off ||
                 up_data_off > NSUIntegerMax - gate_scales_off ||
                 down_data_off > NSUIntegerMax - down_scales_off)) {
                return 0;
            }
            ok = ds4_gpu_encode_cpy_f32_f16_1d(cb,
                                               xbuf,
                                               ds4_gpu_tensor_offset(x),
                                               g_mpp_prefill_x_half_buffer,
                                               0,
                                               x_elems);
            if (ok && !use_fp4_native_plane_split) {
                ok = ds4_gpu_encode_mxfp4_repack_planes(cb,
                                                        gate_bankbuf,
                                                        gate_data_off,
                                                        g_mpp_prefill_gate_i8_buffer,
                                                        0,
                                                        gate_scales_off,
                                                        expert_mid_dim,
                                                        expert_in_dim) &&
                     ds4_gpu_encode_mxfp4_repack_planes(cb,
                                                        up_bankbuf,
                                                        up_data_off,
                                                        g_mpp_prefill_up_i8_buffer,
                                                        0,
                                                        gate_scales_off,
                                                        expert_mid_dim,
                                                        expert_in_dim) &&
                     ds4_gpu_encode_mxfp4_repack_planes(cb,
                                                        down_bankbuf,
                                                        down_data_off,
                                                        g_mpp_prefill_down_i8_buffer,
                                                        0,
                                                        down_scales_off,
                                                        out_dim,
                                                        expert_mid_dim);
            }
            id<MTLBuffer> gate_w = use_fp4_native_plane_split ? gate_bankbuf : g_mpp_prefill_gate_i8_buffer;
            id<MTLBuffer> up_w = use_fp4_native_plane_split ? up_bankbuf : g_mpp_prefill_up_i8_buffer;
            id<MTLBuffer> down_w = use_fp4_native_plane_split ? down_bankbuf : g_mpp_prefill_down_i8_buffer;
            const NSUInteger gate_w_data_off = use_fp4_native_plane_split ? gate_data_off : 0;
            const NSUInteger up_w_data_off = use_fp4_native_plane_split ? up_data_off : 0;
            const NSUInteger down_w_data_off = use_fp4_native_plane_split ? down_data_off : 0;
            const NSUInteger gate_w_scale_off = use_fp4_native_plane_split ? gate_data_off + gate_scales_off : gate_scales_off;
            const NSUInteger up_w_scale_off = use_fp4_native_plane_split ? up_data_off + gate_scales_off : gate_scales_off;
            const NSUInteger down_w_scale_off = use_fp4_native_plane_split ? down_data_off + down_scales_off : down_scales_off;
            ok = ok &&
                 ds4_gpu_encode_mxfp4_native_matmul(cb,
                                                    g_mpp_prefill_x_half_buffer, 0,
                                                    gate_w,
                                                    gate_w_data_off, gate_w_scale_off,
                                                    gatebuf, ds4_gpu_tensor_offset(gate),
                                                    n_tokens, expert_mid_dim, expert_in_dim) &&
                 ds4_gpu_encode_mxfp4_native_matmul(cb,
                                                    g_mpp_prefill_x_half_buffer, 0,
                                                    up_w,
                                                    up_w_data_off, up_w_scale_off,
                                                    upbuf, ds4_gpu_tensor_offset(up),
                                                    n_tokens, expert_mid_dim, expert_in_dim) &&
                 ds4_gpu_encode_mpp_swiglu_weight(cb,
                                                  gatebuf, ds4_gpu_tensor_offset(gate),
                                                  upbuf, ds4_gpu_tensor_offset(up),
                                                  midbuf, ds4_gpu_tensor_offset(mid),
                                                  weightsbuf, ds4_gpu_tensor_offset(weights),
                                                  expert_mid_dim, n_tokens, clamp, 1.0f) &&
                 ds4_gpu_encode_cpy_f32_f16_1d(cb,
                                               midbuf,
                                               ds4_gpu_tensor_offset(mid),
                                               g_mpp_prefill_mid_half_buffer,
                                               0,
                                               mid_elems) &&
                 ds4_gpu_encode_mxfp4_native_matmul(cb,
                                                    g_mpp_prefill_mid_half_buffer, 0,
                                                    down_w,
                                                    down_w_data_off, down_w_scale_off,
                                                   outbuf, ds4_gpu_tensor_offset(out),
                                                    n_tokens, out_dim, expert_mid_dim);
        } else if (use_mxfp4_dequant) {
            static int s_mxfp4_w8a8_logged = 0;
            if (!s_mxfp4_w8a8_logged) {
                s_mxfp4_w8a8_logged = 1;
                fprintf(stderr,
                        "ds4: [mxfp4-w8a8-exp] diagnostic MPP/NAX dequant prefill arm engaged "
                        "(%s, first group n_tokens=%u; may change routing/quality)\n",
                        mxfp4_plane_split ? "plane-sidecar/no-repack" : "interleaved-block",
                        n_tokens);
            }

            if (use_h_h) {
                /* half x half matmul2d (non-int8): activations -> f16, experts
                 * dequant -> f16 weight bank, gate/up via h_h_f, down via f_h_f
                 * (mid is f32 from swiglu). No int8 rescale -- f16 dequant bakes
                 * the real scale, so swiglu scale = 1.0. */
                ok = h_h_gate_pipe != nil && h_h_down_pipe != nil &&
                     ds4_gpu_encode_cpy_f32_f16_1d(cb,
                                                    xbuf,
                                                    ds4_gpu_tensor_offset(x),
                                                    g_mpp_prefill_x_half_buffer,
                                                    0,
                                                    x_elems) &&
                     ds4_gpu_encode_ane_dequant_f16_for_bank_type(gate_type,
                                                                   gate_mxfp4_plane_split,
                                                                   cb,
                                                                   gate_bankbuf,
                                                                   ds4_gpu_tensor_offset(gate_bank),
                                                                   g_mpp_prefill_gate_f16_buffer,
                                                                   expert_mid_dim,
                                                                   expert_in_dim) &&
                     ds4_gpu_encode_ane_dequant_f16_for_bank_type(gate_type,
                                                                   up_mxfp4_plane_split,
                                                                   cb,
                                                                   up_bankbuf,
                                                                   ds4_gpu_tensor_offset(up_bank),
                                                                   g_mpp_prefill_up_f16_buffer,
                                                                   expert_mid_dim,
                                                                   expert_in_dim) &&
                     ds4_gpu_encode_ane_dequant_f16_for_bank_type(down_type,
                                                                   down_mxfp4_plane_split,
                                                                   cb,
                                                                   down_bankbuf,
                                                                   ds4_gpu_tensor_offset(down_bank),
                                                                   g_mpp_prefill_down_f16_buffer,
                                                                   out_dim,
                                                                   expert_mid_dim);
                if (ok && use_fused_gate_up && n_tokens >= fused_min_refs) {
                    if (getenv("DS4_FLASH_MOE_NAX_FUSED_DIAG")) {
                        static int s_fused_diag_once = 0;
                        if (!s_fused_diag_once) {
                            s_fused_diag_once = 1;
                            fprintf(stderr,
                                    "ds4: [slot-bank nax-fused] Plan A engaged "
                                    "(n_tokens=%u >= min_refs=%u)\n",
                                    n_tokens, fused_min_refs);
                        }
                    }
                    ok = ds4_gpu_encode_mpp_fused_gate_up_swiglu(cb,
                                                                 g_mpp_prefill_x_half_buffer, 0,
                                                                 g_mpp_prefill_gate_f16_buffer,
                                                                 g_mpp_prefill_up_f16_buffer,
                                                                 midbuf, ds4_gpu_tensor_offset(mid),
                                                                 n_tokens, expert_mid_dim, expert_in_dim,
                                                                 clamp) &&
                         ds4_gpu_encode_mpp_mul_rows_weight_f32(cb,
                                                                midbuf, ds4_gpu_tensor_offset(mid),
                                                                weightsbuf, ds4_gpu_tensor_offset(weights),
                                                                expert_mid_dim, n_tokens);
                } else if (ok) {
                    ok = ds4_gpu_encode_mpp_matmul_tile(cb, h_h_gate_pipe, h_h_tile,
                                                        g_mpp_prefill_x_half_buffer, 0,
                                                        g_mpp_prefill_gate_f16_buffer,
                                                        gatebuf, ds4_gpu_tensor_offset(gate),
                                                        n_tokens, expert_mid_dim, expert_in_dim) &&
                         ds4_gpu_encode_mpp_matmul_tile(cb, h_h_gate_pipe, h_h_tile,
                                                        g_mpp_prefill_x_half_buffer, 0,
                                                        g_mpp_prefill_up_f16_buffer,
                                                        upbuf, ds4_gpu_tensor_offset(up),
                                                        n_tokens, expert_mid_dim, expert_in_dim) &&
                         ds4_gpu_encode_mpp_swiglu_weight(cb,
                                                           gatebuf, ds4_gpu_tensor_offset(gate),
                                                           upbuf, ds4_gpu_tensor_offset(up),
                                                           midbuf, ds4_gpu_tensor_offset(mid),
                                                           weightsbuf, ds4_gpu_tensor_offset(weights),
                                                           expert_mid_dim, n_tokens, clamp, 1.0f);
                }
                ok = ok &&
                     ds4_gpu_encode_mpp_matmul_tile(cb, h_h_down_pipe, h_h_tile,
                                                    midbuf, ds4_gpu_tensor_offset(mid),
                                                    g_mpp_prefill_down_f16_buffer,
                                                    outbuf, ds4_gpu_tensor_offset(out),
                                                    n_tokens, out_dim, expert_mid_dim);
            } else if (use_i8_i8) {
                const uint32_t full_fused_min_refs =
                    ds4_gpu_flash_mpp_full_fused_min_refs();
                const bool use_i8_i8_full_fused =
                    ds4_gpu_flash_mpp_full_fused_gate_up_swiglu_enabled() &&
                    gate_type == DS4_METAL_TENSOR_IQ2_XXS &&
                    (down_type == DS4_METAL_TENSOR_Q2_K ||
                     down_type == DS4_METAL_TENSOR_IQ2_XXS) &&
                    n_tokens >= full_fused_min_refs;
                ok = ds4_gpu_encode_mpp_quant_f32_i8(cb,
                                                     xbuf,
                                                     ds4_gpu_tensor_offset(x),
                                                     g_mpp_prefill_x_i8_buffer,
                                                     x_elems,
                                                     mpp_x_qscale) &&
                     ds4_gpu_encode_mpp_dequant_i8_for_bank_type(down_type,
                                                                 down_mxfp4_plane_split,
                                                                 cb,
                                                                 down_bankbuf,
                                                                 ds4_gpu_tensor_offset(down_bank),
                                                                 g_mpp_prefill_down_i8_buffer,
                                                                 out_dim,
                                                                 expert_mid_dim,
                                                                 mpp_i8_qscale);
                if (ok && use_i8_i8_full_fused) {
                    if (getenv("DS4_FLASH_MOE_NAX_FUSED_DIAG")) {
                        static int s_path_c_diag_once = 0;
                        if (!s_path_c_diag_once) {
                            s_path_c_diag_once = 1;
                            fprintf(stderr,
                                    "ds4: [slot-bank path-c] fused iq2 gate+up+swiglu engaged "
                                    "(n_tokens=%u >= min_refs=%u)\n",
                                    n_tokens, full_fused_min_refs);
                        }
                    }
                    ok = ds4_gpu_encode_mpp_iq2_fused_gate_up_swiglu_contig(cb,
                                                                            g_mpp_prefill_x_i8_buffer,
                                                                            0,
                                                                            gate_bankbuf,
                                                                            ds4_gpu_tensor_offset(gate_bank),
                                                                            up_bankbuf,
                                                                            ds4_gpu_tensor_offset(up_bank),
                                                                            g_mpp_prefill_mid_i8_buffer,
                                                                            0,
                                                                            weightsbuf,
                                                                            ds4_gpu_tensor_offset(weights),
                                                                            n_tokens,
                                                                            expert_mid_dim,
                                                                            expert_in_dim,
                                                                            mpp_i8_qscale,
                                                                            mpp_gate_scale,
                                                                            clamp,
                                                                            mpp_mid_qscale);
                } else if (ok) {
                    ok = ds4_gpu_encode_mpp_dequant_i8_for_bank_type(gate_type,
                                                                     gate_mxfp4_plane_split,
                                                                     cb,
                                                                     gate_bankbuf,
                                                                     ds4_gpu_tensor_offset(gate_bank),
                                                                     g_mpp_prefill_gate_i8_buffer,
                                                                     expert_mid_dim,
                                                                     expert_in_dim,
                                                                     mpp_i8_qscale) &&
                         ds4_gpu_encode_mpp_dequant_i8_for_bank_type(gate_type,
                                                                     up_mxfp4_plane_split,
                                                                     cb,
                                                                     up_bankbuf,
                                                                     ds4_gpu_tensor_offset(up_bank),
                                                                     g_mpp_prefill_up_i8_buffer,
                                                                     expert_mid_dim,
                                                                     expert_in_dim,
                                                                     mpp_i8_qscale) &&
                         ds4_gpu_encode_mpp_matmul(cb,
                                                   g_mpp_i8_i8_i32_pipeline,
                                                   g_mpp_prefill_x_i8_buffer,
                                                   0,
                                                   g_mpp_prefill_gate_i8_buffer,
                                                   g_mpp_prefill_gate_i32_buffer,
                                                   0,
                                                   n_tokens,
                                                   expert_mid_dim,
                                                   expert_in_dim) &&
                         ds4_gpu_encode_mpp_matmul(cb,
                                                   g_mpp_i8_i8_i32_pipeline,
                                                   g_mpp_prefill_x_i8_buffer,
                                                   0,
                                                   g_mpp_prefill_up_i8_buffer,
                                                   g_mpp_prefill_up_i32_buffer,
                                                   0,
                                                   n_tokens,
                                                   expert_mid_dim,
                                                   expert_in_dim);
                    if (ok) {
                        if (use_i8_i8_fused) {
                            ok = ds4_gpu_encode_mpp_swiglu_i32_weight_i8(cb,
                                                                         g_mpp_prefill_gate_i32_buffer,
                                                                         g_mpp_prefill_up_i32_buffer,
                                                                         g_mpp_prefill_mid_i8_buffer,
                                                                         weightsbuf,
                                                                         ds4_gpu_tensor_offset(weights),
                                                                         expert_mid_dim,
                                                                         n_tokens,
                                                                         clamp,
                                                                         mpp_gate_scale,
                                                                         mpp_mid_qscale);
                        } else {
                            ok = ds4_gpu_encode_mpp_swiglu_i32_weight(cb,
                                                                      g_mpp_prefill_gate_i32_buffer,
                                                                      g_mpp_prefill_up_i32_buffer,
                                                                      midbuf,
                                                                      ds4_gpu_tensor_offset(mid),
                                                                      weightsbuf,
                                                                      ds4_gpu_tensor_offset(weights),
                                                                      expert_mid_dim,
                                                                      n_tokens,
                                                                      clamp,
                                                                      mpp_gate_scale) &&
                                 ds4_gpu_encode_mpp_quant_mid_f32_i8(cb,
                                                                     midbuf,
                                                                     ds4_gpu_tensor_offset(mid),
                                                                     g_mpp_prefill_mid_i8_buffer,
                                                                     expert_mid_dim,
                                                                     n_tokens,
                                                                     mpp_mid_qscale);
                        }
                    }
                }
                ok = ok &&
                     ds4_gpu_encode_mpp_matmul(cb,
                                               g_mpp_i8_i8_i32_pipeline,
                                               g_mpp_prefill_mid_i8_buffer,
                                               0,
                                               g_mpp_prefill_down_i8_buffer,
                                               g_mpp_prefill_out_i32_buffer,
                                               0,
                                               n_tokens,
                                               out_dim,
                                               expert_mid_dim) &&
                     ds4_gpu_encode_mpp_scale_i32_f32(cb,
                                                      g_mpp_prefill_out_i32_buffer,
                                                      outbuf,
                                                      ds4_gpu_tensor_offset(out),
                                                      n_tokens * out_dim,
                                                      mpp_down_scale);
            } else {
                ok = ds4_gpu_encode_cpy_f32_f16_1d(cb,
                                                    xbuf,
                                                    ds4_gpu_tensor_offset(x),
                                                    g_mpp_prefill_x_half_buffer,
                                                    0,
                                                    x_elems) &&
                     ds4_gpu_encode_mpp_dequant_i8_for_bank_type(gate_type,
                                                                 gate_mxfp4_plane_split,
                                                                 cb,
                                                                 gate_bankbuf,
                                                                 ds4_gpu_tensor_offset(gate_bank),
                                                                 g_mpp_prefill_gate_i8_buffer,
                                                                 expert_mid_dim,
                                                                 expert_in_dim,
                                                                 mpp_i8_qscale) &&
                     ds4_gpu_encode_mpp_dequant_i8_for_bank_type(gate_type,
                                                                 up_mxfp4_plane_split,
                                                                 cb,
                                                                 up_bankbuf,
                                                                 ds4_gpu_tensor_offset(up_bank),
                                                                 g_mpp_prefill_up_i8_buffer,
                                                                 expert_mid_dim,
                                                                 expert_in_dim,
                                                                 mpp_i8_qscale) &&
                     ds4_gpu_encode_mpp_dequant_i8_for_bank_type(down_type,
                                                                 down_mxfp4_plane_split,
                                                                 cb,
                                                                 down_bankbuf,
                                                                 ds4_gpu_tensor_offset(down_bank),
                                                                 g_mpp_prefill_down_i8_buffer,
                                                                 out_dim,
                                                                 expert_mid_dim,
                                                                 mpp_i8_qscale) &&
                     ds4_gpu_encode_mpp_matmul(cb,
                                               g_mpp_h_i8_f_pipeline,
                                               g_mpp_prefill_x_half_buffer,
                                               0,
                                               g_mpp_prefill_gate_i8_buffer,
                                               gatebuf,
                                               ds4_gpu_tensor_offset(gate),
                                               n_tokens,
                                               expert_mid_dim,
                                               expert_in_dim) &&
                     ds4_gpu_encode_mpp_matmul(cb,
                                               g_mpp_h_i8_f_pipeline,
                                               g_mpp_prefill_x_half_buffer,
                                               0,
                                               g_mpp_prefill_up_i8_buffer,
                                               upbuf,
                                               ds4_gpu_tensor_offset(up),
                                               n_tokens,
                                               expert_mid_dim,
                                               expert_in_dim) &&
                     ds4_gpu_encode_mpp_swiglu_weight(cb,
                                                       gatebuf,
                                                       ds4_gpu_tensor_offset(gate),
                                                       upbuf,
                                                       ds4_gpu_tensor_offset(up),
                                                       midbuf,
                                                       ds4_gpu_tensor_offset(mid),
                                                       weightsbuf,
                                                       ds4_gpu_tensor_offset(weights),
                                                       expert_mid_dim,
                                                       n_tokens,
                                                       clamp,
                                                       mpp_i8_scale) &&
                     ds4_gpu_encode_mpp_matmul(cb,
                                               g_mpp_f_i8_f_pipeline,
                                               midbuf,
                                               ds4_gpu_tensor_offset(mid),
                                               g_mpp_prefill_down_i8_buffer,
                                               outbuf,
                                               ds4_gpu_tensor_offset(out),
                                               n_tokens,
                                               out_dim,
                                               expert_mid_dim) &&
                     ds4_gpu_encode_scale_f32_rows(cb,
                                                   outbuf,
                                                   ds4_gpu_tensor_offset(out),
                                                   outbuf,
                                                   ds4_gpu_tensor_offset(out),
                                                   out_dim,
                                                   n_tokens,
                                                   mpp_i8_scale);
            }
        } else if (use_h_h) {
            /* half x half matmul2d (non-int8): activations -> f16, experts
             * dequant -> f16 weight bank, gate/up via h_h_f, down via f_h_f
             * (mid is f32 from swiglu). No int8 rescale -- f16 dequant bakes
             * the real scale, so swiglu scale = 1.0. */
            ok = h_h_gate_pipe != nil && h_h_down_pipe != nil &&
                 ds4_gpu_encode_cpy_f32_f16_1d(cb,
                                                xbuf,
                                                ds4_gpu_tensor_offset(x),
                                                g_mpp_prefill_x_half_buffer,
                                                0,
                                                x_elems) &&
                 ds4_gpu_encode_ane_dequant_f16_for_bank_type(gate_type,
                                                               gate_mxfp4_plane_split,
                                                               cb,
                                                               gate_bankbuf,
                                                               ds4_gpu_tensor_offset(gate_bank),
                                                               g_mpp_prefill_gate_f16_buffer,
                                                               expert_mid_dim,
                                                               expert_in_dim) &&
                 ds4_gpu_encode_ane_dequant_f16_for_bank_type(gate_type,
                                                               up_mxfp4_plane_split,
                                                               cb,
                                                               up_bankbuf,
                                                               ds4_gpu_tensor_offset(up_bank),
                                                               g_mpp_prefill_up_f16_buffer,
                                                               expert_mid_dim,
                                                               expert_in_dim) &&
                 ds4_gpu_encode_ane_dequant_f16_for_bank_type(down_type,
                                                               down_mxfp4_plane_split,
                                                               cb,
                                                               down_bankbuf,
                                                               ds4_gpu_tensor_offset(down_bank),
                                                               g_mpp_prefill_down_f16_buffer,
                                                               out_dim,
                                                               expert_mid_dim);
            if (ok && use_fused_gate_up && n_tokens >= fused_min_refs) {
                /* Plan A (NAX+ALU): one fused gate+up+swiglu kernel writes mid
                 * (= SiLU(gate)*up, no routing weight), then reapply the per-token
                 * routing weight. Replaces the 2 separate matmuls + weighted swiglu
                 * below. f16 dequant bakes the real scale, so no int8 rescale. */
                if (getenv("DS4_FLASH_MOE_NAX_FUSED_DIAG")) {
                    static int s_fused_diag_once = 0;
                    if (!s_fused_diag_once) {
                        s_fused_diag_once = 1;
                        fprintf(stderr,
                                "ds4: [slot-bank nax-fused] Plan A engaged "
                                "(n_tokens=%u >= min_refs=%u)\n",
                                n_tokens, fused_min_refs);
                    }
                }
                ok = ds4_gpu_encode_mpp_fused_gate_up_swiglu(cb,
                                                             g_mpp_prefill_x_half_buffer, 0,
                                                             g_mpp_prefill_gate_f16_buffer,
                                                             g_mpp_prefill_up_f16_buffer,
                                                             midbuf, ds4_gpu_tensor_offset(mid),
                                                             n_tokens, expert_mid_dim, expert_in_dim,
                                                             clamp) &&
                     ds4_gpu_encode_mpp_mul_rows_weight_f32(cb,
                                                            midbuf, ds4_gpu_tensor_offset(mid),
                                                            weightsbuf, ds4_gpu_tensor_offset(weights),
                                                            expert_mid_dim, n_tokens);
            } else if (ok) {
                /* Separate gate/up matmul + weighted swiglu (NAX-half). swiglu
                 * scale = 1.0 (f16 dequant baked the real scale). */
                ok = ds4_gpu_encode_mpp_matmul_tile(cb, h_h_gate_pipe, h_h_tile,
                                                    g_mpp_prefill_x_half_buffer, 0,
                                                    g_mpp_prefill_gate_f16_buffer,
                                                    gatebuf, ds4_gpu_tensor_offset(gate),
                                                    n_tokens, expert_mid_dim, expert_in_dim) &&
                     ds4_gpu_encode_mpp_matmul_tile(cb, h_h_gate_pipe, h_h_tile,
                                                    g_mpp_prefill_x_half_buffer, 0,
                                                    g_mpp_prefill_up_f16_buffer,
                                                    upbuf, ds4_gpu_tensor_offset(up),
                                                    n_tokens, expert_mid_dim, expert_in_dim) &&
                     ds4_gpu_encode_mpp_swiglu_weight(cb,
                                                       gatebuf, ds4_gpu_tensor_offset(gate),
                                                       upbuf, ds4_gpu_tensor_offset(up),
                                                       midbuf, ds4_gpu_tensor_offset(mid),
                                                       weightsbuf, ds4_gpu_tensor_offset(weights),
                                                       expert_mid_dim, n_tokens, clamp, 1.0f);
            }
            ok = ok &&
                 ds4_gpu_encode_mpp_matmul_tile(cb, h_h_down_pipe, h_h_tile,
                                                midbuf, ds4_gpu_tensor_offset(mid),
                                                g_mpp_prefill_down_f16_buffer,
                                                outbuf, ds4_gpu_tensor_offset(out),
                                                n_tokens, out_dim, expert_mid_dim);
        } else if (use_hybrid_native_down) {
            const uint64_t down_scales_rel64 =
                (uint64_t)expert_mid_dim * out_dim / 2u;
            const NSUInteger down_data_off = ds4_gpu_tensor_offset(down_bank);
            if (down_scales_rel64 > NSUIntegerMax ||
                down_data_off > NSUIntegerMax - (NSUInteger)down_scales_rel64) {
                return 0;
            }
            static int s_hybrid_native_prefill_logged = 0;
            if (!s_hybrid_native_prefill_logged) {
                s_hybrid_native_prefill_logged = 1;
                fprintf(stderr,
                        "ds4: [hybrid-moe] IQ2 gate/up + MXFP4_NATIVE down prefill arm engaged "
                        "(plane-sidecar/no-repack, first group n_tokens=%u)\n",
                        n_tokens);
            }
            ok = ds4_gpu_encode_cpy_f32_f16_1d(cb,
                                               xbuf,
                                               ds4_gpu_tensor_offset(x),
                                               g_mpp_prefill_x_half_buffer,
                                               0,
                                               x_elems) &&
                 ds4_gpu_encode_mpp_dequant_i8_for_bank_type(gate_type,
                                                             gate_mxfp4_plane_split,
                                                             cb,
                                                             gate_bankbuf,
                                                             ds4_gpu_tensor_offset(gate_bank),
                                                             g_mpp_prefill_gate_i8_buffer,
                                                             expert_mid_dim,
                                                             expert_in_dim,
                                                             mpp_i8_qscale) &&
                 ds4_gpu_encode_mpp_dequant_i8_for_bank_type(gate_type,
                                                             up_mxfp4_plane_split,
                                                             cb,
                                                             up_bankbuf,
                                                             ds4_gpu_tensor_offset(up_bank),
                                                             g_mpp_prefill_up_i8_buffer,
                                                             expert_mid_dim,
                                                             expert_in_dim,
                                                             mpp_i8_qscale) &&
                 ds4_gpu_encode_mpp_matmul(cb,
                                           g_mpp_h_i8_f_pipeline,
                                           g_mpp_prefill_x_half_buffer,
                                           0,
                                           g_mpp_prefill_gate_i8_buffer,
                                           gatebuf,
                                           ds4_gpu_tensor_offset(gate),
                                           n_tokens,
                                           expert_mid_dim,
                                           expert_in_dim) &&
                 ds4_gpu_encode_mpp_matmul(cb,
                                           g_mpp_h_i8_f_pipeline,
                                           g_mpp_prefill_x_half_buffer,
                                           0,
                                           g_mpp_prefill_up_i8_buffer,
                                           upbuf,
                                           ds4_gpu_tensor_offset(up),
                                           n_tokens,
                                           expert_mid_dim,
                                           expert_in_dim) &&
                 ds4_gpu_encode_mpp_swiglu_weight(cb,
                                                   gatebuf,
                                                   ds4_gpu_tensor_offset(gate),
                                                   upbuf,
                                                   ds4_gpu_tensor_offset(up),
                                                   midbuf,
                                                   ds4_gpu_tensor_offset(mid),
                                                   weightsbuf,
                                                   ds4_gpu_tensor_offset(weights),
                                                   expert_mid_dim,
                                                   n_tokens,
                                                   clamp,
                                                   mpp_i8_scale) &&
                 ds4_gpu_encode_cpy_f32_f16_1d(cb,
                                               midbuf,
                                               ds4_gpu_tensor_offset(mid),
                                               g_mpp_prefill_mid_half_buffer,
                                               0,
                                               mid_elems) &&
                 ds4_gpu_encode_mxfp4_native_matmul(cb,
                                                    g_mpp_prefill_mid_half_buffer,
                                                    0,
                                                    down_bankbuf,
                                                    down_data_off,
                                                    down_data_off + (NSUInteger)down_scales_rel64,
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    n_tokens,
                                                    out_dim,
                                                    expert_mid_dim);
        } else if (use_i8_i8) {
            const uint32_t full_fused_min_refs =
                ds4_gpu_flash_mpp_full_fused_min_refs();
            const bool use_i8_i8_full_fused =
                ds4_gpu_flash_mpp_full_fused_gate_up_swiglu_enabled() &&
                gate_type == DS4_METAL_TENSOR_IQ2_XXS &&
                (down_type == DS4_METAL_TENSOR_Q2_K ||
                 down_type == DS4_METAL_TENSOR_IQ2_XXS) &&
                n_tokens >= full_fused_min_refs;
            ok = ds4_gpu_encode_mpp_quant_f32_i8(cb,
                                                 xbuf,
                                                 ds4_gpu_tensor_offset(x),
                                                 g_mpp_prefill_x_i8_buffer,
                                                 x_elems,
                                                 mpp_x_qscale) &&
                 ds4_gpu_encode_mpp_dequant_i8_for_bank_type(down_type,
                                                             down_mxfp4_plane_split,
                                                             cb,
                                                             down_bankbuf,
                                                             ds4_gpu_tensor_offset(down_bank),
                                                             g_mpp_prefill_down_i8_buffer,
                                                             out_dim,
                                                             expert_mid_dim,
                                                             mpp_i8_qscale);
            if (ok && use_i8_i8_full_fused) {
                if (getenv("DS4_FLASH_MOE_NAX_FUSED_DIAG")) {
                    static int s_path_c_diag_once = 0;
                    if (!s_path_c_diag_once) {
                        s_path_c_diag_once = 1;
                        fprintf(stderr,
                                "ds4: [slot-bank path-c] fused iq2 gate+up+swiglu engaged "
                                "(n_tokens=%u >= min_refs=%u)\n",
                                n_tokens, full_fused_min_refs);
                    }
                }
                ok = ds4_gpu_encode_mpp_iq2_fused_gate_up_swiglu_contig(cb,
                                                                        g_mpp_prefill_x_i8_buffer,
                                                                        0,
                                                                        gate_bankbuf,
                                                                        ds4_gpu_tensor_offset(gate_bank),
                                                                        up_bankbuf,
                                                                        ds4_gpu_tensor_offset(up_bank),
                                                                        g_mpp_prefill_mid_i8_buffer,
                                                                        0,
                                                                        weightsbuf,
                                                                        ds4_gpu_tensor_offset(weights),
                                                                        n_tokens,
                                                                        expert_mid_dim,
                                                                        expert_in_dim,
                                                                        mpp_i8_qscale,
                                                                        mpp_gate_scale,
                                                                        clamp,
                                                                        mpp_mid_qscale);
            } else if (ok) {
                ok = ds4_gpu_encode_mpp_dequant_i8_for_bank_type(gate_type,
                                                                 gate_mxfp4_plane_split,
                                                                 cb,
                                                                 gate_bankbuf,
                                                                 ds4_gpu_tensor_offset(gate_bank),
                                                                 g_mpp_prefill_gate_i8_buffer,
                                                                 expert_mid_dim,
                                                                 expert_in_dim,
                                                                 mpp_i8_qscale) &&
                     ds4_gpu_encode_mpp_dequant_i8_for_bank_type(gate_type,
                                                                 up_mxfp4_plane_split,
                                                                 cb,
                                                                 up_bankbuf,
                                                                 ds4_gpu_tensor_offset(up_bank),
                                                                 g_mpp_prefill_up_i8_buffer,
                                                                 expert_mid_dim,
                                                                 expert_in_dim,
                                                                 mpp_i8_qscale) &&
                     ds4_gpu_encode_mpp_matmul(cb,
                                               g_mpp_i8_i8_i32_pipeline,
                                               g_mpp_prefill_x_i8_buffer,
                                               0,
                                               g_mpp_prefill_gate_i8_buffer,
                                               g_mpp_prefill_gate_i32_buffer,
                                               0,
                                               n_tokens,
                                               expert_mid_dim,
                                               expert_in_dim) &&
                     ds4_gpu_encode_mpp_matmul(cb,
                                               g_mpp_i8_i8_i32_pipeline,
                                               g_mpp_prefill_x_i8_buffer,
                                               0,
                                               g_mpp_prefill_up_i8_buffer,
                                               g_mpp_prefill_up_i32_buffer,
                                               0,
                                               n_tokens,
                                               expert_mid_dim,
                                               expert_in_dim);
                if (ok) {
                    if (use_i8_i8_fused) {
                        ok = ds4_gpu_encode_mpp_swiglu_i32_weight_i8(cb,
                                                                     g_mpp_prefill_gate_i32_buffer,
                                                                     g_mpp_prefill_up_i32_buffer,
                                                                     g_mpp_prefill_mid_i8_buffer,
                                                                     weightsbuf,
                                                                     ds4_gpu_tensor_offset(weights),
                                                                     expert_mid_dim,
                                                                     n_tokens,
                                                                     clamp,
                                                                     mpp_gate_scale,
                                                                     mpp_mid_qscale);
                    } else {
                        ok = ds4_gpu_encode_mpp_swiglu_i32_weight(cb,
                                                                  g_mpp_prefill_gate_i32_buffer,
                                                                  g_mpp_prefill_up_i32_buffer,
                                                                  midbuf,
                                                                  ds4_gpu_tensor_offset(mid),
                                                                  weightsbuf,
                                                                  ds4_gpu_tensor_offset(weights),
                                                                  expert_mid_dim,
                                                                  n_tokens,
                                                                  clamp,
                                                                  mpp_gate_scale) &&
                             ds4_gpu_encode_mpp_quant_mid_f32_i8(cb,
                                                                 midbuf,
                                                                 ds4_gpu_tensor_offset(mid),
                                                                 g_mpp_prefill_mid_i8_buffer,
                                                                 expert_mid_dim,
                                                                 n_tokens,
                                                                 mpp_mid_qscale);
                    }
                }
            }
            ok = ok &&
                 ds4_gpu_encode_mpp_matmul(cb,
                                           g_mpp_i8_i8_i32_pipeline,
                                           g_mpp_prefill_mid_i8_buffer,
                                           0,
                                           g_mpp_prefill_down_i8_buffer,
                                           g_mpp_prefill_out_i32_buffer,
                                           0,
                                           n_tokens,
                                           out_dim,
                                           expert_mid_dim) &&
                 ds4_gpu_encode_mpp_scale_i32_f32(cb,
                                                  g_mpp_prefill_out_i32_buffer,
                                                  outbuf,
                                                  ds4_gpu_tensor_offset(out),
                                                  n_tokens * out_dim,
                                                  mpp_down_scale);
        } else {
            ok = ds4_gpu_encode_cpy_f32_f16_1d(cb,
                                                xbuf,
                                                ds4_gpu_tensor_offset(x),
                                                g_mpp_prefill_x_half_buffer,
                                                0,
                                                x_elems) &&
                 ds4_gpu_encode_mpp_dequant_i8_for_bank_type(gate_type,
                                                             gate_mxfp4_plane_split,
                                                             cb,
                                                             gate_bankbuf,
                                                             ds4_gpu_tensor_offset(gate_bank),
                                                             g_mpp_prefill_gate_i8_buffer,
                                                             expert_mid_dim,
                                                             expert_in_dim,
                                                             mpp_i8_qscale) &&
                 ds4_gpu_encode_mpp_dequant_i8_for_bank_type(gate_type,
                                                             up_mxfp4_plane_split,
                                                             cb,
                                                             up_bankbuf,
                                                             ds4_gpu_tensor_offset(up_bank),
                                                             g_mpp_prefill_up_i8_buffer,
                                                             expert_mid_dim,
                                                             expert_in_dim,
                                                             mpp_i8_qscale) &&
                 ds4_gpu_encode_mpp_dequant_i8_for_bank_type(down_type,
                                                             down_mxfp4_plane_split,
                                                             cb,
                                                             down_bankbuf,
                                                             ds4_gpu_tensor_offset(down_bank),
                                                             g_mpp_prefill_down_i8_buffer,
                                                             out_dim,
                                                             expert_mid_dim,
                                                             mpp_i8_qscale) &&
                 ds4_gpu_encode_mpp_matmul(cb,
                                           g_mpp_h_i8_f_pipeline,
                                           g_mpp_prefill_x_half_buffer,
                                           0,
                                           g_mpp_prefill_gate_i8_buffer,
                                           gatebuf,
                                           ds4_gpu_tensor_offset(gate),
                                           n_tokens,
                                           expert_mid_dim,
                                           expert_in_dim) &&
                 ds4_gpu_encode_mpp_matmul(cb,
                                           g_mpp_h_i8_f_pipeline,
                                           g_mpp_prefill_x_half_buffer,
                                           0,
                                           g_mpp_prefill_up_i8_buffer,
                                           upbuf,
                                           ds4_gpu_tensor_offset(up),
                                           n_tokens,
                                           expert_mid_dim,
                                           expert_in_dim) &&
                 ds4_gpu_encode_mpp_swiglu_weight(cb,
                                                   gatebuf,
                                                   ds4_gpu_tensor_offset(gate),
                                                   upbuf,
                                                   ds4_gpu_tensor_offset(up),
                                                   midbuf,
                                                   ds4_gpu_tensor_offset(mid),
                                                   weightsbuf,
                                                   ds4_gpu_tensor_offset(weights),
                                                   expert_mid_dim,
                                                   n_tokens,
                                                   clamp,
                                                   mpp_i8_scale) &&
                 ds4_gpu_encode_mpp_matmul(cb,
                                           g_mpp_f_i8_f_pipeline,
                                           midbuf,
                                           ds4_gpu_tensor_offset(mid),
                                           g_mpp_prefill_down_i8_buffer,
                                           outbuf,
                                           ds4_gpu_tensor_offset(out),
                                           n_tokens,
                                           out_dim,
                                           expert_mid_dim) &&
                 ds4_gpu_encode_scale_f32_rows(cb,
                                               outbuf,
                                               ds4_gpu_tensor_offset(out),
                                               outbuf,
                                               ds4_gpu_tensor_offset(out),
                                               out_dim,
                                               n_tokens,
                                               mpp_i8_scale);
        }
        if (!ok) return 0;
        return ds4_gpu_finish_command_buffer(cb, owned, "Flash-MoE MPP int8 prefill expert batch");
    }
}

int ds4_gpu_routed_moe_batch_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                gate_offset,
        uint64_t                up_offset,
        uint64_t                down_offset,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t                n_total_expert,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x,
        uint32_t                n_tokens,
        bool                   *mid_is_f16) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !gate || !up || !mid || !x || !model_map || !selected || !weights ||
        n_tokens == 0 ||
        n_total_expert == 0 || n_total_expert > DS4_METAL_N_EXPERT ||
        n_expert == 0 || n_expert > DS4_METAL_N_EXPERT_USED ||
        n_expert > n_total_expert) {
        return 0;
    }
    if ((expert_in_dim % 256u) != 0 || (expert_mid_dim % 256u) != 0) return 0;

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> gatebuf = ds4_gpu_tensor_buffer(gate);
        id<MTLBuffer> upbuf = ds4_gpu_tensor_buffer(up);
        id<MTLBuffer> midbuf = ds4_gpu_tensor_buffer(mid);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> expertsbuf = ds4_gpu_tensor_buffer(experts);
        id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        const uint64_t x_bytes = (uint64_t)n_tokens * expert_in_dim * sizeof(float);
        const uint64_t mid_bytes = (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float);
        const uint64_t out_bytes = (uint64_t)n_tokens * out_dim * sizeof(float);
        const uint64_t selected_bytes = (uint64_t)n_tokens * n_expert * sizeof(int);
        const uint64_t weights_bytes = (uint64_t)n_tokens * n_expert * sizeof(float);
        if (!xbuf || !gatebuf || !upbuf || !midbuf || !outbuf || !selectedbuf || !weightsbuf ||
            ds4_gpu_tensor_bytes(x) < x_bytes ||
            ds4_gpu_tensor_bytes(gate) < mid_bytes ||
            ds4_gpu_tensor_bytes(up) < mid_bytes ||
            ds4_gpu_tensor_bytes(mid) < mid_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes ||
            ds4_gpu_tensor_bytes(selected) < selected_bytes ||
            ds4_gpu_tensor_bytes(weights) < weights_bytes) {
            fprintf(stderr, "ds4: Metal routed batch MoE received undersized activation buffers\n");
            return 0;
        }
        if (n_expert > 1 &&
            (!expertsbuf ||
             ds4_gpu_tensor_bytes(experts) < (uint64_t)n_tokens * n_expert * out_dim * sizeof(float))) {
            fprintf(stderr, "ds4: Metal routed batch MoE received undersized expert output buffer\n");
            return 0;
        }

        const uint64_t gate_tensor_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
        const uint64_t down_tensor_bytes = (uint64_t)n_total_expert * down_expert_bytes;
        uint64_t gate_inner = 0;
        uint64_t up_inner = 0;
        uint64_t down_inner = 0;
        id<MTLBuffer> gate_buf = ds4_gpu_wrap_model_range(model_map, model_size, gate_offset, gate_tensor_bytes, &gate_inner);
        id<MTLBuffer> up_buf = ds4_gpu_wrap_model_range(model_map, model_size, up_offset, gate_tensor_bytes, &up_inner);
        id<MTLBuffer> down_buf = ds4_gpu_wrap_model_range(model_map, model_size, down_offset, down_tensor_bytes, &down_inner);
        if (!gate_buf || !up_buf || !down_buf) return 0;

        const uint32_t pair_rows = n_tokens * n_expert;
        const uint64_t down_scratch_bytes = (uint64_t)pair_rows * out_dim * sizeof(float);
        if ((n_expert > 1 && !expertsbuf &&
             !ds4_gpu_ensure_scratch_buffer(&g_moe_down_scratch_buffer,
                                              &g_moe_down_scratch_bytes,
                                              (NSUInteger)down_scratch_bytes,
                                              "ds4_moe_down_scratch"))) {
            return 0;
        }

        const uint32_t gate_nr0 = ds4_gpu_routed_mv_nr0(gate_type);
        const uint32_t down_nr0 = ds4_gpu_routed_mv_nr0(down_type);
        id<MTLComputePipelineState> gate_mv_pipeline = ds4_gpu_routed_mv_pipeline(gate_type);
        id<MTLComputePipelineState> down_mv_pipeline = ds4_gpu_routed_mv_pipeline(down_type);
        id<MTLComputePipelineState> gate_mm_pipeline = nil;
        id<MTLComputePipelineState> down_mm_pipeline = nil;
        /* Wide-token tile per matmul type (see banked path). */
        uint32_t gate_mm_tile_n = 32u;
        uint32_t down_mm_tile_n = 32u;
        if (gate_nr0 == 0 || down_nr0 == 0 || !gate_mv_pipeline || !down_mv_pipeline) {
            fprintf(stderr, "ds4: unsupported Metal routed batch MoE quant types gate=%u down=%u\n",
                    gate_type, down_type);
            return 0;
        }

        ds4_gpu_mul_mv_id_args gate_args =
            ds4_gpu_make_mul_mv_id_args(expert_in_dim, expert_mid_dim, n_total_expert,
                                          gate_row_bytes, gate_expert_bytes,
                                          1, n_expert, n_tokens, gate_nr0);
        ds4_gpu_mul_mv_id_args down_args =
            ds4_gpu_make_mul_mv_id_args(expert_mid_dim, out_dim, n_total_expert,
                                          down_row_bytes, down_expert_bytes,
                                          n_expert, n_expert, n_tokens, down_nr0);
        const bool use_mm_id =
            n_tokens >= ds4_gpu_moe_mm_min_refs(gate_type, down_type) &&
            ds4_gpu_mul_mm_id_map0_name(n_expert) != NULL;
        /* Per-chunk backend selection (precedence: explicit param > JSON prefill_by_tokens
         * table > the predefined env gates below). Only grouped-path backends are honored
         * here. ane* chunks are handled by the outer resident ANE orchestrator; if this
         * grouped helper sees one, it is the ANE cold tail and should not warn. */
        char tok_backend[24];
        ds4_gpu_resident_backend_for_tokens(n_tokens, tok_backend, sizeof(tok_backend));
        const bool tb_set     = tok_backend[0] != '\0';
        const bool tb_mulmm   = tb_set && strcmp(tok_backend, "mulmm") == 0;
        const bool tb_half    = tb_set && strstr(tok_backend, "half") != NULL;
        const bool tb_int8    = tb_set && strstr(tok_backend, "int8") != NULL;
        const bool tb_ane     = tb_set && strncmp(tok_backend, "ane", 3) == 0;
        const bool tb_use     = tb_mulmm || tb_half || tb_int8;   /* table drives this chunk */
        if (tb_set && !tb_use && !tb_ane && !ds4_gpu_backend_logs_suppressed()) {
            static bool warned_tb_unsup = false;
            if (!warned_tb_unsup) {
                warned_tb_unsup = true;
                fprintf(stderr, "ds4: prefill_by_tokens backend '%s' is not switchable per-chunk in the "
                        "grouped path (use mulmm/nax_half/nax_half_alu/nax_int8); falling back to env gates\n",
                        tok_backend);
            }
        }
        /*
         * MTP verification is neither normal decode nor large prefill: the
         * target model must verify a tiny suffix (usually 2 tokens) in one
         * layer-major pass.  For that shape the prefill expert-major GEMM path
         * is too large, but the decode pair kernels are exactly the right
         * primitive: they read the same activation once and compute routed
         * gate/up together for every selected expert row.  Keep this limited to
         * tiny batches so ordinary prefill keeps using the higher-throughput
         * grouped matmul path.
         */
        const bool use_tiny_pair_mv =
            !g_quality_mode &&
            n_tokens <= 4u &&
            !use_mm_id &&
            ((gate_type == DS4_METAL_TENSOR_IQ2_XXS && g_moe_mul_mv_id_iq2_xxs_pair_pipeline) ||
             (gate_type == DS4_METAL_TENSOR_Q4_K && g_moe_mul_mv_id_q4_k_pair_pipeline));
        ds4_gpu_mul_mm_id_map_args gate_map_args = { 0 };
        ds4_gpu_mul_mm_id_args gate_mm_args = { 0 };
        ds4_gpu_mul_mm_id_args down_mm_args = { 0 };
        id<MTLComputePipelineState> map_pipeline = nil;
        const bool skip_mask_active = g_ane_skip_mask_active != 0;
        const bool resident_mpp_shape_supported =
            use_mm_id &&
            n_expert == 6u &&
            gate_type == DS4_METAL_TENSOR_IQ2_XXS &&
            (down_type == DS4_METAL_TENSOR_Q2_K ||
             down_type == DS4_METAL_TENSOR_IQ2_XXS) &&
            expert_in_dim == 4096u &&
            expert_mid_dim == 2048u &&
            out_dim == 4096u;
        /* ANE+NAX hybrid: the resident grouped path runs the COLD experts on NAX-half
         * while the ANE skip mask (set by the dedup orchestrator) excludes the ANE
         * experts. Normally skip_mask_active forces classic mul_mm_id (that path is
         * ane_gpu). ANE+NAX lifts exactly that one case so the cold tail uses resident
         * NAX-half instead. Two mechanisms keep the ANE experts out of the NAX compute:
         * encode_zero_skipped zeroes their counts (applied right after map0, before this
         * path consumes them) AND the resident per-expert loop checks the skip mask
         * directly (g_ane_skip_mask check, iter-12). Token weights stay fully normalized
         * (the selection is untouched) — the ANE share was already scatter-added. */
        const bool ane_nax_under_skip =
            skip_mask_active &&
            ds4_gpu_env_flag_enabled("DS4_RESIDENT_MOE_ANE_NAX_HYBRID");
        const bool no_int8_paths = ds4_gpu_no_int8_paths_enabled();
        const bool no_int8_resident_nax_half_safe =
            !no_int8_paths || ds4_gpu_resident_nax_half_safe(n_tokens);
        const bool resident_mpp_requested =
            resident_mpp_shape_supported &&
            (!skip_mask_active || ane_nax_under_skip) &&
            /* the table can also turn the resident path ON for a NAX/int8 chunk even
             * if the legacy MPP_INT8 request flag is unset */
            (ds4_gpu_resident_mpp_int8_prefill_requested() || (tb_use && !tb_mulmm) ||
             ane_nax_under_skip);
        const bool use_resident_mpp_standard =
            resident_mpp_requested &&
            no_int8_resident_nax_half_safe &&
            (ane_nax_under_skip
                /* ANE+NAX: always take the resident NAX path for the cold tail */
                ? true
                : (tb_use
                    /* table: a NAX/int8 backend -> resident standard; mulmm -> mul_mm_id */
                    ? !tb_mulmm
                    /* fallback gate (to be phased out): the MIN_TOKENS auto-threshold */
                    : ds4_gpu_resident_mpp_int8_prefill_should_run(n_tokens)));
        if (resident_mpp_requested && !use_resident_mpp_standard) {
            static bool warned_resident_mpp_auto_gpu = false;
            if (!warned_resident_mpp_auto_gpu) {
                if (no_int8_paths && !no_int8_resident_nax_half_safe) {
                    fprintf(stderr,
                            "ds4: --no-int8 requested, but %u-token resident chunks "
                            "cannot use NAX-half safely -> using GPU mul_mm_id "
                            "(NAX-half requires M5+ and n_tokens %% 64 == 0)\n",
                            n_tokens);
                } else {
                    fprintf(stderr,
                            "ds4: resident MPP/NAX requested, but %u-token "
                            "resident chunks use the faster fused GPU path "
                            "(auto min=%u; set DS4_RESIDENT_MOE_MPP_FORCE=1 to "
                            "force staged MPP/NAX)\n",
                            n_tokens,
                            ds4_gpu_resident_mpp_int8_min_tokens());
                }
                warned_resident_mpp_auto_gpu = true;
            }
        }
        /*
         * The grouped routed-MoE matmul loads activation tiles as half before
         * using SIMD-group MMA.  Store the SwiGLU/route-weight intermediate in
         * that same precision so the down projection avoids a large F32 mid
         * write/read.  --quality or DS4_METAL_MOE_MID_F32 keeps the older F32
         * intermediate for isolated diagnostics.
         */
        const bool request_mid_f16 =
            !use_resident_mpp_standard &&
            !g_quality_mode && getenv("DS4_METAL_MOE_MID_F32") == NULL;
        if (use_mm_id) {
            gate_map_args =
                ds4_gpu_make_mul_mm_id_map_args(expert_in_dim, n_total_expert, 1, n_expert, n_tokens);
            gate_mm_args =
                ds4_gpu_make_mul_mm_id_args(expert_in_dim, expert_mid_dim, n_total_expert,
                                              gate_row_bytes, gate_expert_bytes,
                                              1, n_expert, n_tokens);
            down_mm_args =
                ds4_gpu_make_mul_mm_id_args_src1_size(expert_mid_dim, out_dim, n_total_expert,
                                                        down_row_bytes, down_expert_bytes,
                                                        n_expert, n_expert, n_tokens,
                                                        request_mid_f16 ? sizeof(uint16_t) : sizeof(float));

            map_pipeline = ds4_gpu_get_pipeline(ds4_gpu_mul_mm_id_map0_name(n_expert));
            gate_mm_tile_n = ds4_gpu_moe_mm_tile_n(gate_type, n_tokens);
            down_mm_tile_n = ds4_gpu_moe_mm_tile_n(down_type, n_tokens);
            gate_mm_pipeline = ds4_gpu_routed_mm_pipeline_for_tile(gate_type, gate_mm_tile_n);
            down_mm_pipeline = request_mid_f16 ?
                ds4_gpu_routed_mm_f16_rhs_pipeline_for_tile(down_type, down_mm_tile_n) :
                ds4_gpu_routed_mm_pipeline_for_tile(down_type, down_mm_tile_n);
            if (!map_pipeline || !gate_mm_pipeline || !down_mm_pipeline) {
                return 0;
            }
        }

        if (!ds4_gpu_backend_logs_suppressed() && getenv("DS4_RESIDENT_MOE_KERNEL_LOG")) {
            static bool logged_default_gpu = false;
            static bool logged_mpp_int8 = false;
            static bool logged_mpp_half = false;
            static bool logged_mv = false;
            const bool mpp_half_requested =
                resident_mpp_requested &&
                ds4_gpu_env_flag_enabled("DS4_RESIDENT_MOE_NAX_HALF");
            const uint32_t min_tokens = ds4_gpu_resident_mpp_int8_min_tokens();
            const uint32_t sync_max_tokens = ds4_gpu_resident_mpp_sync_max_tokens();
            const char *sync_bridge_env = getenv("DS4_RESIDENT_MOE_MPP_SYNC_BRIDGE");
            const bool use_sync_bridge = sync_bridge_env && sync_bridge_env[0] ?
                atoi(sync_bridge_env) != 0 :
                (sync_max_tokens != 0u && n_tokens <= sync_max_tokens);
            const char *compact_bridge_env = getenv("DS4_RESIDENT_MOE_MPP_COMPACT_BRIDGE");
            const bool compact_bridge_set = compact_bridge_env && compact_bridge_env[0];
            const bool use_compact_bridge =
                compact_bridge_set ? atoi(compact_bridge_env) != 0 : false;
            const char *pairrow_bridge_env = getenv("DS4_RESIDENT_MOE_MPP_PAIRROW_BRIDGE");
            uint32_t compact_min_tokens =
                ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_MPP_COMPACT_MIN_TOKENS", min_tokens);
            compact_min_tokens =
                ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_NAX_COMPACT_MIN_TOKENS",
                                        compact_min_tokens);
            const bool auto_compact_bridge =
                !compact_bridge_set &&
                (!pairrow_bridge_env || !pairrow_bridge_env[0]) &&
                compact_min_tokens != 0u &&
                n_tokens >= compact_min_tokens;
            const bool use_pairrow_bridge =
                pairrow_bridge_env && pairrow_bridge_env[0] ?
                    atoi(pairrow_bridge_env) != 0 :
                    !use_compact_bridge && !auto_compact_bridge;
            const bool compact_bridge_active =
                use_resident_mpp_standard && !use_sync_bridge &&
                (use_compact_bridge || auto_compact_bridge);
            const bool mpp_half =
                mpp_half_requested && use_resident_mpp_standard &&
                !use_sync_bridge && !compact_bridge_active;
            bool *logged_ptr = use_resident_mpp_standard ?
                (mpp_half ? &logged_mpp_half : &logged_mpp_int8) :
                (use_mm_id ? &logged_default_gpu : &logged_mv);
            if (!*logged_ptr) {
                const char *mpp_bridge = "n/a";
                if (use_resident_mpp_standard) {
                    if (use_sync_bridge) {
                        mpp_bridge = "sync";
                    } else if (use_compact_bridge) {
                        mpp_bridge = "compact-forced";
                    } else if (auto_compact_bridge) {
                        mpp_bridge = "compact-auto";
                    } else if (use_pairrow_bridge) {
                        mpp_bridge = "pairrow";
                    } else {
                        mpp_bridge = "counted-indirect";
                    }
                }
                const bool mpp_fused_dequant =
                    use_resident_mpp_standard &&
                    ds4_gpu_resident_mpp_fused_dequant_enabled();
                const bool mpp_full_fused =
                    use_resident_mpp_standard &&
                    ds4_gpu_env_flag_enabled("DS4_RESIDENT_MOE_NAX_FULL_FUSED");
                const bool mpp_fused_gate_up =
                    use_resident_mpp_standard &&
                    ds4_gpu_env_flag_enabled("DS4_RESIDENT_MOE_NAX_FUSED_GATE_UP");
                const char *route = use_resident_mpp_standard ?
                    (mpp_half ? "forced/resident-MPP-NAX-half" : "forced/resident-MPP-NAX-int8") :
                    (use_mm_id ? "default-GPU-mul_mm_id" :
                     (use_tiny_pair_mv ? "default-GPU-tiny-pair-mv" : "default-GPU-mul_mv_id"));
                const char *mpp_kernels = "n/a";
                uint32_t mpp_tile_m = 0;
                uint32_t mpp_tile_n = 0;
                uint32_t mpp_tile_k = 0;
                uint32_t mpp_threads = 0;
                if (use_resident_mpp_standard) {
                    mpp_tile_m = 64u;
                    mpp_tile_n = 32u;
                    mpp_tile_k = 256u;
                    mpp_threads = 128u;
                    if (mpp_half && mpp_fused_gate_up) {
                        mpp_tile_m = 32u;
                        mpp_tile_n = 32u;
                        mpp_tile_k = 32u;
                        mpp_threads = 32u;
                        mpp_kernels =
                            "half: dequant_iq2/q2k_f16 + ds4_mpp_fused_gate_up_swiglu_h_h_f_n32 + h_h_f down";
                    } else if (mpp_half) {
                        uint32_t half_tile =
                            ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_NAX_HALF_TILE", 128u);
                        half_tile = (half_tile >= 256u) ? 256u :
                                    (half_tile >= 128u) ? 128u :
                                    (half_tile >= 64u)  ? 64u  : 32u;
                        mpp_tile_n = half_tile;
                        mpp_tile_k = 0u; /* dynamic K tile in the half helper. */
                        mpp_kernels =
                            "half: dequant_iq2/q2k_f16 + h_h_f gate/up/down + GPU swiglu";
                    } else if (mpp_fused_dequant && mpp_full_fused) {
                        mpp_kernels =
                            "int8: gather_i8 + ds4_mpp_iq2_fused_gate_up_swiglu_counted + ds4_mpp_q2k_i8_i32_counted";
                    } else if (mpp_fused_dequant) {
                        mpp_tile_n = ds4_gpu_resident_mpp_int8_tile_n();
                        mpp_kernels =
                            "int8: gather_i8 + ds4_mpp_iq2_i8_i32_counted gate/up + swiglu_i32 + ds4_mpp_q2k_i8_i32_counted";
                    } else {
                        mpp_kernels =
                            "int8: dequant_i8 + i8_i8_i32 gate/up/down + GPU swiglu";
                    }
                }
                fprintf(stderr,
                        "ds4: resident MoE kernel log: tokens=%u route=%s "
                        "use_mm_id=%d mpp_shape=%d mpp_requested=%d mpp_forced=%d "
                        "mpp_should_run=%d mpp_min_tokens=%u mpp_bridge=%s "
                        "mpp_mode=%s mpp_half_requested=%d mpp_fused_dequant=%d mpp_full_fused=%d "
                        "mpp_fused_gate_up=%d gate_type=%s down_type=%s experts=%u "
                        "map_kernel=%s gate_kernel=%s up_kernel=%s down_kernel=%s "
                        "mpp_tile_m=%u mpp_tile_n=%u mpp_tile_k=%u mpp_threads=%u "
                        "gate_tile=%u down_tile=%u mid=%s activation=GPU_swiglu_weight "
                        "sum=GPU_sum_experts dense_proj=%s dense_i8_min=%llu "
                        "mpp_kernels=\"%s\"\n",
                        n_tokens,
                        route,
                        use_mm_id ? 1 : 0,
                        resident_mpp_shape_supported ? 1 : 0,
                        resident_mpp_requested ? 1 : 0,
                        ds4_gpu_resident_mpp_int8_prefill_forced() ? 1 : 0,
                        use_resident_mpp_standard ? 1 : 0,
                        min_tokens,
                        mpp_bridge,
                        mpp_half ? "half" : "int8",
                        mpp_half_requested ? 1 : 0,
                        mpp_fused_dequant ? 1 : 0,
                        mpp_full_fused ? 1 : 0,
                        mpp_fused_gate_up ? 1 : 0,
                        ds4_gpu_metal_tensor_name(gate_type),
                        ds4_gpu_metal_tensor_name(down_type),
                        n_expert,
                        use_mm_id ? ds4_gpu_mul_mm_id_map0_name(n_expert) : "n/a",
                        use_mm_id ? ds4_gpu_routed_mm_kernel_name_for_tile(gate_type, gate_mm_tile_n, false) : "n/a",
                        use_mm_id ? ds4_gpu_routed_mm_kernel_name_for_tile(gate_type, gate_mm_tile_n, false) : "n/a",
                        use_mm_id ? ds4_gpu_routed_mm_kernel_name_for_tile(down_type, down_mm_tile_n, request_mid_f16) : "n/a",
                        mpp_tile_m,
                        mpp_tile_n,
                        mpp_tile_k,
                        mpp_threads,
                        gate_mm_tile_n,
                        down_mm_tile_n,
                        request_mid_f16 ? "f16" : "f32",
                        ds4_gpu_dense_backend_name(),
                        (unsigned long long)ds4_gpu_dense_i8_min_tokens(),
                        mpp_kernels);
                *logged_ptr = true;
            }
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        const bool moe_stage_profile =
            getenv("DS4_METAL_MOE_STAGE_PROFILE") != NULL && g_batch_cb != nil;
        double moe_stage_t0 = moe_stage_profile ? ds4_gpu_now_ms() : 0.0;
        if (moe_stage_profile) {
            if (ds4_gpu_end_commands() == 0 || ds4_gpu_begin_commands() == 0) {
                return 0;
            }
            cb = ds4_gpu_command_buffer(&owned);
            if (!cb) return 0;
            moe_stage_t0 = ds4_gpu_now_ms();
        }
#define DS4_METAL_PROFILE_MOE_STAGE(name) do { \
            if (ok && moe_stage_profile) { \
                if (ds4_gpu_end_commands() == 0) { \
                    ok = 0; \
                } else { \
                    const double now_ms = ds4_gpu_now_ms(); \
                    fprintf(stderr, \
                            "ds4: Metal routed MoE stage tokens=%u pairs=%u %s=%.3f ms\n", \
                            n_tokens, pair_rows, (name), now_ms - moe_stage_t0); \
                    moe_stage_t0 = now_ms; \
                    if (ds4_gpu_begin_commands() == 0) { \
                        ok = 0; \
                    } else { \
                        cb = ds4_gpu_command_buffer(&owned); \
                        if (!cb) ok = 0; \
                    } \
                } \
            } \
        } while (0)

        const NSUInteger gate_smem = ds4_gpu_routed_mv_smem(gate_type);
        const NSUInteger down_smem = ds4_gpu_routed_mv_smem(down_type);
        id<MTLComputePipelineState> down_sum6_pipeline = nil;
        if (down_type == DS4_METAL_TENSOR_Q2_K) {
            down_sum6_pipeline = g_moe_mul_mv_id_q2_k_sum6_pipeline;
        } else if (down_type == DS4_METAL_TENSOR_Q4_K) {
            down_sum6_pipeline = g_moe_mul_mv_id_q4_k_sum6_pipeline;
        }
        const bool direct_down_sum =
            !g_quality_mode &&
            !use_mm_id &&
            n_expert == 6 &&
            n_tokens <= 4u &&
            down_sum6_pipeline != nil;
        int ok = 0;
        bool resident_mpp_completed = false;
        if (use_mm_id) {
            /*
             * The routed pair ids are the same for gate, up, and down. Build
             * the expert-major work map once, then reuse it for all three
             * batched expert matmuls.
             */
            ok = ds4_gpu_encode_mul_mm_id_map(cb,
                                                map_pipeline,
                                                &gate_map_args,
                                                &gate_mm_args,
                                                selectedbuf,
                                                ds4_gpu_tensor_offset(selected));
            if (ok && skip_mask_active) {
                ok = ds4_gpu_encode_zero_skipped_moe_counts(cb, (uint32_t)gate_mm_args.ne02);
            }
            DS4_METAL_PROFILE_MOE_STAGE("map");
            if (ok && use_resident_mpp_standard) {
                static bool announced = false;
                if (!announced) {
                    if (ds4_gpu_backend_stats_logs_enabled()) {
                        fprintf(stderr,
                                "ds4: resident routed MoE using standard MPP/NAX "
                                "grouped prefill\n");
                    }
                    announced = true;
                }

                uint32_t sync_max_tokens =
                    ds4_gpu_resident_mpp_sync_max_tokens();
                const char *sync_bridge_env =
                    getenv("DS4_RESIDENT_MOE_MPP_SYNC_BRIDGE");
                const bool use_sync_bridge =
                    sync_bridge_env && sync_bridge_env[0] ?
                        atoi(sync_bridge_env) != 0 :
                        (sync_max_tokens != 0u && n_tokens <= sync_max_tokens);
                /* AUTHORITATIVE one-time print of the param that actually gates the
                 * sync bridge: the resident-MoE TILE n_tokens (NOT the prefill chunk —
                 * the resident path tiles by batch_routed_scratch_cap, hard-capped to
                 * 2048 whenever DS4_RESIDENT_MOE_ANE_HYBRID / COMPACT_SCRATCH is set,
                 * ds4.c:9895). tile <= sync_max_tokens -> slow CPU<->GPU count-readback
                 * (map_wait); tile > it -> fast fully-indirect. Surfaced so a hidden
                 * tiling override can't silently force the slow path. */
                if (ds4_gpu_backend_stats_logs_enabled()) {
                    static bool synced_logged = false;
                    if (!synced_logged) {
                        synced_logged = true;
                        fprintf(stderr,
                            "ds4: resident-NAX tile n_tokens=%u -> sync-bridge=%s "
                            "(sync_max_tokens=%u, src=%s) -> %s\n",
                            n_tokens,
                            use_sync_bridge ? "ON" : "off",
                            sync_max_tokens,
                            (sync_bridge_env && sync_bridge_env[0]) ? "env" : "auto(tile<=max)",
                            use_sync_bridge ? "slow count-readback (map_wait)"
                                            : "fast fully-indirect (no readback)");
                    }
                }
                if (!use_sync_bridge) {
                    const uint32_t total_model_experts = n_total_expert;
                    const NSUInteger tpe_bytes =
                        (NSUInteger)total_model_experts * sizeof(uint32_t);
                    const NSUInteger hids_stride =
                        (NSUInteger)n_tokens * sizeof(int32_t);
                    const NSUInteger hids_bytes =
                        (NSUInteger)total_model_experts * hids_stride;
                    const NSUInteger indirect_arg_bytes = 3u * sizeof(uint32_t);
                    const NSUInteger gather_indirect_off = 0;
                    const NSUInteger gate_indirect_off =
                        gather_indirect_off + (NSUInteger)total_model_experts * indirect_arg_bytes;
                    const NSUInteger down_indirect_off =
                        gate_indirect_off + (NSUInteger)total_model_experts * indirect_arg_bytes;
                    const NSUInteger indirect_bytes =
                        down_indirect_off + (NSUInteger)total_model_experts * indirect_arg_bytes;
                    if (!g_moe_id_map_buffer ||
                        g_moe_id_map_bytes < tpe_bytes + hids_bytes) {
                        ok = 0;
                    }

                    float mpp_i8_qscale = 512.0f;
                    float mpp_x_qscale = 32.0f;
                    float mpp_mid_qscale = 32.0f;
                    ds4_gpu_prefill_int8_scales(0,
                                                &mpp_i8_qscale,
                                                NULL,
                                                &mpp_x_qscale,
                                                NULL,
                                                &mpp_mid_qscale,
                                                NULL);
                    const float mpp_gate_scale = 1.0f / (mpp_x_qscale * mpp_i8_qscale);
                    const float mpp_down_scale = 1.0f / (mpp_mid_qscale * mpp_i8_qscale);

                    const uint64_t gate_i8_bytes = (uint64_t)expert_in_dim * expert_mid_dim;
                    const uint64_t down_i8_bytes = (uint64_t)expert_mid_dim * out_dim;
                    const uint64_t x_i8_bytes = (uint64_t)n_tokens * expert_in_dim;
                    const uint64_t gate_i32_bytes =
                        (uint64_t)n_tokens * expert_mid_dim * sizeof(int32_t);
                    const uint64_t mid_i8_bytes = (uint64_t)n_tokens * expert_mid_dim;
                    const uint64_t out_i32_bytes =
                        (uint64_t)n_tokens * out_dim * sizeof(int32_t);
                    if (ok &&
                        (gate_i8_bytes > NSUIntegerMax ||
                         down_i8_bytes > NSUIntegerMax ||
                         x_i8_bytes > NSUIntegerMax ||
                         gate_i32_bytes > NSUIntegerMax ||
                         mid_i8_bytes > NSUIntegerMax ||
                         out_i32_bytes > NSUIntegerMax ||
                         (uint64_t)n_tokens * expert_in_dim > UINT32_MAX ||
                         (uint64_t)n_tokens * expert_mid_dim > UINT32_MAX ||
                         (uint64_t)n_tokens * out_dim > UINT32_MAX ||
                         indirect_bytes > NSUIntegerMax)) {
                        ok = 0;
                    }
                    if (ok) {
                        ok = ds4_gpu_ensure_mpp_int8_prefill_pipelines() &&
                             ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_gate_i8_buffer,
                                                           &g_mpp_prefill_gate_i8_bytes,
                                                           (NSUInteger)gate_i8_bytes,
                                                           "ds4_mpp_prefill_gate_i8") &&
                             ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_up_i8_buffer,
                                                           &g_mpp_prefill_up_i8_bytes,
                                                           (NSUInteger)gate_i8_bytes,
                                                           "ds4_mpp_prefill_up_i8") &&
                             ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_down_i8_buffer,
                                                           &g_mpp_prefill_down_i8_bytes,
                                                           (NSUInteger)down_i8_bytes,
                                                           "ds4_mpp_prefill_down_i8") &&
                             ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_x_i8_buffer,
                                                           &g_mpp_prefill_x_i8_bytes,
                                                           (NSUInteger)x_i8_bytes,
                                                           "ds4_mpp_prefill_x_i8") &&
                             ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_gate_i32_buffer,
                                                           &g_mpp_prefill_gate_i32_bytes,
                                                           (NSUInteger)gate_i32_bytes,
                                                           "ds4_mpp_prefill_gate_i32") &&
                             ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_up_i32_buffer,
                                                           &g_mpp_prefill_up_i32_bytes,
                                                           (NSUInteger)gate_i32_bytes,
                                                           "ds4_mpp_prefill_up_i32") &&
                             ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_mid_i8_buffer,
                                                           &g_mpp_prefill_mid_i8_bytes,
                                                           (NSUInteger)mid_i8_bytes,
                                                           "ds4_mpp_prefill_mid_i8") &&
	                             ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_out_i32_buffer,
	                                                           &g_mpp_prefill_out_i32_bytes,
	                                                           (NSUInteger)out_i32_bytes,
	                                                           "ds4_mpp_prefill_out_i32") &&
	                             ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_counts_buffer,
	                                                           &g_mpp_prefill_counts_bytes,
	                                                           tpe_bytes,
	                                                           "ds4_mpp_prefill_counts") &&
	                             ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_indirect_buffer,
	                                                           &g_mpp_prefill_indirect_bytes,
	                                                           indirect_bytes,
                                                           "ds4_mpp_prefill_indirect");
                    }
                    const char *compact_bridge_env =
                        getenv("DS4_RESIDENT_MOE_MPP_COMPACT_BRIDGE");
                    const bool compact_bridge_set =
                        compact_bridge_env && compact_bridge_env[0];
                    const bool use_compact_bridge =
                        compact_bridge_set ? atoi(compact_bridge_env) != 0 : false;
                    const char *pairrow_bridge_env =
                        getenv("DS4_RESIDENT_MOE_MPP_PAIRROW_BRIDGE");
                    uint32_t compact_min_tokens =
                        ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_MPP_COMPACT_MIN_TOKENS",
                                                ds4_gpu_resident_mpp_int8_min_tokens());
                    compact_min_tokens =
                        ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_NAX_COMPACT_MIN_TOKENS",
                                                compact_min_tokens);
                    const bool auto_compact_bridge =
                        !compact_bridge_set &&
                        (!pairrow_bridge_env || !pairrow_bridge_env[0]) &&
                        compact_min_tokens != 0u &&
                        n_tokens >= compact_min_tokens;
                    bool use_pairrow_bridge =
                        pairrow_bridge_env && pairrow_bridge_env[0] ?
                            atoi(pairrow_bridge_env) != 0 :
                            !use_compact_bridge && !auto_compact_bridge;
                    bool compact_active = use_compact_bridge || auto_compact_bridge;
                    /* The compact bridge runs ONLY the int8 fused-dequant kernels —
                     * it has no half path. With NAX-half requested it would silently
                     * run int8 (and any "half" label would be a lie). Yield to the
                     * half-capable pairrow bridge so NAX-half actually runs half. */
                    const char *nax_half_bridge_env = getenv("DS4_RESIDENT_MOE_NAX_HALF");
                    const bool want_nax_half =
                        nax_half_bridge_env && nax_half_bridge_env[0] &&
                        atoi(nax_half_bridge_env) != 0;
                    if (want_nax_half && compact_active) {
                        static int warned_half_vs_compact = 0;
                        if (!warned_half_vs_compact) {
                            warned_half_vs_compact = 1;
                            fprintf(stderr,
                                "ds4: NAX-half requested -> using pairrow bridge "
                                "(compact bridge is int8-only; it would silently run "
                                "int8). Unset DS4_RESIDENT_MOE_NAX_HALF to use the "
                                "compact int8 bridge.\n");
                        }
                        compact_active = false;
                        use_pairrow_bridge = true;
                    }
                    if (compact_active) {
                        use_pairrow_bridge = false;
                    }
                    if (!use_pairrow_bridge) {
                        const double mpp_encode_t0 = ds4_gpu_now_ms();
                        const bool use_fused = ds4_gpu_resident_mpp_fused_dequant_enabled();
                        const bool use_full_fused =
                            use_fused && ds4_gpu_resident_mpp_full_fused_gate_up_swiglu_enabled();
                        const uint32_t mpp_int8_tile =
                            (use_fused && !use_full_fused) ? ds4_gpu_resident_mpp_int8_tile_n() : 32u;
                        id<MTLComputePipelineState> iq2_fused_tile_pipe =
                            ds4_gpu_iq2_fused_pipeline_for_tile(mpp_int8_tile);
                        id<MTLComputePipelineState> q2k_fused_tile_pipe =
                            ds4_gpu_q2k_fused_pipeline_for_tile(mpp_int8_tile);
                        if (use_fused && !use_full_fused &&
                            (!iq2_fused_tile_pipe || !q2k_fused_tile_pipe)) {
                            ok = 0;
                        }
                        if (ok) {
                            ok = ds4_gpu_encode_mpp_make_routed_indirect(cb,
                                                                         g_moe_id_map_buffer,
                                                                         g_mpp_prefill_indirect_buffer,
                                                                         gather_indirect_off,
                                                                         gate_indirect_off,
                                                                         down_indirect_off,
                                                                         expert_mid_dim,
                                                                         out_dim,
                                                                         mpp_int8_tile) &&
                                 ds4_gpu_encode_fill_f32_rows(cb,
                                                              outbuf,
                                                              ds4_gpu_tensor_offset(out),
                                                              out_dim,
                                                              n_tokens,
                                                              0.0f);
                        }
                        for (uint32_t expert = 0; ok && expert < total_model_experts; expert++) {
                            const NSUInteger hids_off =
                                tpe_bytes + (NSUInteger)expert * hids_stride;
                            const NSUInteger gather_arg_off =
                                gather_indirect_off + (NSUInteger)expert * indirect_arg_bytes;
                            const NSUInteger gate_arg_off =
                                gate_indirect_off + (NSUInteger)expert * indirect_arg_bytes;
                            const NSUInteger down_arg_off =
                                down_indirect_off + (NSUInteger)expert * indirect_arg_bytes;
                            const NSUInteger gate_expert_off =
                                (NSUInteger)(gate_inner + (uint64_t)expert * gate_expert_bytes);
                            const NSUInteger up_expert_off =
                                (NSUInteger)(up_inner + (uint64_t)expert * gate_expert_bytes);
                            const NSUInteger down_expert_off =
                                (NSUInteger)(down_inner + (uint64_t)expert * down_expert_bytes);

                            if (use_fused) {
                                /* Fused-dequant NAX path: gather acts to int8, then
                                 * matmul reading quantized weights directly (no global
                                 * int8 weight buffer).  gate/up share the gate indirect
                                 * args (N=mid_dim); down uses out_dim args.
                                 * Path C (DS4_RESIDENT_MOE_NAX_FULL_FUSED=1): collapse
                                 * gate matmul + up matmul + swiglu into one dispatch. */
                                ok = ds4_gpu_encode_mpp_gather_token_f32_i8_counted_indirect(cb,
                                                                                       xbuf,
                                                                                       ds4_gpu_tensor_offset(x),
                                                                                       g_moe_id_map_buffer,
                                                                                       hids_off,
                                                                                       g_mpp_prefill_x_i8_buffer,
                                                                                       g_moe_id_map_buffer,
                                                                                       expert,
                                                                                       expert_in_dim,
                                                                                       n_expert,
                                                                                       mpp_x_qscale,
                                                                                       g_mpp_prefill_indirect_buffer,
                                                                                       gather_arg_off) &&
                                     (use_full_fused
                                      ? ds4_gpu_encode_mpp_iq2_fused_gate_up_swiglu_counted_indirect(cb,
                                                                                              g_mpp_prefill_x_i8_buffer, 0,
                                                                                              gate_buf, gate_expert_off,
                                                                                              up_buf, up_expert_off,
                                                                                              g_mpp_prefill_mid_i8_buffer, 0,
                                                                                              weightsbuf,
                                                                                              ds4_gpu_tensor_offset(weights),
                                                                                              g_moe_id_map_buffer, hids_off,
                                                                                              g_moe_id_map_buffer, expert,
                                                                                              expert_mid_dim, expert_in_dim,
                                                                                              mpp_i8_qscale,
                                                                                              mpp_gate_scale,
                                                                                              clamp,
                                                                                              mpp_mid_qscale,
                                                                                              g_mpp_prefill_indirect_buffer,
                                                                                              gate_arg_off)
                                      : (ds4_gpu_encode_mpp_fused_matmul_counted_indirect(cb,
                                                                                      iq2_fused_tile_pipe,
                                                                                      g_mpp_prefill_x_i8_buffer, 0,
                                                                                      gate_buf, gate_expert_off,
                                                                                      g_mpp_prefill_gate_i32_buffer, 0,
                                                                                      g_moe_id_map_buffer, expert,
                                                                                      expert_mid_dim, expert_in_dim,
                                                                                      mpp_i8_qscale,
                                                                                      g_mpp_prefill_indirect_buffer,
                                                                                      gate_arg_off) &&
                                         ds4_gpu_encode_mpp_fused_matmul_counted_indirect(cb,
                                                                                      iq2_fused_tile_pipe,
                                                                                      g_mpp_prefill_x_i8_buffer, 0,
                                                                                      up_buf, up_expert_off,
                                                                                      g_mpp_prefill_up_i32_buffer, 0,
                                                                                      g_moe_id_map_buffer, expert,
                                                                                      expert_mid_dim, expert_in_dim,
                                                                                      mpp_i8_qscale,
                                                                                      g_mpp_prefill_indirect_buffer,
                                                                                      gate_arg_off) &&
                                         ds4_gpu_encode_mpp_swiglu_i32_hids_weight_i8_counted_indirect(cb,
                                                                                              g_mpp_prefill_gate_i32_buffer,
                                                                                              g_mpp_prefill_up_i32_buffer,
                                                                                              g_mpp_prefill_mid_i8_buffer,
                                                                                              weightsbuf,
                                                                                              ds4_gpu_tensor_offset(weights),
                                                                                              g_moe_id_map_buffer,
                                                                                              hids_off,
                                                                                              g_moe_id_map_buffer,
                                                                                              expert,
                                                                                              expert_mid_dim,
                                                                                              clamp,
                                                                                              mpp_gate_scale,
                                                                                              mpp_mid_qscale,
                                                                                              g_mpp_prefill_indirect_buffer,
                                                                                              gather_arg_off))) &&
                                     ds4_gpu_encode_mpp_fused_matmul_counted_indirect(cb,
                                                                                      q2k_fused_tile_pipe,
                                                                                      g_mpp_prefill_mid_i8_buffer, 0,
                                                                                      down_buf, down_expert_off,
                                                                                      g_mpp_prefill_out_i32_buffer, 0,
                                                                                      g_moe_id_map_buffer, expert,
                                                                                      out_dim, expert_mid_dim,
                                                                                      mpp_i8_qscale,
                                                                                      g_mpp_prefill_indirect_buffer,
                                                                                      down_arg_off) &&
                                     ds4_gpu_encode_mpp_scatter_add_token_i32_f32_counted_indirect(cb,
                                                                                              g_mpp_prefill_out_i32_buffer,
                                                                                              g_moe_id_map_buffer,
                                                                                              hids_off,
                                                                                              outbuf,
                                                                                              ds4_gpu_tensor_offset(out),
                                                                                              g_moe_id_map_buffer,
                                                                                              expert,
                                                                                              out_dim,
                                                                                              n_expert,
                                                                                              mpp_down_scale,
                                                                                              g_mpp_prefill_indirect_buffer,
                                                                                              gather_arg_off);
                                continue;
                            }

                            ok = ds4_gpu_encode_mpp_dequant_gud_i8(cb,
                                                                   gate_buf,
                                                                   gate_expert_off,
                                                                   g_mpp_prefill_gate_i8_buffer,
                                                                   up_buf,
                                                                   up_expert_off,
                                                                   g_mpp_prefill_up_i8_buffer,
                                                                   down_buf,
                                                                   down_expert_off,
                                                                   g_mpp_prefill_down_i8_buffer,
                                                                   expert_mid_dim,
                                                                   expert_in_dim,
                                                                   out_dim,
                                                                   mpp_i8_qscale) &&
                                 ds4_gpu_encode_mpp_gather_token_f32_i8_counted_indirect(cb,
                                                                                       xbuf,
                                                                                       ds4_gpu_tensor_offset(x),
                                                                                       g_moe_id_map_buffer,
                                                                                       hids_off,
                                                                                       g_mpp_prefill_x_i8_buffer,
                                                                                       g_moe_id_map_buffer,
                                                                                       expert,
                                                                                       expert_in_dim,
                                                                                       n_expert,
                                                                                       mpp_x_qscale,
                                                                                       g_mpp_prefill_indirect_buffer,
                                                                                       gather_arg_off) &&
                                 ds4_gpu_encode_mpp_gate_up_counted_indirect(cb,
                                                                             g_mpp_prefill_x_i8_buffer,
                                                                             0,
                                                                             g_mpp_prefill_gate_i8_buffer,
                                                                             g_mpp_prefill_gate_i32_buffer,
                                                                             0,
                                                                             g_mpp_prefill_up_i8_buffer,
                                                                             g_mpp_prefill_up_i32_buffer,
                                                                             0,
                                                                             g_moe_id_map_buffer,
                                                                             expert,
                                                                             expert_mid_dim,
                                                                             expert_in_dim,
                                                                             g_mpp_prefill_indirect_buffer,
                                                                             gate_arg_off) &&
                                 ds4_gpu_encode_mpp_swiglu_i32_hids_weight_i8_counted_indirect(cb,
                                                                                              g_mpp_prefill_gate_i32_buffer,
                                                                                              g_mpp_prefill_up_i32_buffer,
                                                                                              g_mpp_prefill_mid_i8_buffer,
                                                                                              weightsbuf,
                                                                                              ds4_gpu_tensor_offset(weights),
                                                                                              g_moe_id_map_buffer,
                                                                                              hids_off,
                                                                                              g_moe_id_map_buffer,
                                                                                              expert,
                                                                                              expert_mid_dim,
                                                                                              clamp,
                                                                                              mpp_gate_scale,
                                                                                              mpp_mid_qscale,
                                                                                              g_mpp_prefill_indirect_buffer,
                                                                                              gather_arg_off) &&
                                 ds4_gpu_encode_mpp_matmul_counted_indirect(cb,
                                                                            g_mpp_prefill_mid_i8_buffer,
                                                                            0,
                                                                            g_mpp_prefill_down_i8_buffer,
                                                                            g_mpp_prefill_out_i32_buffer,
                                                                            0,
                                                                            g_moe_id_map_buffer,
                                                                            expert,
                                                                            out_dim,
                                                                            expert_mid_dim,
                                                                            g_mpp_prefill_indirect_buffer,
                                                                            down_arg_off) &&
                                 ds4_gpu_encode_mpp_scatter_add_token_i32_f32_counted_indirect(cb,
                                                                                              g_mpp_prefill_out_i32_buffer,
                                                                                              g_moe_id_map_buffer,
                                                                                              hids_off,
                                                                                              outbuf,
                                                                                              ds4_gpu_tensor_offset(out),
                                                                                              g_moe_id_map_buffer,
                                                                                              expert,
                                                                                              out_dim,
                                                                                              n_expert,
                                                                                              mpp_down_scale,
                                                                                              g_mpp_prefill_indirect_buffer,
                                                                                              gather_arg_off);
                        }
                        DS4_METAL_PROFILE_MOE_STAGE("mpp_compact");
                        if (ok) {
                            if (mid_is_f16) *mid_is_f16 = false;
                            resident_mpp_completed = true;
                            if (!ds4_gpu_backend_logs_suppressed() &&
                                (ds4_gpu_env_flag_enabled("DS4_RESIDENT_MOE_MPP_STATS") ||
                                 ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_PROFILE"))) {
                                fprintf(stderr,
                                        "ds4: resident MPP/NAX compact MoE tokens=%u "
                                        "indirect=1 encode_wall=%.3f ms "
                                        "w_qscale=%.6g x_qscale=%.6g mid_qscale=%.6g\n",
                                        n_tokens,
                                        ds4_gpu_now_ms() - mpp_encode_t0,
                                        mpp_i8_qscale,
                                        mpp_x_qscale,
                                        mpp_mid_qscale);
                            }
                        }
	                    } else {
	                    const double mpp_encode_t0 = ds4_gpu_now_ms();
	                    uint32_t hybrid_min_refs =
	                        ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_MPP_HYBRID_MIN_REFS", 0u);
	                    hybrid_min_refs =
	                        ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_NAX_HYBRID_MIN_REFS",
	                                                hybrid_min_refs);
	                    const bool hybrid_pairrow = hybrid_min_refs != 0u;
	                    id<MTLBuffer> mpp_counts_buffer = g_moe_id_map_buffer;
	                    if (ok && hybrid_pairrow) {
	                        ok = ds4_gpu_encode_mpp_split_counts(cb,
	                                                              g_moe_id_map_buffer,
	                                                              g_mpp_prefill_counts_buffer,
	                                                              hybrid_min_refs);
	                        mpp_counts_buffer = g_mpp_prefill_counts_buffer;
	                    }
	                    if (ok) {
	                        ok = ds4_gpu_encode_mpp_make_routed_indirect(cb,
	                                                                     mpp_counts_buffer,
	                                                                     g_mpp_prefill_indirect_buffer,
	                                                                     gather_indirect_off,
	                                                                     gate_indirect_off,
	                                                                     down_indirect_off,
	                                                                     expert_mid_dim,
	                                                                     out_dim,
                                                                         32u);
	                    }
                    for (uint32_t expert = 0; ok && expert < total_model_experts; expert++) {
                        const NSUInteger hids_off =
                            tpe_bytes + (NSUInteger)expert * hids_stride;
                        const NSUInteger gather_arg_off =
                            gather_indirect_off + (NSUInteger)expert * indirect_arg_bytes;
                        const NSUInteger gate_arg_off =
                            gate_indirect_off + (NSUInteger)expert * indirect_arg_bytes;
                        const NSUInteger gate_expert_off =
                            (NSUInteger)(gate_inner + (uint64_t)expert * gate_expert_bytes);
	                        const NSUInteger up_expert_off =
	                            (NSUInteger)(up_inner + (uint64_t)expert * gate_expert_bytes);

	                        if (hybrid_pairrow) {
	                            ok = ds4_gpu_encode_mpp_dequant_iq2_xxs_i8_counted(cb,
	                                                                               gate_buf,
	                                                                               gate_expert_off,
	                                                                               g_mpp_prefill_gate_i8_buffer,
	                                                                               expert_mid_dim,
	                                                                               expert_in_dim,
	                                                                               mpp_i8_qscale,
	                                                                               mpp_counts_buffer,
	                                                                               expert) &&
	                                 ds4_gpu_encode_mpp_dequant_iq2_xxs_i8_counted(cb,
	                                                                               up_buf,
	                                                                               up_expert_off,
	                                                                               g_mpp_prefill_up_i8_buffer,
	                                                                               expert_mid_dim,
	                                                                               expert_in_dim,
	                                                                               mpp_i8_qscale,
	                                                                               mpp_counts_buffer,
	                                                                               expert);
	                        } else {
	                            ok = ds4_gpu_encode_mpp_dequant_iq2_xxs_i8(cb,
	                                                                       gate_buf,
	                                                                       gate_expert_off,
	                                                                       g_mpp_prefill_gate_i8_buffer,
	                                                                       expert_mid_dim,
	                                                                       expert_in_dim,
	                                                                       mpp_i8_qscale) &&
	                                 ds4_gpu_encode_mpp_dequant_iq2_xxs_i8(cb,
	                                                                       up_buf,
	                                                                       up_expert_off,
	                                                                       g_mpp_prefill_up_i8_buffer,
	                                                                       expert_mid_dim,
	                                                                       expert_in_dim,
	                                                                       mpp_i8_qscale);
	                        }
	                        ok = ok &&
	                             ds4_gpu_encode_mpp_gather_token_f32_i8_counted_indirect(cb,
	                                                                                   xbuf,
	                                                                                   ds4_gpu_tensor_offset(x),
	                                                                                   g_moe_id_map_buffer,
	                                                                                   hids_off,
	                                                                                   g_mpp_prefill_x_i8_buffer,
	                                                                                  mpp_counts_buffer,
	                                                                                   expert,
	                                                                                   expert_in_dim,
	                                                                                   n_expert,
                                                                                   mpp_x_qscale,
                                                                                   g_mpp_prefill_indirect_buffer,
                                                                                   gather_arg_off) &&
	                             ds4_gpu_encode_mpp_gate_up_counted_indirect(cb,
	                                                                         g_mpp_prefill_x_i8_buffer,
	                                                                         0,
		                                                                         g_mpp_prefill_gate_i8_buffer,
		                                                                         g_mpp_prefill_gate_i32_buffer,
		                                                                         0,
		                                                                         g_mpp_prefill_up_i8_buffer,
		                                                                         g_mpp_prefill_up_i32_buffer,
		                                                                         0,
		                                                                         mpp_counts_buffer,
		                                                                         expert,
		                                                                         expert_mid_dim,
		                                                                         expert_in_dim,
	                                                                         g_mpp_prefill_indirect_buffer,
	                                                                         gate_arg_off) &&
                             ds4_gpu_encode_mpp_scatter_ids_i32_f32_counted_indirect(cb,
                                                                                    g_mpp_prefill_gate_i32_buffer,
	                                                                                    g_moe_id_map_buffer,
	                                                                                    hids_off,
	                                                                                    gatebuf,
	                                                                                    ds4_gpu_tensor_offset(gate),
	                                                                                    mpp_counts_buffer,
	                                                                                    expert,
	                                                                                    expert_mid_dim,
	                                                                                    mpp_gate_scale,
                                                                                    g_mpp_prefill_indirect_buffer,
                                                                                    gather_arg_off) &&
                             ds4_gpu_encode_mpp_scatter_ids_i32_f32_counted_indirect(cb,
                                                                                    g_mpp_prefill_up_i32_buffer,
	                                                                                    g_moe_id_map_buffer,
	                                                                                    hids_off,
	                                                                                    upbuf,
	                                                                                    ds4_gpu_tensor_offset(up),
	                                                                                    mpp_counts_buffer,
	                                                                                    expert,
	                                                                                    expert_mid_dim,
	                                                                                    mpp_gate_scale,
                                                                                    g_mpp_prefill_indirect_buffer,
                                                                                    gather_arg_off);
                    }
                    DS4_METAL_PROFILE_MOE_STAGE("mpp_gate_up");

                    if (ok) {
                        ok = ds4_gpu_encode_moe_swiglu_weight(cb,
                                                              gatebuf,
                                                              ds4_gpu_tensor_offset(gate),
                                                              upbuf,
                                                              ds4_gpu_tensor_offset(up),
                                                              midbuf,
                                                              ds4_gpu_tensor_offset(mid),
                                                              weightsbuf,
                                                              ds4_gpu_tensor_offset(weights),
                                                              expert_mid_dim,
                                                              pair_rows,
                                                              clamp,
                                                              false);
                    }
                    DS4_METAL_PROFILE_MOE_STAGE("mpp_activation_weight");

                    id<MTLBuffer> mpp_down_dst =
                        expertsbuf ? expertsbuf : g_moe_down_scratch_buffer;
                    const NSUInteger mpp_down_dst_off =
                        expertsbuf ? ds4_gpu_tensor_offset(experts) : 0;
                    for (uint32_t expert = 0; ok && expert < total_model_experts; expert++) {
                        const NSUInteger hids_off =
                            tpe_bytes + (NSUInteger)expert * hids_stride;
                        const NSUInteger gather_arg_off =
                            gather_indirect_off + (NSUInteger)expert * indirect_arg_bytes;
                        const NSUInteger down_arg_off =
                            down_indirect_off + (NSUInteger)expert * indirect_arg_bytes;
	                        const NSUInteger down_expert_off =
	                            (NSUInteger)(down_inner + (uint64_t)expert * down_expert_bytes);

	                        if (hybrid_pairrow) {
	                            ok = ds4_gpu_encode_mpp_dequant_q2_k_i8_counted(cb,
	                                                                            down_buf,
	                                                                            down_expert_off,
	                                                                            g_mpp_prefill_down_i8_buffer,
	                                                                            out_dim,
	                                                                            expert_mid_dim,
	                                                                            mpp_i8_qscale,
	                                                                            mpp_counts_buffer,
	                                                                            expert);
	                        } else {
	                            ok = ds4_gpu_encode_mpp_dequant_q2_k_i8(cb,
	                                                                    down_buf,
	                                                                    down_expert_off,
	                                                                    g_mpp_prefill_down_i8_buffer,
	                                                                    out_dim,
	                                                                    expert_mid_dim,
	                                                                    mpp_i8_qscale);
	                        }
	                        ok = ok &&
	                             ds4_gpu_encode_mpp_gather_pair_f32_i8_counted_indirect(cb,
	                                                                                  midbuf,
	                                                                                  ds4_gpu_tensor_offset(mid),
	                                                                                  g_moe_id_map_buffer,
	                                                                                  hids_off,
	                                                                                  g_mpp_prefill_mid_i8_buffer,
	                                                                                  mpp_counts_buffer,
	                                                                                  expert,
	                                                                                  expert_mid_dim,
	                                                                                  mpp_mid_qscale,
                                                                                  g_mpp_prefill_indirect_buffer,
                                                                                  gather_arg_off) &&
                             ds4_gpu_encode_mpp_matmul_counted_indirect(cb,
                                                                        g_mpp_prefill_mid_i8_buffer,
                                                                        0,
	                                                                        g_mpp_prefill_down_i8_buffer,
	                                                                        g_mpp_prefill_out_i32_buffer,
	                                                                        0,
	                                                                        mpp_counts_buffer,
	                                                                        expert,
	                                                                        out_dim,
	                                                                        expert_mid_dim,
                                                                        g_mpp_prefill_indirect_buffer,
                                                                        down_arg_off) &&
                             ds4_gpu_encode_mpp_scatter_ids_i32_f32_counted_indirect(cb,
                                                                                    g_mpp_prefill_out_i32_buffer,
	                                                                                    g_moe_id_map_buffer,
	                                                                                    hids_off,
	                                                                                    mpp_down_dst,
	                                                                                    mpp_down_dst_off,
	                                                                                    mpp_counts_buffer,
	                                                                                    expert,
	                                                                                    out_dim,
	                                                                                    mpp_down_scale,
                                                                                    g_mpp_prefill_indirect_buffer,
                                                                                    gather_arg_off);
	                    }
	                    DS4_METAL_PROFILE_MOE_STAGE("mpp_down");

	                    if (ok && hybrid_pairrow) {
	                        ok = ds4_gpu_encode_mul_mm_id_mapped_tile(cb,
	                                                             gate_mm_pipeline,
	                                                             &gate_mm_args,
	                                                             gate_buf,
	                                                             (NSUInteger)gate_inner,
	                                                             xbuf,
	                                                             ds4_gpu_tensor_offset(x),
	                                                             gatebuf,
	                                                             ds4_gpu_tensor_offset(gate),
	                                                             gate_mm_tile_n);
	                    }
	                    DS4_METAL_PROFILE_MOE_STAGE("hybrid_gpu_gate");

	                    if (ok && !hybrid_pairrow) {
	                        ok = ds4_gpu_encode_moe_sum_experts(cb,
	                                                            mpp_down_dst,
	                                                            mpp_down_dst_off,
                                                            outbuf,
                                                            ds4_gpu_tensor_offset(out),
                                                            out_dim,
                                                            n_expert,
                                                            n_tokens);
                    }
	                    DS4_METAL_PROFILE_MOE_STAGE("mpp_sum");

	                    if (ok) {
	                        if (!hybrid_pairrow) {
	                            if (mid_is_f16) *mid_is_f16 = false;
	                            resident_mpp_completed = true;
	                        }
	                        if (!ds4_gpu_backend_logs_suppressed() &&
	                            (ds4_gpu_env_flag_enabled("DS4_RESIDENT_MOE_MPP_STATS") ||
	                             ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_PROFILE"))) {
	                            fprintf(stderr,
	                                    "ds4: resident MPP/NAX standard MoE tokens=%u "
	                                    "indirect=1 hybrid_min_refs=%u encode_wall=%.3f ms "
	                                    "w_qscale=%.6g x_qscale=%.6g mid_qscale=%.6g\n",
	                                    n_tokens,
	                                    hybrid_min_refs,
	                                    ds4_gpu_now_ms() - mpp_encode_t0,
	                                    mpp_i8_qscale,
                                    mpp_x_qscale,
                                    mpp_mid_qscale);
                        }
                    }
                    }
                } else {
                const double map_wait_t0 = ds4_gpu_now_ms();
                if (owned) {
                    ok = ds4_gpu_finish_command_buffer(cb, owned, "resident MPP/NAX map");
                } else {
                    ok = ds4_gpu_end_commands();
                }
                const double map_wait_ms = ds4_gpu_now_ms() - map_wait_t0;

                const uint32_t total_model_experts = n_total_expert;
                const NSUInteger tpe_bytes =
                    (NSUInteger)total_model_experts * sizeof(uint32_t);
                const NSUInteger hids_stride =
                    (NSUInteger)n_tokens * sizeof(int32_t);
                const NSUInteger hids_bytes =
                    (NSUInteger)total_model_experts * hids_stride;
                uint32_t *counts = NULL;
                if (ok && g_moe_id_map_buffer &&
                    g_moe_id_map_bytes >= tpe_bytes + hids_bytes) {
                    counts = (uint32_t *)[g_moe_id_map_buffer contents];
                }
                if (!counts) ok = 0;

                if (ok) {
                    if (!owned && ds4_gpu_begin_commands() == 0) ok = 0;
                    cb = ds4_gpu_command_buffer(&owned);
                    if (!cb) ok = 0;
                }

                float mpp_i8_qscale = 512.0f;
                float mpp_x_qscale = 32.0f;
                float mpp_mid_qscale = 32.0f;
                ds4_gpu_prefill_int8_scales(0,
                                            &mpp_i8_qscale,
                                            NULL,
                                            &mpp_x_qscale,
                                            NULL,
                                            &mpp_mid_qscale,
                                            NULL);
                const float mpp_gate_scale = 1.0f / (mpp_x_qscale * mpp_i8_qscale);
                const float mpp_down_scale = 1.0f / (mpp_mid_qscale * mpp_i8_qscale);

                const uint64_t gate_i8_bytes = (uint64_t)expert_in_dim * expert_mid_dim;
                const uint64_t down_i8_bytes = (uint64_t)expert_mid_dim * out_dim;
                const uint64_t x_i8_bytes = (uint64_t)n_tokens * expert_in_dim;
                const uint64_t gate_i32_bytes =
                    (uint64_t)n_tokens * expert_mid_dim * sizeof(int32_t);
                const uint64_t mid_i8_bytes = (uint64_t)n_tokens * expert_mid_dim;
                const uint64_t out_i32_bytes =
                    (uint64_t)n_tokens * out_dim * sizeof(int32_t);
                if (ok &&
                    (gate_i8_bytes > NSUIntegerMax ||
                     down_i8_bytes > NSUIntegerMax ||
                     x_i8_bytes > NSUIntegerMax ||
                     gate_i32_bytes > NSUIntegerMax ||
                     mid_i8_bytes > NSUIntegerMax ||
                     out_i32_bytes > NSUIntegerMax ||
                     (uint64_t)n_tokens * expert_in_dim > UINT32_MAX ||
                     (uint64_t)n_tokens * expert_mid_dim > UINT32_MAX ||
                     (uint64_t)n_tokens * out_dim > UINT32_MAX)) {
                    ok = 0;
                }
                if (ok) {
                    ok = ds4_gpu_ensure_mpp_int8_prefill_pipelines() &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_gate_i8_buffer,
                                                       &g_mpp_prefill_gate_i8_bytes,
                                                       (NSUInteger)gate_i8_bytes,
                                                       "ds4_mpp_prefill_gate_i8") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_up_i8_buffer,
                                                       &g_mpp_prefill_up_i8_bytes,
                                                       (NSUInteger)gate_i8_bytes,
                                                       "ds4_mpp_prefill_up_i8") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_down_i8_buffer,
                                                       &g_mpp_prefill_down_i8_bytes,
                                                       (NSUInteger)down_i8_bytes,
                                                       "ds4_mpp_prefill_down_i8") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_x_i8_buffer,
                                                       &g_mpp_prefill_x_i8_bytes,
                                                       (NSUInteger)x_i8_bytes,
                                                       "ds4_mpp_prefill_x_i8") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_gate_i32_buffer,
                                                       &g_mpp_prefill_gate_i32_bytes,
                                                       (NSUInteger)gate_i32_bytes,
                                                       "ds4_mpp_prefill_gate_i32") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_up_i32_buffer,
                                                       &g_mpp_prefill_up_i32_bytes,
                                                       (NSUInteger)gate_i32_bytes,
                                                       "ds4_mpp_prefill_up_i32") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_mid_i8_buffer,
                                                       &g_mpp_prefill_mid_i8_bytes,
                                                       (NSUInteger)mid_i8_bytes,
                                                       "ds4_mpp_prefill_mid_i8") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_out_i32_buffer,
                                                       &g_mpp_prefill_out_i32_bytes,
                                                       (NSUInteger)out_i32_bytes,
                                                       "ds4_mpp_prefill_out_i32");
                }
                /* NAX-half (resident): parallel half x half (matmul2d) path on the
                 * compact bridge -- gather acts to half, dequant experts to f16,
                 * h_h_f matmul into the i32 scratch reused as f32, scatter f32
                 * (scale 1.0, f16 dequant bakes the real scale). DS4_RESIDENT_MOE_NAX_HALF=1;
                 * tile 32/64/128/256 via DS4_RESIDENT_MOE_NAX_HALF_TILE (default 128). */
                /* iter-4: ANE+GPU concurrent (resident). Per expert with refs >=
                 * threshold, async-submit ANE via _ane_start_tensor with model
                 * tensor views; GPU runs the other experts in parallel. Wait+
                 * finish ANE jobs before swiglu (ANE already produces per-token
                 * out contribution; scatter-add into batch_routed_out). */
                const char *ane_hybrid_env = getenv("DS4_RESIDENT_MOE_ANE_HYBRID");
                const bool use_ane_hybrid =
                    ane_hybrid_env && ane_hybrid_env[0] && atoi(ane_hybrid_env) != 0;
                const uint32_t ane_min_refs =
                    ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_ANE_MIN_REFS", 129u);
                (void)use_ane_hybrid; (void)ane_min_refs;
                /* Single-active-ANE pattern (mirrors flash hybrid "concurrent" mode,
                 * not the pipelined predict/queue): submit one ANE job per eligible
                 * expert; before submitting the next one, wait+finish the previous
                 * (reusing g->flash_prefill_x/out scratches). GPU runs other experts
                 * in parallel because ANE runs on its own pthread. After the gate/up
                 * loop, drain the final job. Down loop skips ANE-handled experts. */
                uint8_t ane_mask[256];
                memset(ane_mask, 0, sizeof(ane_mask));

                const char *nax_half_env = getenv("DS4_RESIDENT_MOE_NAX_HALF");
                bool use_h_h;
                if (tb_use) {
                    /* JSON prefill_by_tokens (or DS4_RESIDENT_MOE_BACKEND param) drives
                     * this chunk: a *half* backend -> NAX-half, else int8. mulmm never
                     * reaches this resident-standard branch. */
                    use_h_h = tb_half;
                } else {
                    /* fallback gate (to be phased out): static NAX_HALF env clamped by
                     * the NAX_HALF_MAX_TOKENS auto-threshold. */
                    use_h_h = nax_half_env && nax_half_env[0] && atoi(nax_half_env) != 0;
                    if (no_int8_paths) {
                        use_h_h = true;
                    } else {
                        const uint32_t nax_half_max_tokens =
                            ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_NAX_HALF_MAX_TOKENS", 0u);
                        if (use_h_h && nax_half_max_tokens != 0u && n_tokens >= nax_half_max_tokens) {
                            use_h_h = false;
                        }
                    }
                }
                /* CORRECTNESS FLOOR: the NAX-half matmul2d tiles M (tokens) in units of
                 * 64 (matmul2d_descriptor(64,NT); tA.slice(0, tgid.y*64)). It is only
                 * correct when n_tokens is a full multiple of 64 — a partial M-tile
                 * over-reads and corrupts output. Round benchmark chunks (4096/8192/...)
                 * masked this; real prefill (a short/odd prompt, the partial last chunk)
                 * and decode (n_tokens=1) are NOT multiples of 64. Normal fast mode
                 * demotes them to int8; --no-int8 keeps them on GPU before this branch.
                 * Mirrors the same guard on the mul_mm_id n64 kernel (n_tokens
                 * >= 64 && n_tokens % 64 == 0). Override with
                 * DS4_RESIDENT_MOE_NAX_HALF_ALLOW_PARTIAL=1 only for isolated A/B. */
                if (use_h_h && (n_tokens < 64u || (n_tokens % 64u) != 0u) &&
                    !ds4_gpu_env_flag_enabled("DS4_RESIDENT_MOE_NAX_HALF_ALLOW_PARTIAL")) {
                    use_h_h = false;
                    /* NEVER demote silently: NAX-half was requested but the matmul2d M-tile
                     * is a fixed 64 and the h_h_f kernel over-reads a partial tile, so in
                     * normal fast mode a non-multiple-of-64 chunk is demoted to int8
                     * (whose counted-indirect kernels clamp the partial tile and stay correct).
                     * Log it once so a
                     * "requested half, ran int8" surprise is visible, not hidden. */
                    if (!ds4_gpu_backend_logs_suppressed()) {
                        static bool warned_half_floor = false;
                        if (!warned_half_floor) {
                            warned_half_floor = true;
                            fprintf(stderr,
                                "ds4: NAX-half requested but chunk n_tokens=%u is not a "
                                "multiple of 64 -> DEMOTED to int8 (h_h_f matmul2d M-tile=64 "
                                "over-reads partial tiles; int8 counted kernels clamp). "
                                "Set DS4_RESIDENT_MOE_NAX_HALF_ALLOW_PARTIAL=1 to force half "
                                "(UNSAFE / corrupts).\n",
                                n_tokens);
                        }
                    }
                }
                uint32_t h_h_tile =
                    ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_NAX_HALF_TILE", 128u);
                h_h_tile = (h_h_tile >= 256u) ? 256u :
                           (h_h_tile >= 128u) ? 128u :
                           (h_h_tile >= 64u)  ? 64u  : 32u;
                id<MTLComputePipelineState> h_h_pipe =
                    (h_h_tile == 256u) ? g_mpp_h_h_f_n256_pipeline :
                    (h_h_tile == 128u) ? g_mpp_h_h_f_n128_pipeline :
                    (h_h_tile == 64u)  ? g_mpp_h_h_f_n64_pipeline  :
                                         g_mpp_h_h_f_n32_pipeline;
                /* iter-4 Path C: fused gate+up+swiglu (matmul2d + ALU on cooperative
                 * tensors, in-kernel NAX∥ALU). Per fused-eligible expert, replaces the
                 * gate/up matmul+scatter+swiglu chain with one shader that writes the
                 * per-expert `mid`; that `mid` is then scattered (overwriting the
                 * tensor-wide swiglu's garbage) into pair-indexed midbuf before down. */
                const char *fused_gu_env = getenv("DS4_RESIDENT_MOE_NAX_FUSED_GATE_UP");
                /* fused (Plan A) follows the selected backend: the table picks it by name
                 * (nax_half_alu -> fused, plain nax_half -> not); otherwise the env flag. */
                const bool fused_requested = tb_use
                    ? (strstr(tok_backend, "alu") != NULL || strstr(tok_backend, "fused") != NULL)
                    : (fused_gu_env && fused_gu_env[0] && atoi(fused_gu_env) != 0);
                const bool use_fused_gate_up =
                    use_h_h && fused_requested &&
                    g_mpp_fused_gate_up_swiglu_h_h_f_n32_pipeline != nil;
                /* Default 128: sweep shows the fused kernel barely helps at M=64
                 * (~1.08x, can hurt with wrong tile) but gives 1.4–1.7x at M>=128
                 * (peak 1.72x@M=128, 1.69x@M=512). See moe-batch-bench/fused_kernel_probe.m. */
                const uint32_t fused_min_refs =
                    ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_NAX_FUSED_MIN_REFS", 128u);
                if (ok && (use_h_h || use_fused_gate_up)) {
                    ok = h_h_pipe != nil &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_x_half_buffer,
                                                       &g_mpp_prefill_x_half_bytes,
                                                       (NSUInteger)x_i8_bytes * 2u,
                                                       "ds4_mpp_prefill_x_half") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_gate_f16_buffer,
                                                       &g_mpp_prefill_gate_f16_bytes,
                                                       (NSUInteger)gate_i8_bytes * 2u,
                                                       "ds4_mpp_prefill_gate_f16") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_up_f16_buffer,
                                                       &g_mpp_prefill_up_f16_bytes,
                                                       (NSUInteger)gate_i8_bytes * 2u,
                                                       "ds4_mpp_prefill_up_f16") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_down_f16_buffer,
                                                       &g_mpp_prefill_down_f16_bytes,
                                                       (NSUInteger)down_i8_bytes * 2u,
                                                       "ds4_mpp_prefill_down_f16") &&
                         ds4_gpu_ensure_scratch_buffer(&g_mpp_prefill_mid_half_buffer,
                                                       &g_mpp_prefill_mid_half_bytes,
                                                       (NSUInteger)mid_i8_bytes * 2u,
                                                       "ds4_mpp_prefill_mid_half");
                }

                uint32_t mpp_experts = 0;
                uint64_t mpp_refs = 0;
                uint32_t fused_experts = 0;
                uint64_t fused_refs = 0;
                uint64_t total_refs = 0;
                uint32_t max_refs = 0;
                uint32_t original_counts[256];
                uint8_t mpp_mask[256];
                uint8_t fused_mask[256];  // iter-4 Path C: experts handled by fused gate+up+swiglu
                memset(fused_mask, 0, sizeof(fused_mask));
                uint32_t hybrid_min_refs =
                    ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_MPP_HYBRID_MIN_REFS", 0u);
                hybrid_min_refs =
                    ds4_gpu_env_u32_default("DS4_RESIDENT_MOE_NAX_HYBRID_MIN_REFS",
                                            hybrid_min_refs);
                /* iter-4 ANE+GPU hybrid (resident): tag experts with refs >=
                 * ane_min_refs (default 129) for ANE offload. Step 1 = observe
                 * only: count eligible experts, log to env-gated diag stream.
                 * ANE submission wiring lands in subsequent iterations. */
                uint32_t ane_eligible_experts = 0;
                uint64_t ane_eligible_refs = 0;
                for (uint32_t expert = 0; expert < total_model_experts; expert++) {
                    const uint32_t refs = counts[expert];
                    original_counts[expert] = refs;
                    total_refs += refs;
                    mpp_mask[expert] =
                        (hybrid_min_refs == 0u || refs >= hybrid_min_refs) ? 1u : 0u;
                    if (use_ane_hybrid && refs >= ane_min_refs) {
                        ane_mask[expert] = 1u;
                        ane_eligible_experts++;
                        ane_eligible_refs += refs;
                    }
                }
                if (use_ane_hybrid && getenv("DS4_RESIDENT_MOE_ANE_HYBRID_DIAG")) {
                    fprintf(stderr,
                            "ds4: [ane-hybrid] eligible_experts=%u eligible_refs=%llu "
                            "(of %u experts, %llu refs; min_refs=%u)\n",
                            ane_eligible_experts,
                            (unsigned long long)ane_eligible_refs,
                            total_model_experts,
                            (unsigned long long)total_refs,
                            ane_min_refs);
                }
                const double mpp_encode_t0 = ds4_gpu_now_ms();
                for (uint32_t expert = 0; ok && expert < total_model_experts; expert++) {
                    const uint32_t refs = original_counts[expert];
                    if (refs == 0) continue;
                    if (!mpp_mask[expert]) continue;
                    /* iter-12: skip experts handled by the outer-caller ANE pass. */
                    if (g_ane_skip_mask_active && g_ane_skip_mask[expert]) continue;
                    if (refs > n_tokens) {
                        ok = 0;
                        break;
                    }
                    /* iter-4 ANE-hybrid step 2-3: take the hottest experts first
                     * for ANE before they get routed to the fused-GPU path.
                     * ANE wants refs in [ane_min_refs, 256] (function caps at
                     * ane_max_refs=256). Currently builds views + lazy-allocs
                     * the per-expert filtered-x scratch; full submission lands
                     * once a per-expert hids→f32 gather is wired (iter 4). */
                    if (use_ane_hybrid && ane_mask[expert] && refs <= 256u) {
                        /* Lazy-alloc the x + weights scratches on first ANE-eligible
                         * call. Sized for max ANE batch (256) × expert_in_dim float32
                         * for x; 256 floats for weights. */
                        const uint64_t needed_x_bytes =
                            (uint64_t)256u * expert_in_dim * sizeof(float);
                        const uint64_t needed_w_bytes =
                            (uint64_t)256u * sizeof(float);
                        if (!g_resident_ane_x_scratch ||
                            g_resident_ane_x_scratch_bytes < needed_x_bytes) {
                            if (g_resident_ane_x_scratch) {
                                ds4_gpu_tensor_free(g_resident_ane_x_scratch);
                                g_resident_ane_x_scratch = NULL;
                            }
                            g_resident_ane_x_scratch = ds4_gpu_tensor_alloc(needed_x_bytes);
                            g_resident_ane_x_scratch_bytes =
                                g_resident_ane_x_scratch ? needed_x_bytes : 0;
                        }
                        if (!g_resident_ane_w_scratch ||
                            g_resident_ane_w_scratch_bytes < needed_w_bytes) {
                            if (g_resident_ane_w_scratch) {
                                ds4_gpu_tensor_free(g_resident_ane_w_scratch);
                                g_resident_ane_w_scratch = NULL;
                            }
                            g_resident_ane_w_scratch = ds4_gpu_tensor_alloc(needed_w_bytes);
                            g_resident_ane_w_scratch_bytes =
                                g_resident_ane_w_scratch ? needed_w_bytes : 0;
                        }
                        const uint64_t gate_w_off  = gate_offset + (uint64_t)expert * gate_expert_bytes;
                        const uint64_t up_w_off    = up_offset   + (uint64_t)expert * gate_expert_bytes;
                        const uint64_t down_w_off  = down_offset + (uint64_t)expert * down_expert_bytes;
                        ds4_gpu_tensor *ane_gate_view =
                            ds4_gpu_model_tensor_view(model_map, model_size, gate_w_off, gate_expert_bytes);
                        ds4_gpu_tensor *ane_up_view =
                            ds4_gpu_model_tensor_view(model_map, model_size, up_w_off, gate_expert_bytes);
                        ds4_gpu_tensor *ane_down_view =
                            ds4_gpu_model_tensor_view(model_map, model_size, down_w_off, down_expert_bytes);
                        /* Wrap the per-expert hids slice (raw MTLBuffer + offset
                         * inside g_moe_id_map_buffer) as a non-owning tensor view
                         * so we can pass it to ds4_gpu_gather_rows_f32_tensor.
                         * Pattern matches the selection-view trick at line 15769. */
                        const NSUInteger ane_hids_off =
                            tpe_bytes + (NSUInteger)expert * hids_stride;
                        DS4MetalTensor *hids_view_obj = [DS4MetalTensor new];
                        hids_view_obj.buffer = g_moe_id_map_buffer;
                        hids_view_obj.offset = ane_hids_off;
                        hids_view_obj.bytes = (NSUInteger)refs * sizeof(int32_t);
                        hids_view_obj.owner = 0;
                        ds4_gpu_tensor *hids_tensor =
                            (__bridge ds4_gpu_tensor *)hids_view_obj;

                        int gather_x_ok = 0, gather_w_ok = 0;
                        if (ane_gate_view && ane_up_view && ane_down_view &&
                            g_resident_ane_x_scratch && g_resident_ane_w_scratch &&
                            hids_tensor) {
                            gather_x_ok = ds4_gpu_gather_rows_f32_tensor(
                                g_resident_ane_x_scratch,  /* out: f32 [refs x in_dim] */
                                x,                          /* src: full f32 input */
                                hids_tensor,                /* rows: per-expert pair IDs */
                                refs,
                                expert_in_dim);
                            gather_w_ok = ds4_gpu_gather_rows_f32_tensor(
                                g_resident_ane_w_scratch,  /* out: f32 [refs] */
                                weights,                    /* src: per-pair routing weights */
                                hids_tensor,
                                refs,
                                1);                         /* width = 1 (single float/row) */
                        }

                        /* Iter-5 attempt: ane_start_tensor() succeeded ad-hoc on
                         * single-expert smoke (ane_submit_ok=1) but the full
                         * prefill HANGS because the ANE function internally calls
                         * ds4_gpu_flush_commands() which conflicts with the GPU
                         * command-buffer encoding loop we're inside. Flash hybrid
                         * handles this via commands_open + end_commands tracking
                         * (ds4.c:13269+). Iter 6 task: do the equivalent here.
                         * Gated by an explicit opt-in so the default path is safe. */
                        int ane_submit_ok = 0, ane_finish_ok = 0;
                        const bool actually_submit_ane =
                            getenv("DS4_RESIDENT_MOE_ANE_HYBRID_SUBMIT") &&
                            atoi(getenv("DS4_RESIDENT_MOE_ANE_HYBRID_SUBMIT")) != 0;
                        /* Switching strategy per user guidance: low-level
                         * ds4_ane_mlp_i8w_i8x_tiled_fused_eval inside a worker
                         * pthread (matches the M3 production pattern at line
                         * 6759+). Avoids the cb-conflict by NOT touching the
                         * GPU command-buffer state at all from this thread.
                         *
                         * Iter 7: fetch the cached ANE ctx for shape
                         * (H=in_dim, I=mid_dim, B=256, scales matching the
                         * existing flash hybrid path's defaults). No eval yet
                         * — verify the ctx is available. Eval + pthread wrap
                         * land in iter 8. */
                        ds4_ane_mlp_int8w_ctx *ane_ctx = NULL;
                        if (actually_submit_ane) {
                            const float ane_w_scale  = 1.0f / 512.0f;  /* matches start_tensor defaults */
                            const float ane_x_scale  = 1.0f / 32.0f;
                            const float ane_mid_scale = 1.0f / 32.0f;
                            ane_ctx = ds4_gpu_ane_get_i8i8_tiled_ctx(
                                expert_in_dim, expert_mid_dim, 256,
                                ane_w_scale, ane_x_scale, ane_mid_scale,
                                /*compile_limit=*/8u);
                            if (getenv("DS4_RESIDENT_MOE_ANE_HYBRID_DIAG")) {
                                fprintf(stderr,
                                        "ds4: [ane-hybrid] expert=%u refs=%u ctx_ok=%d\n",
                                        expert, refs, ane_ctx ? 1 : 0);
                            }
                        }
                        (void)ane_ctx;
                        (void)ane_submit_ok; (void)ane_finish_ok;

                        if (getenv("DS4_RESIDENT_MOE_ANE_HYBRID_DIAG")) {
                            fprintf(stderr,
                                    "ds4: [ane-hybrid] expert=%u refs=%u views_ok=%d "
                                    "scratch_ok=%d gather_x_ok=%d gather_w_ok=%d "
                                    "ane_submit_ok=%d ane_finish_ok=%d\n",
                                    expert, refs,
                                    (ane_gate_view && ane_up_view && ane_down_view) ? 1 : 0,
                                    (g_resident_ane_x_scratch && g_resident_ane_w_scratch) ? 1 : 0,
                                    gather_x_ok, gather_w_ok,
                                    ane_submit_ok, ane_finish_ok);
                        }
                        ds4_gpu_tensor_free(ane_gate_view);
                        ds4_gpu_tensor_free(ane_up_view);
                        ds4_gpu_tensor_free(ane_down_view);
                        /* Continue to GPU path for now — ANE submit + skip happens
                         * in iter 4 once we wire start_tensor + finish_tensor +
                         * skip-in-GPU-stages logic. */
                    }
                    /* iter-4 Path C: defer this expert to the post-swiglu fused
                     * loop which writes per-expert mid via one shader (fused
                     * gate+up+swiglu) and scatter-overwrites pair-indexed midbuf. */
                    if (use_fused_gate_up && refs >= fused_min_refs) {
                        fused_mask[expert] = 1;
                        fused_experts++;
                        fused_refs += refs;
                        if (refs > max_refs) max_refs = refs;
                        continue;
                    }
                    mpp_experts++;
                    mpp_refs += refs;
                    if (refs > max_refs) max_refs = refs;
                    const NSUInteger hids_off =
                        tpe_bytes + (NSUInteger)expert * hids_stride;
                    const NSUInteger gate_expert_off =
                        (NSUInteger)(gate_inner + (uint64_t)expert * gate_expert_bytes);
                    const NSUInteger up_expert_off =
                        (NSUInteger)(up_inner + (uint64_t)expert * gate_expert_bytes);

                    if (use_h_h) {
                        ok = ds4_gpu_encode_ane_dequant_iq2_xxs_f16(cb,
                                                                    gate_buf, gate_expert_off,
                                                                    g_mpp_prefill_gate_f16_buffer,
                                                                    expert_mid_dim, expert_in_dim) &&
                             ds4_gpu_encode_ane_dequant_iq2_xxs_f16(cb,
                                                                    up_buf, up_expert_off,
                                                                    g_mpp_prefill_up_f16_buffer,
                                                                    expert_mid_dim, expert_in_dim) &&
                             ds4_gpu_encode_mpp_gather_token_f32_half(cb,
                                                                    xbuf, ds4_gpu_tensor_offset(x),
                                                                    g_moe_id_map_buffer, hids_off,
                                                                    g_mpp_prefill_x_half_buffer,
                                                                    refs, expert_in_dim, n_expert) &&
                             ds4_gpu_encode_mpp_matmul_tile(cb, h_h_pipe, h_h_tile,
                                                            g_mpp_prefill_x_half_buffer, 0,
                                                            g_mpp_prefill_gate_f16_buffer,
                                                            g_mpp_prefill_gate_i32_buffer, 0,
                                                            refs, expert_mid_dim, expert_in_dim) &&
                             ds4_gpu_encode_mpp_matmul_tile(cb, h_h_pipe, h_h_tile,
                                                            g_mpp_prefill_x_half_buffer, 0,
                                                            g_mpp_prefill_up_f16_buffer,
                                                            g_mpp_prefill_up_i32_buffer, 0,
                                                            refs, expert_mid_dim, expert_in_dim) &&
                             ds4_gpu_encode_mpp_scatter_ids_f32_f32(cb,
                                                                    g_mpp_prefill_gate_i32_buffer,
                                                                    g_moe_id_map_buffer, hids_off,
                                                                    gatebuf, ds4_gpu_tensor_offset(gate),
                                                                    refs, expert_mid_dim, 1.0f) &&
                             ds4_gpu_encode_mpp_scatter_ids_f32_f32(cb,
                                                                    g_mpp_prefill_up_i32_buffer,
                                                                    g_moe_id_map_buffer, hids_off,
                                                                    upbuf, ds4_gpu_tensor_offset(up),
                                                                    refs, expert_mid_dim, 1.0f);
                    } else {
                    ok = ds4_gpu_encode_mpp_dequant_iq2_xxs_i8(cb,
                                                               gate_buf,
                                                               gate_expert_off,
                                                               g_mpp_prefill_gate_i8_buffer,
                                                               expert_mid_dim,
                                                               expert_in_dim,
                                                               mpp_i8_qscale) &&
                         ds4_gpu_encode_mpp_dequant_iq2_xxs_i8(cb,
                                                               up_buf,
                                                               up_expert_off,
                                                               g_mpp_prefill_up_i8_buffer,
                                                               expert_mid_dim,
                                                               expert_in_dim,
                                                               mpp_i8_qscale) &&
                         ds4_gpu_encode_mpp_gather_token_f32_i8(cb,
                                                               xbuf,
                                                               ds4_gpu_tensor_offset(x),
                                                               g_moe_id_map_buffer,
                                                               hids_off,
                                                               g_mpp_prefill_x_i8_buffer,
                                                               refs,
                                                               expert_in_dim,
                                                               n_expert,
                                                               mpp_x_qscale) &&
                         ds4_gpu_encode_mpp_matmul(cb,
                                                   g_mpp_i8_i8_i32_pipeline,
                                                   g_mpp_prefill_x_i8_buffer,
                                                   0,
                                                   g_mpp_prefill_gate_i8_buffer,
                                                   g_mpp_prefill_gate_i32_buffer,
                                                   0,
                                                   refs,
                                                   expert_mid_dim,
                                                   expert_in_dim) &&
                         ds4_gpu_encode_mpp_matmul(cb,
                                                   g_mpp_i8_i8_i32_pipeline,
                                                   g_mpp_prefill_x_i8_buffer,
                                                   0,
                                                   g_mpp_prefill_up_i8_buffer,
                                                   g_mpp_prefill_up_i32_buffer,
                                                   0,
                                                   refs,
                                                   expert_mid_dim,
                                                   expert_in_dim) &&
                         ds4_gpu_encode_mpp_scatter_ids_i32_f32(cb,
                                                                g_mpp_prefill_gate_i32_buffer,
                                                                g_moe_id_map_buffer,
                                                                hids_off,
                                                                gatebuf,
                                                                ds4_gpu_tensor_offset(gate),
                                                                refs,
                                                                expert_mid_dim,
                                                                mpp_gate_scale) &&
                         ds4_gpu_encode_mpp_scatter_ids_i32_f32(cb,
                                                                g_mpp_prefill_up_i32_buffer,
                                                                g_moe_id_map_buffer,
                                                                hids_off,
                                                                upbuf,
                                                                ds4_gpu_tensor_offset(up),
                                                                refs,
                                                                expert_mid_dim,
                                                                mpp_gate_scale);
                    }
                }
                DS4_METAL_PROFILE_MOE_STAGE("mpp_gate_up");

                if (ok) {
                    ok = ds4_gpu_encode_moe_swiglu_weight(cb,
                                                          gatebuf,
                                                          ds4_gpu_tensor_offset(gate),
                                                          upbuf,
                                                          ds4_gpu_tensor_offset(up),
                                                          midbuf,
                                                          ds4_gpu_tensor_offset(mid),
                                                          weightsbuf,
                                                          ds4_gpu_tensor_offset(weights),
                                                          expert_mid_dim,
                                                          pair_rows,
                                                          clamp,
                                                          false);
                }
                DS4_METAL_PROFILE_MOE_STAGE("mpp_activation_weight");

                /* iter-4 Path C: per fused-eligible expert, run the in-kernel
                 * matmul2d+ALU fused gate+up+swiglu shader, then scatter the
                 * per-expert `mid` (refs x mid_dim) into pair-indexed midbuf at
                 * this expert's pair positions — overwriting whatever the
                 * tensor-wide swiglu wrote for these positions (which was
                 * garbage since gate/up weren't populated for fused experts). */
                if (ok && use_fused_gate_up) {
                    for (uint32_t expert = 0; ok && expert < total_model_experts; expert++) {
                        if (!fused_mask[expert]) continue;
                        const uint32_t refs = original_counts[expert];
                        if (refs == 0) continue;
                        const NSUInteger hids_off =
                            tpe_bytes + (NSUInteger)expert * hids_stride;
                        const NSUInteger gate_expert_off =
                            (NSUInteger)(gate_inner + (uint64_t)expert * gate_expert_bytes);
                        const NSUInteger up_expert_off =
                            (NSUInteger)(up_inner + (uint64_t)expert * gate_expert_bytes);
                        ok = ds4_gpu_encode_ane_dequant_iq2_xxs_f16(cb,
                                                                    gate_buf, gate_expert_off,
                                                                    g_mpp_prefill_gate_f16_buffer,
                                                                    expert_mid_dim, expert_in_dim) &&
                             ds4_gpu_encode_ane_dequant_iq2_xxs_f16(cb,
                                                                    up_buf, up_expert_off,
                                                                    g_mpp_prefill_up_f16_buffer,
                                                                    expert_mid_dim, expert_in_dim) &&
                             ds4_gpu_encode_mpp_gather_token_f32_half(cb,
                                                                      xbuf, ds4_gpu_tensor_offset(x),
                                                                      g_moe_id_map_buffer, hids_off,
                                                                      g_mpp_prefill_x_half_buffer,
                                                                      refs, expert_in_dim, n_expert) &&
                             ds4_gpu_encode_mpp_fused_gate_up_swiglu(cb,
                                                                     g_mpp_prefill_x_half_buffer, 0,
                                                                     g_mpp_prefill_gate_f16_buffer,
                                                                     g_mpp_prefill_up_f16_buffer,
                                                                     g_mpp_prefill_gate_i32_buffer, 0,
                                                                     refs, expert_mid_dim, expert_in_dim,
                                                                     (float)clamp) &&
                             /* WEIGHTED scatter: the fused kernel wrote mid=SiLU(gate)*up
                              * WITHOUT the per-token routing weight, so fold weights[pair]
                              * in here (matches the non-fused ds4_gpu_encode_moe_swiglu_weight).
                              * Without this the routing weight is dropped -> divergent output. */
                             ds4_gpu_encode_mpp_scatter_ids_f32_f32_weighted(cb,
                                                                    g_mpp_prefill_gate_i32_buffer,
                                                                    g_moe_id_map_buffer, hids_off,
                                                                    midbuf, ds4_gpu_tensor_offset(mid),
                                                                    weightsbuf, ds4_gpu_tensor_offset(weights),
                                                                    refs, expert_mid_dim, 1.0f);
                    }
                }
                DS4_METAL_PROFILE_MOE_STAGE("mpp_fused_gate_up");

                id<MTLBuffer> mpp_down_dst =
                    expertsbuf ? expertsbuf : g_moe_down_scratch_buffer;
                const NSUInteger mpp_down_dst_off =
                    expertsbuf ? ds4_gpu_tensor_offset(experts) : 0;
                for (uint32_t expert = 0; ok && expert < total_model_experts; expert++) {
                    const uint32_t refs = original_counts[expert];
                    if (refs == 0) continue;
                    if (!mpp_mask[expert]) continue;
                    const NSUInteger hids_off =
                        tpe_bytes + (NSUInteger)expert * hids_stride;
                    const NSUInteger down_expert_off =
                        (NSUInteger)(down_inner + (uint64_t)expert * down_expert_bytes);

                    if (use_h_h) {
                        ok = ds4_gpu_encode_ane_dequant_q2_k_f16(cb,
                                                                 down_buf, down_expert_off,
                                                                 g_mpp_prefill_down_f16_buffer,
                                                                 out_dim, expert_mid_dim) &&
                             ds4_gpu_encode_mpp_gather_pair_f32_half(cb,
                                                                    midbuf, ds4_gpu_tensor_offset(mid),
                                                                    g_moe_id_map_buffer, hids_off,
                                                                    g_mpp_prefill_mid_half_buffer,
                                                                    refs, expert_mid_dim) &&
                             ds4_gpu_encode_mpp_matmul_tile(cb, h_h_pipe, h_h_tile,
                                                            g_mpp_prefill_mid_half_buffer, 0,
                                                            g_mpp_prefill_down_f16_buffer,
                                                            g_mpp_prefill_out_i32_buffer, 0,
                                                            refs, out_dim, expert_mid_dim) &&
                             ds4_gpu_encode_mpp_scatter_ids_f32_f32(cb,
                                                                    g_mpp_prefill_out_i32_buffer,
                                                                    g_moe_id_map_buffer, hids_off,
                                                                    mpp_down_dst, mpp_down_dst_off,
                                                                    refs, out_dim, 1.0f);
                    } else {
                    ok = ds4_gpu_encode_mpp_dequant_q2_k_i8(cb,
                                                            down_buf,
                                                            down_expert_off,
                                                            g_mpp_prefill_down_i8_buffer,
                                                            out_dim,
                                                            expert_mid_dim,
                                                            mpp_i8_qscale) &&
                         ds4_gpu_encode_mpp_gather_pair_f32_i8(cb,
                                                              midbuf,
                                                              ds4_gpu_tensor_offset(mid),
                                                              g_moe_id_map_buffer,
                                                              hids_off,
                                                              g_mpp_prefill_mid_i8_buffer,
                                                              refs,
                                                              expert_mid_dim,
                                                              mpp_mid_qscale) &&
                         ds4_gpu_encode_mpp_matmul(cb,
                                                   g_mpp_i8_i8_i32_pipeline,
                                                   g_mpp_prefill_mid_i8_buffer,
                                                   0,
                                                   g_mpp_prefill_down_i8_buffer,
                                                   g_mpp_prefill_out_i32_buffer,
                                                   0,
                                                   refs,
                                                   out_dim,
                                                   expert_mid_dim) &&
                         ds4_gpu_encode_mpp_scatter_ids_i32_f32(cb,
                                                                g_mpp_prefill_out_i32_buffer,
                                                                g_moe_id_map_buffer,
                                                                hids_off,
                                                                mpp_down_dst,
                                                                mpp_down_dst_off,
                                                                refs,
                                                                out_dim,
                                                                mpp_down_scale);
                    }
                }
                DS4_METAL_PROFILE_MOE_STAGE("mpp_down");

                const bool hybrid_gpu_tail =
                    hybrid_min_refs != 0u && mpp_refs < total_refs;
                if (ok && hybrid_gpu_tail) {
                    for (uint32_t expert = 0; expert < total_model_experts; expert++) {
                        if (mpp_mask[expert]) counts[expert] = 0;
                    }
                    ok = ds4_gpu_encode_mul_mm_id_mapped_tile(cb,
                                                         gate_mm_pipeline,
                                                         &gate_mm_args,
                                                         gate_buf,
                                                         (NSUInteger)gate_inner,
                                                         xbuf,
                                                         ds4_gpu_tensor_offset(x),
                                                         gatebuf,
                                                         ds4_gpu_tensor_offset(gate),
                                                         gate_mm_tile_n);
                }
                DS4_METAL_PROFILE_MOE_STAGE("hybrid_gpu_gate");

                if (ok && !hybrid_gpu_tail) {
                    ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                        mpp_down_dst,
                                                        mpp_down_dst_off,
                                                        outbuf,
                                                        ds4_gpu_tensor_offset(out),
                                                        out_dim,
                                                        n_expert,
                                                        n_tokens);
                }
                DS4_METAL_PROFILE_MOE_STAGE("mpp_sum");

                if (ok) {
                    if (!hybrid_gpu_tail) {
                        if (mid_is_f16) *mid_is_f16 = false;
                        resident_mpp_completed = true;
                    }
                    if (!ds4_gpu_backend_logs_suppressed() &&
                        (ds4_gpu_env_flag_enabled("DS4_RESIDENT_MOE_MPP_STATS") ||
                         ds4_gpu_env_flag_enabled("DS4_FLASH_MOE_PROFILE"))) {
                        const uint64_t handled_refs = mpp_refs + fused_refs;
                        fprintf(stderr,
                                "ds4: resident MPP/NAX standard MoE mode=%s tokens=%u "
                                "experts=%u refs=%llu fused_experts=%u fused_refs=%llu "
                                "total_refs=%llu max_refs=%u hybrid_min_refs=%u "
                                "gpu_tail_refs=%llu map_wait=%.3f ms "
                                "encode_wall=%.3f ms w_qscale=%.6g x_qscale=%.6g mid_qscale=%.6g\n",
                                use_h_h ? "half" : "int8",
                                n_tokens,
                                mpp_experts,
                                (unsigned long long)mpp_refs,
                                fused_experts,
                                (unsigned long long)fused_refs,
                                (unsigned long long)total_refs,
                                max_refs,
                                hybrid_min_refs,
                                (unsigned long long)(total_refs > handled_refs ? total_refs - handled_refs : 0),
                                map_wait_ms,
                                ds4_gpu_now_ms() - mpp_encode_t0,
                                mpp_i8_qscale,
                                mpp_x_qscale,
                                mpp_mid_qscale);
                    }
                }
                }
            } else if (ok) {
                ok = ds4_gpu_encode_mul_mm_id_mapped_tile(cb,
                                                   gate_mm_pipeline,
                                                   &gate_mm_args,
                                                   gate_buf,
                                                   (NSUInteger)gate_inner,
                                                   xbuf,
                                                   ds4_gpu_tensor_offset(x),
                                                   gatebuf,
                                                   ds4_gpu_tensor_offset(gate),
                                                   gate_mm_tile_n);
                DS4_METAL_PROFILE_MOE_STAGE("gate");
            }
            if (ok && !resident_mpp_completed) {
                ok = ds4_gpu_encode_mul_mm_id_mapped_tile(cb,
                                                   gate_mm_pipeline,
                                                   &gate_mm_args,
                                                   up_buf,
                                                   (NSUInteger)up_inner,
                                                   xbuf,
                                                   ds4_gpu_tensor_offset(x),
                                                   upbuf,
                                                   ds4_gpu_tensor_offset(up),
                                                   gate_mm_tile_n);
                DS4_METAL_PROFILE_MOE_STAGE("up");
            }
        } else if (use_tiny_pair_mv) {
            id<MTLComputePipelineState> pair_pipeline =
                gate_type == DS4_METAL_TENSOR_IQ2_XXS ?
                    g_moe_mul_mv_id_iq2_xxs_pair_pipeline :
                    g_moe_mul_mv_id_q4_k_pair_pipeline;
            ok = ds4_gpu_encode_mul_mv_id_pair(cb,
                                                 pair_pipeline,
                                                 &gate_args,
                                                 gate_buf,
                                                 (NSUInteger)gate_inner,
                                                 up_buf,
                                                 (NSUInteger)up_inner,
                                                 xbuf,
                                                 ds4_gpu_tensor_offset(x),
                                                 gatebuf,
                                                 ds4_gpu_tensor_offset(gate),
                                                 upbuf,
                                                 ds4_gpu_tensor_offset(up),
                                                 selectedbuf,
                                                 ds4_gpu_tensor_offset(selected),
                                                 gate_smem,
                                                 2,
                                                 false);
        } else {
            ok = ds4_gpu_encode_mul_mv_id(cb,
                                                  gate_mv_pipeline,
                                                  &gate_args,
                                                  gate_buf,
                                                  (NSUInteger)gate_inner,
                                                  xbuf,
                                                  ds4_gpu_tensor_offset(x),
                                                  gatebuf,
                                                  ds4_gpu_tensor_offset(gate),
                                                  selectedbuf,
                                                  ds4_gpu_tensor_offset(selected),
                                                  gate_smem,
                                                  2,
                                                  false) &&
                 ds4_gpu_encode_mul_mv_id(cb,
                                                  gate_mv_pipeline,
                                                  &gate_args,
                                                  up_buf,
                                                  (NSUInteger)up_inner,
                                                  xbuf,
                                                  ds4_gpu_tensor_offset(x),
                                                  upbuf,
                                                  ds4_gpu_tensor_offset(up),
                                                  selectedbuf,
                                                  ds4_gpu_tensor_offset(selected),
                                                  gate_smem,
                                                  2,
                                                  false);
        }
        DS4_METAL_PROFILE_MOE_STAGE("gate_up");
        if (!resident_mpp_completed) {
        const bool use_fused_activation = !g_quality_mode;
        const bool use_mid_f16 =
            use_mm_id &&
            use_fused_activation &&
            request_mid_f16;
        if (mid_is_f16) *mid_is_f16 = use_mid_f16;
        if (ok && use_fused_activation) {
            ok = ds4_gpu_encode_moe_swiglu_weight(cb,
                                                    gatebuf,
                                                    ds4_gpu_tensor_offset(gate),
                                                    upbuf,
                                                    ds4_gpu_tensor_offset(up),
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    weightsbuf,
                                                    ds4_gpu_tensor_offset(weights),
                                                    expert_mid_dim,
                                                    pair_rows,
                                                    clamp,
                                                    use_mid_f16);
        } else if (ok && clamp > 1.0e-6f) {
            ok = ds4_gpu_encode_unary_f32_rows(cb,
                                                 g_unary_clamp_pipeline,
                                                 gatebuf,
                                                 ds4_gpu_tensor_offset(gate),
                                                 gatebuf,
                                                 ds4_gpu_tensor_offset(gate),
                                                 expert_mid_dim,
                                                 pair_rows,
                                                 0,
                                                 -FLT_MAX,
                                                 clamp);
            if (ok) {
                ok = ds4_gpu_encode_unary_f32_rows(cb,
                                                     g_unary_silu_pipeline,
                                                     gatebuf,
                                                     ds4_gpu_tensor_offset(gate),
                                                     midbuf,
                                                     ds4_gpu_tensor_offset(mid),
                                                     expert_mid_dim,
                                                     pair_rows,
                                                     1,
                                                     0.0f,
                                                     0.0f);
            }
            if (ok) {
                ok = ds4_gpu_encode_unary_f32_rows(cb,
                                                 g_unary_clamp_pipeline,
                                                 upbuf,
                                                 ds4_gpu_tensor_offset(up),
                                                 upbuf,
                                                 ds4_gpu_tensor_offset(up),
                                                 expert_mid_dim,
                                                 pair_rows,
                                                 0,
                                                 -clamp,
                                                 clamp);
            }
            if (ok) {
                ds4_gpu_bin_args mul_args =
                    ds4_gpu_make_bin_same_rows_args(expert_mid_dim, pair_rows);
                ok = ds4_gpu_encode_bin_f32_rows(cb,
                                                   g_mul_pipeline,
                                                   &mul_args,
                                                   midbuf,
                                                   ds4_gpu_tensor_offset(mid),
                                                   upbuf,
                                                   ds4_gpu_tensor_offset(up),
                                                   midbuf,
                                                   ds4_gpu_tensor_offset(mid));
            }
        } else if (ok) {
            ok = ds4_gpu_encode_swiglu_flat(cb,
                                              gatebuf,
                                              ds4_gpu_tensor_offset(gate),
                                              upbuf,
                                              ds4_gpu_tensor_offset(up),
                                              midbuf,
                                              ds4_gpu_tensor_offset(mid),
                                              (uint32_t)((uint64_t)pair_rows * expert_mid_dim));
        }
        if (ok && !use_fused_activation) {
            ds4_gpu_bin_args weight_args =
                ds4_gpu_make_bin_rowwise_scalar_args(expert_mid_dim, pair_rows);
            ok = ds4_gpu_encode_bin_f32_rows(cb,
                                               g_bin_mul_scalar_pipeline,
                                               &weight_args,
                                               midbuf,
                                               ds4_gpu_tensor_offset(mid),
                                               weightsbuf,
                                               ds4_gpu_tensor_offset(weights),
                                               midbuf,
                                               ds4_gpu_tensor_offset(mid));
        }
        DS4_METAL_PROFILE_MOE_STAGE("activation_weight");

        id<MTLBuffer> down_dst = n_expert == 1 ? outbuf : (expertsbuf ? expertsbuf : g_moe_down_scratch_buffer);
        NSUInteger down_dst_off = n_expert == 1 ? ds4_gpu_tensor_offset(out) :
            (expertsbuf ? ds4_gpu_tensor_offset(experts) : 0);
        if (ok && skip_mask_active && n_expert > 1) {
            ok = ds4_gpu_encode_fill_f32_rows(cb,
                                              down_dst,
                                              down_dst_off,
                                              out_dim,
                                              pair_rows,
                                              0.0f);
        }
        if (ok) {
            if (direct_down_sum) {
                ok = ds4_gpu_encode_mul_mv_id_sum6(cb,
                                                     down_sum6_pipeline,
                                                     &down_args,
                                                     down_buf,
                                                     (NSUInteger)down_inner,
                                                     midbuf,
                                                     ds4_gpu_tensor_offset(mid),
                                                     outbuf,
                                                     ds4_gpu_tensor_offset(out),
                                                     selectedbuf,
                                                     ds4_gpu_tensor_offset(selected),
                                                     down_smem,
                                                     2);
            } else if (use_mm_id) {
                ok = ds4_gpu_encode_mul_mm_id_mapped_tile(cb,
                                                       down_mm_pipeline,
                                                       &down_mm_args,
                                                       down_buf,
                                                       (NSUInteger)down_inner,
                                                       midbuf,
                                                       ds4_gpu_tensor_offset(mid),
                                                       down_dst,
                                                       down_dst_off,
                                                       down_mm_tile_n);
            } else {
                ok = ds4_gpu_encode_mul_mv_id(cb,
                                                     down_mv_pipeline,
                                                     &down_args,
                                                     down_buf,
                                                     (NSUInteger)down_inner,
                                                     midbuf,
                                                     ds4_gpu_tensor_offset(mid),
                                                     down_dst,
                                                     down_dst_off,
                                                     selectedbuf,
                                                     ds4_gpu_tensor_offset(selected),
                                                     down_smem,
                                                     2,
                                                     false);
            }
        }
        DS4_METAL_PROFILE_MOE_STAGE("down");
        if (ok && n_expert > 1 && !direct_down_sum) {
            ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                       down_dst,
                                                       down_dst_off,
                                                       outbuf,
                                                       ds4_gpu_tensor_offset(out),
                                                       out_dim,
                                                       n_expert,
                                                       n_tokens);
        }
        DS4_METAL_PROFILE_MOE_STAGE("sum");
        }
        if (!ok) return 0;

        if (!ds4_gpu_finish_command_buffer(cb, owned, "routed batch MoE")) return 0;
#undef DS4_METAL_PROFILE_MOE_STAGE
    }

    return 1;
}

int ds4_gpu_hc_split_sinkhorn_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *mix,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (n_hc == 0 || n_hc > 16) return 0;
    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    const uint64_t mix_bytes = mix_hc * sizeof(float);
    const uint64_t scale_bytes = 3ull * sizeof(float);

    @autoreleasepool {
        id<MTLBuffer> mixbuf = ds4_gpu_tensor_buffer(mix);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t mix_tensor_bytes = ds4_gpu_tensor_bytes(mix);
        const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
        if (!mixbuf || !outbuf ||
            mix_tensor_bytes < mix_bytes ||
            out_tensor_bytes < mix_bytes) {
            fprintf(stderr, "ds4: Metal HC split received undersized activation buffers\n");
            return 0;
        }
        if (scale_offset > model_size || scale_bytes > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset) {
            fprintf(stderr, "ds4: Metal HC split parameter range is outside the mapped model\n");
            return 0;
        }

        uint64_t scale_inner = 0;
        uint64_t base_inner = 0;
        id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(model_map, model_size, scale_offset, scale_bytes, &scale_inner);
        id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(model_map, model_size, base_offset, mix_bytes, &base_inner);
        if (!scalebuf || !basebuf) return 0;

        uint64_t n_rows64 = mix_tensor_bytes / mix_bytes;
        const uint64_t out_rows64 = out_tensor_bytes / mix_bytes;
        if (out_rows64 < n_rows64) n_rows64 = out_rows64;
        if (n_rows64 == 0 || n_rows64 > UINT32_MAX) {
            fprintf(stderr, "ds4: Metal HC split row count is outside supported range\n");
            return 0;
        }

        ds4_gpu_hc_split_args args = {
            .n_hc = (int32_t)n_hc,
            .sinkhorn_iters = (int32_t)sinkhorn_iters,
            .n_rows = (int64_t)n_rows64,
            .mix_hc = (int64_t)mix_hc,
            .nb01 = mix_bytes,
            .nb1 = mix_bytes,
            .eps = eps,
        };
        const NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)n_rows64));
        const NSUInteger n_tg = ((NSUInteger)n_rows64 + nth - 1u) / nth;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_hc_split_sinkhorn_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:mixbuf offset:ds4_gpu_tensor_offset(mix) atIndex:1];
        [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:2];
        [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:3];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:4];
        [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "HC split/sinkhorn")) return 0;
    }

    return 1;
}

static int ds4_gpu_hc_weighted_sum_strided(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *weights,
        uint64_t                weight_offset,
        uint64_t                weight_row_stride,
        uint32_t                n_embd,
        uint32_t                n_hc,
        const char             *label) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !residual_hc || !weights || n_embd == 0 || n_hc == 0 ||
        weight_row_stride < (uint64_t)n_hc * sizeof(float)) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(residual_hc);
        id<MTLBuffer> wbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
        const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
        if (out_row_bytes == 0 || out_tensor_bytes < out_row_bytes || out_tensor_bytes % out_row_bytes != 0) {
            fprintf(stderr, "ds4: Metal HC weighted sum output size is not a whole token row\n");
            return 0;
        }

        const uint64_t n_tokens64 = out_tensor_bytes / out_row_bytes;
        if (n_tokens64 == 0 || n_tokens64 > UINT32_MAX) {
            fprintf(stderr, "ds4: Metal HC weighted sum token count is outside supported range\n");
            return 0;
        }

        const uint64_t x_row_values = (uint64_t)n_hc * n_embd;
        if (x_row_values == 0 ||
            x_row_values > UINT64_MAX / sizeof(float) ||
            n_tokens64 > UINT64_MAX / (x_row_values * sizeof(float)) ||
            n_tokens64 > UINT64_MAX / ((uint64_t)n_hc * sizeof(float))) {
            fprintf(stderr, "ds4: Metal HC weighted sum activation size overflow\n");
            return 0;
        }

        const uint64_t x_bytes = n_tokens64 * x_row_values * sizeof(float);
        const uint64_t w_last = weight_offset +
                                (n_tokens64 - 1u) * weight_row_stride +
                                (uint64_t)n_hc * sizeof(float);
        if (!xbuf || !wbuf || !outbuf ||
            ds4_gpu_tensor_bytes(residual_hc) < x_bytes ||
            ds4_gpu_tensor_bytes(weights) < w_last) {
            fprintf(stderr, "ds4: Metal HC weighted sum received undersized activation buffers\n");
            return 0;
        }

        ds4_gpu_hc_weighted_sum_args args = {
            .n_embd = n_embd,
            .n_hc = n_hc,
            .n_tokens = (int64_t)n_tokens64,
            .nb_x0 = sizeof(float),
            .nb_x1 = (uint64_t)n_embd * sizeof(float),
            .nb_x2 = (uint64_t)n_hc * n_embd * sizeof(float),
            .nb_w0 = sizeof(float),
            .nb_w1 = weight_row_stride,
            .nb0 = sizeof(float),
            .nb1 = (uint64_t)n_embd * sizeof(float),
        };
        const uint64_t n_elem = (uint64_t)n_embd * n_tokens64;
        const NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)n_elem));
        const NSUInteger n_tg = ((NSUInteger)n_elem + nth - 1u) / nth;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_hc_weighted_sum_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:1];
        [enc setBuffer:wbuf offset:ds4_gpu_tensor_offset(weights) + (NSUInteger)weight_offset atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, label)) return 0;
    }

    return 1;
}

int ds4_gpu_hc_weighted_sum_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *weights,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    return ds4_gpu_hc_weighted_sum_strided(out,
                                             residual_hc,
                                             weights,
                                             0,
                                             (uint64_t)n_hc * sizeof(float),
                                             n_embd,
                                             n_hc,
                                             "HC weighted sum");
}

int ds4_gpu_hc_weighted_sum_split_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    return ds4_gpu_hc_weighted_sum_strided(out,
                                             residual_hc,
                                             split,
                                             0,
                                             mix_hc * sizeof(float),
                                             n_embd,
                                             n_hc,
                                             "HC weighted sum split");
}

/* Release decode fused HC pre-sublayer operation.  The graph driver owns the
 * optional reference fallback so this function stays a direct fused dispatch. */
int ds4_gpu_hc_split_weighted_sum_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !split || !mix || !residual_hc || !model_map ||
        n_embd == 0 || n_hc == 0) {
        return 0;
    }
    if (n_hc != 4) {
        fprintf(stderr, "ds4: Metal fused HC split/sum is specialized for HC=4\n");
        return 0;
    }

    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    const uint64_t mix_bytes = mix_hc * sizeof(float);
    const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
    const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
    const uint64_t scale_bytes = 3ull * sizeof(float);

    @autoreleasepool {
        id<MTLBuffer> mixbuf = ds4_gpu_tensor_buffer(mix);
        id<MTLBuffer> splitbuf = ds4_gpu_tensor_buffer(split);
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(residual_hc);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
        if (out_row_bytes == 0 || out_tensor_bytes < out_row_bytes ||
            out_tensor_bytes % out_row_bytes != 0) {
            fprintf(stderr, "ds4: Metal fused HC split/sum output size is not a whole token row\n");
            return 0;
        }

        const uint64_t n_rows64 = out_tensor_bytes / out_row_bytes;
        if (n_rows64 == 0 || n_rows64 > UINT32_MAX ||
            n_rows64 > UINT64_MAX / mix_bytes ||
            n_rows64 > UINT64_MAX / residual_row_bytes) {
            fprintf(stderr, "ds4: Metal fused HC split/sum row count is outside supported range\n");
            return 0;
        }

        const uint64_t mix_total_bytes = n_rows64 * mix_bytes;
        const uint64_t residual_total_bytes = n_rows64 * residual_row_bytes;
        if (!mixbuf || !splitbuf || !xbuf || !outbuf ||
            ds4_gpu_tensor_bytes(mix) < mix_total_bytes ||
            ds4_gpu_tensor_bytes(split) < mix_total_bytes ||
            ds4_gpu_tensor_bytes(residual_hc) < residual_total_bytes) {
            fprintf(stderr, "ds4: Metal fused HC split/sum received undersized activation buffers\n");
            return 0;
        }

        if (scale_offset > model_size || scale_bytes > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset) {
            fprintf(stderr, "ds4: Metal fused HC split/sum parameter range is outside the mapped model\n");
            return 0;
        }

        uint64_t scale_inner = 0;
        uint64_t base_inner = 0;
        id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(model_map, model_size, scale_offset, scale_bytes, &scale_inner);
        id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(model_map, model_size, base_offset, mix_bytes, &base_inner);
        if (!scalebuf || !basebuf) return 0;

        ds4_gpu_hc_split_weighted_sum_args args = {
            .n_embd = (int64_t)n_embd,
            .n_hc = (int32_t)n_hc,
            .sinkhorn_iters = (int32_t)sinkhorn_iters,
            .n_rows = (int64_t)n_rows64,
            .mix_hc = (int64_t)mix_hc,
            .nb_mix1 = mix_bytes,
            .nb_split1 = mix_bytes,
            .nb_x0 = sizeof(float),
            .nb_x1 = (uint64_t)n_embd * sizeof(float),
            .nb_x2 = residual_row_bytes,
            .nb0 = sizeof(float),
            .nb1 = out_row_bytes,
            .eps = eps,
        };

        NSUInteger nth = g_hc_split_weighted_sum_pipeline.maxTotalThreadsPerThreadgroup;
        if (nth > 256u) nth = 256u;
        if (nth > (NSUInteger)n_embd) nth = (NSUInteger)n_embd;
        if (nth == 0) nth = 1u;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_hc_split_weighted_sum_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:mixbuf offset:ds4_gpu_tensor_offset(mix) atIndex:1];
        [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:2];
        [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:3];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:4];
        [enc setBuffer:splitbuf offset:ds4_gpu_tensor_offset(split) atIndex:5];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:6];
        [enc setThreadgroupMemoryLength:(NSUInteger)n_hc * sizeof(float) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n_rows64, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "HC split/sum fused")) return 0;
    }

    return 1;
}

/* Decode-only HC-pre plus the immediately following weighted RMSNorm.  This is
 * intentionally specialized for DS4's fixed HC=4 shape; larger batched prefill
 * keeps using the existing two-stage path. */
int ds4_gpu_hc_split_weighted_sum_norm_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *norm_out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint64_t                norm_weight_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps,
        float                   norm_eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !norm_out || !split || !mix || !residual_hc || !model_map ||
        n_embd == 0 || (n_embd & 3u) != 0 || n_hc != 4) {
        return 0;
    }

    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    const uint64_t mix_bytes = mix_hc * sizeof(float);
    const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
    const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
    const uint64_t scale_bytes = 3ull * sizeof(float);

    @autoreleasepool {
        id<MTLBuffer> mixbuf = ds4_gpu_tensor_buffer(mix);
        id<MTLBuffer> splitbuf = ds4_gpu_tensor_buffer(split);
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(residual_hc);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> normbuf = ds4_gpu_tensor_buffer(norm_out);
        const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
        if (out_row_bytes == 0 || out_tensor_bytes < out_row_bytes ||
            out_tensor_bytes % out_row_bytes != 0) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm output size is not a whole token row\n");
            return 0;
        }

        const uint64_t n_rows64 = out_tensor_bytes / out_row_bytes;
        if (n_rows64 == 0 || n_rows64 > UINT32_MAX ||
            n_rows64 > UINT64_MAX / mix_bytes ||
            n_rows64 > UINT64_MAX / residual_row_bytes) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm row count is outside supported range\n");
            return 0;
        }

        const uint64_t mix_total_bytes = n_rows64 * mix_bytes;
        const uint64_t residual_total_bytes = n_rows64 * residual_row_bytes;
        const uint64_t out_total_bytes = n_rows64 * out_row_bytes;
        if (!mixbuf || !splitbuf || !xbuf || !outbuf || !normbuf ||
            ds4_gpu_tensor_bytes(mix) < mix_total_bytes ||
            ds4_gpu_tensor_bytes(split) < mix_total_bytes ||
            ds4_gpu_tensor_bytes(residual_hc) < residual_total_bytes ||
            ds4_gpu_tensor_bytes(norm_out) < out_total_bytes) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm received undersized activation buffers\n");
            return 0;
        }

        if (scale_offset > model_size || scale_bytes > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset ||
            norm_weight_offset > model_size || out_row_bytes > model_size - norm_weight_offset) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm parameter range is outside the mapped model\n");
            return 0;
        }

        uint64_t scale_inner = 0;
        uint64_t base_inner = 0;
        uint64_t norm_inner = 0;
        id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(model_map, model_size, scale_offset, scale_bytes, &scale_inner);
        id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(model_map, model_size, base_offset, mix_bytes, &base_inner);
        id<MTLBuffer> normwbuf = ds4_gpu_wrap_model_range(model_map, model_size, norm_weight_offset, out_row_bytes, &norm_inner);
        if (!scalebuf || !basebuf || !normwbuf) return 0;

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_hc_split_weighted_sum_norm_pipeline,
                                   "kernel_dsv4_hc_split_weighted_sum_norm4");
        if (!pipeline) return 0;

        ds4_gpu_hc_split_weighted_sum_norm_args args = {
            .n_embd = (int64_t)n_embd,
            .n_hc = (int32_t)n_hc,
            .sinkhorn_iters = (int32_t)sinkhorn_iters,
            .n_rows = (int64_t)n_rows64,
            .mix_hc = (int64_t)mix_hc,
            .nb_mix1 = mix_bytes,
            .nb_split1 = mix_bytes,
            .nb_x0 = sizeof(float),
            .nb_x1 = (uint64_t)n_embd * sizeof(float),
            .nb_x2 = residual_row_bytes,
            .nb0 = sizeof(float),
            .nb1 = out_row_bytes,
            .nb_norm1 = out_row_bytes,
            .eps = eps,
            .norm_eps = norm_eps,
        };

        NSUInteger nth = ds4_gpu_rms_norm_threads(n_embd);
        if (nth > pipeline.maxTotalThreadsPerThreadgroup) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm requires %lu threads but pipeline supports %lu\n",
                    (unsigned long)nth,
                    (unsigned long)pipeline.maxTotalThreadsPerThreadgroup);
            return 0;
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:mixbuf offset:ds4_gpu_tensor_offset(mix) atIndex:1];
        [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:2];
        [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:3];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:4];
        [enc setBuffer:splitbuf offset:ds4_gpu_tensor_offset(split) atIndex:5];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:6];
        [enc setBuffer:normwbuf offset:(NSUInteger)norm_inner atIndex:7];
        [enc setBuffer:normbuf offset:ds4_gpu_tensor_offset(norm_out) atIndex:8];
        [enc setThreadgroupMemoryLength:((NSUInteger)n_embd + 4u + 32u) * sizeof(float)
                                atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n_rows64, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "HC split/sum/norm fused")) return 0;
    }

    return 1;
}

int ds4_gpu_output_hc_weights_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *pre,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_hc,
        float                   eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !pre || !model_map || n_hc == 0) return 0;

    @autoreleasepool {
        if ((n_hc % 4u) != 0) {
            fprintf(stderr, "ds4: Metal output HC weights requires a multiple-of-4 HC width\n");
            return 0;
        }

        id<MTLBuffer> prebuf = ds4_gpu_tensor_buffer(pre);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t row_bytes = (uint64_t)n_hc * sizeof(float);
        const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
        if (row_bytes == 0 || out_tensor_bytes < row_bytes || out_tensor_bytes % row_bytes != 0) {
            fprintf(stderr, "ds4: Metal output HC weights size is not a whole token row\n");
            return 0;
        }

        const uint64_t n_tokens64 = out_tensor_bytes / row_bytes;
        if (n_tokens64 == 0 || n_tokens64 > UINT32_MAX ||
            n_tokens64 > UINT64_MAX / row_bytes) {
            fprintf(stderr, "ds4: Metal output HC weights token count is outside supported range\n");
            return 0;
        }

        const uint64_t bytes = n_tokens64 * row_bytes;
        if (!prebuf || !outbuf ||
            ds4_gpu_tensor_bytes(pre) < bytes ||
            ds4_gpu_tensor_bytes(out) < bytes) {
            fprintf(stderr, "ds4: Metal output HC weights received undersized buffers\n");
            return 0;
        }

        uint64_t scale_inner = 0;
        uint64_t base_inner = 0;
        id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                            scale_offset, sizeof(float),
                                                            &scale_inner);
        id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                           base_offset, row_bytes,
                                                           &base_inner);
        if (!scalebuf || !basebuf) return 0;

        const uint32_t n_tokens = (uint32_t)n_tokens64;
        ds4_gpu_bin_args mul_args = ds4_gpu_make_bin_rows_args(n_hc, n_tokens, 1);
        ds4_gpu_bin_args add_args = ds4_gpu_make_bin_rows_args(n_hc, n_tokens, n_hc);
        ds4_gpu_unary_args sigmoid_args = ds4_gpu_make_unary_rows_args(n_hc, n_tokens, 1, 0.0f, 0.0f);
        ds4_gpu_unary_args scale_args = ds4_gpu_make_unary_rows_args(n_hc, n_tokens, 1, 1.0f, eps);

        NSUInteger mul_nth_max = g_bin_mul_scalar_pipeline.maxTotalThreadsPerThreadgroup;
        if (mul_nth_max > 256u) mul_nth_max = 256u;
        NSUInteger mul_nth = 1u;
        while (2u * mul_nth < (NSUInteger)mul_args.ne0 && mul_nth < mul_nth_max) {
            mul_nth *= 2u;
        }

        NSUInteger add_nth_max = g_add_pipeline.maxTotalThreadsPerThreadgroup;
        if (add_nth_max > 256u) add_nth_max = 256u;
        NSUInteger add_nth = 1u;
        while (2u * add_nth < (NSUInteger)add_args.ne0 && add_nth < add_nth_max) {
            add_nth *= 2u;
        }

        NSUInteger unary_nth_max = g_unary_sigmoid_pipeline.maxTotalThreadsPerThreadgroup;
        if (unary_nth_max > 256u) unary_nth_max = 256u;
        NSUInteger unary_nth = (NSUInteger)sigmoid_args.ne00;
        if (unary_nth > unary_nth_max) unary_nth = unary_nth_max;
        if (unary_nth == 0) unary_nth = 1u;
        const NSUInteger unary_nk0 = ((NSUInteger)sigmoid_args.ne00 + unary_nth - 1u) / unary_nth;
        const NSUInteger out_offset = ds4_gpu_tensor_offset(out);

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
